window.RECIPE_DATA = [{"name":"清炒时蔬","cat":"素菜","region":"家常","time":12,"diff":"简单","main":[["小白菜","300g"],["胡萝卜","半根"]],"sea":["蒜","盐","食用油"],"steps":["小白菜逐棵掰开洗净，甩干水分；胡萝卜削皮切薄片，蒜切末备用。","炒锅烧到微微冒青烟，倒食用油晃匀，下蒜末小火炝出香味。","转大火下胡萝卜片炒半分钟，再下小白菜快速翻炒至叶片塌软。","菜叶出水时加盐，大火再炒二十秒收干汤汁出锅。"],"tip":"小白菜一定沥干水再下锅，带水下锅会变成煮菜，出汤又发黄。"},{"name":"蒜蓉油麦菜","cat":"素菜","region":"家常","time":10,"diff":"简单","main":[["油麦菜","400g"]],"sea":["蒜","盐","食用油"],"steps":["油麦菜逐片掰开洗净，切成两段，蒜剁成蓉后平均分成两份。","大火烧锅至微微冒烟，倒食用油后下三分之二蒜蓉，小火炒到浅黄。","转大火倒入油麦菜，快速翻炒到叶子刚塌下、颜色转深绿。","加盐和剩下的生蒜蓉，大火翻炒十秒立刻出锅装盘。"],"tip":"蒜蓉分两次放，一半炒香一半生蒜，蒜味才够冲，全程别超过一分钟。"},{"name":"干煸豆角","cat":"素菜","region":"川","time":25,"diff":"中等","main":[["豆角","400g"]],"sea":["干辣椒","花椒","蒜","盐","生抽","食用油"],"steps":["豆角掐头去尾撕掉两侧的筋，掰成五厘米长的段，洗净后彻底擦干。","锅里倒多一点食用油，中火下豆角慢煸六分钟，煸到表皮起皱发白。","把豆角拨到锅边，下干辣椒段、花椒和蒜末，小火炒出香味。","合在一起大火翻炒，加盐和几滴生抽炒匀，豆角软塌即可出锅。"],"tip":"豆角必须煸到皮皱发软，半生的豆角有毒，绝不能为求脆而少煸。"},{"name":"手撕包菜","cat":"素菜","region":"湘","time":15,"diff":"简单","main":[["包菜","半颗"]],"sea":["干辣椒","蒜","醋","生抽","盐","食用油"],"steps":["包菜剥去外层老叶，用手撕成大片，粗菜梗用刀背拍松。","撕好的包菜放清水里泡洗两遍，捞出甩干表面水分。","锅烧热倒食用油，下干辣椒段和蒜片，小火炒到辣椒变色。","转最大火倒入包菜，快速翻炒一分钟，沿锅边淋一圈醋。","加盐和生抽，大火再炒三十秒到菜叶边缘透明即可出锅。"],"tip":"手撕比刀切更挂汁入味，菜梗拍松才和叶子同时熟，别炒过头。"},{"name":"醋溜白菜","cat":"素菜","region":"鲁","time":18,"diff":"中等","main":[["大白菜","500g"]],"sea":["干辣椒","醋","白糖","盐","生抽","淀粉","食用油","蒜"],"steps":["大白菜掰开洗净，菜帮斜刀片成薄片，菜叶撕成大块，分开放。","碗里放醋、白糖、盐、生抽和淀粉，加两勺清水调成碗汁。","热锅倒食用油，下干辣椒和蒜末小火炒香，先下菜帮大火炒一分钟。","下菜叶炒到塌软，倒入碗汁，大火翻到汤汁变稠挂勺即可。"],"tip":"菜帮先下菜叶后下，碗汁一次倒入，醋味才聚得住不挥发。"},{"name":"炝炒藕片","cat":"素菜","region":"鄂","time":18,"diff":"中等","main":[["莲藕","1节"]],"sea":["干辣椒","花椒","醋","盐","食用油","蒜"],"steps":["莲藕削皮切成两毫米薄片，泡在清水里，滴几滴醋防止发黑。","水烧开下藕片焯三十秒，捞出立刻过凉水，沥干水分备用。","锅烧热倒食用油，下花椒和干辣椒段，小火炸到花椒变深色。","转大火下蒜末和藕片，快速翻炒一分钟，沿锅边淋一勺醋。","保持大火加盐炒匀，藕片边缘透亮、咬着脆响时立刻出锅。"],"tip":"藕片先焯水再下锅，去涩又缩短炒制时间，脆而不生。"},{"name":"蒜蓉西兰花","cat":"素菜","region":"家常","time":15,"diff":"简单","main":[["西兰花","1颗"]],"sea":["蒜","盐","食用油","淀粉"],"steps":["西兰花切成小朵，用淡盐水泡十分钟，再冲洗两遍沥干。","水烧开加一勺盐和几滴食用油，下西兰花焯一分钟后捞出控水。","锅中倒食用油，小火下蒜末炒到微微发黄、香味冲出。","转大火倒入西兰花翻炒一分钟，加盐炒匀，淋水淀粉勾薄芡出锅。"],"tip":"焯水时加油加盐，西兰花颜色更翠，炒时也不容易渗水。"},{"name":"白灼芥蓝","cat":"素菜","region":"粤","time":12,"diff":"简单","main":[["芥蓝","400g"]],"sea":["蒜","蒸鱼豉油","食用油","盐"],"steps":["芥蓝削掉根部老皮，粗梗从中间竖划一刀，洗净沥干水。","水烧开加一勺盐和几滴食用油，芥蓝根部朝下入锅烫一分半钟。","捞出芥蓝整齐码在盘里，梗朝外摆开，倒掉盘底的积水。","蒜末铺在芥蓝上，均匀淋两勺蒸鱼豉油，别浇在盘底。","锅里烧热三勺食用油到冒烟，趁热浇在蒜末上激出香味即可。"],"tip":"水里加盐和油，烫完仍翠绿；根部先入水，梗叶才同时熟透。"},{"name":"清炒土豆丝","cat":"素菜","region":"家常","time":20,"diff":"简单","main":[["土豆","2个"],["青椒","1个"]],"sea":["蒜","醋","盐","食用油","花椒"],"steps":["土豆削皮切细丝，放清水里抓洗两遍，洗到水清不浑为止。","土豆丝捞出沥干，青椒去籽切细丝，蒜去皮切片备用。","锅烧热倒食用油，下花椒小火炸香，捞出花椒不要。","大火下蒜片和土豆丝，快炒一分钟，沿锅边淋一勺醋。","大火加青椒丝和盐炒三十秒，土豆丝断生仍脆时出锅。"],"tip":"土豆丝洗掉表面淀粉再炒，根根分明不粘锅，醋分两次放更脆。"},{"name":"蒜蓉菠菜","cat":"素菜","region":"家常","time":10,"diff":"简单","main":[["菠菜","400g"]],"sea":["蒜","盐","食用油"],"steps":["菠菜切掉老根，整棵洗净泥沙，蒜拍碎后剁成细末。","水烧开下菠菜烫二十秒，捞出过凉水，挤干水分切成两段。","锅烧热倒食用油，小火下蒜末炒到微黄出香，别炒糊。","转大火下菠菜段，快速翻炒一分钟，加盐炒匀出锅。"],"tip":"菠菜先焯水去草酸，口感不涩，回锅炒的时间也能压到一分钟内。"},{"name":"蒜蓉空心菜","cat":"素菜","region":"粤","time":10,"diff":"简单","main":[["空心菜","400g"]],"sea":["蒜","盐","食用油"],"steps":["空心菜摘掉老梗，掐成五厘米长的段，洗净后沥干水分。","四瓣蒜剁成蓉，另外两瓣切成薄片，分开放。","锅烧到冒烟再倒食用油，下蒜片小火爆出香味。","转大火倒入空心菜，快速翻炒四十秒到叶子塌软。","加蒜蓉和盐，大火翻炒十秒立刻出锅，梗脆叶嫩。"],"tip":"全程大火快炒、锅要够热，空心菜才不会发黑出汤变软塌。"},{"name":"清炒莴笋丝","cat":"素菜","region":"家常","time":15,"diff":"简单","main":[["莴笋","1根"]],"sea":["蒜","盐","食用油"],"steps":["莴笋削去外皮和白色粗筋，切五厘米长的细丝，蒜切末。","莴笋丝放淡盐水里泡五分钟，捞出沥干水分备用。","锅烧热倒食用油，下蒜末小火炒出香味，别炒焦。","转大火下莴笋丝，快炒一分半钟，加盐炒匀。","大火炒到莴笋丝变半透明、咬着脆嫩时立刻出锅，别久炒。"],"tip":"莴笋丝泡淡盐水能去涩保脆，炒过头就发软出水，最多两分钟。"},{"name":"干煸杏鲍菇","cat":"素菜","region":"川","time":22,"diff":"中等","main":[["杏鲍菇","3根"]],"sea":["干辣椒","花椒","蒜","盐","生抽","食用油"],"steps":["杏鲍菇切掉老根，用手撕成筷子粗的条，撒少许盐抓匀。","平底锅不放油，中火下杏鲍菇干煸四分钟，煸到出水变软。","继续中火煸到水分收干、菌条边缘微黄时盛出。","锅里倒食用油，下蒜末、干辣椒段和花椒小火炒香。","倒回杏鲍菇，大火翻炒，加生抽和盐炒到干香即可。"],"tip":"先干锅煸出水分再放油，杏鲍菇才有嚼劲，不会一炒就出汤。"},{"name":"干煸茶树菇","cat":"素菜","region":"川","time":25,"diff":"中等","main":[["茶树菇","300g"]],"sea":["干辣椒","花椒","蒜","盐","生抽","食用油"],"steps":["茶树菇剪掉老根，撕成小把，清水冲洗后摊开彻底晾干。","锅中倒食用油烧到六成热，下茶树菇中火炸两分钟。","炸到菌柄收缩、颜色变深时捞出，放在漏勺里控油。","锅留底油，下干辣椒段、花椒和蒜末小火炒出香味。","倒入茶树菇大火翻炒，加盐和生抽炒匀，干香有韧劲即可。"],"tip":"茶树菇必须晾干再下锅，带水炸会溅油，也煸不出干香。"},{"name":"蒜蓉茼蒿","cat":"素菜","region":"家常","time":10,"diff":"简单","main":[["茼蒿","400g"]],"sea":["蒜","盐","食用油"],"steps":["茼蒿掐掉老梗，只留嫩茎和叶，洗净后切成两段。","茼蒿摊在笊篱里沥干水，五瓣蒜剁成细蓉。","锅烧热倒食用油，小火下蒜蓉炒到微微发黄出香。","转大火下茼蒿，快速翻炒五十秒到叶子塌软。","大火加盐炒匀，茼蒿刚断生就出锅，久炒会发苦发黄。"],"tip":"茼蒿自带清香，只用蒜蓉和盐调味，放酱油会压住本味还发黑。"},{"name":"白灼菜心","cat":"素菜","region":"粤","time":12,"diff":"简单","main":[["菜心","400g"]],"sea":["蒜","蒸鱼豉油","食用油","盐"],"steps":["菜心摘去老叶，根部削平，粗梗划十字刀，洗净沥干水。","水烧开加盐和几滴油，菜心根部朝下先烫二十秒。","再把整棵按进水里烫一分钟，捞出控干水摆盘。","蒜末撒在菜心上，淋三勺蒸鱼豉油，沿菜梗淋匀。","烧两勺食用油到冒烟，趁热浇在蒜末上激香即可。"],"tip":"根部先烫二十秒，梗和叶才同时熟；出锅控干水，淋汁不被稀释。"},{"name":"清炒芦笋","cat":"素菜","region":"家常","time":12,"diff":"简单","main":[["芦笋","300g"]],"sea":["蒜","盐","食用油"],"steps":["芦笋掰掉根部老的一段，削去下半截粗皮，斜切成段。","水烧开下芦笋焯三十秒，捞出立刻过凉水沥干。","锅烧热倒食用油，下蒜片小火炒出香味。","转大火下芦笋，翻炒一分钟，加盐炒匀。","大火炒到芦笋颜色转深绿、咬着脆甜时立刻出锅，炒久会发黄。"],"tip":"芦笋先焯水去涩，回锅炒不超过一分半钟，否则失去脆甜。"},{"name":"山药炒木耳","cat":"素菜","region":"家常","time":20,"diff":"简单","main":[["山药","1根"],["木耳","1小把"]],"sea":["蒜","盐","醋","食用油"],"steps":["木耳提前用冷水泡两小时，撕成小朵，冲洗掉根部泥沙。","山药削皮切薄片，泡在滴了几滴醋的水里防止氧化发黑。","水烧开下木耳和山药片，焯一分钟后捞出沥干。","锅烧热倒食用油，下蒜片小火炒香，转大火下山药和木耳。","大火翻炒一分半钟，加盐炒匀，淋几滴醋提味出锅。"],"tip":"削山药戴手套防手痒，泡醋水能保持雪白，炒前焯水更爽脆。"},{"name":"蒜蓉秋葵","cat":"素菜","region":"家常","time":12,"diff":"简单","main":[["秋葵","300g"]],"sea":["蒜","蒸鱼豉油","食用油","盐"],"steps":["秋葵用盐搓洗表面绒毛，冲净后切掉硬蒂，别切开。","水烧开加几滴食用油，下秋葵烫两分钟，捞出过凉水。","秋葵对半剖开，切面朝上整齐码在盘里。","蒜末铺在秋葵上，均匀淋两勺蒸鱼豉油。","烧热三勺食用油到冒烟，浇在蒜末上激出蒜香即可。"],"tip":"秋葵整根焯水再剖开，黏液不流失，口感才滑嫩不柴。"},{"name":"清炒豆芽","cat":"素菜","region":"家常","time":8,"diff":"简单","main":[["豆芽","400g"]],"sea":["蒜","醋","盐","食用油"],"steps":["豆芽放清水里泡洗两遍，漂掉浮起的豆皮，捞出沥干。","锅烧到冒烟倒食用油，下蒜末小火炝出香味。","转最大火倒入豆芽，快速翻炒一分钟到豆芽略透明。","保持大火沿锅边淋一勺醋，加盐炒匀，豆芽刚断生就出锅。"],"tip":"豆芽大火快炒加一点醋，脆爽不出水，炒久了就软塌发酸。"},{"name":"蒜蓉娃娃菜","cat":"素菜","region":"家常","time":15,"diff":"简单","main":[["娃娃菜","2颗"]],"sea":["蒜","盐","食用油"],"steps":["娃娃菜切掉根部，纵向切成四瓣，逐瓣洗净沥干水。","六瓣蒜剁成蓉，锅烧热倒食用油，小火炒香蒜蓉。","先下娃娃菜的菜帮部分，中火翻炒一分钟到边缘变软。","再下菜叶，转大火翻炒到叶子塌软出水。","大火加盐炒匀，汤汁略收、菜帮透明不烂时出锅。"],"tip":"菜帮先炒一分钟再放叶，熟度才一致，叶子不会烂成泥。"},{"name":"香菇油菜","cat":"素菜","region":"家常","time":18,"diff":"简单","main":[["油菜","300g"],["香菇","6朵"]],"sea":["蒜","盐","生抽","淀粉","食用油"],"steps":["油菜掰开洗净，香菇去蒂切厚片，蒜切片备用。","水烧开加盐和几滴油，油菜焯三十秒捞出摆盘。","锅烧热倒食用油，下蒜片和香菇片，中火炒两分钟出香。","加生抽、盐和小半碗水，中火煮一分钟后淋水淀粉勾薄芡。","把香菇连汁一起浇在油菜上，摆好盘即可上桌。"],"tip":"香菇要炒到边缘微焦再加水，菌香才浓；薄芡能让汁挂住菜。"},{"name":"韭菜炒香干","cat":"素菜","region":"家常","time":12,"diff":"简单","main":[["韭菜","200g"],["香干","3块"]],"sea":["盐","生抽","食用油"],"steps":["韭菜择洗干净，切成四厘米长的段，梗和叶分开放。","香干切薄片，放开水里烫三十秒去掉豆腥味，捞出沥干。","锅烧热倒食用油，下香干片中火煸到边缘微黄。","下韭菜梗大火炒三十秒，再下韭菜叶炒二十秒。","加盐和几滴生抽调味，大火炒匀，韭菜刚变软就出锅。"],"tip":"香干先焯水去豆腥，韭菜叶最后下锅，炒久会出水发黄。"},{"name":"芹菜炒香干","cat":"素菜","region":"家常","time":15,"diff":"简单","main":[["芹菜","300g"],["香干","3块"]],"sea":["蒜","盐","生抽","食用油"],"steps":["芹菜撕掉背部老筋，斜切成段，香干切细条，蒜切末。","水烧开下芹菜焯三十秒，捞出过凉水沥干。","锅烧热倒食用油，下蒜末炒香，倒入香干中火煸一分钟。","转大火下芹菜，翻炒一分半钟，加盐和生抽炒匀。","大火炒到芹菜断生仍翠绿、咬着脆响时立刻出锅，久炒会发黄。"],"tip":"芹菜先焯水再炒，颜色翠绿，还能去掉涩味和多余水分。"},{"name":"青椒炒豆干","cat":"素菜","region":"家常","time":15,"diff":"简单","main":[["青椒","2个"],["豆干","4块"]],"sea":["蒜","盐","生抽","食用油"],"steps":["青椒去籽切成菱形片，豆干切三角片，蒜切片。","锅烧热倒食用油，下豆干中火煎两分钟，煎到两面微黄盛出。","锅留底油，下蒜片和青椒片，大火炒一分钟到青椒断生。","倒回豆干，加盐和生抽，大火翻炒三十秒炒匀出锅。"],"tip":"豆干先煎出焦边再回锅，口感有嚼劲，翻炒时也不容易碎。"},{"name":"清炒苦瓜","cat":"素菜","region":"家常","time":15,"diff":"简单","main":[["苦瓜","1根"]],"sea":["蒜","盐","食用油"],"steps":["苦瓜对半剖开，用勺子刮净内壁白瓤，斜切成薄片。","苦瓜片加一勺盐抓匀腌五分钟，挤掉苦水后冲洗沥干。","锅烧热倒食用油，下蒜末小火炒出香味。","转大火下苦瓜片，快炒一分半钟，加盐炒匀。","大火炒到苦瓜翠绿略透明、咬着发脆时立刻出锅。"],"tip":"白瓤刮干净、盐腌后挤水，苦味能去掉大半，脆度还保得住。"},{"name":"清炒丝瓜","cat":"素菜","region":"家常","time":12,"diff":"简单","main":[["丝瓜","2根"]],"sea":["蒜","盐","食用油","淀粉"],"steps":["丝瓜刮掉外层硬皮，切成滚刀块，蒜切片备用。","切好的丝瓜泡在清水里，炒前捞出沥干防止发黑。","锅烧热倒食用油，下蒜片小火炒出香味。","转中大火下丝瓜，翻炒两分钟到丝瓜变软出水。","保持中大火加盐炒匀，淋少许水淀粉勾薄芡，汤汁挂勺即可。"],"tip":"丝瓜极易发黑，切好先泡水、热锅快炒，别用铁锅久煮。"},{"name":"白灼生菜","cat":"素菜","region":"粤","time":10,"diff":"简单","main":[["生菜","400g"]],"sea":["蒜","蒸鱼豉油","食用油","盐"],"steps":["生菜掰成大片，放淡盐水里泡五分钟，冲洗后沥干。","水烧开加几滴食用油，下生菜烫二十秒立刻捞出。","烫好的生菜控干水分，整齐码在盘中，别堆太厚。","蒜末撒在生菜上，均匀淋两勺蒸鱼豉油。","锅烧两勺食用油到冒烟，浇在蒜末上激出香味即可。"],"tip":"生菜下锅只烫二十秒，久烫就软烂；捞出控干水再淋汁。"},{"name":"红烧茄子","cat":"素菜","region":"家常","time":25,"diff":"简单","main":[["茄子","400g"],["青椒","1个"]],"sea":["蒜","生抽","老抽","白糖","盐","淀粉","食用油"],"steps":["茄子切滚刀块，撒少许盐抓匀腌10分钟，挤掉渗出的水，拍一层薄淀粉。","碗里放两勺生抽、半勺老抽、一勺白糖、半碗清水和少许淀粉，搅匀成料汁。","锅中多放油烧至六成热，下茄块中火煎4分钟，煎到表面金黄起壳后盛出。","锅留底油爆香蒜末，倒回茄块，淋入调好的料汁转大火翻动，汁收浓挂勺时下青椒块炒半分钟。"],"tip":"茄子先用盐杀水再拍淀粉，煎时不吃油，外壳还不易回软。"},{"name":"鱼香茄子","cat":"素菜","region":"川","time":25,"diff":"中等","main":[["茄子","400g"]],"sea":["泡椒","姜","蒜","醋","白糖","盐","淀粉","食用油"],"steps":["茄子去皮切成长条，撒少许盐腌10分钟，挤干水分后拍一层薄淀粉。","泡椒去籽剁成细末，姜蒜切末；碗里放醋、白糖、少许盐和淀粉，加两勺清水调成鱼香汁。","锅中放油烧至六成热，下茄条中火炸3分钟，炸到表面微黄发硬捞出控油。","锅留底油，中小火把泡椒末、姜末、蒜末炒香，炒到油色红亮。","倒回茄条转大火翻炒，淋入鱼香汁快速翻匀，汁收浓裹住茄条时关火。"],"tip":"泡椒剁得越细红油越亮，糖醋比例按一勺糖两勺醋最稳。"},{"name":"干锅花菜","cat":"素菜","region":"湘","time":25,"diff":"中等","main":[["菜花","500g"],["尖椒","2个"],["蒜苗","2根"]],"sea":["干辣椒","花椒","蒜","姜","豆瓣酱","生抽","盐","食用油"],"steps":["菜花掰成小朵，用淡盐水泡10分钟，捞出沥干水分，大朵的从中间剖开。","锅烧干不放油，下菜花中火干煸3分钟，煸到边缘微黄发软盛出。","锅中放油，中小火炒香干辣椒段、花椒、蒜片、姜丝和豆瓣酱，炒出红油。","下尖椒块和菜花转大火翻炒2分钟，加生抽和盐炒匀。","撒蒜苗段炒到断生，连锅端上桌或盛入小干锅。"],"tip":"菜花先干锅煸掉水汽再炒，口感脆不塌，也不吸一肚子油。"},{"name":"白菜炖豆腐","cat":"素菜","region":"东北","time":30,"diff":"简单","main":[["大白菜","500g"],["豆腐","400g"]],"sea":["葱","姜","蒜","生抽","盐","白胡椒","食用油"],"steps":["大白菜洗净，菜帮斜刀片成薄片，菜叶用手撕成大块，帮叶分开放。","锅中放油，中火把豆腐厚片两面煎5分钟，煎到微黄结皮盛出。","底油爆香葱段、姜片、蒜片，下白菜帮大火炒2分钟至变软出水，再下菜叶炒塌。","倒回豆腐，加生抽和没过食材的开水，大火烧开转中小火炖12分钟。","汤色发白略浓时加盐和白胡椒，再炖2分钟出锅。"],"tip":"豆腐先煎出硬皮再炖，久煮不散还能吸饱汤汁。"},{"name":"地三鲜","cat":"素菜","region":"东北","time":30,"diff":"中等","main":[["土豆","2个"],["茄子","2根"],["青椒","2个"]],"sea":["蒜","葱","生抽","老抽","白糖","淀粉","盐","食用油"],"steps":["土豆去皮切滚刀块，泡清水5分钟洗去表面淀粉；茄子切滚刀块撒盐腌5分钟挤水；青椒切块。","锅放宽油烧至六成热，下土豆块中火炸4分钟至金黄，再下茄子炸2分钟至发软，一起捞出控油。","碗里放生抽、少许老抽、白糖、盐、淀粉和半碗清水，调成芡汁。","锅留底油爆香蒜末葱花，下青椒块炒半分钟，倒入炸好的土豆和茄子。","淋入芡汁大火翻炒，汁收浓挂在食材上、锅底不留汤时关火。"],"tip":"土豆和茄子分开炸，先土豆后茄子，油温不降才不吸油。"},{"name":"油焖春笋","cat":"素菜","region":"淮扬","time":20,"diff":"简单","main":[["竹笋","500g"]],"sea":["生抽","老抽","白糖","香油","盐","食用油"],"steps":["竹笋剥壳削去老根，切滚刀块，冷水下锅煮8分钟去涩，捞出沥干。","锅中放比平时多的油，中火下笋块煎5分钟，煎到边缘微黄起皱。","加生抽、少许老抽和一勺白糖翻匀上色，倒小半碗清水，盖盖中小火焖8分钟。","开盖转大火收汁，汤汁浓稠裹住笋块时淋香油，加盐调味出锅。"],"tip":"笋先煮透去草酸和涩味，油要宽，焖到汤汁挂身才够鲜。"},{"name":"土豆炖豆角","cat":"素菜","region":"东北","time":35,"diff":"简单","main":[["土豆","2个"],["豆角","400g"]],"sea":["葱","姜","蒜","黄豆酱","生抽","盐","食用油"],"steps":["豆角掐去两头撕掉老筋，掰成两段洗净；土豆去皮切滚刀块，用清水冲一下。","锅中放油，中火下豆角煸6分钟，煸到表皮起皱发亮盛出。","底油爆香葱姜蒜，放一勺黄豆酱小火炒香，下土豆块翻炒裹匀。","倒回豆角，加生抽和没过一半的开水，盖盖中小火炖15分钟。","土豆一戳就烂时开大火收汁，加盐，汤汁浓稠裹住豆角即可。"],"tip":"豆角必须煸透炖透，颜色转暗、完全软烂才没有豆腥味。"},{"name":"香菇烧豆腐","cat":"素菜","region":"家常","time":25,"diff":"简单","main":[["香菇","8朵"],["豆腐","400g"]],"sea":["蒜","葱","生抽","蚝油","白糖","淀粉","食用油"],"steps":["豆腐切1厘米厚的三角块，用厨房纸吸干表面水分；香菇去蒂切厚片。","平底锅放油，中小火把豆腐煎4分钟，两面金黄结皮后盛出。","底油爆香蒜片和葱白，下香菇片中火炒3分钟，炒到出水又收干、边缘微焦。","加生抽、蚝油、白糖和小半碗水烧开，倒回豆腐，中小火烧6分钟。","淋水淀粉勾薄芡，汁挂住豆腐时撒葱花出锅。"],"tip":"香菇要炒到水汽收干再调味，鲜味才浓，豆腐也不出水。"},{"name":"干锅土豆片","cat":"素菜","region":"川","time":25,"diff":"简单","main":[["土豆","2个"],["尖椒","2个"],["蒜苗","2根"]],"sea":["干辣椒","花椒","豆瓣酱","蒜","姜","生抽","白糖","食用油"],"steps":["土豆去皮切3毫米厚的片，放清水里泡5分钟洗掉淀粉，捞出沥干。","平底锅放少许油，中火把土豆片煎6分钟，两面煎到金黄微焦盛出。","锅中放油，小火炒香干辣椒段、花椒、蒜片和姜片，加豆瓣酱炒出红油。","下尖椒块炒半分钟，倒回土豆片转大火翻炒1分钟，加生抽和白糖。","撒蒜苗段炒到断生，锅底干爽时出锅。"],"tip":"土豆片先煎再炒，边缘起焦壳才香，不会炒成糊糊。"},{"name":"干锅茶树菇","cat":"素菜","region":"湘","time":30,"diff":"中等","main":[["茶树菇","300g"],["尖椒","2个"],["蒜苗","2根"]],"sea":["干辣椒","蒜","姜","豆瓣酱","生抽","白糖","食用油"],"steps":["茶树菇剪去老根，撕成粗条，用清水泡洗两遍后彻底沥干水。","锅中不放油，中火下茶树菇干煸5分钟，煸到水分收干、菇身发软盛出。","锅中放油，小火煸香干辣椒段、蒜片和姜丝，加豆瓣酱炒出红油。","下茶树菇转大火翻炒2分钟，让每条菇都裹上红油。","加生抽、白糖和尖椒段炒1分钟，撒蒜苗段断生后盛入干锅。"],"tip":"茶树菇一定要干煸去水，否则下锅只会煮出一汪汤。"},{"name":"干锅藕片","cat":"素菜","region":"湘","time":25,"diff":"简单","main":[["莲藕","400g"],["尖椒","2个"]],"sea":["干辣椒","花椒","蒜","豆瓣酱","生抽","盐","白糖","食用油"],"steps":["莲藕去皮切3毫米薄片，泡在清水里防止发黑，下锅前捞出沥干。","水烧开加少许盐，下藕片焯1分钟捞出过凉水，控干水分。","锅中放油，小火炒香干辣椒、花椒和蒜片，加豆瓣酱炒出红油。","下藕片转大火翻炒3分钟，炒到藕片边缘微透明、表面挂红油。","加生抽、白糖和尖椒块炒半分钟，断生即出锅。"],"tip":"藕片焯水时加盐，炒出来更脆，也不易粘锅发黑。"},{"name":"干锅娃娃菜","cat":"素菜","region":"湘","time":20,"diff":"简单","main":[["娃娃菜","3棵"],["尖椒","2个"]],"sea":["蒜","干辣椒","豆瓣酱","生抽","蚝油","白糖","食用油"],"steps":["娃娃菜纵向切成四瓣，洗净沥干，菜帮和菜叶分开放。","锅中放油，中小火把菜帮切面朝下煎2分钟，煎到微黄再翻面煎1分钟。","另起锅放油，小火炒香蒜末和干辣椒段，加豆瓣酱炒出红油。","下煎好的娃娃菜和尖椒块，转大火翻炒2分钟，让菜叶塌软裹上红油。","加生抽、蚝油、白糖炒匀，汤汁收干时出锅。"],"tip":"菜帮先煎出焦边再炒，甜味出来，口感也脆。"},{"name":"红烧冬瓜","cat":"素菜","region":"家常","time":25,"diff":"简单","main":[["冬瓜","600g"]],"sea":["蒜","葱","生抽","老抽","蚝油","白糖","盐","食用油"],"steps":["冬瓜去皮去瓤，切成3厘米见方的块，在朝上一面划十字花刀。","平底锅放少许油，中火把冬瓜块切面朝下煎4分钟，煎到金黄起壳。","锅中留底油爆香蒜末，加生抽、老抽、蚝油、白糖和小半碗水烧开。","放入冬瓜块，盖盖中小火烧10分钟，烧到边缘透明、筷子能轻松插入。","开大火收汁，汁浓时加盐撒葱花，晃锅让每块冬瓜裹上酱色。"],"tip":"冬瓜先煎后烧，表面结壳才不烂成泥，还能挂住酱汁。"},{"name":"红烧萝卜","cat":"素菜","region":"家常","time":30,"diff":"简单","main":[["白萝卜","600g"]],"sea":["蒜","葱","八角","生抽","老抽","白糖","盐","食用油"],"steps":["白萝卜去皮切滚刀块，冷水下锅煮5分钟去掉辛辣味，捞出沥干。","锅中放油，中火下萝卜块煎5分钟，煎到表面微黄、边缘发亮。","加蒜片和一颗八角炒香，放生抽、老抽、白糖翻匀上色。","倒入没过萝卜一半的热水，盖盖中小火炖15分钟。","萝卜用筷子能扎透时开大火收汁，加盐撒葱花出锅。"],"tip":"萝卜先煮去辣气再烧，只留清甜，汤汁也更透亮。"},{"name":"干煸四季豆","cat":"素菜","region":"川","time":25,"diff":"中等","main":[["四季豆","400g"],["蒜苗","2根"]],"sea":["干辣椒","花椒","蒜","姜","盐","生抽","食用油"],"steps":["四季豆撕去两侧老筋，掰成5厘米长的段，洗净后彻底擦干水分。","锅中放宽油烧至七成热，下四季豆中火炸3分钟，炸到表皮起皱发白捞出。","锅留底油，小火炒香干辣椒段、花椒、蒜末和姜末。","倒回四季豆转大火翻炒1分钟，让香料裹匀。","加盐和生抽炒匀，撒蒜苗段断生，豆角完全熟透才出锅。"],"tip":"四季豆必须炸透或煸透，表皮起皱才算断生，避免中毒。"},{"name":"红烧腐竹","cat":"素菜","region":"家常","time":30,"diff":"简单","main":[["腐竹","150g"],["木耳","20g"]],"sea":["蒜","葱","生抽","老抽","蚝油","白糖","淀粉","食用油"],"steps":["腐竹用温水泡2小时至完全软透，挤干水切成5厘米长的段；木耳泡发撕小朵。","锅中放油，中火把腐竹段煎3分钟，煎到表面微黄收紧盛出。","底油爆香蒜末和葱白，下木耳炒2分钟，炒到木耳噼啪作响。","加生抽、老抽、蚝油、白糖和小半碗水烧开，放入腐竹中小火烧8分钟。","腐竹吸饱汤汁后淋水淀粉勾薄芡，撒葱花出锅。"],"tip":"腐竹用温水泡、不用开水，泡到中心无硬芯才不夹生。"},{"name":"干锅杏鲍菇","cat":"素菜","region":"家常","time":20,"diff":"简单","main":[["杏鲍菇","400g"],["尖椒","2个"]],"sea":["干辣椒","蒜","姜","豆瓣酱","生抽","白糖","食用油"],"steps":["杏鲍菇顺长切成半厘米厚的片，两面划浅十字花刀方便入味。","平底锅不放油，中火把杏鲍菇干煎5分钟，煎到出水收干、两面金黄。","淋少许油再煎1分钟，把菇片推到锅边，下蒜片、姜丝和干辣椒段炒香。","加豆瓣酱炒出红油，与菇片一起大火翻炒1分钟。","加生抽、白糖和尖椒块炒到断生，汁水收干即出锅。"],"tip":"杏鲍菇干锅先煎，把水分逼出来，口感才有嚼劲像鲍鱼。"},{"name":"干锅包菜","cat":"素菜","region":"湘","time":15,"diff":"简单","main":[["包菜","500g"]],"sea":["干辣椒","蒜","豆瓣酱","生抽","醋","白糖","食用油"],"steps":["包菜剥开洗净，用手撕成巴掌大的片，菜梗用刀背拍松。","锅烧到冒烟再放油，立刻下包菜大火快炒2分钟，炒到边缘变软。","把包菜拨到一边，下蒜片和干辣椒段炒香，加豆瓣酱炒出红油。","与包菜一起大火翻炒1分钟，沿锅边淋醋，加生抽和白糖炒匀。","菜梗断生、锅底无汤水时立刻出锅。"],"tip":"手撕不切刀，断面粗糙更挂汁；全程大火，出锅才脆。"},{"name":"蚝油香菇","cat":"素菜","region":"粤","time":20,"diff":"简单","main":[["香菇","300g"],["油菜","200g"]],"sea":["蒜","蚝油","生抽","白糖","淀粉","盐","食用油"],"steps":["香菇去蒂，在菇伞表面划十字花刀；油菜从根部切开洗净。","水烧开加盐和几滴油，下油菜焯1分钟，捞出摆盘围边。","锅中放油，中火下香菇煎3分钟，煎到两面微黄出香味。","加蒜末炒香，放蚝油、生抽、白糖和半碗水，中小火烧6分钟。","香菇变软、汤汁变少时淋水淀粉勾薄芡，盛在油菜中间。"],"tip":"香菇划十字花刀更易入味，蚝油最后放鲜味才不跑。"},{"name":"酸菜炖粉条","cat":"素菜","region":"东北","time":35,"diff":"简单","main":[["酸菜","400g"],["粉条","150g"]],"sea":["葱","姜","蒜","花椒","生抽","盐","白胡椒","食用油"],"steps":["酸菜洗净挤干水，菜帮片薄后切成细丝，再攥一遍水去掉多余酸味。","粉条用温水泡30分钟，泡到能弯折但中心还有一点硬芯。","锅中放油，中小火炒香葱姜蒜和花椒，下酸菜丝中火炒5分钟，炒出酸香味。","加生抽和足量开水，大火烧开转中小火炖15分钟。","下粉条再炖8分钟，粉条透明软糯时加盐和白胡椒，汤宽味厚即可。"],"tip":"酸菜要炒过再炖，酸香才厚；粉条后放，久煮不糊汤。"},{"name":"葱油芋头","cat":"素菜","region":"本帮","time":35,"diff":"简单","main":[["芋头","600g"]],"sea":["葱","盐","白糖","生抽","食用油"],"steps":["芋头洗净带皮上锅，水开后大火蒸20分钟，蒸到筷子能轻松扎透。","晾到不烫手后剥皮，切成滚刀块。","锅中放三勺油，中小火下葱段慢炸5分钟，炸到葱段焦黄发脆，捞出葱段留油。","下芋头块中火翻炒2分钟，让每块都裹上葱油。","加盐、少许白糖和一勺生抽，倒小半碗水，中小火烧5分钟收汁，撒新葱花。"],"tip":"葱段要小火慢炸到焦黄，葱油才香；芋头蒸透再烧不粘锅。"},{"name":"咖喱土豆","cat":"素菜","region":"家常","time":30,"diff":"简单","main":[["土豆","2个"],["胡萝卜","1根"],["洋葱","半个"]],"sea":["咖喱块","盐","食用油"],"steps":["土豆和胡萝卜去皮切滚刀块，洋葱切粗丝。","锅中放油，中火炒洋葱丝3分钟，炒到变软出甜香。","下土豆和胡萝卜块翻炒2分钟，倒入没过食材的开水，大火烧开转中小火炖12分钟。","土豆能用筷子扎透时转小火，放入咖喱块搅拌到完全化开。","再小火煮5分钟，汤汁浓稠能挂住勺背时加盐调味。"],"tip":"咖喱块要关小火再放，边搅边化，不然容易糊底发苦。"},{"name":"白菜炖粉条","cat":"素菜","region":"东北","time":30,"diff":"简单","main":[["大白菜","500g"],["粉条","120g"]],"sea":["葱","姜","蒜","八角","生抽","盐","食用油"],"steps":["粉条用温水泡30分钟至软；大白菜菜帮斜片成薄片，菜叶手撕成块。","锅中放油，中火下八角炸香，再放葱姜蒜爆香。","下白菜帮大火炒3分钟至变软出水，再下菜叶炒到塌秧。","加生抽和开水没过白菜，大火烧开后下粉条，转中小火炖12分钟。","粉条吸饱汤汁变透明时加盐，汤汁略收即可出锅。"],"tip":"粉条别提前煮，直接下锅炖，吸的是白菜汤汁才够味。"},{"name":"蒜泥茄子","cat":"凉菜","region":"家常","time":25,"diff":"简单","main":[["长茄子","3根"]],"sea":["蒜","生抽","醋","白糖","香油","盐","辣椒油"],"steps":["长茄子洗净去蒂，顺长剖成两半，皮朝下摆进蒸盘。","水开后上锅大火蒸12分钟，蒸到筷子一戳就透、茄子软塌出水。","倒掉盘里的水，晾到温热后用手撕成粗条，轻轻挤掉多余水分。","蒜捣成泥，加生抽、醋、白糖、盐和香油调匀，尝一下酸咸平衡。","把蒜泥汁浇在茄条上，淋一勺辣椒油，拌开静置5分钟入味。"],"tip":"茄子蒸好一定倒掉盘里的水，否则拌出来寡淡还出水。"},{"name":"凉拌海带丝","cat":"凉菜","region":"家常","time":20,"diff":"简单","main":[["海带","300g"],["胡萝卜","半根"]],"sea":["蒜","醋","生抽","白糖","盐","香油","辣椒油"],"steps":["海带洗净切成细丝，胡萝卜去皮切细丝。","水大火烧开下海带丝煮5分钟，煮到海带变软能咬断，捞出过凉水。","胡萝卜丝下开水焯30秒，捞出过凉，与海带丝一起沥干水分。","蒜切末，加醋、生抽、白糖、盐和香油调成料汁。","料汁倒入海带丝拌匀，淋辣椒油，冷藏10分钟更爽口。"],"tip":"海带煮后立刻过凉水，口感脆；醋多放一点能压住海腥味。"},{"name":"凉拌木耳","cat":"凉菜","region":"家常","time":20,"diff":"简单","main":[["木耳","30g"],["彩椒","半个"],["香菜","2根"]],"sea":["蒜","生抽","醋","白糖","盐","香油","辣椒油"],"steps":["木耳用冷水泡2小时至完全发开，剪去根部硬蒂，撕成小朵。","水大火烧开下木耳煮3分钟，捞出立刻过凉水，控干水分。","彩椒去籽切细丝，香菜洗净切成3厘米长的段。","蒜切末，加生抽、醋、白糖、盐和香油调匀。","木耳、彩椒丝、香菜段放盆里，淋料汁和辣椒油拌匀，静置5分钟。"],"tip":"木耳冷水泡发才脆，焯水后过凉水，拌前务必控干水。"},{"name":"鱼香肉丝","cat":"荤菜","region":"川","time":25,"diff":"中等","main":[["猪里脊","250g"],["木耳","30g"],["胡萝卜","半根"]],"sea":["泡椒","豆瓣酱","葱","姜","蒜","醋","白糖","淀粉"],"steps":["猪里脊顺着纹路切细丝，加淀粉和一勺清水抓至发黏，静置十分钟。","木耳提前泡发切丝，胡萝卜切细丝，泡椒剁碎，蒜和姜切末备用。","小碗里放醋、白糖、淀粉和两勺清水搅匀，调成鱼香汁待用。","中火烧油至四成热下肉丝滑散，肉色变白立刻盛出，锅留底油。","小火下泡椒、豆瓣酱、蒜姜末炒出红油，转大火下木耳和胡萝卜丝炒一分钟。","倒回肉丝，淋入鱼香汁快速翻匀，汁浓裹住肉丝时撒葱末出锅。"],"tip":"肉丝上浆后再封一层油，滑炒不粘连；鱼香汁下锅前要再搅一次，淀粉易沉底。"},{"name":"京酱肉丝","cat":"荤菜","region":"鲁","time":25,"diff":"中等","main":[["猪里脊","250g"],["豆皮","4张"]],"sea":["甜面酱","白糖","淀粉","料酒","葱","姜"],"steps":["猪里脊切细丝，加料酒、淀粉抓匀，表面封少许油腌十分钟。","甜面酱加白糖和两勺清水调开，避免下锅后发苦发咸。","中火滑炒肉丝，炒到变白断生盛出控油，锅洗净烧干。","小火下甜面酱不停推炒，炒到冒小泡、颜色发亮再倒回肉丝。","转大火快速翻裹，酱汁均匀挂在每根肉丝上时关火。","豆皮切方块上锅蒸两分钟，配葱丝和肉丝一起卷着吃。"],"tip":"甜面酱先用糖水澥开再炒，酱香不糊锅，色泽也更透亮好看。"},{"name":"糖醋里脊","cat":"荤菜","region":"鲁","time":30,"diff":"中等","main":[["猪里脊","300g"],["鸡蛋","1个"]],"sea":["淀粉","番茄酱","白糖","醋","料酒","盐","食用油"],"steps":["猪里脊切粗条，加盐和料酒抓匀腌十分钟，用厨房纸吸干水分。","淀粉加鸡蛋和少量清水调成稠糊，能挂住肉条、提起不滴落。","中火烧油至五成热，肉条逐根下锅炸到定型微黄捞出。","大火把油温升到八成，复炸三十秒至外壳金黄酥脆，立刻捞出。","锅留底油，下番茄酱、白糖、醋小火熬到冒泡变稠、能挂勺。","倒入肉条大火翻两下，糖醋汁裹匀马上出锅，久炒会回软。"],"tip":"复炸是酥脆的关键，油温不够高炸不出壳；糖醋汁熬稠再下肉。"},{"name":"锅包肉","cat":"荤菜","region":"东北","time":35,"diff":"较难","main":[["猪里脊","300g"],["胡萝卜","半根"],["香菜","1把"]],"sea":["淀粉","白糖","醋","生抽","葱","姜","蒜","食用油"],"steps":["猪里脊切厚片，用刀背轻拍松，加生抽抓匀腌十分钟。","淀粉加水泡透，倒掉上层清水，用沉底的湿淀粉裹住肉片。","中火烧油至六成热，肉片逐片展开下锅，炸到浮起定型捞出。","大火复炸到边缘微焦、外壳起小泡，捞出沥油。","碗里放白糖、醋、生抽和两勺水调成汁，葱姜蒜切丝。","锅烧热下汁熬稠，倒肉片和胡萝卜丝大火翻匀，撒香菜出锅。"],"tip":"湿淀粉要沉淀后只用底下的厚糊，挂得住才够脆；汁最后下，翻两下离火。"},{"name":"水煮肉片","cat":"荤菜","region":"川","time":30,"diff":"中等","main":[["猪里脊","300g"],["豆芽","200g"]],"sea":["豆瓣酱","干辣椒","花椒","蒜","淀粉","料酒","盐","食用油"],"steps":["猪里脊逆纹切薄片，加盐、料酒、淀粉抓匀，腌十五分钟。","豆芽下沸水焯一分钟，捞出铺在大碗底，撒少许盐拌匀。","中小火下豆瓣酱炒出红油，加两碗水烧开，转小火煮三分钟。","肉片抖散下锅，中火煮到变白卷起，约一分钟连汤倒进碗中。","面上铺蒜末、干辣椒段和花椒，另起锅烧热油泼上去激出香味。"],"tip":"肉片下锅后先别搅，定型再推散；煮过头就柴，一分钟足够。"},{"name":"回锅肉","cat":"荤菜","region":"川","time":30,"diff":"中等","main":[["五花肉","400g"],["青椒","1个"],["蒜苗","1把"]],"sea":["豆瓣酱","豆豉","甜面酱","姜","葱","料酒","生抽"],"steps":["五花肉整块冷水下锅，加姜葱和料酒，中火煮二十分钟至筷子能穿透。","肉捞出晾凉切薄片，青椒切块，蒜苗斜切成段。","中小火下肉片慢煸，煸到肉片卷起成灯盏窝、边缘微焦。","拨开肉片，下豆瓣酱、豆豉、甜面酱小火炒出红油。","转大火下青椒和蒜苗，淋生抽快炒一分钟至断生关火。"],"tip":"肉煮到七成熟再切，晾凉后片得薄；一定要煸出油，吃着才不腻。"},{"name":"红烧肉","cat":"荤菜","region":"家常","time":80,"diff":"中等","main":[["五花肉","500g"]],"sea":["冰糖","生抽","老抽","料酒","八角","姜","葱","食用油"],"steps":["五花肉切三厘米方块，冷水下锅焯三分钟，撇净血沫捞出洗净。","锅烧热下肉块，中小火干煸出油，表面微黄时盛出。","留底油下冰糖小火炒到枣红色冒小泡，倒肉块翻裹上色。","加姜葱、八角、料酒、生抽、老抽，倒热水没过肉块两指。","大火烧开转小火炖五十分钟，肉皮用筷子能轻松扎透。","开大火收汁，汤汁浓稠挂在肉上、油亮发红时关火。"],"tip":"糖色炒到枣红立刻下肉，晚一秒就发苦；中途只加热水，肉不发紧。"},{"name":"粉蒸肉","cat":"荤菜","region":"湘","time":90,"diff":"中等","main":[["五花肉","500g"],["大米","80g"]],"sea":["豆瓣酱","料酒","生抽","姜","葱","八角"],"steps":["大米加八角下锅小火炒到微黄，晾凉后用擀面杖擀成粗米粉。","五花肉切厚片，加豆瓣酱、生抽、料酒、姜末抓匀腌二十分钟。","肉片分次加入米粉和清水，抓到每片肉都裹上湿润的粉。","碗底铺葱段，肉片皮朝下码紧，上汽后中火蒸一小时。","取出倒扣在盘中，撒上葱花，趁热上桌，肉片一夹就断。"],"tip":"米粉要粗不要细，加水抓到粉发潮，蒸出来才不干不散。"},{"name":"梅菜扣肉","cat":"荤菜","region":"客家","time":120,"diff":"较难","main":[["五花肉","500g"],["梅干菜","100g"]],"sea":["生抽","老抽","冰糖","料酒","八角","姜","蒜","食用油"],"steps":["梅干菜用温水泡二十分钟，反复抓洗掉泥沙，挤干水分切碎。","五花肉整块冷水下锅煮二十分钟，捞出趁热在肉皮上抹一层老抽。","中火烧油，肉皮朝下入锅炸到起泡发皱，捞出泡冷水十分钟。","肉切厚片，皮朝下码入碗中，加生抽、冰糖、八角、姜蒜。","梅干菜下锅用余油炒香，铺在肉上压紧，上汽后中火蒸九十分钟。","倒扣盘中，把蒸出的原汁回锅勾薄芡，淋在肉片上。"],"tip":"肉皮炸后泡冷水才起虎皮皱，蒸的时间宁长不短，筷子一夹就烂才对。"},{"name":"小炒肉","cat":"荤菜","region":"湘","time":20,"diff":"简单","main":[["五花肉","300g"],["尖椒","4个"]],"sea":["豆豉","生抽","蒜","姜","料酒","食用油","盐"],"steps":["五花肉切薄片，尖椒斜切圈，蒜切片，姜切细丝。","锅烧热不放油，下尖椒干煸到表面起白斑，盛出备用。","中小火下五花肉煸炒，煸到出油、边缘微焦卷起。","下蒜姜和豆豉炒香，淋料酒、生抽翻炒上色。","倒回尖椒大火快炒一分钟，加盐炒匀出锅。"],"tip":"尖椒先干煸出虎皮斑，最后回锅合炒，香辣味才够足不夹生。"},{"name":"糖醋排骨","cat":"荤菜","region":"淮扬","time":45,"diff":"中等","main":[["排骨","500g"]],"sea":["冰糖","醋","料酒","生抽","姜","葱","食用油"],"steps":["排骨剁段冷水下锅，加姜葱料酒焯三分钟，捞出冲净沥干。","中火下排骨煎到两面微黄，逼出多余油脂后盛出。","锅留底油下冰糖炒成糖色，倒排骨翻炒裹匀。","加生抽、料酒、醋和热水没过排骨，大火烧开转小火炖三十分钟。","大火收汁，边收边翻，汤汁浓稠裹住排骨、能拉丝时关火。"],"tip":"糖和醋分两次放，起锅前补半勺醋，酸甜味才立得住不闷。"},{"name":"红烧排骨","cat":"荤菜","region":"家常","time":60,"diff":"中等","main":[["排骨","600g"]],"sea":["冰糖","生抽","老抽","料酒","八角","桂皮","姜","葱"],"steps":["排骨冷水浸泡半小时去血水，再冷水下锅焯三分钟捞出洗净。","中小火下冰糖炒到琥珀色，倒排骨翻炒到每块都上色。","加姜葱、八角、桂皮、料酒、生抽、老抽炒出香味。","倒热水没过排骨，大火烧开转小火炖三十五分钟。","开大火收汁，汤汁浓稠发亮、能挂在排骨上即可关火。"],"tip":"焯水后用温水冲洗，冷水一激肉质收紧，炖一小时也不烂。"},{"name":"豆豉蒸排骨","cat":"荤菜","region":"粤","time":40,"diff":"简单","main":[["排骨","400g"]],"sea":["豆豉","蒜","淀粉","生抽","蚝油","白糖","姜","食用油"],"steps":["排骨剁小块，清水泡二十分钟去血水，捞出沥干擦干。","豆豉剁碎，蒜切末，与生抽、蚝油、白糖、姜末拌成腌料。","排骨加腌料和淀粉抓匀，最后淋一勺食用油封住水分。","腌三十分钟后平铺在浅盘中，水开上汽中火蒸十八分钟。","取出撒葱花，静置两分钟再上桌，肉汁更稳不流失。"],"tip":"淀粉和油最后放，锁住水分，蒸出来才滑嫩到轻轻一抿就脱骨。"},{"name":"土豆炖排骨","cat":"荤菜","region":"东北","time":55,"diff":"简单","main":[["排骨","500g"],["土豆","2个"]],"sea":["生抽","老抽","料酒","八角","姜","葱","盐","食用油"],"steps":["排骨冷水下锅焯三分钟，撇去浮沫捞出用温水冲净。","土豆去皮切滚刀块，泡清水防氧化，姜切片葱切段。","中火下排骨煎到微黄，加姜葱、八角炒香，淋料酒去腥。","加生抽、老抽和热水没过排骨，大火烧开转小火炖二十五分钟。","下土豆块继续炖十五分钟，筷子能轻松插入土豆即可。","加盐调味，大火收汁到汤汁浓稠挂勺关火。"],"tip":"土豆后放，炖十五分钟刚好粉糯不散，放早了容易糊成一锅汤。"},{"name":"红烧猪蹄","cat":"荤菜","region":"家常","time":100,"diff":"中等","main":[["猪蹄","2只"]],"sea":["冰糖","生抽","老抽","料酒","八角","桂皮","姜","葱"],"steps":["猪蹄剁块冷水下锅，加料酒和姜片焯五分钟，捞出刮净浮沫。","中小火下冰糖炒出糖色，倒猪蹄翻炒到每块都裹上红亮糖色。","加姜葱、八角、桂皮、料酒、生抽、老抽炒匀出香。","倒热水没过猪蹄两指，大火烧开转小火炖八十分钟至皮糯。","开大火收汁，汤汁黏稠发亮、能挂住猪蹄时关火。"],"tip":"水一次加足，中途添水会让皮发硬；炖到筷子能戳透猪皮最合适。"},{"name":"卤猪蹄","cat":"荤菜","region":"家常","time":120,"diff":"中等","main":[["猪蹄","2只"]],"sea":["八角","桂皮","香叶","花椒","生抽","老抽","冰糖","姜"],"steps":["猪蹄剁块用火烧净残毛，冷水下锅焯五分钟，捞出刷洗干净。","锅中放八角、桂皮、香叶、花椒、姜和冰糖，小火炒出香味。","加生抽、老抽和足量热水烧开，放入猪蹄再次煮沸。","转小火卤六十分钟，关火后让猪蹄在卤水里继续泡两小时。","捞出刷一层香油，斩块装盘，浇一勺烧热的卤汁。"],"tip":"关火后浸泡比久煮更入味，皮还不烂；卤水滤净可留作老卤。"},{"name":"花生炖猪蹄","cat":"荤菜","region":"家常","time":100,"diff":"简单","main":[["猪蹄","1只"],["花生米","100g"],["枸杞","1小把"]],"sea":["姜","葱","料酒","盐","白胡椒"],"steps":["花生米提前用温水泡两小时，猪蹄剁块焯水五分钟洗净。","砂锅放猪蹄、姜片、葱段和料酒，加足量热水大火烧开。","转小火炖四十分钟，中途撇净表面浮油。","下花生米继续炖四十分钟，猪蹄皮能用筷子轻松戳透。","加盐和白胡椒调味，撒枸杞再煮两分钟关火。"],"tip":"花生泡透再炖才粉糯；盐一定最后放，早了猪蹄不容易炖软。"},{"name":"爆炒猪肝","cat":"荤菜","region":"川","time":15,"diff":"简单","main":[["猪肝","300g"],["青椒","1个"]],"sea":["料酒","生抽","淀粉","蒜","姜","干辣椒","盐","食用油"],"steps":["猪肝切薄片，清水反复抓洗到水变清，捞出沥干。","加料酒、生抽、淀粉抓匀腌十分钟，青椒切片，蒜姜切末。","大火烧油至微微冒烟，下猪肝快速划散，变粉白立刻盛出。","锅留底油爆香蒜姜和干辣椒，下青椒大火炒一分钟。","倒回猪肝，加盐，沿锅边淋生抽，翻炒二十秒出锅。"],"tip":"全程大火，猪肝从下锅到出锅不超过一分钟，多炒十秒就粉面发柴。"},{"name":"溜肝尖","cat":"荤菜","region":"鲁","time":20,"diff":"中等","main":[["猪肝","300g"],["木耳","30g"],["竹笋","1根"]],"sea":["葱","姜","蒜","醋","生抽","料酒","淀粉","食用油"],"steps":["猪肝切片用清水抓到不黏手，加料酒、淀粉上浆腌十分钟。","木耳撕小朵，竹笋切片，葱姜蒜切末，分别备好。","小碗放生抽、醋、淀粉和两勺清水，调成芡汁。","大火烧油至五成热下肝片滑散，变色立即捞出控油。","锅留底油爆香葱姜蒜，下木耳和笋片炒一分钟，倒回肝片。","淋入芡汁大火翻匀，汁亮裹住肝片时马上出锅。"],"tip":"肝片滑油时间越短越嫩，芡汁调稀一点，挂匀就离火不糊锅。"},{"name":"卤猪肝","cat":"荤菜","region":"家常","time":45,"diff":"简单","main":[["猪肝","500g"]],"sea":["八角","桂皮","香叶","花椒","生抽","料酒","姜","葱"],"steps":["猪肝整块用清水泡一小时，中间换两次水，泡到颜色发白。","冷水下锅焯三分钟，捞出用温水洗净表面血沫。","锅中放八角、桂皮、香叶、花椒、姜葱、生抽和料酒，加水烧开。","下猪肝小火卤二十分钟，关火后再泡三十分钟入味。","捞出晾凉切厚片，淋一勺卤汁，配蒜泥醋碟上桌。"],"tip":"卤猪肝全程小火，水面微沸就够，大火煮会起蜂窝、口感发柴。"},{"name":"卤猪肚","cat":"荤菜","region":"家常","time":90,"diff":"中等","main":[["猪肚","1个"]],"sea":["八角","桂皮","花椒","生抽","料酒","姜","葱","盐"],"steps":["猪肚翻面用盐和醋反复搓洗三遍，冲净后刮掉内壁白膜。","冷水下锅焯五分钟，捞出再洗一遍，切成大块。","锅中放八角、桂皮、花椒、姜葱、生抽、料酒和盐，加水烧开。","下猪肚小火卤七十分钟，筷子能轻松穿透即熟。","关火泡一小时捞出切条，浇热卤汁，撒葱花。"],"tip":"盐和醋分两次搓洗，内壁白膜去净才不腥，卤好泡着更入味。"},{"name":"红烧猪肚","cat":"荤菜","region":"家常","time":70,"diff":"中等","main":[["猪肚","1个"],["青椒","1个"]],"sea":["生抽","老抽","冰糖","八角","姜","蒜","料酒","食用油"],"steps":["熟猪肚切条，冷水下锅加料酒焯两分钟，捞出沥干。","青椒切块，蒜拍碎，姜切片，八角和冰糖提前备好。","中小火下冰糖炒出糖色，倒猪肚条翻炒上色。","加姜蒜、八角、生抽、老抽炒香，倒热水没过猪肚。","大火烧开转小火炖三十分钟，下青椒再烧两分钟收汁。"],"tip":"用熟猪肚能省一半时间，炖到汤汁挂勺再下青椒，脆嫩不老。"},{"name":"酸菜炒猪肚","cat":"荤菜","region":"东北","time":20,"diff":"简单","main":[["猪肚","300g"],["酸菜","200g"],["尖椒","2个"]],"sea":["蒜","姜","料酒","生抽","白糖","食用油"],"steps":["熟猪肚切细条，酸菜切碎挤干水分，尖椒斜切圈。","锅中火干煸酸菜两分钟，炒干水汽后盛出。","补油下蒜姜爆香，倒猪肚条大火炒一分钟，淋料酒去腥。","加酸菜和尖椒同炒，放生抽、白糖提鲜。","大火炒到酸菜边缘微焦、酸香扑鼻，淋一勺明油出锅。"],"tip":"酸菜先干煸去水汽，酸香味才浓；猪肚用熟的，快炒才脆。"},{"name":"九转大肠","cat":"荤菜","region":"鲁","time":90,"diff":"较难","main":[["猪大肠","600g"],["香菜","1小把"]],"sea":["白糖","醋","生抽","老抽","料酒","桂皮","八角","姜"],"steps":["猪大肠用盐和醋反复搓洗，翻面撕净肥油，冲净后切段。","大肠冷水下锅，加姜和料酒焯五分钟，捞出切三厘米段。","中火烧油下大肠炸到表面起皱、颜色微黄，捞出控油。","锅留底油下白糖炒成糖色，倒大肠翻裹，加生抽、老抽。","加醋、料酒、八角、桂皮和热水，小火煨四十分钟至软。","大火收汁到浓稠发亮，撒香菜末，淋一勺热油出锅。"],"tip":"大肠要先煮后炸再煨，三次火候都到位，才有外焦里嫩的口感。"},{"name":"红烧肥肠","cat":"荤菜","region":"川","time":80,"diff":"中等","main":[["猪大肠","600g"],["白萝卜","半根"]],"sea":["豆瓣酱","干辣椒","花椒","八角","生抽","老抽","姜","蒜"],"steps":["猪大肠用盐和醋反复搓洗两遍，翻面去净油脂，切段。","冷水下锅加姜和料酒焯五分钟，捞出沥干。","中小火下豆瓣酱、干辣椒、花椒、八角炒出红油，倒肥肠翻匀。","加生抽、老抽和热水没过，大火烧开转小火炖五十分钟。","下白萝卜块再炖十五分钟，萝卜透明入味即可。","大火收汁，汤汁浓稠裹住肥肠时撒蒜末出锅。"],"tip":"肥肠炖到筷子一戳就透再收汁，萝卜后放，早了容易炖成泥。"},{"name":"干煸肥肠","cat":"荤菜","region":"川","time":40,"diff":"中等","main":[["猪大肠","500g"],["蒜苗","1把"]],"sea":["干辣椒","花椒","蒜","姜","生抽","料酒","盐","食用油"],"steps":["熟肥肠切段，冷水下锅加料酒焯三分钟，捞出彻底沥干。","锅中火烧油，下肥肠煸炒到表皮金黄起泡、油分析出。","盛出多余的油，下干辣椒、花椒、蒜姜小火炒出香味。","倒回肥肠，淋生抽大火翻炒一分钟，让酱色裹匀。","下蒜苗段炒到断生，加盐炒匀即可出锅。"],"tip":"肥肠一定沥干水下锅，先煸干水汽再上色，既不溅油也不腥。"},{"name":"爆炒腰花","cat":"荤菜","region":"川","time":20,"diff":"中等","main":[["猪腰","2个"],["木耳","30g"],["青椒","1个"]],"sea":["料酒","生抽","淀粉","蒜","姜","醋","盐","食用油"],"steps":["猪腰对半剖开，片净中间白色腰臊，切十字花刀再改小块。","腰花加料酒和淀粉抓匀，泡清水十分钟去血水后沥干。","木耳泡发撕小朵，青椒切片，蒜姜切末，醋和生抽兑成汁。","大火烧油至冒烟，下腰花快速翻炒十秒，卷成麦穗花。","下蒜姜、木耳、青椒炒一分钟，淋兑好的汁翻匀，加盐出锅。"],"tip":"腰臊必须片干净，火要旺，腰花一卷就出锅，多炒十秒就老。"},{"name":"麻油腰花","cat":"荤菜","region":"台","time":20,"diff":"简单","main":[["猪腰","2个"]],"sea":["香油","姜","料酒","盐","白胡椒"],"steps":["猪腰剖开片净腰臊，切薄片，用清水泡十分钟去血水。","腰片加料酒和盐抓匀腌五分钟，捞出沥干备用。","锅小火烧香油，下姜片慢煎到边缘卷起、香味浓郁。","转大火下腰片快炒三十秒，变白卷曲立刻关火。","沿锅边淋一圈料酒，撒白胡椒，拌匀装盘趁热吃。"],"tip":"香油必须小火慢煸姜片，火大姜会发苦；腰片大火快炒才脆嫩。"},{"name":"番茄炖牛腩","cat":"荤菜","region":"家常","time":90,"diff":"中等","main":[["牛腩","800g"],["西红柿","3个"]],"sea":["葱","姜","八角","料酒","生抽","盐","白糖","食用油"],"steps":["牛腩切3厘米见方的块，冷水下锅加姜片和料酒，大火煮沸后撇净浮沫，捞出用温水冲洗干净。","西红柿顶部划十字，用开水烫30秒撕去皮，两个切小块、一个切大块分开装。","锅中放油，中小火把西红柿小块炒到出红汁成酱，再倒牛腩块翻炒2分钟裹匀。","加生抽、白糖和八角，倒开水没过牛腩两指，大火烧开转小火盖盖炖60分钟。","下西红柿大块再炖15分钟，加盐调味，转大火收汁到汤汁略稠、能挂住勺子即可。"],"tip":"西红柿分两次下，先炒成酱打底出味，后放块状保留口感，汤色红亮不寡淡。"},{"name":"土豆炖牛肉","cat":"荤菜","region":"东北","time":100,"diff":"中等","main":[["牛腩","700g"],["土豆","2个"],["胡萝卜","1根"]],"sea":["葱","姜","八角","桂皮","生抽","老抽","料酒","盐"],"steps":["牛腩切3厘米块，冷水下锅加姜片和料酒，大火焯3分钟，撇净浮沫后捞出沥干。","土豆和胡萝卜去皮切滚刀块，土豆块泡在清水里防止氧化发黑。","热锅放少量油，中火下葱段、姜片、八角和桂皮炒香，倒牛腩煸炒到表面微焦。","烹入料酒，加生抽和老抽翻匀上色，倒开水没过牛肉，大火烧开转小火炖50分钟。","下土豆和胡萝卜，中火再炖20分钟，筷子能扎透土豆时加盐，大火收浓汤汁。"],"tip":"土豆后放、少翻动，块形完整不糊汤；泡过水的土豆炖出来口感更清爽。"},{"name":"白萝卜炖牛腩","cat":"荤菜","region":"家常","time":110,"diff":"简单","main":[["牛腩","800g"],["白萝卜","半根"],["香菜","1小把"]],"sea":["葱","姜","花椒","料酒","盐","白胡椒"],"steps":["牛腩切大块，冷水加姜片和料酒大火煮开，撇净血沫后捞出用温水洗净。","白萝卜去皮切滚刀块，姜切片，葱打成一个结，香菜切末备用。","砂锅里放牛腩、姜片、葱结和十几粒花椒，一次加足开水，大火烧开转小火炖70分钟。","放入白萝卜块，中小火再炖25分钟，炖到萝卜半透明、筷子一戳就透。","挑出葱结，加盐和白胡椒调味，撒上香菜末，连汤带肉盛出。"],"tip":"萝卜别早放，久炖易发苦发空；牛腩炖到筋膜透亮再下萝卜最合适。"},{"name":"清炖羊肉","cat":"荤菜","region":"西北","time":90,"diff":"简单","main":[["羊肉","1000g"]],"sea":["葱","姜","花椒","料酒","盐","白胡椒"],"steps":["羊肉切4厘米大块，冷水浸泡30分钟去血水，中途换两次水。","羊肉冷水下锅，加姜片和料酒，大火煮开撇净浮沫，煮3分钟捞出冲净。","砂锅放羊肉、姜片、葱段和花椒，一次加足开水，大火烧开转小火炖70分钟。","炖到汤色乳白、筷子能轻松插入羊肉，加盐和白胡椒再煮5分钟关火。"],"tip":"全程只添开水不添冷水，汤才乳白不腥；盐最后放，羊肉更容易炖烂。"},{"name":"萝卜炖羊肉","cat":"荤菜","region":"家常","time":95,"diff":"中等","main":[["羊肉","800g"],["白萝卜","1根"]],"sea":["葱","姜","干辣椒","花椒","料酒","生抽","盐"],"steps":["羊肉切3厘米块，冷水下锅加姜片和料酒，大火焯3分钟，撇沫后捞出沥干。","白萝卜去皮切滚刀块，姜切片，葱切段，干辣椒剪成两段。","热锅放油，中火下葱姜、花椒和干辣椒炒香，倒羊肉煸炒到边缘微焦出油。","烹料酒加生抽翻匀，倒开水没过羊肉，大火烧开转小火炖45分钟。","下白萝卜块，中小火再炖25分钟，萝卜变透明后加盐，大火收汁至汤汁微浓。"],"tip":"羊肉先干煸出油再炖，去膻又增香；萝卜切大块吸油，久炖不烂成泥。"},{"name":"红焖羊肉","cat":"荤菜","region":"家常","time":100,"diff":"中等","main":[["羊肉","900g"],["胡萝卜","1根"]],"sea":["葱","姜","蒜","干辣椒","八角","料酒","生抽","白糖"],"steps":["羊肉切4厘米块，冷水加姜片和料酒大火焯3分钟，撇净浮沫捞出。","胡萝卜切滚刀块，姜蒜切片，葱切段，干辣椒剪成小段备好。","热锅放油，中小火下葱姜蒜、干辣椒和八角炒香，倒羊肉煸炒到表面收缩微焦。","烹料酒，加生抽和白糖翻炒上色，倒开水没过羊肉，大火烧开转小火焖60分钟。","下胡萝卜块再焖20分钟，汤汁收到浓稠挂勺、羊肉一抿就烂时关火。"],"tip":"羊肉一定要煸到出油再添水，糖色炒到枣红立刻加水，再久就发苦。"},{"name":"手把羊肉","cat":"荤菜","region":"西北","time":80,"diff":"简单","main":[["羊肉","1200g"]],"sea":["葱","姜","花椒","盐"],"steps":["羊肉带骨剁成大块，冷水浸泡1小时去血水，捞出冲净沥干。","锅中放羊肉，加足量冷水没过肉面，只放葱段、姜片和一小把花椒。","大火烧开，撇净浮沫后转小火煮50分钟，水面保持微微冒泡、不翻滚。","煮到筷子能轻松扎透肉块，加盐再煮10分钟让咸味渗进去。","捞出装盘，趁热用手抓着吃，蘸一点锅里的原汤更鲜。"],"tip":"手把肉不放酱油不放大料，小火慢煮不翻滚，肉才嫩而不柴。"},{"name":"咖喱牛腩","cat":"荤菜","region":"粤","time":110,"diff":"中等","main":[["牛腩","700g"],["土豆","2个"],["洋葱","1个"]],"sea":["姜","料酒","咖喱块","椰浆","生抽","食用油"],"steps":["牛腩切3厘米块，冷水加姜片和料酒大火焯3分钟，撇沫后捞出温水冲净。","土豆去皮切滚刀块，洋葱切粗丝，咖喱块掰成小块备用。","热锅倒油，中火把洋葱丝炒到微黄出甜香，再倒牛腩块翻炒2分钟。","加生抽和开水没过牛腩，大火烧开转小火炖60分钟至肉质变软。","下土豆块煮15分钟，关小火放入咖喱块搅到完全化开，倒椰浆再煮5分钟至浓稠。"],"tip":"咖喱块要关小火再放，边放边搅防糊底；椰浆最后下，久煮会油水分离。"},{"name":"红烧牛肉","cat":"荤菜","region":"家常","time":120,"diff":"中等","main":[["牛肉","800g"]],"sea":["葱","姜","八角","桂皮","生抽","老抽","料酒","冰糖"],"steps":["牛肉切4厘米块，冷水下锅加姜片和料酒，大火煮开撇沫，煮3分钟捞出冲净。","热锅放少量油，中小火下冰糖炒到融化起泡、变成枣红色，立刻倒牛肉翻炒上色。","下葱段、姜片、八角和桂皮炒香，烹入料酒，加生抽和老抽翻匀。","倒开水没过牛肉两指，大火烧开转小火盖盖炖80分钟，中途翻动两次。","炖到筷子能插入肉块，开大火收汁，收到汤汁浓稠裹住牛肉时关火。"],"tip":"炒糖色全程中小火，起泡变枣红立刻下肉，晚十秒就会发苦。"},{"name":"麻婆豆腐","cat":"荤菜","region":"川","time":25,"diff":"中等","main":[["豆腐","400g"],["牛肉末","100g"],["蒜苗","2根"]],"sea":["豆瓣酱","豆豉","蒜","姜","花椒粉","生抽","淀粉","食用油"],"steps":["豆腐切2厘米方块，放清水里泡5分钟去豆腥，捞出沥干；蒜苗斜切小段。","热锅下油，中小火把牛肉末炒到干香出油、粒粒分明，盛出一半备用。","锅内留油，小火下豆瓣酱、豆豉、蒜末和姜末炒出红油，加生抽和一碗水烧开。","沿锅边轻轻推入豆腐块，中火煮3分钟，分两次淋淀粉水勾芡，让汁挂住豆腐。","倒回牛肉末，撒蒜苗段和花椒粉，中火推匀10秒立刻出锅。"],"tip":"豆腐下锅用锅铲背面推，别翻炒；芡分两次勾，汤汁才挂得住不澥。"},{"name":"干煸牛肉丝","cat":"荤菜","region":"川","time":30,"diff":"中等","main":[["牛里脊","300g"],["芹菜","150g"]],"sea":["姜","蒜","干辣椒","花椒","豆瓣酱","生抽","料酒","食用油"],"steps":["牛里脊逆纹切细丝，加料酒和生抽抓匀腌15分钟，芹菜切段，姜蒜切丝。","锅烧热放油，中火下牛肉丝摊平别动，煎到底面微焦再翻面煸散。","转小火，下干辣椒丝、花椒、姜丝蒜丝和豆瓣酱，煸出红油和香味。","倒入芹菜段，转大火快炒1分钟，炒到芹菜断生仍脆、牛肉丝干香。","沿锅边淋少许生抽，翻匀后立刻出锅。"],"tip":"牛肉丝下锅先别翻，煎出焦边再煸散，才有干香不柴的口感。"},{"name":"牙签牛肉","cat":"荤菜","region":"湘","time":35,"diff":"中等","main":[["牛里脊","400g"]],"sea":["姜","蒜","干辣椒","孜然","辣椒面","生抽","料酒","食用油"],"steps":["牛里脊逆纹切0.5厘米厚片，加生抽、料酒和姜末抓匀，腌20分钟。","用牙签把每片牛肉串起来，串好摊开晾5分钟，让表面不那么湿。","锅中倒油烧到六成热，下牛肉串中火炸2分钟，炸到边缘微焦捞出。","锅留底油，小火下蒜末、干辣椒段和孜然炒香，倒回牛肉串。","撒辣椒面，转大火颠锅15秒让调料裹匀，趁热装盘。"],"tip":"肉片别切太薄，复炸更酥：先中火炸熟，升油温再复炸20秒。"},{"name":"泡椒牛肉丝","cat":"荤菜","region":"川","time":25,"diff":"中等","main":[["牛里脊","300g"],["泡椒","8个"],["青椒","1个"]],"sea":["姜","蒜","花椒","生抽","料酒","淀粉","醋","食用油"],"steps":["牛里脊逆纹切细丝，加料酒、生抽和淀粉抓匀，表面封一层油腌15分钟。","泡椒切斜段，青椒切丝，姜蒜切末，另用生抽、醋和淀粉调一小碗汁。","锅烧热倒油至五成热，下牛肉丝快速划散，一变白立刻盛出。","锅内留油，中火下泡椒、姜蒜末和花椒炒出酸香，倒青椒丝炒30秒。","倒回牛肉丝，淋入碗汁，大火快炒20秒至汁收亮出锅。"],"tip":"泡椒要炒出酸香味再下肉；碗汁提前调好，下锅十几秒就得起锅。"},{"name":"黑椒牛柳","cat":"荤菜","region":"粤","time":20,"diff":"简单","main":[["牛里脊","350g"],["洋葱","半个"],["彩椒","1个"]],"sea":["蒜","黑胡椒","生抽","蚝油","料酒","淀粉","白糖","食用油"],"steps":["牛里脊逆纹切1厘米粗条，加生抽、料酒和淀粉抓匀，腌20分钟。","洋葱和彩椒切条，蒜切末，黑胡椒现磨成粗粒备用。","锅烧到微微冒烟再倒油，大火下牛柳摊开，煎20秒再翻，炒到七成熟盛出。","锅内留油，中火炒香蒜末和洋葱，下彩椒条炒1分钟至断生。","倒回牛柳，加蚝油、白糖和大量黑胡椒，大火颠炒20秒出锅。"],"tip":"牛柳全程大火，快炒不超过两分钟，七成熟盛出回锅刚好嫩。"},{"name":"小炒黄牛肉","cat":"荤菜","region":"湘","time":20,"diff":"中等","main":[["牛肉","300g"],["尖椒","6个"],["蒜苗","2根"]],"sea":["姜","蒜","干辣椒","生抽","料酒","淀粉","盐","食用油"],"steps":["牛肉逆纹切薄片，加生抽、料酒、淀粉和一点油抓匀，腌15分钟。","尖椒斜切成圈，蒜苗切段，姜蒜切末，干辣椒剪成小段。","锅烧到冒青烟，放油后大火下牛肉片，快速划散到变色立即盛出。","锅内补油，中火下姜蒜末、干辣椒和尖椒圈，炒到尖椒表皮起虎皮。","倒回牛肉片，加盐和蒜苗段，大火颠炒30秒，蒜苗断生就出锅。"],"tip":"湘菜小炒讲究锅气，锅要烧到冒烟再下油下肉，全程不超过三分钟。"},{"name":"孜然羊肉","cat":"荤菜","region":"新疆","time":20,"diff":"简单","main":[["羊肉","400g"],["洋葱","半个"]],"sea":["孜然","辣椒面","盐","生抽","料酒","淀粉","食用油","蒜"],"steps":["羊肉切薄片，加生抽、料酒和淀粉抓匀，腌15分钟去腥上浆。","洋葱切粗丝，蒜切末，孜然一半磨成粉、一半留颗粒。","锅烧热放油，大火下羊肉片摊平，煎到边缘焦黄再翻散。","下蒜末和洋葱丝，大火炒1分钟至洋葱微软出甜味。","撒孜然粒、孜然粉、辣椒面和盐，颠锅20秒炒匀立刻出锅。"],"tip":"孜然分两次用，粉腌肉入味、粒最后撒才香；羊肉变色即熟别久炒。"},{"name":"蚝油牛肉","cat":"荤菜","region":"粤","time":20,"diff":"简单","main":[["牛肉","300g"],["芥蓝","300g"]],"sea":["蒜","蚝油","生抽","料酒","淀粉","白糖","食用油","香油"],"steps":["牛肉逆纹切薄片，加生抽、料酒、淀粉和一勺水抓匀，腌20分钟。","芥蓝削去老皮切段，蒜切末；水烧开滴几滴油，下芥蓝焯1分钟捞出摆盘。","锅烧热放油，中火下牛肉片滑炒到七成熟，盛出备用。","锅内留油炒香蒜末，加蚝油、生抽、白糖和两勺水烧开。","倒回牛肉片，中火翻炒30秒让酱汁裹匀，淋香油后浇在芥蓝上。"],"tip":"上浆时加一勺水抓进去，牛肉才滑嫩；蚝油最后放，久煮会发苦。"},{"name":"青椒牛肉丝","cat":"荤菜","region":"家常","time":20,"diff":"简单","main":[["牛里脊","300g"],["青椒","2个"]],"sea":["姜","蒜","生抽","料酒","淀粉","盐","食用油"],"steps":["牛里脊逆纹切细丝，加生抽、料酒和淀粉抓匀，腌15分钟。","青椒去籽切丝，姜蒜切末；干锅不放油，先下青椒丝煸30秒盛出。","热锅倒油，大火下牛肉丝快速划散，炒到刚变色盛出。","锅内留油，中火下姜蒜末炒香，倒青椒丝大火炒30秒。","倒回牛肉丝，加盐和半勺生抽，大火炒10秒出锅。"],"tip":"青椒先干煸去掉生涩水汽，再和牛肉合炒，椒香浓又不出水。"},{"name":"苦瓜炒牛肉","cat":"荤菜","region":"粤","time":25,"diff":"中等","main":[["牛肉","300g"],["苦瓜","1根"]],"sea":["蒜","豆豉","生抽","料酒","淀粉","白糖","盐","食用油"],"steps":["牛肉逆纹切薄片，加生抽、料酒、淀粉和白糖抓匀，腌20分钟。","苦瓜剖开去瓤切薄片，撒盐抓2分钟，冲水后挤干去苦味。","水烧开下苦瓜焯30秒，捞出过凉水沥干。","热锅放油，大火下牛肉片炒到变色盛出；锅留油炒香蒜末和豆豉。","倒苦瓜大火炒1分钟，回牛肉片，加盐和生抽颠匀出锅。"],"tip":"苦瓜用盐抓过再焯水，苦味减半还保脆；豆豉是这道菜的灵魂，别省。"},{"name":"西兰花炒牛肉","cat":"荤菜","region":"家常","time":25,"diff":"简单","main":[["牛肉","300g"],["西兰花","1个"]],"sea":["蒜","蚝油","生抽","料酒","淀粉","盐","食用油"],"steps":["牛肉切薄片，加生抽、料酒和淀粉抓匀腌15分钟；西兰花掰成小朵。","水烧开加盐和几滴油，下西兰花焯1分钟，捞出过凉水沥干。","热锅放油，大火下牛肉片划散，炒到七成熟盛出。","锅内留油炒香蒜末，倒西兰花大火翻炒30秒，加蚝油和盐。","倒回牛肉片，大火合炒20秒，让蚝油汁裹匀出锅。"],"tip":"西兰花焯水加盐和油，颜色才翠绿；牛肉七成熟盛出，回锅不老。"},{"name":"水煮牛肉","cat":"荤菜","region":"川","time":40,"diff":"较难","main":[["牛肉","400g"],["豆芽","200g"],["莴笋","1根"]],"sea":["豆瓣酱","干辣椒","花椒","蒜","姜","淀粉","生抽","食用油"],"steps":["牛肉逆纹切大薄片，加生抽、淀粉和两勺水抓到发黏，腌20分钟。","豆芽掐根，莴笋切片；锅中少油大火炒到断生，加少许生抽铺在深碗底。","锅内放油，中小火下豆瓣酱、姜末蒜末炒出红油，加开水烧开成汤。","汤转小火，牛肉片一片片抖散下锅，煮到变色约40秒，连汤倒入碗中。","表面撒蒜末、干辣椒段和花椒；另起锅烧油到冒烟，泼在辣椒上激香。"],"tip":"牛肉片一片片下、别搅动，汤微沸不滚才嫩；热油必须冒烟再泼。"},{"name":"涮羊肉","cat":"荤菜","region":"家常","time":30,"diff":"简单","main":[["羊肉","500g"],["大白菜","半棵"],["粉丝","1把"]],"sea":["芝麻酱","豆腐乳","生抽","香油","葱","姜","蒜"],"steps":["羊肉冷冻20分钟后切薄片，越薄越好；大白菜切段，粉丝温水泡软。","芝麻酱用温水少量多次澥开，加豆腐乳、生抽和香油调成蘸料，撒葱花蒜末。","锅中放清水、葱段和姜片烧开，先下大白菜和粉丝煮2分钟垫底。","转中火保持汤微沸，羊肉片用筷子夹住在锅里涮10到15秒，变色立刻捞出蘸食。","最后撇去汤面浮沫，连白菜粉丝一起盛出当汤喝。"],"tip":"羊肉半冻状态最好切薄；涮的时间以变色为准，超过二十秒就柴。"},{"name":"烤羊肉串","cat":"荤菜","region":"新疆","time":45,"diff":"中等","main":[["羊肉","600g"],["洋葱","1个"]],"sea":["孜然","辣椒面","盐","生抽","料酒","食用油"],"steps":["羊肉切2厘米见方的块，加盐、生抽、料酒和洋葱丝抓匀，腌30分钟。","竹签提前泡水20分钟，把羊肉肥瘦相间串成串，每串四五块。","烤箱预热220度，烤盘铺锡纸，羊肉串刷一层油后摆好。","中层烤10分钟，取出翻面刷油，撒孜然和辣椒面，再烤8分钟。","烤到表面焦褐、油脂滋滋冒出，出炉趁热再撒一层孜然和盐。"],"tip":"肥瘦相间串才香，中间夹一块肥肉；孜然分两次撒，出炉那次最提味。"},{"name":"烤羊排","cat":"荤菜","region":"新疆","time":90,"diff":"中等","main":[["羊排","1000g"],["洋葱","1个"]],"sea":["孜然","黑胡椒","盐","生抽","料酒","蜂蜜","食用油"],"steps":["羊排洗净擦干，用刀背在肉面轻拍几下断筋，方便腌料渗入。","洋葱切碎，加盐、生抽、料酒、黑胡椒和孜然抓匀，抹遍羊排腌1小时。","烤箱预热200度，羊排放在烤架上，下层放烤盘接油，表面刷一层油。","烤25分钟后取出翻面，刷一层蜂蜜水，再烤15分钟至表面焦红。","取出静置5分钟再切条，撒孜然和盐，配洋葱丝上桌。"],"tip":"羊排先擦干再腌，表皮才烤得脆；出炉静置五分钟，肉汁不流失。"},{"name":"牛肉炖粉条","cat":"荤菜","region":"东北","time":80,"diff":"简单","main":[["牛肉","600g"],["粉条","1把"],["大白菜","半棵"]],"sea":["葱","姜","八角","生抽","老抽","料酒","盐"],"steps":["牛肉切3厘米块，冷水下锅加姜片和料酒大火焯3分钟，撇沫捞出冲净。","粉条用温水泡30分钟至软，大白菜切大片，葱切段。","热锅少油，中火下葱段、姜片和八角炒香，倒牛肉煸炒2分钟。","加生抽、老抽和开水没过牛肉，大火烧开转小火炖50分钟。","下大白菜煮5分钟，再放粉条煮8分钟，粉条透明吸饱汤汁后加盐出锅。"],"tip":"粉条最后放且别久煮，泡软后煮八分钟刚好；汤多留些，粉条会吸。"},{"name":"烤羊腿","cat":"荤菜","region":"新疆","time":180,"diff":"较难","main":[["羊腿","1只"]],"sea":["孜然","辣椒面","盐","黑胡椒","生抽","料酒","蒜","食用油"],"steps":["羊腿洗净擦干，用尖刀在肉厚处戳若干小孔，深到骨头方便入味。","蒜切末，加盐、生抽、料酒、黑胡椒和孜然调成腌料，抹匀后按摩10分钟。","装入保鲜袋冷藏腌2小时，中途翻面一次让味道均匀。","烤箱预热200度，羊腿放烤架刷油，下面垫烤盘接油，烤40分钟。","取出翻面撒孜然和辣椒面，再烤30分钟至表皮焦脆、油脂析出。","筷子扎最厚处无血水冒出即熟，取出静置10分钟再切片。"],"tip":"肉厚处一定戳孔腌透；中途刷两次油，表皮才焦脆不发干。"},{"name":"可乐鸡翅","cat":"荤菜","region":"家常","time":35,"diff":"简单","main":[["鸡翅中","500g"],["可乐","1罐"]],"sea":["姜","葱","料酒","生抽","老抽","盐","食用油"],"steps":["鸡翅中洗净，两面各划两刀，冷水下锅加姜片和料酒，大火煮开撇净浮沫后捞出沥干。","锅里放少量食用油，中火烧热后下鸡翅，煎到两面微黄、表皮收紧，约3分钟。","倒入可乐没过鸡翅，加生抽、老抽和盐，大火烧开后转中小火焖15分钟。","开大火收汁，边收边翻动鸡翅，汤汁收浓挂勺、表面油亮时关火，撒葱花。"],"tip":"可乐要一次倒足，收汁时勤翻动，糖分高容易糊底。"},{"name":"红烧鸡翅","cat":"荤菜","region":"家常","time":30,"diff":"简单","main":[["鸡翅中","500g"]],"sea":["姜","八角","料酒","生抽","老抽","冰糖","盐","食用油"],"steps":["鸡翅中洗净沥干，在肉厚处划一刀，冷水下锅焯3分钟，捞出用温水冲净血沫。","锅中倒食用油，中小火放冰糖炒到融化变枣红，下鸡翅翻炒，让每只都裹上糖色。","加姜片、八角炒香，淋料酒、生抽、老抽，倒热水没过鸡翅，大火烧开。","转中小火焖18分钟，加盐调味，再转大火把汤汁收稠，能挂在鸡翅上即可。"],"tip":"糖液冒细密小泡、颜色变枣红就下鸡翅，炒过头会发苦。"},{"name":"蜜汁烤鸡翅","cat":"荤菜","region":"家常","time":45,"diff":"简单","main":[["鸡翅中","500g"],["蜂蜜","2勺"]],"sea":["蒜","生抽","蚝油","料酒","黑胡椒","盐"],"steps":["鸡翅中洗净擦干，两面各划两刀，加蒜末、生抽、蚝油、料酒、盐和黑胡椒抓匀。","盖上保鲜膜放冰箱冷藏腌2小时以上，中途翻一次面，让酱汁均匀渗入。","烤箱预热到200度，鸡翅排在铺了锡纸的烤盘上，中层烤15分钟。","取出刷一层蜂蜜，翻面再刷一遍，回炉烤8分钟，表面焦红冒油即可。"],"tip":"蜂蜜最后十分钟再刷，早刷容易烤黑，鸡翅擦干才挂得住酱。"},{"name":"红烧鸡翅根","cat":"荤菜","region":"家常","time":40,"diff":"简单","main":[["鸡翅根","600g"]],"sea":["姜","八角","料酒","生抽","老抽","冰糖","盐","食用油"],"steps":["鸡翅根洗净，在肉厚处划两刀，冷水下锅加料酒焯5分钟，捞出冲净浮沫。","锅中下食用油，中小火炒冰糖到枣红，倒入翅根翻炒，让每根都裹上糖色。","放姜片和八角炒香，加生抽、老抽和热水没过翅根，大火烧开转中小火炖25分钟。","加盐，转大火收汁，汤汁浓稠裹住翅根、筷子能轻松扎透肉厚处即可出锅。"],"tip":"翅根肉厚，划刀能让血水出净、入味更快，炖的时间也要比翅中长。"},{"name":"土豆炖鸡块","cat":"荤菜","region":"家常","time":55,"diff":"简单","main":[["鸡腿","600g"],["土豆","2个"]],"sea":["姜","葱","八角","生抽","老抽","料酒","盐","食用油"],"steps":["鸡腿剁成块，冷水下锅加料酒焯5分钟，捞出冲净；土豆去皮切滚刀块泡在清水里。","锅中放食用油，中火下姜片和八角炒香，倒入鸡块翻炒到表面微黄。","加生抽、老抽炒上色，倒热水没过鸡块，大火烧开转中小火炖20分钟。","下土豆块再炖15分钟，加盐，转大火收汁到土豆边缘发沙、汤汁浓稠即可。"],"tip":"土豆要后放，炖15分钟正好粉而不烂，早放就化在汤里成糊了。"},{"name":"咖喱鸡块","cat":"荤菜","region":"家常","time":45,"diff":"简单","main":[["鸡腿","500g"],["土豆","1个"],["胡萝卜","1根"],["洋葱","半个"],["咖喱块","2块"]],"sea":["姜","料酒","盐","食用油"],"steps":["鸡腿去骨切块，加料酒和姜片腌10分钟；土豆、胡萝卜切滚刀块，洋葱切块。","锅中放食用油，中火炒洋葱到透明出甜味，下鸡块煎到表面变白。","加土豆和胡萝卜翻炒2分钟，倒热水没过食材，大火烧开转中小火煮15分钟。","关火放入咖喱块，搅到完全化开，再开小火煮5分钟，汤汁变浓稠能挂勺即可。"],"tip":"咖喱块要关火后放，边搅边化，直接大火煮容易结块糊底。"},{"name":"宫保鸡丁","cat":"荤菜","region":"川","time":25,"diff":"中等","main":[["鸡胸肉","300g"],["花生米","80g"],["黄瓜","半根"]],"sea":["干辣椒","花椒","葱","生抽","醋","白糖","淀粉","食用油"],"steps":["鸡胸肉切1.5厘米见方的丁，加生抽和淀粉抓匀腌15分钟；黄瓜切丁，葱切段。","碗里放生抽、醋、白糖、淀粉和两勺清水，调成碗汁备用。","锅中放食用油，中小火下花生米炸到微黄酥脆，捞出摊在盘里放凉。","大火下鸡丁滑炒到变白散开，加干辣椒、花椒和葱段炒香，倒黄瓜丁翻两下。","淋入碗汁，大火翻炒到汁水裹住鸡丁，关火拌入花生米即可。"],"tip":"花生米最后放，早放回软；碗汁提前调好，下锅后全程大火十秒收汁。"},{"name":"酱爆鸡丁","cat":"荤菜","region":"鲁","time":25,"diff":"中等","main":[["鸡胸肉","300g"],["黄瓜","1根"]],"sea":["甜面酱","黄豆酱","葱","姜","料酒","白糖","淀粉","食用油"],"steps":["鸡胸肉切1.5厘米丁，加料酒和淀粉抓匀腌15分钟；黄瓜切丁，葱切段。","甜面酱加黄豆酱、白糖和两勺清水调开，避免下锅后糊成团。","锅中放食用油，中火烧到五成热，下鸡丁滑散炒到变白，盛出控油。","锅留底油，小火下葱姜炒香，倒入调好的酱料，炒到冒小泡、颜色发亮。","倒回鸡丁和黄瓜丁，大火翻炒20秒，让酱汁均匀裹住鸡丁即可出锅。"],"tip":"酱要小火炒出香味再下鸡丁，火大容易发苦，糖能压住酱的咸。"},{"name":"凉拌鸡丝","cat":"凉菜","region":"家常","time":30,"diff":"简单","main":[["鸡胸肉","300g"],["黄瓜","1根"]],"sea":["姜","葱","蒜","生抽","香醋","辣椒油","白糖","香油"],"steps":["鸡胸肉冷水下锅，加姜片和葱段，大火烧开转中小火煮12分钟，关火焖5分钟。","捞出放凉，顺着纹理撕成细丝；黄瓜切细丝铺在盘底。","碗里放蒜末、生抽、香醋、白糖、辣椒油和香油，搅到糖化开。","鸡丝铺在黄瓜丝上，淋上料汁，撒葱花，吃前拌开即可。"],"tip":"鸡胸煮好焖5分钟再捞，肉才不柴；顺纹理撕丝更嫩更挂汁。"},{"name":"芙蓉鸡片","cat":"荤菜","region":"鲁","time":30,"diff":"较难","main":[["鸡胸肉","250g"],["鸡蛋","3个"]],"sea":["姜","葱","料酒","盐","淀粉","白胡椒","食用油"],"steps":["鸡胸肉剁成细泥，加料酒、盐、白胡椒和两个蛋清，顺一个方向搅到起胶。","加淀粉和两勺清水再搅匀，调成能缓慢流动的鸡糊，静置10分钟。","锅中倒食用油烧到四成热，用勺子把鸡糊舀成片下锅，小火滑到浮起变白捞出。","锅留底油，下葱姜炒香，加一勺清水、盐和淀粉勾薄芡，倒入鸡片轻推翻匀。"],"tip":"油温四成、全程小火，鸡片才白嫩；鸡糊要搅上劲下锅才不散。"},{"name":"手撕鸡","cat":"凉菜","region":"川","time":50,"diff":"中等","main":[["整鸡","半只"],["香菜","1把"]],"sea":["姜","葱","蒜","辣椒油","生抽","香醋","白糖","香油"],"steps":["半只鸡冷水下锅，加姜片和葱段，大火烧开转中小火煮20分钟，关火焖10分钟。","捞出泡进冰水10分钟，沥干后戴手套把鸡肉顺纹理撕成粗条，鸡皮切条。","碗里放蒜末、生抽、香醋、白糖、辣椒油和香油，搅匀成料汁。","鸡丝加香菜段，淋料汁抓拌均匀，静置5分钟入味后装盘。"],"tip":"手撕比刀切更挂汁，鸡皮一起拌才香；料汁最后淋，早了会出水。"},{"name":"香菇炖鸡","cat":"汤羹","region":"家常","time":95,"diff":"简单","main":[["整鸡","半只"],["干香菇","10朵"],["红枣","6颗"]],"sea":["姜","葱","料酒","盐","白胡椒"],"steps":["干香菇用温水泡发30分钟，泡菇水滤去沉渣留用；红枣冲洗干净。","半只鸡剁块，冷水下锅加料酒和姜片，大火煮开撇净浮沫后捞出冲净。","鸡块、香菇、红枣和姜片放进砂锅，倒泡菇水和清水，总量没过食材两指。","大火烧开后转小火炖70分钟，汤面保持微微冒泡，出锅前加盐和白胡椒。"],"tip":"小火慢炖汤才清亮，盐一定要最后放，早放鸡肉容易发柴。"},{"name":"小鸡炖蘑菇","cat":"荤菜","region":"东北","time":70,"diff":"中等","main":[["整鸡","半只"],["干香菇","10朵"],["粉条","1把"]],"sea":["姜","葱","八角","生抽","老抽","料酒","盐","食用油"],"steps":["干香菇温水泡发30分钟，泡菇水留用；粉条用冷水泡软；半只鸡剁成块。","鸡块冷水下锅加料酒焯5分钟，撇净浮沫后捞出，用温水冲洗一遍。","锅中放食用油，中火下姜片、葱段和八角炒香，倒入鸡块翻炒到表面微黄。","加生抽、老抽炒上色，倒泡菇水和热水没过鸡块，大火烧开转中小火炖30分钟。","下香菇炖15分钟，再放粉条煮8分钟，加盐，汤汁收浓即可。"],"tip":"粉条最后放，煮8分钟刚好透亮不烂；泡菇水是这道菜的鲜味底。"},{"name":"酱鸭","cat":"荤菜","region":"本帮","time":90,"diff":"中等","main":[["鸭肉","半只(约800g)"]],"sea":["姜","葱","八角","桂皮","生抽","老抽","冰糖","料酒"],"steps":["鸭肉洗净擦干，冷水下锅加姜片和料酒焯8分钟，捞出冲净血沫。","锅烧热，鸭皮朝下中火煎5分钟，煎出鸭油、表皮金黄。","加姜片、葱段、八角和桂皮炒香，淋料酒、生抽、老抽，放冰糖。","倒热水没过鸭肉，大火烧开转小火焖60分钟，中途翻面两次。","转大火收汁，边收边把汤汁淋在鸭身上，汁浓发亮后取出晾凉斩件。"],"tip":"鸭皮先煎出油再酱，香味更足；收汁时不断淋汁，颜色才红亮。"},{"name":"泡椒鸡爪","cat":"凉菜","region":"川","time":50,"diff":"简单","main":[["鸡爪","500g"]],"sea":["泡椒","姜","花椒","白醋","盐","白糖","料酒","干辣椒"],"steps":["鸡爪剪去指甲，从中间剖开，冷水下锅加姜片、花椒和料酒，大火煮10分钟。","捞出鸡爪用流动冷水冲5分钟，洗掉表面胶质，再泡冰水10分钟。","锅里放清水，加泡椒、白醋、盐、白糖和干辣椒，大火煮开转小火5分钟，彻底放凉。","鸡爪放进凉透的泡椒水里，冷藏浸泡4小时以上，入味后捞出食用。"],"tip":"鸡爪煮10分钟就够，煮久了皮烂不脆；泡汁必须凉透再放鸡爪。"},{"name":"虎皮鸡爪","cat":"荤菜","region":"粤","time":70,"diff":"较难","main":[["鸡爪","600g"]],"sea":["姜","蒜","干辣椒","八角","生抽","老抽","冰糖","食用油"],"steps":["鸡爪剪去指甲，冷水下锅加姜片煮8分钟，捞出后用厨房纸彻底擦干水分。","锅中倒食用油烧到七成热，下鸡爪盖盖炸5分钟，炸到表皮起皱起泡后捞出。","炸好的鸡爪立刻放进冷水泡30分钟，泡到皮起虎皮纹、体积涨大。","锅留底油，下姜蒜、干辣椒和八角炒香，加生抽、老抽、冰糖和热水。","放入鸡爪，大火烧开转中小火焖40分钟，收汁到汤汁浓稠裹住鸡爪。"],"tip":"鸡爪必须擦干再炸，否则油会爆；炸完立刻泡冷水才起虎皮。"},{"name":"啤酒鸭","cat":"荤菜","region":"湘","time":70,"diff":"中等","main":[["鸭肉","800g"],["啤酒","1罐"]],"sea":["姜","蒜","干辣椒","八角","生抽","老抽","冰糖","料酒"],"steps":["鸭肉剁成块，冷水下锅加姜片和料酒焯8分钟，撇净浮沫后捞出沥干。","锅中不放油，中火把鸭块皮朝下煎8分钟，煎出鸭油、表面金黄。","加姜片、蒜、干辣椒和八角炒香，放冰糖、生抽、老抽翻炒上色。","倒入整罐啤酒，大火烧开转中小火焖40分钟，中途翻动两次。","开大火收汁，汤汁浓稠发亮、鸭肉能用筷子扎透时出锅。"],"tip":"鸭块先干煸出油，腥味跟着油走；啤酒一次倒够，中途别加水。"},{"name":"老鸭汤","cat":"汤羹","region":"淮扬","time":130,"diff":"简单","main":[["鸭肉","800g"],["红枣","6颗"],["枸杞","10g"]],"sea":["姜","葱","料酒","盐","白胡椒"],"steps":["鸭肉剁大块，冷水下锅加姜片和料酒，大火煮开撇净浮沫，捞出用温水冲净。","鸭块放进砂锅，加足量清水和姜片、葱段，水面高出鸭肉约三指。","大火烧开后转最小火，保持汤面似开非开，炖100分钟。","放红枣再炖20分钟，出锅前5分钟下枸杞，最后加盐和白胡椒调味。"],"tip":"水一次加足，中途加水汤会腥；小火慢炖汤才清而不浑。"},{"name":"姜母鸭","cat":"荤菜","region":"闽","time":100,"diff":"中等","main":[["鸭肉","800g"]],"sea":["姜","香油","料酒","生抽","冰糖","盐"],"steps":["鸭肉剁块，冷水下锅焯8分钟，撇净浮沫捞出沥干；姜切厚片，用量约150克。","锅中倒香油，小火把姜片煎到边缘卷曲发干，煎出姜香，约8分钟。","倒入鸭块，中火翻炒到鸭皮出油、表面金黄，淋料酒炒到酒气散尽。","加生抽、冰糖和少量热水，大火烧开转小火焖50分钟，中途翻动两次。","开大火收汁，汤汁浓稠、姜香浓郁时加盐调味，连姜片一起出锅。"],"tip":"姜要煎到卷边发干才出味，香油别省，这道菜靠姜和麻油压鸭腥。"},{"name":"烤鸭腿","cat":"荤菜","region":"家常","time":50,"diff":"简单","main":[["鸭腿","2只"]],"sea":["蒜","生抽","蚝油","料酒","蜂蜜","黑胡椒","盐","五香粉"],"steps":["鸭腿洗净擦干，用叉子在皮上扎十几个小孔，方便出油和入味。","加蒜末、生抽、蚝油、料酒、盐、黑胡椒和五香粉抓匀，冷藏腌3小时。","烤箱预热到200度，鸭腿放在烤架上，下层垫烤盘接油，烤25分钟。","取出刷一层蜂蜜，翻面再烤15分钟，表皮焦亮、筷子扎腿根无血水即可。"],"tip":"鸭皮扎孔才出油不腻，蜂蜜最后刷，用烤架比烤盘更脆。"},{"name":"红烧鲈鱼","cat":"荤菜","region":"家常","time":30,"diff":"中等","main":[["鲈鱼","1条约600g"]],"sea":["葱","姜","蒜","料酒","生抽","老抽","白糖","食用油"],"steps":["鲈鱼处理干净，鱼身两面各划三刀，用厨房纸把表面和腹腔的水分彻底吸干。","锅烧到微微冒烟再放油，转中火下鱼，一面煎三分钟到金黄定型再翻面。","下葱姜蒜爆香，烹入料酒，加生抽、老抽、白糖和一碗热水，大火烧开。","转中小火炖十分钟，中途舀汤汁反复浇在鱼身上，最后大火收汁到浓稠挂勺。"],"tip":"煎鱼前把锅烧透再下油，鱼皮才不粘；全程只翻一次面，用晃锅代替铲子推鱼。"},{"name":"水煮鱼","cat":"荤菜","region":"川","time":45,"diff":"较难","main":[["草鱼","1条约1000g"],["豆芽","200g"]],"sea":["干辣椒","花椒","豆瓣酱","姜","蒜","料酒","淀粉","食用油"],"steps":["草鱼去骨片成薄片，鱼头鱼骨剁块，鱼片加料酒和淀粉抓到发黏，腌十五分钟。","豆芽下开水焯一分钟断生，捞出沥干，平铺在大盆底部。","锅中放油炒香豆瓣酱和姜蒜末，下鱼骨煎炒两分钟，冲入开水大火煮五分钟。","转中火把鱼片一片片铺进汤里，煮到变白卷曲，约一分半钟，连汤倒入盆中。","另起锅烧热油，下干辣椒段和花椒炸到变色，连油一起泼在鱼片上激香。"],"tip":"鱼片下锅后别用力搅，用筷子轻推散开，一变色就起锅，煮过头肉就散成渣。"},{"name":"红烧鲫鱼","cat":"荤菜","region":"家常","time":30,"diff":"中等","main":[["鲫鱼","2条约500g"]],"sea":["葱","姜","蒜","生抽","老抽","料酒","白糖","食用油"],"steps":["鲫鱼去鳞去内脏，刮净腹内黑膜，两面各划两刀，用料酒抹匀腌十分钟。","锅烧热用姜片擦一遍再放油，中火把鱼煎到两面金黄定型，不要急着翻动。","下葱姜蒜炒香，烹入料酒，加生抽、老抽、白糖和热水，没过鱼身一半。","大火烧开转中小火炖十二分钟，最后开大火收汁，汤浓到能挂勺即可。"],"tip":"鲫鱼细刺多，两面多划几刀更易入味；收汁时晃锅别用铲翻，鱼身才完整。"},{"name":"红烧带鱼","cat":"荤菜","region":"家常","time":30,"diff":"简单","main":[["带鱼","500g"]],"sea":["葱","姜","蒜","生抽","老抽","料酒","淀粉","食用油"],"steps":["带鱼剪去头尾和内脏，切六厘米长段，用料酒腌十分钟，擦干后薄薄拍一层淀粉。","锅烧热放油，中火下带鱼段，一面煎三分钟到定型金黄再翻面煎另一面。","下葱姜蒜炒香，烹入料酒，加生抽、老抽和半碗热水，汤汁刚没过鱼段一半。","大火烧开转中小火焖八分钟，最后开大火收汁，汁浓裹住鱼段就出锅。"],"tip":"带鱼表面的银膜别刮太狠，那层脂香是鲜味来源；拍层薄淀粉煎起来不粘锅。"},{"name":"干煎带鱼","cat":"荤菜","region":"家常","time":25,"diff":"简单","main":[["带鱼","500g"]],"sea":["葱","姜","盐","料酒","白胡椒","淀粉","花椒粉","食用油"],"steps":["带鱼去头尾内脏，切八厘米长段，用盐、料酒、白胡椒和姜片腌二十分钟。","倒掉腌出的汁水，用厨房纸把每段彻底吸干，两面薄薄拍一层淀粉。","平底锅烧热放油，中小火下带鱼段，一面煎四分钟到金黄酥脆再翻面。","两面煎好后撒花椒粉和葱花，出锅前开大火十秒逼出多余油分。"],"tip":"带鱼必须吸干水分再下锅，油温七成热下、中小火慢煎，皮才酥而不破。"},{"name":"红烧黄鱼","cat":"荤菜","region":"家常","time":30,"diff":"中等","main":[["黄鱼","1条约500g"]],"sea":["葱","姜","蒜","生抽","老抽","料酒","淀粉","食用油"],"steps":["黄鱼去鳞去内脏洗净，两面斜划三刀，用料酒腌十分钟，擦干后拍薄淀粉。","锅烧热放油，中火下黄鱼煎到两面金黄，煎时轻晃锅防止粘底。","下葱姜蒜爆香，烹入料酒，加生抽、老抽和小半碗热水，大火烧开。","转中小火炖十分钟，中途舀汤浇淋鱼身，最后大火收汁到汤汁浓亮。"],"tip":"黄鱼肉嫩容易散，炖的过程别翻面，用勺舀汤汁反复浇淋就够入味。"},{"name":"干炸小黄鱼","cat":"荤菜","region":"鲁","time":30,"diff":"中等","main":[["黄鱼","6条约500g"]],"sea":["葱","姜","盐","料酒","白胡椒","淀粉","花椒粉","食用油"],"steps":["小黄鱼去头去内脏洗净，用盐、料酒、白胡椒和姜葱腌二十分钟入味。","倒掉腌出的水，把鱼身擦干，均匀拍一层干淀粉，抖掉多余的粉。","锅中倒油烧到六成热，逐条下鱼，中小火炸三分钟到外壳定型捞出。","油温升到八成热，回锅复炸四十秒到金黄酥脆，捞出撒花椒粉。"],"tip":"复炸是酥脆的关键，第一次只炸熟，晾两分钟再高温炸一次才响脆不回软。"},{"name":"蒜蓉粉丝蒸虾","cat":"荤菜","region":"粤","time":25,"diff":"简单","main":[["虾","400g"],["粉丝","1把"]],"sea":["蒜","葱","蒸鱼豉油","料酒","盐","食用油"],"steps":["粉丝用温水泡十分钟到变软，剪成短段，平铺在盘底。","虾剪须开背去虾线，从背部片开但不要剪断，摊平摆在粉丝上。","蒜剁成末，一半用小火温油炸到微黄，与另一半生蒜末加盐拌匀。","蒜蓉铺在虾身上，淋一勺料酒，水开后上锅大火蒸六分钟。","取出淋蒸鱼豉油，撒葱花，浇一勺烧到冒烟的热油激香。"],"tip":"蒜一半炸香一半生用，味道才立体不苦；蒸六分钟正好，久了虾肉发硬。"},{"name":"虾仁滑蛋","cat":"荤菜","region":"粤","time":15,"diff":"简单","main":[["虾仁","200g"],["鸡蛋","4个"]],"sea":["葱","盐","料酒","白胡椒","淀粉","食用油"],"steps":["虾仁挑去虾线，用盐、料酒、白胡椒和半勺淀粉抓匀，腌十分钟。","鸡蛋打散，加少许盐和一勺清水搅匀，蛋液会更嫩。","锅烧热放油，中火下虾仁滑炒到变粉红卷起，约一分钟盛出。","锅中补油转中小火倒入蛋液，底部微凝就用铲子从边缘往中间推。","蛋液还有三成流动时倒回虾仁，快速拌匀撒葱花，立刻关火出锅。"],"tip":"蛋液七分熟就关火，余温会继续凝固；全程中小火，火一大蛋就老了。"},{"name":"凉拌虾仁","cat":"凉菜","region":"鲁","time":20,"diff":"简单","main":[["虾仁","300g"],["黄瓜","1根"]],"sea":["蒜","姜","尖椒","生抽","香醋","白糖","香油","盐"],"steps":["虾仁挑净虾线，锅中水开加姜片，下虾仁煮一分半钟到变红卷曲。","捞出立刻放进冰水里泡三分钟，虾肉更弹，沥干水分备用。","黄瓜拍裂切段，撒少许盐腌五分钟，倒掉渗出的水。","蒜末、尖椒圈加生抽、香醋、白糖和香油调成料汁。","虾仁和黄瓜放大碗，淋上料汁拌匀，冷藏十分钟更入味。"],"tip":"虾仁煮好过冰水是关键，热虾直接拌会出水，把料汁的味道全稀释掉。"},{"name":"虾仁炒饭","cat":"主食","region":"家常","time":20,"diff":"简单","main":[["米饭","2碗"],["虾仁","150g"],["鸡蛋","2个"]],"sea":["葱","盐","生抽","料酒","白胡椒","食用油"],"steps":["米饭提前用手抓散，用隔夜冷藏的最好，粒粒分开不结块。","虾仁用盐、料酒和白胡椒腌五分钟，鸡蛋打散备用。","热锅放油，中火炒蛋液到半凝固就盛出，补油下虾仁炒到变红。","转大火下米饭，用铲子压散翻炒两分钟，炒到米粒跳动、锅底滋滋响。","倒回鸡蛋，加盐和几滴生抽，撒葱花大火炒三十秒出锅。"],"tip":"炒饭要用大火和干爽的隔夜饭，米饭下锅前先抓散，才不会粘成一团。"},{"name":"麻辣小龙虾","cat":"荤菜","region":"川","time":45,"diff":"中等","main":[["小龙虾","1000g"]],"sea":["干辣椒","花椒","豆瓣酱","姜","蒜","料酒","盐","食用油"],"steps":["小龙虾用刷子刷净腹部和虾壳，剪去虾头前端，抽出虾线，冲洗到水清。","锅中多放油烧到七成热，下小龙虾大火炸两分钟到通体变红，捞出控油。","另起锅放油，中小火炒香干辣椒段、花椒、姜蒜末和豆瓣酱，炒出红油。","倒入小龙虾翻炒裹上料，烹料酒，加热水没过一半，大火烧开。","转中火焖十五分钟，加盐调味，最后开大火收汁到汤汁挂壳。"],"tip":"小龙虾先高温油炸定型，壳肉分离更好剥，还能带走泥腥味。"},{"name":"蒜香小龙虾","cat":"荤菜","region":"家常","time":45,"diff":"中等","main":[["小龙虾","1000g"]],"sea":["蒜","姜","葱","料酒","盐","白糖","食用油"],"steps":["小龙虾刷洗干净，剪头去虾线，用料酒和盐腌十分钟。","大蒜两头剁成粗粒，一半冷油下锅小火炸到金黄，捞出备用。","锅中留底油，下姜片和另一半生蒜粒炒香，倒入小龙虾大火翻炒到变红。","烹料酒，加热水没过虾身一半，大火烧开转中火焖十二分钟。","倒入炸好的金蒜，加盐和白糖，大火收汁到汤浓，撒葱花出锅。"],"tip":"蒜分两次下，先炸的金蒜出香、后放的生蒜提味，蒜香才厚而不发苦。"},{"name":"清蒸大闸蟹","cat":"荤菜","region":"本帮","time":20,"diff":"简单","main":[["蟹","4只"]],"sea":["葱","姜","料酒","生抽","香醋","白糖"],"steps":["大闸蟹用刷子刷净蟹壳和蟹腿缝，用棉绳把蟹脚捆紧防止蒸时掉腿。","蒸锅水开后放姜片和葱段，蟹肚朝上摆在蒸屉上，淋一勺料酒。","大火蒸十二分钟，关火再焖两分钟，蟹壳完全变红就是熟了。","姜末加香醋、生抽和少许白糖调成蘸汁，趁热蘸食。"],"tip":"蟹必须肚皮朝上蒸，蟹黄才不外流；水开后再上锅，蒸够十二分钟才杀菌。"},{"name":"葱姜炒蟹","cat":"荤菜","region":"粤","time":25,"diff":"中等","main":[["蟹","3只"]],"sea":["葱","姜","蒜","料酒","生抽","蚝油","淀粉","食用油"],"steps":["蟹刷洗干净，去脐去鳃斩成四块，切口处拍一层干淀粉锁住蟹肉。","锅烧热放油，中火把蟹块切口朝下煎到定型金黄，盛出备用。","锅中留油，下大量葱段、姜片和蒜片，小火煸到葱边微焦。","倒回蟹块，烹料酒，加生抽、蚝油和半碗水，加盖中火焖六分钟。","开盖大火收汁，晃锅让汤汁裹住蟹块，汁浓即可出锅。"],"tip":"蟹块切口先拍淀粉再煎，蟹肉不散、汤汁也能挂住；葱姜要多放才压得住腥。"},{"name":"辣炒蛤蜊","cat":"荤菜","region":"鲁","time":15,"diff":"简单","main":[["蛤蜊","750g"]],"sea":["干辣椒","花椒","姜","蒜","葱","料酒","生抽","食用油"],"steps":["蛤蜊放淡盐水里静置两小时吐净泥沙，再用手搓洗两遍。","锅中水烧开，下蛤蜊焯三十秒，开口的立刻捞出，没开口的直接丢掉。","热锅放油，中小火炒香干辣椒、花椒和姜蒜末，炒到出香味。","转大火倒入蛤蜊，烹料酒，加生抽，快速翻炒一分钟。","撒葱段翻两下出锅，汤汁不要收太干，留着拌饭最香。"],"tip":"蛤蜊焯水只要开口就捞，下锅炒的时间越短肉越嫩，久炒就缩成一小团。"},{"name":"蛤蜊蒸蛋","cat":"荤菜","region":"家常","time":20,"diff":"简单","main":[["蛤蜊","300g"],["鸡蛋","3个"]],"sea":["葱","姜","料酒","盐","生抽","香油"],"steps":["蛤蜊放盐水吐沙两小时，洗净后加姜片和料酒，水开下锅煮到开口捞出。","煮蛤蜊的水撇去浮沫留半碗放凉，鸡蛋打散加少许盐。","蛋液按一比一点五兑入蛤蜊水，搅匀后过筛两遍去掉泡沫。","蛤蜊摆进碗里，倒入蛋液，盖一层保鲜膜并扎几个小孔。","水开后中小火蒸十二分钟，蛋面凝固不晃，淋生抽香油撒葱花。"],"tip":"用煮蛤蜊的原汤兑蛋液最鲜，过筛加盖膜是蛋面光滑无蜂窝的关键。"},{"name":"爆炒鱿鱼","cat":"荤菜","region":"家常","time":20,"diff":"简单","main":[["鱿鱼","400g"],["青椒","1个"],["洋葱","半个"]],"sea":["姜","蒜","干辣椒","料酒","生抽","蚝油","盐","食用油"],"steps":["鱿鱼撕去表面紫膜，剖开去内脏和软骨，在内侧切十字花刀再切块。","锅中水烧开加姜片和料酒，下鱿鱼焯十五秒，一卷起立刻捞出过凉。","热锅大火放油，下姜蒜和干辣椒爆香，倒洋葱和青椒块炒三十秒。","下鱿鱼，烹料酒，加生抽、蚝油和盐，大火快炒四十秒出锅。"],"tip":"鱿鱼焯水和爆炒都要极短，卷成花就出锅，多炒十秒就老得像橡皮。"},{"name":"铁板鱿鱼","cat":"荤菜","region":"家常","time":25,"diff":"中等","main":[["鱿鱼","500g"]],"sea":["蒜","姜","葱","孜然","辣椒面","生抽","蚝油","食用油"],"steps":["鱿鱼去膜去内脏，整条洗净沥干，用刀在两面各划几道浅口方便入味。","生抽、蚝油、蒜末和姜末调成酱汁，把鱿鱼抹匀腌二十分钟。","平底锅或铁板烧到冒烟，刷一层油，放鱿鱼中火压着煎三分钟。","翻面再煎三分钟，用铲子反复按压逼出水分，煎到边缘焦卷。","刷上剩下的酱汁，撒孜然和辣椒面，再煎二十秒，撒葱花出锅。"],"tip":"锅要烧到冒烟再下鱿鱼，用铲子压着煎才出焦边，否则就成水煮鱿鱼了。"},{"name":"蒜蓉烤生蚝","cat":"荤菜","region":"家常","time":25,"diff":"简单","main":[["生蚝","8只"]],"sea":["蒜","葱","尖椒","生抽","蚝油","料酒","白糖","食用油"],"steps":["生蚝用刷子刷净壳上的泥沙，用蚝刀从缝隙撬开，去掉碎壳留一半壳。","蚝肉用清水轻冲一遍，加几滴料酒腌五分钟去腥，摆回壳中。","蒜剁成末，一半用温油小火炸香，与生蒜末、生抽、蚝油、白糖拌匀。","烤箱上下火二百度预热，生蚝铺在烤盘上，每只盖一勺蒜蓉酱。","烤八分钟到蒜蓉冒泡、蚝肉边缘收缩，取出撒葱花和尖椒末。"],"tip":"生蚝遇热很快缩水，二百度烤八分钟刚好，久了汁水流失、肉质发柴。"},{"name":"冬瓜排骨汤","cat":"汤羹","region":"家常","time":75,"diff":"简单","main":[["排骨","500g"],["冬瓜","400g"]],"sea":["姜","葱","料酒","盐","白胡椒"],"steps":["排骨剁成小段，冷水下锅加姜片和料酒，大火烧开后撇净浮沫，煮三分钟捞出用温水冲净。","砂锅添足量热水，放入排骨和拍扁的姜块，大火烧开转小火盖盖炖四十分钟。","冬瓜去皮去瓤切厚片，等排骨炖到用筷子能轻松扎透时再下锅。","转中火再煮十二分钟，冬瓜变透明、边角发软时加盐4g和白胡椒1g。","撒葱花关火，静置两分钟让表面浮油聚一聚再盛。"],"tip":"排骨冷水下锅焯、砂锅加热水炖，汤才清亮不腥；冬瓜后放才不炖成泥。"},{"name":"玉米排骨汤","cat":"汤羹","region":"家常","time":70,"diff":"简单","main":[["排骨","500g"],["玉米","1根"],["胡萝卜","1根"]],"sea":["姜","葱","料酒","盐"],"steps":["排骨剁段冷水下锅，加姜片和料酒大火煮开，撇净浮沫后捞出用温水冲洗干净。","玉米剥去外皮，切四厘米厚的段；胡萝卜削皮切滚刀块，姜拍扁备用。","砂锅放排骨和姜，加足量热水大火烧开，转小火盖盖炖三十分钟。","下玉米和胡萝卜，继续小火炖二十五分钟，玉米芯出甜味、胡萝卜能用筷子扎透。","加盐4g再煮两分钟，尝过咸淡后撒葱花关火。"],"tip":"玉米段断面朝下摆进锅，甜味才进汤；水一次加够，中途添水汤会变浑。"},{"name":"山药排骨汤","cat":"汤羹","region":"家常","time":70,"diff":"简单","main":[["排骨","500g"],["山药","300g"],["枸杞","10g"]],"sea":["姜","葱","料酒","盐"],"steps":["排骨冷水下锅，加姜片和料酒焯三分钟，撇净浮沫后捞出用温水洗净。","砂锅放排骨与姜块，一次加足热水，大火烧开转小火炖四十分钟。","山药戴手套削皮，切滚刀块后泡在淡盐水里，防止表面发黑。","把山药下入汤中，中小火再炖十五分钟，筷子能轻松插透即可。","加盐3g和枸杞，煮两分钟后关火，撒葱花。"],"tip":"山药最后十五分钟才下，久炖会化糊；削皮戴手套，黏液沾手很痒。"},{"name":"莲藕排骨汤","cat":"汤羹","region":"鄂","time":90,"diff":"简单","main":[["排骨","500g"],["莲藕","400g"]],"sea":["姜","葱","料酒","盐","白胡椒"],"steps":["排骨冷水下锅焯水三分钟，撇净浮沫捞出冲净；莲藕去皮切滚刀块。","莲藕块放盆里撒少许盐抓匀腌十分钟，冲掉盐水后沥干。","砂锅放排骨、莲藕和姜块，加足量热水大火烧开。","转小火盖盖炖六十分钟，莲藕用筷子一戳就透、汤色微微发粉。","加盐4g和白胡椒1g，再滚三分钟关火，撒葱花。"],"tip":"挑表皮发黄带麻点的粉藕，切块用盐腌过再炖，藕才粉糯拉丝。"},{"name":"海带排骨汤","cat":"汤羹","region":"家常","time":80,"diff":"简单","main":[["排骨","500g"],["海带","200g"]],"sea":["姜","葱","料酒","盐","白胡椒"],"steps":["排骨冷水下锅，加姜片和料酒焯水，水开后撇沫再煮三分钟捞出洗净。","海带提前用清水泡两小时，中途换两遍水，洗净后切菱形片。","砂锅放排骨和姜块，加热水大火烧开，转小火炖四十分钟。","下海带片再炖二十分钟，海带变软、汤面浮起一层清亮的油。","加盐3g和白胡椒1g调味，再滚两分钟让味道进汤，关火。"],"tip":"海带多洗几遍去沙，最后二十分钟下锅，炖太久会烂得没口感。"},{"name":"茶树菇排骨汤","cat":"汤羹","region":"闽","time":85,"diff":"简单","main":[["排骨","500g"],["茶树菇","50g"]],"sea":["姜","葱","料酒","盐"],"steps":["干茶树菇剪去根部老蒂，温水泡二十分钟，反复抓洗掉泥沙。","排骨冷水下锅，加姜片和料酒焯三分钟，撇沫后捞出冲净。","砂锅放排骨、茶树菇和姜块，倒入澄清的泡菇水和热水，大火烧开。","转小火炖五十分钟，汤色转深、茶树菇吸饱汤汁变软。","加盐4g调味，再小火滚三分钟让咸味进汤，撒葱花关火。"],"tip":"泡菇水静置后取上层清液入汤，菌香翻倍；底下的沉沙别倒进去。"},{"name":"香菇鸡汤","cat":"汤羹","region":"家常","time":90,"diff":"简单","main":[["整鸡","半只"],["香菇","200g"]],"sea":["姜","葱","料酒","盐","枸杞"],"steps":["整鸡剁成大块，冷水下锅加姜片和料酒，煮开后撇沫三分钟捞出冲净。","香菇剪去硬蒂，伞面切十字花刀，洗净后沥干水分。","砂锅放鸡块和姜块，加足量热水大火烧开，转小火炖四十分钟。","下香菇继续小火炖二十五分钟，鸡腿肉能轻松脱骨。","加盐4g和几粒枸杞，煮两分钟关火，撒葱花。"],"tip":"干香菇泡发比鲜菇更香；盐一定最后放，早放鸡肉会紧实发柴。"},{"name":"清炖鸡汤","cat":"汤羹","region":"家常","time":110,"diff":"中等","main":[["整鸡","1只"],["红枣","6颗"],["枸杞","10g"]],"sea":["姜","葱","料酒","盐"],"steps":["整鸡去掉鸡屁股和内脏，冷水浸泡半小时去血水，中途换一次水。","冷水下锅加姜片和料酒，大火煮开撇净浮沫，煮五分钟捞出用温水冲净。","砂锅放整鸡和姜块，加热水没过鸡身，大火烧开后转最小火。","汤面保持似开非开，盖盖炖八十分钟，筷子能扎透鸡腿最厚处。","放红枣再炖十分钟，最后加枸杞和盐4g，煮两分钟关火。"],"tip":"全程小火不滚沸，汤才清亮；盐最后放，鸡肉才嫩不柴。"},{"name":"竹荪鸡汤","cat":"汤羹","region":"云南","time":95,"diff":"中等","main":[["整鸡","半只"],["竹荪","30g"]],"sea":["姜","葱","料酒","盐","白胡椒"],"steps":["竹荪用淡盐水泡十分钟，剪掉网状裙边和硬根，只留菌柄，挤干水分。","鸡块冷水下锅，加姜片和料酒焯三分钟，撇沫后捞出冲净。","砂锅放鸡块和姜块，加热水大火烧开，转小火炖六十分钟。","下竹荪再炖十分钟，竹荪吸汤变软、汤面清亮不浑。","加盐4g和白胡椒1g，小火滚两分钟，撒葱花关火。"],"tip":"竹荪裙边味重必须剪掉，而且只煮十分钟，久煮会烂成渣。"},{"name":"猪肚鸡汤","cat":"汤羹","region":"粤","time":150,"diff":"较难","main":[["猪肚","1个"],["整鸡","半只"]],"sea":["姜","葱","白胡椒","料酒","盐","醋"],"steps":["猪肚翻面，用盐和醋各搓洗两遍，冲净后刮掉内壁白膜和黄色杂质。","猪肚冷水下锅，加姜片和料酒煮五分钟，捞出过凉水切成两指宽的条。","鸡块冷水下锅焯三分钟，撇沫捞出洗净；白胡椒粒二十粒拍碎。","砂锅放猪肚条、姜块和碎胡椒，加热水大火烧开，转小火炖七十分钟。","下鸡块再炖三十分钟，猪肚能用筷子轻松扎透、汤色转白。","加盐5g再煮两分钟，汤面浮起白胡椒香时撒葱花关火。"],"tip":"猪肚用盐醋各搓一遍去黏液，白胡椒拍碎下锅，汤才暖胃不腥。"},{"name":"冬瓜老鸭汤","cat":"汤羹","region":"家常","time":100,"diff":"中等","main":[["鸭肉","半只"],["冬瓜","400g"]],"sea":["姜","葱","料酒","盐","白胡椒"],"steps":["鸭肉剁块，冷水下锅加姜片和料酒焯五分钟，撇净浮沫捞出冲净。","锅烧热不放油，下鸭块中火干煸五分钟，逼出鸭油后把多余的油倒掉。","加姜块和足量热水，大火烧开转小火炖七十分钟。","冬瓜去瓤切厚片下锅，中火再煮十五分钟，瓜片透明发软。","加盐4g和白胡椒1g，小火滚两分钟，撒葱花关火。"],"tip":"鸭块先干煸出油再炖，汤不腥不腻；冬瓜后放才不会煮散。"},{"name":"酸菜老鸭汤","cat":"汤羹","region":"川","time":120,"diff":"中等","main":[["鸭肉","半只"],["酸菜","200g"]],"sea":["姜","葱","花椒","料酒","盐","白胡椒"],"steps":["酸菜挤干水分切段；鸭肉剁块冷水下锅，加姜片和料酒焯五分钟，撇沫捞出。","锅放少许油，下酸菜中火炒三分钟，炒出酸香、边缘微微发干时盛出。","原锅下鸭块、姜块和十粒花椒，中火煸五分钟至鸭皮收紧。","倒回酸菜，加热水没过食材，大火烧开转小火炖九十分钟。","尝汤后再补盐，加白胡椒1g，撒葱花关火。"],"tip":"酸菜先炒透再炖，酸香才厚；酸菜本身有咸味，盐要尝过再放。"},{"name":"黄豆猪蹄汤","cat":"汤羹","region":"家常","time":140,"diff":"中等","main":[["猪蹄","1只"],["黄豆","100g"]],"sea":["姜","葱","料酒","盐","白胡椒"],"steps":["黄豆提前用冷水泡四小时以上，泡到豆子掰开没有硬芯。","猪蹄刮净残毛，冷水下锅加姜片和料酒煮十分钟，撇沫捞出用温水洗净。","砂锅放猪蹄、黄豆和姜块，加足量热水大火烧开。","转小火炖九十分钟，猪蹄皮能戳透、汤色发白变稠。","加盐5g和白胡椒1g，再煮五分钟关火，撒葱花。"],"tip":"猪蹄焯水后用温水洗，遇冷水皮会收紧炖不烂；盐最后放才出胶。"},{"name":"花生猪蹄汤","cat":"汤羹","region":"家常","time":130,"diff":"中等","main":[["猪蹄","1只"],["花生米","100g"],["红枣","5颗"]],"sea":["姜","葱","料酒","盐"],"steps":["花生米用温水泡三十分钟，剥掉外层红衣；猪蹄剁成小块。","猪蹄冷水下锅，加姜片和料酒煮开，撇沫后再煮八分钟捞出洗净。","砂锅放猪蹄、花生和姜块，加热水大火烧开，转小火炖八十分钟。","花生炖到一捏就烂、猪蹄皮软糯时加红枣再煮十分钟。","加盐4g调味，小火再煮五分钟，关火后撒葱花。"],"tip":"花生泡透再去红衣，汤不涩；全程小火，汤才清而不浑。"},{"name":"玉米筒骨汤","cat":"汤羹","region":"家常","time":110,"diff":"中等","main":[["筒骨","800g"],["玉米","1根"]],"sea":["姜","葱","料酒","盐"],"steps":["筒骨让摊主剖开，冷水浸泡二十分钟去血水，中间换一次水。","冷水下锅加姜片和料酒，大火煮开撇净浮沫，煮五分钟捞出冲净。","筒骨放回锅，加足量热水和姜块，大火滚十五分钟至汤色转白。","转小火炖六十分钟，下玉米段再炖二十分钟。","加盐4g调味，再小火滚三分钟让咸味进汤，撒葱花关火。"],"tip":"筒骨先大火滚十几分钟再转小火，汤色才白；中途别添凉水。"},{"name":"鲫鱼豆腐汤","cat":"汤羹","region":"家常","time":35,"diff":"中等","main":[["鲫鱼","1条"],["豆腐","300g"]],"sea":["姜","葱","料酒","盐","白胡椒","食用油"],"steps":["鲫鱼去鳞去内脏，撕掉腹内黑膜，用厨房纸把鱼身擦干，两面各划三刀。","锅烧到冒青烟，倒油转一圈，下姜片擦锅后放鱼，中火煎三分钟至底面金黄。","翻面再煎两分钟，沿锅边淋料酒10ml，立刻冲入滚开的热水。","大火滚八分钟，汤色转奶白，下豆腐块转中火再煮五分钟。","加盐3g和白胡椒1g，中火滚一分钟，撒葱花关火。"],"tip":"鱼身擦干、锅烧透再下鱼才不破皮；一定冲开水，冷水冲汤不白。"},{"name":"鲫鱼萝卜丝汤","cat":"汤羹","region":"家常","time":40,"diff":"中等","main":[["鲫鱼","1条"],["白萝卜","300g"]],"sea":["姜","葱","料酒","盐","白胡椒","食用油"],"steps":["鲫鱼处理干净，撕去腹内黑膜，两面划刀后擦干水分；白萝卜切细丝。","锅烧热放油和姜片，下鲫鱼中火煎至两面微黄，沿锅边淋料酒10ml。","冲入开水没过鱼身，大火滚十分钟，汤色奶白。","下萝卜丝转中火煮八分钟，萝卜丝变透明、筷子能夹断。","加盐3g和白胡椒1g，中火滚一分钟，撒葱花关火。"],"tip":"萝卜丝切细些更易熟，煮到透明就好；久煮会散，汤也发苦。"},{"name":"黑鱼汤","cat":"汤羹","region":"家常","time":40,"diff":"中等","main":[["黑鱼","1条"]],"sea":["姜","葱","料酒","盐","白胡椒","食用油"],"steps":["黑鱼去鳞去内脏，片下两侧鱼肉斜切厚片，鱼骨鱼头剁块，用料酒和姜片腌十分钟。","锅烧热放油，下姜片和鱼骨鱼头，中火煎到表面微焦。","冲入开水没过鱼骨，大火滚十分钟，汤色转白、表面浮油。","下鱼片，转中小火煮三分钟，肉色变白、边缘卷起即熟。","加盐3g和白胡椒1g，中火滚一分钟，撒葱花关火。"],"tip":"鱼片最后下、只煮三分钟，久煮就老；鱼骨先煎再冲开水汤才白。"},{"name":"雪菜黄鱼汤","cat":"汤羹","region":"本帮","time":35,"diff":"中等","main":[["黄鱼","1条"],["雪里蕻","100g"]],"sea":["姜","葱","料酒","盐","白胡椒","食用油"],"steps":["黄鱼去鳞去内脏洗净擦干，两面各划两刀；雪里蕻切碎，清水泡十分钟去咸味后挤干。","锅放油烧热，下黄鱼中火煎至两面微黄定型，淋料酒10ml。","冲入开水没过鱼身，大火滚八分钟，汤色奶白、鱼肉定型。","下雪里蕻转中火煮五分钟，汤味转鲜咸。","尝味后补少许盐，加白胡椒1g，撒葱花关火。"],"tip":"雪里蕻先泡去多余盐分；鱼煎定型再冲开水，汤才白而不腥。"},{"name":"西红柿鸡蛋汤","cat":"汤羹","region":"家常","time":15,"diff":"简单","main":[["西红柿","2个"],["鸡蛋","2个"]],"sea":["葱","盐","香油","食用油","淀粉"],"steps":["西红柿顶部划十字，用开水烫一分钟后撕皮，切小滚刀块；鸡蛋打散。","锅放油烧热，下西红柿块中火炒三分钟，炒到出红汁、块变软塌。","加两碗开水，大火烧开后转中火煮三分钟。","淋入少许水淀粉搅匀，沿锅边转圈淋蛋液，停十秒待其凝固再轻推两下。","加盐3g，尝过咸淡撒上葱花，滴香油3滴，关火后盛进汤碗。"],"tip":"西红柿炒出红汁再加水，汤才红亮；蛋液淋入后别马上搅，蛋花才成片。"},{"name":"丝瓜蛋汤","cat":"汤羹","region":"家常","time":15,"diff":"简单","main":[["丝瓜","1根"],["鸡蛋","2个"]],"sea":["姜","葱","盐","香油","食用油"],"steps":["丝瓜刮掉外皮，切滚刀块，泡在清水里防止发黑；鸡蛋加一小撮盐打散。","锅放油烧热，下姜丝和丝瓜块中火炒两分钟，炒到边缘变软。","加两碗开水，大火烧开煮三分钟至丝瓜透明。","沿锅边转圈淋入蛋液，静置十秒待蛋花浮起，再加盐2g。","撒上葱花，滴香油3滴，关火后盛进汤碗。"],"tip":"丝瓜去皮后马上下锅，久放会发黑；蛋液淋入后别搅，蛋花才整片。"},{"name":"紫菜蛋花汤","cat":"汤羹","region":"家常","time":10,"diff":"简单","main":[["紫菜","10g"],["鸡蛋","2个"],["虾皮","5g"]],"sea":["姜","葱","盐","白胡椒","香油"],"steps":["紫菜撕成小片铺在碗底，虾皮用温水冲洗一遍去咸腥。","锅加两碗水，放姜丝和虾皮，大火烧开。","鸡蛋打散，沿锅边细细淋入，转中小火等蛋花全部浮起。","加盐2g和白胡椒1g，用勺搅匀化开，然后关火。","把滚汤冲进紫菜碗里，撒葱花，滴香油3滴。"],"tip":"紫菜不用下锅煮，用滚汤冲开最鲜；蛋液淋入后别搅，蛋花才细。"},{"name":"冬瓜丸子汤","cat":"汤羹","region":"家常","time":35,"diff":"中等","main":[["冬瓜","300g"],["猪肉末","200g"]],"sea":["姜","葱","淀粉","料酒","盐","白胡椒","香油"],"steps":["猪肉末加姜末、料酒10ml、盐2g和淀粉10g，分三次打入两勺清水，顺一个方向搅到发黏上劲。","冬瓜去皮去瓤切薄片；锅加清水和姜片大火烧开。","转中小火，用虎口挤出丸子逐个下锅，全部浮起后再煮三分钟。","下冬瓜片煮八分钟，瓜片变透明、汤面清亮。","加盐3g和白胡椒1g，撒上葱花，滴香油3滴，关火后盛进汤碗。"],"tip":"肉末顺一个方向搅上劲丸子才弹；水微开时下丸子，滚沸会冲散。"},{"name":"白菜豆腐汤","cat":"汤羹","region":"家常","time":25,"diff":"简单","main":[["大白菜","300g"],["豆腐","300g"]],"sea":["姜","葱","盐","白胡椒","食用油"],"steps":["大白菜帮斜刀片成薄片，叶子撕成块，帮和叶分开放；豆腐切两厘米方块。","锅放少许油烧热，下姜丝和白菜帮，中火炒三分钟至帮变软出水。","加两碗开水，大火烧开，下豆腐块转中火煮八分钟。","放白菜叶再煮三分钟，叶子塌软、汤色转清即可。","加盐3g和白胡椒1g，中火滚一分钟，撒葱花关火。"],"tip":"菜帮先炒软再加水，汤才清甜；豆腐下锅后别大火翻滚，容易碎。"},{"name":"冬瓜虾皮汤","cat":"汤羹","region":"家常","time":20,"diff":"简单","main":[["冬瓜","300g"],["虾皮","10g"]],"sea":["姜","葱","盐","白胡椒","香油"],"steps":["虾皮用温水泡五分钟，洗掉浮盐后挤干；冬瓜去皮去瓤切薄片。","锅烧热不放油，下虾皮小火焙一分钟至微微出香。","加两碗开水，放姜丝和冬瓜片，大火烧开转中火煮十分钟。","冬瓜变透明、汤色微白时加盐2g和白胡椒1g。","撒上葱花，滴香油3滴，关火后盛进汤碗。"],"tip":"虾皮先小火焙香再加水，鲜味才出；虾皮本身咸，盐要少放。"},{"name":"口蘑汤","cat":"汤羹","region":"家常","time":25,"diff":"简单","main":[["口蘑","300g"]],"sea":["姜","葱","香菜","盐","白胡椒","香油","食用油"],"steps":["口蘑用湿布擦净表面，切三毫米厚的片，蒂部老根削掉。","锅放少许油，中火下口蘑片煎三分钟，煎到边缘微黄、锅底出水。","加两碗开水，放姜丝，大火烧开转中火煮八分钟。","汤色转浅褐、蘑菇片变软时加盐3g和白胡椒1g。","撒葱花和香菜末，滴香油3滴，关火装碗。"],"tip":"口蘑先煎到出水上色再加水，汤才鲜；洗蘑菇别泡水，擦净即可。"},{"name":"番茄牛腩汤","cat":"汤羹","region":"家常","time":130,"diff":"中等","main":[["牛腩","500g"],["西红柿","3个"]],"sea":["姜","葱","料酒","盐","白胡椒","食用油"],"steps":["牛腩切三厘米见方的块，冷水下锅加姜片和料酒，煮开撇净浮沫后再煮五分钟捞出冲净。","两个西红柿切块，一个切小丁；锅放油下西红柿丁，中火炒五分钟至化成红汁。","下牛腩块翻炒两分钟裹上番茄汁，加姜片和足量热水。","大火烧开转小火炖九十分钟，牛腩能用筷子扎透。","下西红柿块再炖十五分钟，汤汁略稠、表面浮红油时加盐5g。","撒葱花和白胡椒1g，关火后尝味，淡了再补盐。"],"tip":"西红柿分两批下，先炒化的出汤底，后放的保留果肉；牛腩一定加热水。"},{"name":"萝卜羊肉汤","cat":"汤羹","region":"西北","time":100,"diff":"中等","main":[["羊肉","500g"],["白萝卜","400g"]],"sea":["姜","葱","香菜","花椒","料酒","盐","白胡椒"],"steps":["羊肉切块，冷水浸泡一小时去血水，中途换两次水。","羊肉冷水下锅，加姜片、十粒花椒和料酒，大火煮开撇净浮沫，煮五分钟捞出冲净。","砂锅放羊肉和姜块，加足量热水大火烧开，转小火炖六十分钟。","白萝卜去皮切滚刀块下锅，继续小火炖二十五分钟至萝卜透明。","加盐4g和白胡椒1g，小火滚两分钟，撒葱花和香菜关火。"],"tip":"羊肉冷水泡透、焯水撇沫才去膻；萝卜后放，久炖会烂成泥。"},{"name":"酸辣汤","cat":"汤羹","region":"川","time":20,"diff":"中等","main":[["豆腐","200g"],["木耳","3朵"],["竹笋","1根"],["猪里脊","100g"],["鸡蛋","1个"]],"sea":["葱","姜","醋","白胡椒","生抽","淀粉","盐","香油"],"steps":["豆腐、木耳、竹笋、猪里脊分别切细丝，肉丝加料酒抓匀。","锅中水烧开，下笋丝焯一分钟去涩味，捞出沥干。","清水1000毫升烧开，下肉丝拨散，再下豆腐、木耳、笋丝。","中火煮三分钟，加生抽和盐，分两次淋水淀粉至汤汁略稠。","转小火淋入蛋液推成蛋花，关火后加醋和白胡椒粉。","盛入汤碗，撒葱花和白胡椒，滴几滴香油趁热上桌。"],"tip":"醋和白胡椒一定关火后放，早放酸香和辛辣味都会跑掉。"},{"name":"西湖牛肉羹","cat":"汤羹","region":"杭帮","time":25,"diff":"中等","main":[["牛肉末","150g"],["豆腐","150g"],["鸡蛋","2个"],["香菜","1小把"]],"sea":["姜","淀粉","料酒","盐","白胡椒","香油"],"steps":["牛肉末加料酒、少许盐和淀粉抓匀，腌十分钟去腥。","豆腐切小丁，入沸水焯一分钟捞出，蛋清蛋黄分开打散。","锅中水1000毫升烧开，下姜末和牛肉末，边下边搅散。","撇净浮沫，下豆腐丁中火煮三分钟，加盐和白胡椒。","淋水淀粉勾薄芡，转小火倒入蛋清，轻推成细蛋花。","关火撒香菜末和少许白胡椒，点几滴香油出锅。"],"tip":"只用蛋清、芡要勾得薄，羹才清亮滑口，不会糊成一团。"},{"name":"宋嫂鱼羹","cat":"汤羹","region":"杭帮","time":40,"diff":"较难","main":[["鲈鱼","1条"],["香菇","3朵"],["鸡蛋","2个"],["火腿","30g"]],"sea":["姜","葱","料酒","醋","盐","淀粉","香油","白胡椒"],"steps":["鲈鱼去骨取肉，鱼骨鱼头留用，鱼肉切细丝加料酒姜片腌十分钟。","鱼骨加姜片和1000毫升水，中火熬二十分钟，滤出奶白鱼汤。","香菇、火腿切细丝，与鱼丝一同下鱼汤，中火煮三分钟。","加盐和白胡椒调味，分次淋水淀粉勾至能挂住勺背。","转小火淋入蛋液推散，关火加醋，撒葱花滴香油。"],"tip":"鱼骨先煎再熬汤更白，鱼肉最后下锅，久煮会散成渣。"},{"name":"文思豆腐羹","cat":"汤羹","region":"淮扬","time":45,"diff":"较难","main":[["豆腐","300g"],["鸡胸肉","80g"],["火腿","30g"],["香菇","3朵"],["竹笋","1根"]],"sea":["姜","盐","料酒","淀粉","香油","白胡椒"],"steps":["鸡胸肉加姜片、料酒煮十分钟，捞出顺丝撕成细丝。","豆腐先片成薄片，再切成火柴梗粗的丝，泡清水轻推洗去碎末。","香菇、火腿、竹笋切同样粗细的丝，笋丝先焯水一分钟。","锅中清汤1200毫升烧开，下鸡丝、火腿、香菇、笋丝中火煮三分钟。","轻轻推入豆腐丝，小火煮两分钟，只推不搅防止断裂。","加盐和白胡椒，淋薄芡，点香油盛入汤碗。"],"tip":"切豆腐丝刀要蘸水防粘，下锅后用勺背轻推，一搅就断。"},{"name":"银鱼羹","cat":"汤羹","region":"淮扬","time":20,"diff":"中等","main":[["银鱼","150g"],["鸡蛋","2个"],["豆腐","100g"],["香菜","1小把"]],"sea":["姜","料酒","盐","白胡椒","淀粉","香油","醋"],"steps":["银鱼用清水冲净，加料酒和姜丝抓匀腌五分钟去腥。","豆腐切小丁，入沸水焯一分钟捞出备用。","锅中水900毫升烧开，下银鱼和豆腐丁，中火煮三分钟。","撇去浮沫，加盐和白胡椒，淋水淀粉勾成米汤芡。","转小火淋入蛋液推成蛋花，关火点醋和香油，撒香菜。"],"tip":"银鱼极易熟，水开下锅三分钟就够，久煮会烂成糊。"},{"name":"粟米羹","cat":"汤羹","region":"粤","time":20,"diff":"简单","main":[["玉米","2根"],["鸡蛋","2个"],["鸡胸肉","100g"]],"sea":["盐","淀粉","白胡椒","香油","白糖"],"steps":["玉米剥粒，一半用刀背压碎出浆，鸡胸肉切小丁。","鸡丁加少许盐和淀粉抓匀，静置十分钟。","锅中水900毫升烧开，下玉米碎和玉米粒，中小火煮八分钟。","下鸡丁拨散煮两分钟，加盐、少许白糖和白胡椒。","淋水淀粉勾薄芡，转小火倒入蛋液推成蛋花，点香油。"],"tip":"玉米压碎一半再煮，汤自然浓稠带甜，不全靠勾芡。"},{"name":"蟹粉豆腐羹","cat":"汤羹","region":"淮扬","time":30,"diff":"中等","main":[["蟹","2只"],["豆腐","300g"]],"sea":["姜","葱","料酒","醋","盐","淀粉","猪油","白胡椒"],"steps":["蟹蒸十五分钟取出，拆出蟹黄蟹肉，蟹壳留下。","蟹壳加姜片和600毫升水煮十分钟，滤出蟹汤备用。","锅中放猪油，中火下姜末和蟹粉炒香，烹料酒，加一小勺醋。","倒入蟹汤和豆腐小丁，中火煮三分钟，加盐和白胡椒。","分两次淋水淀粉勾芡至浓稠挂勺，撒葱花出锅。"],"tip":"拆出的蟹黄单独放，最后下锅，成菜颜色才红亮好看。"},{"name":"三鲜豆腐羹","cat":"汤羹","region":"家常","time":25,"diff":"中等","main":[["豆腐","300g"],["虾仁","100g"],["香菇","3朵"],["豌豆","50g"]],"sea":["姜","葱","盐","料酒","淀粉","白胡椒","香油"],"steps":["虾仁去虾线，加料酒、盐和淀粉抓匀腌十分钟。","豆腐切小丁，入沸水焯一分钟去豆腥味，香菇切丁。","锅中油烧五成热，中火滑炒虾仁到变红卷曲，盛出。","原锅下姜末、香菇丁炒香，加水900毫升烧开，下豆腐和豌豆。","中火煮三分钟，倒回虾仁，加盐和白胡椒，淋薄芡。","撒葱花，滴香油，喜欢胡椒味的再加少许白胡椒。"],"tip":"豆腐先焯水定型，煮时不易碎，豆腥味也一并去掉。"},{"name":"咸蛋黄豆腐羹","cat":"汤羹","region":"家常","time":25,"diff":"中等","main":[["咸鸭蛋","3个"],["豆腐","300g"]],"sea":["葱","盐","淀粉","白胡椒","食用油","香油"],"steps":["咸鸭蛋煮熟取黄，用刀背压成细泥；豆腐切小丁焯水一分钟。","锅中放两勺油，中小火下咸蛋黄泥，慢慢炒到起沙冒泡。","冲入清水800毫升搅匀，大火烧开后下豆腐丁。","中火煮三分钟，加少许盐和白胡椒，淋水淀粉勾薄芡。","撒葱花，滴几滴香油，连豆腐带汤盛入深碗。"],"tip":"蛋黄要用小火炒到起沙再加水，汤才金黄起沙不结块。"},{"name":"海带豆腐汤","cat":"汤羹","region":"家常","time":15,"diff":"简单","main":[["海带","100g"],["豆腐","300g"]],"sea":["葱","姜","盐","白胡椒","香油","食用油"],"steps":["海带洗净切菱形片，豆腐切两厘米见方的块。","锅中放少许油，中火下姜丝和葱花炒出香味。","下海带片中火翻炒两分钟，炒到边缘微微发亮。","加清水900毫升大火烧开，下豆腐块转中小火煮八分钟。","加盐和白胡椒调味，撒葱花滴香油出锅。"],"tip":"海带先下锅干炒两分钟，去腥又提鲜，煮出的汤味更厚。"},{"name":"海蛎豆腐汤","cat":"汤羹","region":"闽","time":20,"diff":"简单","main":[["生蚝","200g"],["豆腐","300g"]],"sea":["姜","葱","盐","料酒","白胡椒","香油"],"steps":["生蚝用淡盐水轻轻抓洗两遍，挑净碎壳，加料酒和姜丝腌五分钟。","豆腐切两厘米方块，入沸水焯一分钟去豆腥。","锅中放少许油，中火下姜丝炒香，加清水900毫升烧开。","下豆腐块中火煮三分钟，再下生蚝，煮到蚝肉边缘卷起约两分钟。","加盐和白胡椒调味，撒葱花，滴几滴香油出锅。"],"tip":"生蚝最后下锅，煮两分钟就够，久了缩成硬块没了鲜味。"},{"name":"冬瓜蛤蜊汤","cat":"汤羹","region":"家常","time":25,"diff":"简单","main":[["蛤蜊","500g"],["冬瓜","300g"]],"sea":["姜","葱","盐","料酒","白胡椒"],"steps":["蛤蜊放淡盐水里养两小时吐沙，捞出搓洗外壳。","冬瓜去皮去瓤切成薄片，姜切细丝，蛤蜊再冲一遍。","锅中水800毫升烧开，下姜丝和冬瓜片，中火煮五分钟至透明。","下蛤蜊，淋一勺料酒，煮到壳全部张开约三分钟。","撇去浮沫，加盐和白胡椒，撒葱花关火。"],"tip":"蛤蜊开口就关火，煮久了肉缩发柴；汤本身够鲜，盐要少放。"},{"name":"皮蛋苋菜汤","cat":"汤羹","region":"家常","time":15,"diff":"简单","main":[["皮蛋","2个"],["苋菜","300g"]],"sea":["蒜","盐","食用油","白胡椒","香油"],"steps":["苋菜摘去老梗洗净沥干，皮蛋剥壳切小块，蒜拍碎。","锅中放油烧热，中小火下蒜末和皮蛋块煎一分钟至边缘起泡。","冲入滚水800毫升，大火煮三分钟至汤色发白。","下苋菜，用筷子压入汤中，中火煮两分钟至叶子软塌。","加盐和白胡椒调味，滴几滴香油，连汤盛出。"],"tip":"皮蛋先用油煎出香味再冲滚水，汤才白，也没有碱腥味。"},{"name":"菠菜蛋花汤","cat":"汤羹","region":"家常","time":10,"diff":"简单","main":[["菠菜","300g"],["鸡蛋","2个"]],"sea":["葱","盐","香油","白胡椒","食用油"],"steps":["菠菜去根洗净切段，入沸水焯三十秒去草酸，捞出挤干。","鸡蛋打散，加一勺清水搅匀，蛋花更嫩更蓬松。","锅中放少许油，中火下葱花炒香，加清水800毫升烧开。","下菠菜煮一分钟，转小火淋入蛋液，静置五秒再推散。","加盐和白胡椒调味，滴几滴香油即可关火。"],"tip":"菠菜先焯水去草酸，汤不涩口；蛋液小火淋才成片。"},{"name":"西红柿鱼片汤","cat":"汤羹","region":"家常","time":30,"diff":"中等","main":[["龙利鱼","300g"],["西红柿","2个"]],"sea":["姜","葱","盐","料酒","淀粉","白胡椒","食用油","白糖"],"steps":["龙利鱼斜刀片成薄片，加盐、料酒和淀粉抓匀，腌十分钟。","西红柿去蒂切块，锅中放油，中火炒三分钟至出红汁。","加清水900毫升大火烧开，转中火煮五分钟成红汤。","加盐、少许白糖和白胡椒，转小火把鱼片逐片滑入。","鱼片变白卷边即关火，撒葱花连汤盛出。"],"tip":"鱼片下锅后别搅动，等变白再轻推，肉才整片不碎。"},{"name":"榨菜肉丝汤","cat":"汤羹","region":"家常","time":15,"diff":"简单","main":[["榨菜","100g"],["猪里脊","100g"]],"sea":["葱","姜","盐","料酒","淀粉","白胡椒","香油"],"steps":["猪里脊切细丝，加料酒、淀粉和少许盐抓匀腌十分钟。","榨菜切细丝，用清水泡五分钟去掉多余咸味，挤干。","锅中水800毫升烧开，下姜丝和榨菜丝煮两分钟出味。","下肉丝用筷子拨散，煮到变白约一分钟。","加白胡椒和少许盐，撒葱花，滴香油出锅。"],"tip":"榨菜先泡水再下锅，汤不会过咸，脆感也保留得住。"},{"name":"汆丸子汤","cat":"汤羹","region":"鲁","time":30,"diff":"中等","main":[["猪肉末","250g"],["小白菜","200g"],["粉丝","50g"]],"sea":["姜","葱","盐","料酒","淀粉","白胡椒","香油","鸡蛋"],"steps":["肉末加姜葱末、料酒、盐、蛋清和淀粉，同一方向搅打五分钟。","粉丝用温水泡十分钟，小白菜洗净切段。","锅中水1000毫升烧至微沸转中小火，虎口挤丸子逐个下锅。","丸子全部浮起后撇净浮沫，中火煮五分钟至熟透。","下粉丝煮两分钟，再下小白菜烫一分钟，加盐和白胡椒。","丸子先盛入碗中，再浇上热汤，淋香油撒葱花。"],"tip":"肉馅要打到黏手再挤丸子，下锅不散，咬开还有汤汁。"},{"name":"鱼丸汤","cat":"汤羹","region":"闽","time":20,"diff":"简单","main":[["鱼丸","250g"],["小白菜","100g"]],"sea":["葱","盐","白胡椒","香油","芹菜"],"steps":["鱼丸用清水冲一遍，小白菜洗净切段，芹菜去叶切末。","锅中水800毫升烧开，下鱼丸，中火煮五分钟至全部浮起膨大。","撇去浮沫，下小白菜煮一分钟至叶片变软。","加盐和白胡椒调味，撒芹菜末和葱花。","关火后滴几滴香油，撒葱花，趁热连汤盛碗。"],"tip":"鱼丸浮起后点一次凉水再煮开，丸子更弹，芯也热透。"},{"name":"三鲜汤","cat":"汤羹","region":"家常","time":30,"diff":"中等","main":[["虾仁","100g"],["鱿鱼","100g"],["海参","100g"],["小白菜","100g"]],"sea":["姜","葱","盐","料酒","白胡椒","淀粉","香油"],"steps":["虾仁去虾线，加料酒和淀粉抓匀；鱿鱼切花刀再切块，海参切条。","锅中水烧开，下鱿鱼和海参焯三十秒，卷起即捞出。","另起锅放少许油，中火下姜丝葱段炒香，加清水900毫升烧开。","下虾仁煮两分钟至变红，再下鱿鱼、海参煮一分钟。","下小白菜烫软，加盐和白胡椒，淋薄芡，滴香油出锅。"],"tip":"海鲜分别焯水定型，下锅顺序按耐煮程度，才不会老。"},{"name":"连锅汤","cat":"汤羹","region":"川","time":45,"diff":"中等","main":[["五花肉","300g"],["白萝卜","400g"]],"sea":["姜","葱","花椒","豆瓣酱","生抽","盐"],"steps":["五花肉整块冷水下锅，加姜片和花椒，中火煮二十分钟至筷子能扎透。","捞出肉晾五分钟，切成薄片；煮肉的原汤撇净浮油留着。","白萝卜去皮切薄片，下原汤中火煮十分钟，煮到萝卜片透明。","下肉片和葱段，中火再煮五分钟，加盐和少许生抽调味。","豆瓣酱用两勺热汤化开，撒葱花做成蘸碟，配汤蘸食。"],"tip":"肉煮好晾五分钟再切才不散；原汤别倒，是汤鲜的全部来源。"},{"name":"酸菜白肉汤","cat":"汤羹","region":"东北","time":70,"diff":"中等","main":[["酸菜","300g"],["五花肉","300g"],["粉条","50g"]],"sea":["葱","姜","花椒","盐","料酒"],"steps":["五花肉整块冷水下锅，加姜片、花椒和料酒，中火煮三十分钟至筷子扎透。","肉捞出晾凉切薄片；煮肉汤撇净浮沫留用。","酸菜挤干水分切细丝，锅中放少许油，中火炒三分钟至酸香散出。","把酸菜放入肉汤，大火烧开转小火炖二十分钟。","下粉条煮八分钟至软，再下白肉片煮五分钟，加盐调味。"],"tip":"酸菜先干炒去生酸味，再用肉汤炖，汤才香而不刺酸。"},{"name":"酸辣肚丝汤","cat":"汤羹","region":"湘","time":45,"diff":"中等","main":[["猪肚","1个"],["木耳","3朵"],["竹笋","1根"]],"sea":["姜","葱","醋","白胡椒","干辣椒","盐","淀粉","香油"],"steps":["猪肚用盐和淀粉反复搓洗三遍，撕掉内壁白膜，冷水下锅焯五分钟。","猪肚加姜片和清水，中火煮三十分钟至能咬断，捞出切细丝。","木耳、竹笋切丝，笋丝焯水一分钟；干辣椒剪成小段。","锅中放油，小火煸香干辣椒和姜丝，倒入煮猪肚的汤烧开。","下肚丝、木耳丝、笋丝中火煮五分钟，加盐和白胡椒。","淋水淀粉勾至汤汁略稠，关火加醋，撒葱花滴香油。"],"tip":"醋关火后放，酸味才尖；肚丝切得越细，越容易吸味。"},{"name":"醋椒鱼","cat":"汤羹","region":"鲁","time":35,"diff":"中等","main":[["鲤鱼","1条"],["香菜","1小把"]],"sea":["葱","姜","醋","白胡椒","料酒","盐","香油","食用油"],"steps":["鲤鱼去鳞去内脏，撕掉腹内黑膜，两面各划三刀，用料酒姜片腌十分钟。","锅中放油烧热，中火下鲤鱼两面各煎三分钟至微黄定型。","冲入滚水1200毫升，下葱段和姜片，大火滚十分钟至汤色发白。","加盐、大量白胡椒和三勺醋，中火再煮两分钟。","连汤盛入汤碗，撒香菜末和葱丝，滴几滴香油。"],"tip":"醋和白胡椒分两次放，出锅前补一次，酸辣味才够冲。"},{"name":"疙瘩汤","cat":"汤羹","region":"东北","time":25,"diff":"简单","main":[["面粉","200g"],["西红柿","2个"],["鸡蛋","2个"]],"sea":["葱","盐","生抽","香油","食用油"],"steps":["面粉放大碗，水龙头开最小水流，边滴边用筷子搅成小疙瘩。","西红柿切小块，鸡蛋打散；锅中放油，中火炒西红柿出汁。","加清水1000毫升大火烧开，加盐和少许生抽调味。","把疙瘩分散撒入锅中，边撒边搅，中火煮五分钟。","淋入蛋液推成蛋花，撒葱花滴香油即可。"],"tip":"水要一滴一滴加、筷子不停搅，疙瘩才小而匀、不结大块。"},{"name":"胡辣汤","cat":"汤羹","region":"河南","time":40,"diff":"较难","main":[["牛肉","150g"],["木耳","3朵"],["豆皮","100g"],["面粉","150g"],["粉条","50g"]],"sea":["姜","葱","白胡椒","花椒","八角","醋","盐","香油"],"steps":["面粉加水和成软面团，盖布醒二十分钟，再放清水里反复抓洗。","洗出的面水静置沉淀，面筋上锅蒸十五分钟后切片。","牛肉切小丁，加姜片和八角煮三十分钟，汤留用。","牛肉汤中下木耳丝、豆皮丝、粉条和面筋片，中火煮十分钟。","将沉淀的面水搅匀倒入，边倒边搅至汤汁浓稠挂勺。","加盐、大量白胡椒和醋，撒葱花淋香油。"],"tip":"洗面水要沉淀后再用，边倒边搅，勾出的汤才滑而不澥。"},{"name":"汽锅鸡","cat":"汤羹","region":"云南","time":120,"diff":"中等","main":[["整鸡","半只"],["香菇","5朵"],["火腿","30g"]],"sea":["姜","葱","盐","白胡椒","料酒"],"steps":["鸡剁成四厘米块，冷水浸泡半小时去血水，捞出沥干。","鸡块加盐、料酒和姜片抓匀腌十五分钟，香菇切片，火腿切薄片。","鸡块铺入汽锅，上面放香菇、火腿和姜片，锅内不加一滴水。","汽锅坐在装水的蒸锅上，接口用湿布封严，大火蒸两小时。","蒸到锅内汤汁没过食材一半，加盐和白胡椒，撒葱花。"],"tip":"汤全靠蒸汽凝成，蒸锅水要一次加足，中途只添开水不揭盖。"},{"name":"咖喱牛肉汤","cat":"汤羹","region":"本帮","time":90,"diff":"中等","main":[["牛肉","400g"],["洋葱","1个"],["土豆","1个"],["咖喱块","2块"]],"sea":["姜","盐","料酒","食用油","咖喱粉","面粉"],"steps":["牛肉切大块冷水下锅焯水，撇沫后捞出冲洗干净。","锅中放油，中小火炒面粉两分钟至微黄，加咖喱粉炒成油咖喱。","牛肉加姜片和1500毫升热水，小火炖六十分钟至酥软。","洋葱切丝、土豆切块下锅，中火煮十五分钟至土豆软烂。","油咖喱用少量热汤化开倒入锅中，放咖喱块搅至完全融化。","小火再煮五分钟至汤汁略稠，加盐调味即可。"],"tip":"油咖喱先用热汤化开再下锅，直接丢进去容易结块糊底。"},{"name":"银耳莲子羹","cat":"甜点","region":"家常","time":90,"diff":"简单","main":[["银耳","1朵"],["莲子","50g"],["红枣","8颗"],["枸杞","10g"]],"sea":["冰糖"],"steps":["银耳用冷水泡两小时至完全发开，剪去黄色根部，撕成小朵。","莲子泡三十分钟，去掉莲心；红枣去核。","银耳和莲子放入砂锅，加1500毫升水烧开转小火炖六十分钟。","下红枣和冰糖，继续小火炖二十分钟至汤汁黏稠拉丝。","关火前放枸杞焖五分钟，温热或放凉后食用。"],"tip":"银耳撕得越碎越容易出胶，冷水泡发比热水泡更脆爽。"},{"name":"炸酱面","cat":"主食","region":"家常","time":35,"diff":"中等","main":[["面条","250g"],["五花肉","150g"],["黄瓜","1根"],["豆芽","100g"]],"sea":["黄豆酱","甜面酱","葱","姜","料酒","白糖","食用油"],"steps":["五花肉切小丁，黄瓜切丝，豆芽焯十秒捞出过凉；黄豆酱与甜面酱按二比一加水调开。","中火少许油下肉丁煸炒三分钟，炒到出油微焦，加葱姜末和料酒炒香。","倒入调好的酱，转小火推炒八分钟，炒到酱色发亮、油酱分离，加半勺白糖提鲜。","面条大火煮熟捞出过凉水，码上黄瓜丝和豆芽，浇两勺炸酱拌匀。"],"tip":"酱要小火慢炒到油酱分离才算到位，火大易苦，中途要不停推铲防糊。"},{"name":"红烧牛肉面","cat":"主食","region":"台","time":120,"diff":"中等","main":[["牛腩","600g"],["面条","300g"],["白萝卜","半根"]],"sea":["葱","姜","豆瓣酱","八角","桂皮","香叶","生抽","老抽"],"steps":["牛腩切三厘米块，冷水下锅加姜片和料酒焯五分钟，撇净血沫捞出冲净。","中火少许油炒香葱姜、八角桂皮香叶，加一勺豆瓣酱炒出红油，下牛肉块翻炒上色。","加生抽老抽和足量开水没过牛肉，大火烧开转小火炖九十分钟，放白萝卜块再炖二十分钟。","面条另锅煮熟捞进碗里，浇上滚烫牛肉汤和牛肉块，撒葱花。"],"tip":"炖牛肉一次加足开水，中途添冷水会让肉质发紧，汤也不够浓。"},{"name":"打卤面","cat":"主食","region":"鲁","time":40,"diff":"中等","main":[["面条","250g"],["猪里脊","150g"],["木耳","20g"],["黄花菜","20g"],["鸡蛋","2个"]],"sea":["葱","姜","生抽","老抽","淀粉","花椒","盐","食用油"],"steps":["木耳和黄花菜提前泡发洗净，木耳撕小朵；里脊切片加淀粉和料酒抓匀腌十分钟。","中火放油下肉片滑炒到变白盛出，锅里下葱姜和几粒花椒炒香，再下木耳黄花菜翻炒。","加生抽老抽和三碗清水烧开，倒回肉片煮五分钟，淋水淀粉勾到汤汁浓稠挂勺。","转小火把蛋液沿锅边淋成蛋花，加盐调味；面条煮熟捞出，浇上卤汁。"],"tip":"卤子要勾到浓稠挂勺，蛋花在汤汁微沸时沿锅边淋，才能成大片。"},{"name":"肉丝炒面","cat":"主食","region":"家常","time":25,"diff":"中等","main":[["面条","250g"],["猪里脊","150g"],["包菜","150g"],["胡萝卜","半根"]],"sea":["生抽","老抽","葱","蒜","料酒","淀粉","食用油","盐"],"steps":["里脊切细丝加料酒和淀粉抓匀腌十分钟；面条煮到八分熟捞出过凉水沥干拌少许油。","大火热锅多放油，下肉丝快速滑炒到变白盛出，锅里下葱蒜爆香。","下包菜丝和胡萝卜丝大火炒一分钟至稍软，倒入面条用锅铲抖散翻炒。","淋生抽老抽，倒回肉丝，大火颠炒两分钟到面条干香上色，加盐出锅。"],"tip":"面先煮八分熟拌油再炒，全程大火快翻，才不粘锅、不断条。"},{"name":"刀削面","cat":"主食","region":"西北","time":90,"diff":"较难","main":[["面粉","500g"],["五花肉","200g"],["西红柿","1个"]],"sea":["葱","姜","八角","生抽","老抽","盐","食用油"],"steps":["面粉加一小勺盐和约二百克冷水揉成偏硬面团，盖布醒三十分钟后再揉两遍至光滑。","五花肉切小丁，中火下锅煸炒三分钟出油，加葱姜八角炒香，下西红柿丁炒出汁。","加生抽老抽和两碗水烧开，转小火炖四十分钟成肉臊，加盐调味。","锅烧宽水大火，左手托面团右手持刀削成厚薄均匀的薄片，直接削入滚水。","面片全部浮起后再煮一分钟捞出，浇肉臊和面汤即可。"],"tip":"面团要和得硬、醒得透，削时刀口贴着面往前推，片才薄而不粘。"},{"name":"兰州牛肉面","cat":"主食","region":"西北","time":150,"diff":"中等","main":[["牛腩","500g"],["面条","250g"],["白萝卜","半根"]],"sea":["葱","姜","花椒","八角","桂皮","盐","辣椒油","香菜"],"steps":["牛腩切大块冷水下锅焯五分钟撇净浮沫；白萝卜切片，香菜切末。","牛肉加葱姜、花椒八角桂皮和足量清水，大火烧开转小火炖两小时。","捞出牛肉晾凉切片，汤过滤后加白萝卜片煮十分钟，加盐调成清汤。","面条大火煮两分钟捞进碗里，浇清汤，铺牛肉片和萝卜片，淋辣椒油撒香菜。"],"tip":"汤全程小火保持微沸才清亮，盐最后放，牛肉才不柴不发死。"},{"name":"河南烩面","cat":"主食","region":"家常","time":100,"diff":"较难","main":[["面粉","400g"],["羊肉","300g"],["海带","50g"],["豆皮","100g"],["粉丝","50g"]],"sea":["葱","姜","盐","白胡椒","香菜","食用油"],"steps":["面粉加淡盐水和成软面团，反复揉十分钟后搓条抹油，盖膜醒一小时。","羊肉切块冷水下锅焯净，换清水加葱姜大火烧开，转小火炖一小时至汤色乳白。","海带切丝，豆皮切丝，粉丝泡软，一起下羊汤煮五分钟，加盐和白胡椒调味。","面团扯成宽面片下滚汤煮三分钟，浮起后连汤带料盛碗，撒香菜。"],"tip":"面醒足一小时才扯得开，下锅前先压扁再抖长，厚薄才均匀。"},{"name":"重庆小面","cat":"主食","region":"川","time":20,"diff":"简单","main":[["面条","200g"],["油菜","100g"],["花生米","40g"]],"sea":["辣椒油","花椒粉","芝麻酱","蒜","姜","生抽","醋","葱"],"steps":["碗里放蒜姜水、生抽、醋、花椒粉、一勺芝麻酱和两勺辣椒油，调成红汤料底。","花生米冷油小火炸三分钟捞出拍碎；油菜下开水烫二十秒捞出。","面条大火煮两分钟，先舀一勺面汤冲进碗里把料化开，再捞面入碗。","铺上油菜，撒花生碎和葱花，吃前从碗底往上翻拌均匀。"],"tip":"调料先用滚面汤冲开，面和料才拌得匀，麻辣味也更透。"},{"name":"宜宾燃面","cat":"主食","region":"川","time":25,"diff":"中等","main":[["面条","200g"],["芽菜","50g"],["花生米","50g"]],"sea":["辣椒油","花椒粉","生抽","葱","香油","猪油"],"steps":["芽菜洗净挤干切碎，中火少许猪油炒三分钟至干香盛出；花生米炸酥压成碎粒。","碗里放生抽、辣椒油、花椒粉和一小勺猪油调成料底。","面条大火煮到刚断生捞出，彻底沥干水分，趁热倒进碗里拌料。","拌到面条油亮不粘连，撒芽菜碎、花生碎和葱花即可。"],"tip":"燃面是干拌，面捞出必须沥到不见水，油和料才挂得住不澥。"},{"name":"小锅米线","cat":"主食","region":"云南","time":25,"diff":"简单","main":[["米粉","200g"],["猪肉末","100g"],["韭菜","50g"],["酸菜","50g"]],"sea":["豆瓣酱","生抽","辣椒油","盐","猪油","葱"],"steps":["米粉温水泡二十分钟；韭菜切段，酸菜切碎，猪肉末加少许生抽抓匀。","小锅放猪油中火烧化，下肉末炒散到变色，加豆瓣酱和酸菜碎炒一分钟出香。","倒入两碗开水大火烧开，下米粉煮三分钟，加盐和辣椒油调味。","最后放韭菜段烫二十秒，连汤盛出撒葱花。"],"tip":"用猪油起锅汤才香，韭菜最后放，烫软即出才能保住辛香。"},{"name":"担仔面","cat":"主食","region":"台","time":25,"diff":"简单","main":[["面条","200g"],["猪肉末","100g"],["虾","100g"]],"sea":["蒜","生抽","醋","猪油","香菜","盐"],"steps":["蒜切末，虾去壳留尾；碗里放蒜末、生抽、醋和一点盐调成底料。","中火放猪油化开，下肉末炒散炒到干香，加生抽炒匀成肉臊盛出。","虾下锅煎到两面变红盛出；面条大火煮两分钟捞出。","面汤舀两勺冲进碗里化开底料，放面条、肉臊和虾，撒香菜末。"],"tip":"担仔面讲小碗少量，肉臊要炒干香，汤只浇两勺，味才浓不寡。"},{"name":"雪菜肉丝面","cat":"主食","region":"淮扬","time":25,"diff":"简单","main":[["面条","200g"],["猪里脊","150g"],["雪里蕻","100g"]],"sea":["葱","姜","料酒","淀粉","生抽","盐","食用油"],"steps":["雪里蕻洗净挤干切碎，里脊切丝加料酒和淀粉抓匀腌十分钟。","中火放油下肉丝滑炒到变白盛出，锅里下葱姜末炒香，倒入雪里蕻炒两分钟。","加两碗清水大火烧开，倒回肉丝煮三分钟，加生抽和盐调好咸淡。","面条另锅煮熟捞进碗里，浇上雪菜肉丝汤即可。"],"tip":"雪里蕻本身带咸味，先泡十分钟去咸，盐最后尝过再放。"},{"name":"鸡丝凉面","cat":"主食","region":"家常","time":30,"diff":"简单","main":[["面条","200g"],["鸡胸肉","150g"],["黄瓜","1根"],["花生米","40g"]],"sea":["芝麻酱","醋","生抽","辣椒油","蒜","白糖","香油"],"steps":["鸡胸肉冷水下锅加姜片煮十二分钟，捞出晾凉后顺纹理撕成细丝。","黄瓜切丝，花生米炸酥压碎；面条煮到八分熟捞出过凉水，沥干拌香油。","芝麻酱用温水澥开，加生抽、醋、蒜末、白糖和辣椒油调成凉面汁。","面条装碗，铺鸡丝和黄瓜丝，浇凉面汁，撒花生碎拌匀。"],"tip":"面过凉水后必须拌香油抖散，凉了也不粘连；汁要稠些才挂面。"},{"name":"蒸卤面","cat":"主食","region":"家常","time":60,"diff":"中等","main":[["面条","300g"],["五花肉","200g"],["豆角","200g"],["豆芽","100g"]],"sea":["葱","姜","八角","生抽","老抽","盐","食用油"],"steps":["面条抖散铺在笼布上，大火上汽后蒸十五分钟取出抖开。","五花肉切片，豆角掰段；中火少油下肉片煸出油，加葱姜八角炒香。","下豆角和豆芽翻炒两分钟，加生抽老抽和两碗水烧开，加盐调味。","把蒸好的面条放进汤汁里翻拌吸汁，再回笼大火蒸十分钟至面条软透。"],"tip":"面先蒸后拌汁再回蒸，吸汁均匀不夹生；汤汁别没过面条，拌到润而不涝。"},{"name":"猪肉白菜饺子","cat":"主食","region":"东北","time":70,"diff":"中等","main":[["饺子皮","500g"],["猪肉末","300g"],["大白菜","半棵"]],"sea":["葱","姜","生抽","老抽","盐","香油","食用油","五香粉"],"steps":["大白菜剁碎，撒10g盐抓匀腌15分钟，用纱布包住挤干水分。","猪肉末加葱姜末、两勺生抽、半勺老抽和五香粉，顺一个方向搅匀。","分三次加入三勺清水，每次都搅到水被吸收、肉馅发黏上劲。","拌入白菜碎，淋香油和食用油拌匀，馅料冷藏20分钟更好包。","饺子皮放馅对折，捏紧边缘并捏出褶子，摆在撒了面粉的案板上。","水大开下饺子，勺背推散，点两次凉水，饺子鼓胀浮起即熟。"],"tip":"白菜先杀水再拌油，馅才不出汤；肉馅打水要顺同一方向搅。"},{"name":"韭菜鸡蛋饺子","cat":"主食","region":"家常","time":45,"diff":"简单","main":[["饺子皮","400g"],["韭菜","300g"],["鸡蛋","4个"]],"sea":["盐","食用油","香油","白胡椒"],"steps":["鸡蛋打散加少许盐，热锅多放油炒成碎蛋块，盛出晾凉后剁碎。","韭菜洗净沥干切末，先拌两勺食用油封住切口，防止出水。","韭菜与蛋碎混合，加盐和白胡椒，临包前再淋香油拌匀。","饺子皮包入馅料，捏紧封口，边缘捏薄一些更容易煮熟。","水开下锅煮，浮起后点一次凉水，再开锅煮1分钟捞出。"],"tip":"韭菜一定最后放盐，先用油封口才不出水，煮三个开就够。"},{"name":"三鲜馅饺子","cat":"主食","region":"家常","time":50,"diff":"中等","main":[["饺子皮","400g"],["猪肉末","200g"],["虾仁","150g"],["韭菜","100g"]],"sea":["葱","姜","生抽","盐","香油","白胡椒","料酒","淀粉"],"steps":["虾仁去虾线切小丁，加料酒、白胡椒和半勺淀粉抓匀腌10分钟。","猪肉末加葱姜水、生抽和盐，顺一个方向搅打到黏稠上劲。","拌入虾仁丁和韭菜末，淋香油后轻轻翻拌均匀成馅。","饺子皮包馅捏紧，水开下锅，用漏勺背推散防止粘底。","煮到饺子浮起鼓胀，点两次凉水，第三次开锅即捞出。"],"tip":"虾仁切丁别剁成泥，吃到颗粒才鲜；肉馅打水后冷藏更抱团。"},{"name":"芹菜猪肉饺子","cat":"主食","region":"家常","time":55,"diff":"简单","main":[["饺子皮","400g"],["猪肉末","250g"],["芹菜","300g"]],"sea":["葱","姜","生抽","盐","香油","食用油","五香粉"],"steps":["芹菜去叶切细末，入开水焯20秒捞出过凉，用手挤干水分。","猪肉末加葱姜末、生抽、盐和五香粉，分两次加清水搅上劲。","拌入芹菜末，淋香油和食用油，拌匀后冷藏15分钟。","包成月牙饺，捏紧封口，摆盘时留出空隙防止粘连。","水开下饺子，中火煮开点凉水两次，饺子鼓起漂浮即熟。"],"tip":"芹菜焯水后挤干，香气更纯也不出汤；肉馅肥三瘦七最润。"},{"name":"西葫芦鸡蛋饺子","cat":"主食","region":"家常","time":45,"diff":"简单","main":[["饺子皮","400g"],["西葫芦","1个"],["鸡蛋","3个"]],"sea":["葱","盐","食用油","香油","白胡椒"],"steps":["西葫芦擦成细丝，撒5g盐腌10分钟，双手挤干水分后剁碎。","鸡蛋加少许盐打散，热锅凉油炒成蛋碎，盛出摊开晾凉。","西葫芦、蛋碎加葱花、白胡椒和香油拌匀成馅。","饺子皮放馅对折，捏紧边缘并捏出花边封严。","水开下锅煮，浮起后点一次凉水，再开锅煮1分钟捞出。"],"tip":"西葫芦务必挤干水，馅里先拌油再放盐，煮时才不破皮。"},{"name":"酸菜猪肉饺子","cat":"主食","region":"东北","time":60,"diff":"中等","main":[["饺子皮","400g"],["猪肉末","300g"],["酸菜","400g"]],"sea":["葱","姜","生抽","盐","食用油","香油","五香粉"],"steps":["酸菜切细丝再剁碎，清水抓洗两遍后挤干，去掉过重的酸味。","猪肉末加葱姜末、生抽和五香粉，分次加清水搅到发黏。","拌入酸菜碎，加食用油和香油拌匀，尝味后再补盐。","包成饱满的元宝饺，捏紧边口，案板撒面粉防粘。","水开下饺子，中火点凉水三次，饺子鼓胀浮起即熟。"],"tip":"酸菜要多洗两遍再挤干，拌馅时油给足，酸香才不寡。"},{"name":"羊肉胡萝卜饺子","cat":"主食","region":"西北","time":65,"diff":"中等","main":[["饺子皮","400g"],["羊肉","300g"],["胡萝卜","2根"]],"sea":["葱","姜","花椒粉","盐","生抽","料酒","香油","食用油"],"steps":["羊肉切小块剁成馅，加料酒、花椒粉和姜末腌15分钟去膻。","胡萝卜擦丝剁碎，热锅少油炒软，盛出摊开晾凉。","羊肉馅分三次打入花椒水，顺一个方向搅到黏稠拉丝。","拌入胡萝卜碎和葱花，加盐、生抽、香油拌匀，冷藏20分钟。","饺子皮包馅捏紧，水开下锅点三次凉水，浮起鼓胀即熟。"],"tip":"花椒水是去膻关键，分三次打进肉馅，羊肉才嫩而不柴。"},{"name":"韭菜盒子","cat":"主食","region":"家常","time":60,"diff":"中等","main":[["面粉","300g"],["韭菜","300g"],["鸡蛋","3个"]],"sea":["盐","食用油","香油","白胡椒"],"steps":["面粉用80度热水烫成絮状，揉成光滑面团，盖布醒30分钟。","鸡蛋炒成碎块晾凉，韭菜切末先拌油封口，再混合加盐调味。","面团搓条切剂，擀成圆薄皮，铺一半馅料后对折压实边口。","平底锅刷油烧到五成热，放入盒子用中小火煎3分钟。","底面金黄后翻面，再煎2分钟，两面焦脆鼓起即可出锅。"],"tip":"烫面皮软不易破，边口捏紧后压一圈花边，煎时就不漏馅。"},{"name":"牛肉洋葱馅饼","cat":"主食","region":"家常","time":70,"diff":"中等","main":[["面粉","300g"],["牛肉末","300g"],["洋葱","1个"]],"sea":["葱","姜","生抽","老抽","盐","食用油","白胡椒","香油"],"steps":["面粉加温水揉成偏软的面团，表面抹油盖好醒40分钟。","洋葱切末，牛肉末加姜末、生抽、老抽和白胡椒搅上劲。","拌入洋葱末，淋香油和食用油，冷藏15分钟让馅定型。","面团分剂擀成中间厚边缘薄的皮，包馅收口后按成圆饼。","平底锅刷油小火烙，每面3分钟，饼皮金黄鼓起即熟。"],"tip":"面团和得软、醒得足，饼皮才薄而不硬；洋葱最后拌不出水。"},{"name":"猪肉大葱包子","cat":"主食","region":"鲁","time":150,"diff":"中等","main":[["面粉","500g"],["猪肉末","400g"],["葱","200g"]],"sea":["酵母","姜","生抽","老抽","盐","五香粉","香油","食用油"],"steps":["酵母用温水化开，倒入面粉揉成光滑面团，盖好发到两倍大。","猪肉末加姜末、生抽、老抽和五香粉，分次加水搅上劲。","葱切碎拌入肉馅，淋香油和食用油，放冰箱冷藏备用。","面团排气搓条切剂，擀成中间厚边缘薄的皮，包馅捏褶收口。","包子摆入蒸笼二次醒发20分钟，水开后大火蒸15分钟。","关火别急着开盖，焖3分钟再揭盖取出，皮不塌不回缩。"],"tip":"二发到指按能回弹再上锅，蒸好焖3分钟，包子皮才白胖不塌。"},{"name":"香菇油菜包子","cat":"主食","region":"家常","time":140,"diff":"中等","main":[["面粉","500g"],["香菇","200g"],["油菜","400g"]],"sea":["酵母","葱","姜","生抽","蚝油","盐","香油","食用油"],"steps":["面粉加酵母水和成面团，盖好放温暖处发至两倍大。","油菜焯水10秒过凉挤干剁碎，香菇切小丁下锅炒出香味。","香菇丁、油菜碎加葱姜末、生抽、蚝油和盐拌匀，淋香油。","面团排气切剂擀皮，包入馅料捏褶收口，摆入蒸笼。","醒发20分钟后大火蒸12分钟，关火焖2分钟再开盖。"],"tip":"素馅先把香菇炒香再拌，油菜焯后挤干水，包子才不塌底。"},{"name":"生煎包","cat":"主食","region":"本帮","time":90,"diff":"较难","main":[["面粉","400g"],["猪肉末","300g"],["葱","50g"],["白芝麻","20g"]],"sea":["酵母","姜","生抽","白糖","料酒","食用油","香油","盐"],"steps":["面粉加酵母、少许白糖和温水揉成面团，醒发30分钟至半发。","猪肉末加姜末、生抽、料酒和白糖搅上劲，拌入葱花和香油。","面团排气切剂擀成圆皮，包入肉馅，收口朝下按成小包。","平底锅刷油摆入包子，中火煎到底部微黄定型。","沿锅边淋清水到包子三分之一高，盖盖中小火焖8分钟。","水干听到滋滋声时淋一勺油，撒芝麻葱花，煎到底脆出锅。"],"tip":"生煎用半发面，水煎到滋滋响再开盖，底才焦脆不发软。"},{"name":"灌汤包","cat":"主食","region":"淮扬","time":180,"diff":"较难","main":[["面粉","400g"],["猪肉末","300g"],["猪皮","200g"]],"sea":["葱","姜","盐","生抽","料酒","白胡椒","香油","淀粉"],"steps":["猪皮焯水刮净油脂切条，加葱姜和清水小火煮90分钟至软烂。","滤出汤汁冷藏成皮冻，取出切碎后与猪肉末混合。","肉馅加盐、生抽、料酒、白胡椒和淀粉，顺一个方向搅上劲。","拌入皮冻碎和香油，冷藏30分钟让馅料抱团好包。","面粉加温水揉成偏硬面团，醒30分钟后擀成极薄的圆皮。","包馅捏出18个褶收口，水开后大火蒸8分钟，趁热上桌。"],"tip":"皮冻和肉馅按一比一拌，皮擀得薄而匀，蒸过头就会破汤。"},{"name":"豆沙包","cat":"甜点","region":"家常","time":130,"diff":"中等","main":[["面粉","400g"],["红豆","250g"],["白糖","80g"]],"sea":["酵母","猪油","食用油"],"steps":["红豆提前泡4小时，加水煮40分钟至一捏就烂，沥去多余水。","红豆趁热压成泥，加白糖和两勺猪油，小火炒到能抱团成球。","面粉加酵母水和面，发至两倍大，排气切剂擀成圆皮。","包入豆沙球，收口朝下搓圆，摆入蒸笼醒发20分钟。","水开后大火蒸15分钟，关火焖3分钟再开盖取出。"],"tip":"豆沙炒到不粘铲、能捏成团才好包，糖量按豆沙干湿调整。"},{"name":"奶黄包","cat":"甜点","region":"粤","time":120,"diff":"较难","main":[["面粉","400g"],["鸡蛋","3个"],["牛奶","200g"],["黄油","60g"]],"sea":["酵母","白糖","淀粉"],"steps":["鸡蛋加白糖打散，倒入牛奶和筛过的淀粉，搅成无颗粒的糊。","奶糊倒进不粘锅，加黄油小火不停搅，炒到浓稠抱团离火。","奶黄馅摊开晾凉，分成小份搓圆，冷藏备用。","面粉加酵母和温水和面，发至两倍大后排气切剂。","面团擀皮包入奶黄馅，收口朝下搓圆，醒发20分钟。","水开上锅大火蒸12分钟，关火焖2分钟再揭盖。"],"tip":"炒奶黄全程小火不停搅，能抱团不粘锅才算到位，火大易糊。"},{"name":"糖三角","cat":"甜点","region":"家常","time":110,"diff":"简单","main":[["面粉","400g"],["红糖","100g"],["白芝麻","20g"]],"sea":["酵母","食用油"],"steps":["面粉加酵母温水揉成光滑面团，盖好发至两倍大。","红糖加两勺面粉和白芝麻拌成馅，防止蒸时糖汁外流。","面团排气搓条切剂，擀成圆片，放糖馅后捏成三角形。","三条边逐条压紧，捏出花边，醒发20分钟摆入蒸笼。","水开后大火蒸15分钟，关火焖3分钟再开盖。"],"tip":"红糖里拌面粉能收住糖汁，三条边压实，蒸时才不流糖。"},{"name":"锅贴","cat":"主食","region":"家常","time":50,"diff":"中等","main":[["饺子皮","400g"],["猪肉末","300g"],["大白菜","300g"]],"sea":["葱","姜","生抽","盐","食用油","香油","淀粉","白芝麻"],"steps":["大白菜剁碎加盐腌10分钟，挤干水后与猪肉末混合。","加葱姜末、生抽、盐和香油，顺一个方向搅到馅料发黏。","饺子皮放馅，只捏中间封口，两头留口成锅贴生坯。","平底锅刷油码入锅贴，中火煎1分钟到底部定型。","淋面粉水到锅贴三分之一高，盖盖中小火焖6分钟。","水干后淋一勺油，撒芝麻，再煎1分钟到底部金黄酥脆。"],"tip":"面粉水按一比十调，收干后淋油，冰花底才脆而不糊。"},{"name":"春卷","cat":"主食","region":"家常","time":60,"diff":"中等","main":[["春卷皮","10张"],["猪里脊","150g"],["豆芽","200g"],["韭菜","100g"],["粉丝","50g"]],"sea":["葱","姜","生抽","盐","淀粉","食用油"],"steps":["粉丝温水泡软剪段，豆芽掐去根，韭菜切段，猪里脊切细丝。","肉丝加生抽和淀粉抓匀，热锅热油滑炒到变色盛出。","锅中留油炒豆芽1分钟，下粉丝、肉丝和韭菜，加盐炒匀。","馅料盛出彻底晾凉，倒掉多余汤汁再开始包。","春卷皮铺平放馅，先折两边再卷紧，接口抹淀粉水粘牢。","油温六成热下春卷，中小火炸3分钟至金黄，捞出沥油。"],"tip":"馅必须晾凉再包，接口用淀粉水粘实，炸时才不裂不溅油。"},{"name":"豆沙春卷","cat":"甜点","region":"家常","time":60,"diff":"简单","main":[["春卷皮","10张"],["红豆","200g"],["白糖","60g"]],"sea":["食用油","淀粉","猪油"],"steps":["红豆泡4小时后煮40分钟至软烂，沥水后压成细腻的豆泥。","豆泥加白糖和猪油，小火炒到干爽抱团，盛出晾凉。","豆沙搓成小长条，春卷皮放馅后两边折起卷紧。","接口抹淀粉水封住，逐个卷好摆在盘中。","油温五成热下春卷，中小火慢炸4分钟，不断翻动。","炸到表皮金黄起泡捞出，放厨房纸上吸去浮油。"],"tip":"豆沙要炒到干爽抱团再包，油温别高，慢炸才酥透且不爆皮。"},{"name":"糯米烧麦","cat":"主食","region":"淮扬","time":80,"diff":"中等","main":[["饺子皮","20张"],["糯米","200g"],["猪肉末","100g"],["香菇","5朵"]],"sea":["葱","姜","生抽","老抽","白糖","盐","食用油","香油"],"steps":["糯米提前泡2小时，上锅大火蒸25分钟至熟透，取出晾凉。","热锅少油炒香葱姜末，下猪肉末炒散，加香菇丁炒软。","倒入糯米饭，加生抽、老抽、白糖和盐，中火翻炒上色。","饺子皮边缘擀薄成荷叶边，包入糯米馅，虎口收拢捏出花口。","烧麦摆入蒸笼，水开后大火蒸10分钟，出锅刷一层香油。"],"tip":"糯米蒸比煮更粒粒分明，馅晾到温热再包，皮才不塌。"},{"name":"葱油花卷","cat":"主食","region":"家常","time":120,"diff":"中等","main":[["面粉","500g"],["葱","100g"]],"sea":["酵母","盐","食用油","五香粉"],"steps":["面粉加酵母温水揉成光滑面团，盖好放温暖处发至两倍大。","葱切细末，加盐、五香粉和两勺食用油拌成葱油馅。","面团排气擀成长方形薄片，抹匀葱油后卷成筒状。","卷好的筒切成小段，两段叠起用筷子从中间压到底。","抽出筷子，双手拉长后反向拧一圈，收口压在底下成花卷。","花卷醒发20分钟，水开后大火蒸12分钟，焖3分钟开盖。"],"tip":"面片擀薄、葱油抹匀，拧出的层次才分明；二发千万别省。"},{"name":"手抓饼","cat":"主食","region":"台","time":20,"diff":"简单","main":[["手抓饼","4张"],["鸡蛋","4个"],["生菜","4片"],["火腿","2片"]],"sea":["食用油","番茄酱","盐"],"steps":["平底锅烧热不放油，取一张手抓饼中小火烙2分钟至鼓起。","翻面后打入一个鸡蛋，用铲子摊开铺满整个饼面，撒少许盐。","蛋液半凝固时再翻面，让蛋皮贴锅煎30秒至定型。","火腿片下锅煎到两边微焦，生菜洗净沥干水分。","饼上刷番茄酱，铺生菜和火腿，卷起对折即可食用。"],"tip":"饼不用解冻直接下锅，中小火烙到两面起酥，蛋才嫩。"},{"name":"葱油饼","cat":"主食","region":"本帮","time":70,"diff":"中等","main":[["面粉","400g"],["葱","100g"]],"sea":["盐","食用油","五香粉","猪油"],"steps":["面粉加温水揉成软面团，表面抹油盖好醒40分钟。","葱切末，两勺面粉加盐和五香粉，浇上热油调成油酥。","面团擀成薄大片，抹匀油酥撒上葱花，卷起后盘成圆饼。","饼坯按扁擀成圆片，平底锅刷油中小火烙3分钟。","底面金黄后翻面再烙2分钟，用铲子从边往中间推松层次。"],"tip":"油酥要用热油泼才香，饼擀薄、火别大，层次才能层层起酥。"},{"name":"鸡蛋灌饼","cat":"主食","region":"家常","time":50,"diff":"中等","main":[["面粉","300g"],["鸡蛋","4个"],["生菜","4片"]],"sea":["盐","食用油","甜面酱","葱"],"steps":["面粉加温水揉成软面团，抹油醒30分钟，分剂擀成长条。","面片抹油撒盐，从一头卷起后压扁，再擀成圆饼。","平底锅刷薄油中小火烙饼，鼓起大泡时用筷子挑开一个口。","鸡蛋加葱花和盐打散，从口子灌入饼内，捏住口继续烙。","两面烙到金黄，刷甜面酱，放生菜卷起即可。"],"tip":"饼鼓泡时立刻挑口灌蛋，火小一点，蛋液才不会流出。"},{"name":"土豆丝饼","cat":"主食","region":"家常","time":30,"diff":"简单","main":[["土豆","2个"],["面粉","80g"],["鸡蛋","1个"]],"sea":["葱","盐","白胡椒","食用油","五香粉"],"steps":["土豆去皮擦成细丝，不洗以保留淀粉，加盐抓匀腌5分钟。","拌入面粉、鸡蛋、葱花、白胡椒和五香粉，搅成黏稠糊状。","平底锅刷油烧热，舀一勺土豆丝糊摊成薄圆饼。","中小火煎3分钟至底面金黄定型，翻面再煎2分钟。","出锅前转大火煎10秒逼出油分，切块装盘。"],"tip":"土豆丝别过水，靠自身淀粉黏合，饼才不散；摊得薄更脆。"},{"name":"萝卜丝饼","cat":"主食","region":"淮扬","time":45,"diff":"简单","main":[["白萝卜","1个"],["面粉","150g"],["虾皮","20g"]],"sea":["葱","盐","白胡椒","食用油","香油"],"steps":["白萝卜擦丝，加5g盐腌10分钟，挤干水分后剁几刀。","萝卜丝加虾皮、葱花、白胡椒和香油拌成馅。","面粉加温水揉成软面团，醒20分钟后分剂擀成薄圆皮。","包入萝卜丝馅收口按扁，平底锅刷油中小火烙3分钟。","翻面再烙2分钟，饼皮透亮鼓起即可出锅。"],"tip":"萝卜丝挤得越干越香，虾皮本身有咸味，盐要少放。"},{"name":"南瓜饼","cat":"甜点","region":"家常","time":40,"diff":"简单","main":[["南瓜","300g"],["糯米粉","200g"],["白芝麻","30g"]],"sea":["白糖","食用油"],"steps":["南瓜去皮切片，上锅大火蒸15分钟至筷子一戳就烂。","趁热压成泥，加白糖和糯米粉，揉成不粘手的面团。","面团分剂搓圆按扁，两面蘸水后裹上白芝麻。","平底锅刷油，小火放入南瓜饼煎4分钟至底面金黄。","翻面再煎3分钟，饼身鼓起、按压回弹即可出锅。"],"tip":"南瓜泥要趁热和粉，水分足才软糯；小火慢煎免外焦里生。"},{"name":"芝麻烧饼","cat":"主食","region":"家常","time":70,"diff":"中等","main":[["面粉","400g"],["芝麻酱","80g"],["白芝麻","50g"]],"sea":["酵母","盐","食用油","五香粉"],"steps":["面粉加酵母和温水揉成面团，醒30分钟至半发。","芝麻酱加盐、五香粉和两勺食用油调稀，方便均匀抹开。","面团擀成大片，抹匀芝麻酱后卷起切段，两端收口按成饼。","饼面刷一层水，蘸满白芝麻按实，再稍擀薄一点。","平底锅刷油小火烙，每面3分钟至芝麻香脆、饼身鼓起。"],"tip":"麻酱用油调稀才好抹匀，蘸芝麻后按实，烙时不易脱落。"},{"name":"蛋炒饭","cat":"主食","region":"家常","time":15,"diff":"简单","main":[["米饭","400g"],["鸡蛋","3个"]],"sea":["葱","盐","生抽","食用油"],"steps":["米饭放凉后用勺子背压散，冷藏半小时让表层水分收干，米粒炒时才不粘连。","鸡蛋磕入碗中打散，加两指捏的盐搅匀，锅烧热倒三勺油，油面微冒烟时倒入蛋液。","中火用筷子把蛋液划散成小块，刚凝固就盛出，锅中留底油转大火下米饭。","米饭摊开用铲背压散，不停翻炒三分钟，米粒在锅里跳动、表面泛油光即可。","倒回鸡蛋，沿锅边淋一勺生抽，大火炒三十秒，撒葱花翻两下关火出锅。"],"tip":"米饭提前冷藏、下锅前用手抓散，比现蒸的饭更适合炒，粒粒分明不出水。"},{"name":"扬州炒饭","cat":"主食","region":"淮扬","time":25,"diff":"中等","main":[["米饭","400g"],["鸡蛋","2个"],["虾仁","100g"],["火腿","50g"],["豌豆","50g"]],"sea":["葱","盐","料酒","淀粉","食用油"],"steps":["虾仁挑去泥肠，加半勺盐、一勺料酒和半勺淀粉抓匀，腌十分钟去腥上浆。","火腿切小方丁，豌豆入沸水焯一分钟捞出过凉，鸡蛋磕入碗中打散备用。","锅烧热下三勺油，中火把虾仁炒到卷曲变粉红盛出，再倒蛋液炒成碎粒。","锅中补一勺油转大火下米饭，边压边炒两分钟，米粒散开后加火腿丁和豌豆。","倒回虾仁和鸡蛋，加盐调味，大火翻炒一分钟至米粒干爽跳动，撒葱花出锅。"],"tip":"虾仁先上浆滑炒再回锅，米饭用偏干的隔夜饭，炒出来才干爽不黏。"},{"name":"腊肠煲仔饭","cat":"主食","region":"粤","time":45,"diff":"中等","main":[["大米","200g"],["香肠","2根"],["油菜","4棵"]],"sea":["生抽","老抽","白糖","香油","食用油"],"steps":["大米淘洗两遍后加清水泡二十分钟，米粒发白胀大时捞出沥干备用。","砂锅内壁刷一层油，倒入大米和没过米面一指的清水，中火煮开后转小火。","水面收到与米齐平时铺上斜切的香肠片，盖盖用小火焖十二分钟。","沿锅边淋一勺油，转中小火再焖五分钟，听到锅底轻微噼啪声就成锅巴了。","油菜焯水后摆入锅中，生抽老抽白糖加两勺水调匀淋上，关火焖两分钟。"],"tip":"沿锅边淋油是锅巴酥脆的关键，火别大，闻到焦香就离火，免得糊底。"},{"name":"香菇滑鸡饭","cat":"主食","region":"粤","time":50,"diff":"中等","main":[["大米","200g"],["鸡腿","2个"],["香菇","6朵"]],"sea":["姜","葱","生抽","蚝油","淀粉","料酒","食用油"],"steps":["鸡腿去骨切两厘米见方的块，加生抽、蚝油、料酒和淀粉抓匀，腌十五分钟。","香菇去蒂切厚片，砂锅下油爆香姜片，倒香菇片炒到边缘微黄、香味出来。","大米淘净铺在香菇上，加没过米面一指的水，中火煮开后转小火焖十分钟。","米饭表面出现蜂窝状小孔时铺上鸡块，盖盖用小火焖八分钟至鸡肉变白。","关火焖三分钟，淋一勺生抽撒葱花，连锅底锅巴一起拌匀盛出。"],"tip":"鸡肉铺在饭面后别再翻动，靠蒸汽焖熟才嫩，锅底那层焦饭拌进去最香。"},{"name":"窝蛋牛肉煲仔饭","cat":"主食","region":"粤","time":55,"diff":"中等","main":[["大米","200g"],["牛肉","200g"],["鸡蛋","1个"]],"sea":["生抽","蚝油","淀粉","食用油","姜","香油","白糖","葱"],"steps":["牛肉逆纹切薄片，加生抽、蚝油、淀粉和一勺水抓到发黏，再淋一勺油封住腌二十分钟。","大米泡二十分钟后放入砂锅，加没过米面一指的水，中火煮开转小火焖到表面收干。","牛肉片摊在饭面上，盖盖用中小火焖六分钟，肉片刚变褐还没全熟时开盖。","在饭中间挖个小坑打入鸡蛋，沿锅边淋一圈油，盖盖小火焖两分钟至蛋白凝固。","生抽白糖香油加两勺水调成豉油淋上，撒葱花关火再焖一分钟。"],"tip":"蛋要最后两分钟才打，蛋黄半流心拌饭最滑，煎到全熟就失了窝蛋的意思。"},{"name":"豉汁排骨煲仔饭","cat":"主食","region":"粤","time":60,"diff":"中等","main":[["大米","200g"],["排骨","300g"]],"sea":["豆豉","蒜","生抽","蚝油","淀粉","白糖","食用油"],"steps":["排骨剁成三厘米长的段，冷水泡十分钟去血水，捞出用厨房纸反复吸干水分。","豆豉和蒜剁碎，加生抽、蚝油、白糖、淀粉和排骨抓匀，腌二十分钟。","大米泡好后入砂锅加水，中火煮开转小火，焖到水面与米面齐平。","排骨平铺在饭上，盖盖用中小火焖十五分钟，筷子能轻松扎透即成。","关火焖三分钟，撒葱花，把锅底锅巴和排骨一起拌匀。"],"tip":"排骨一定吸干水再腌，蒸出来才不出一滩水，豉蒜味也更集中。"},{"name":"咖喱鸡饭","cat":"主食","region":"家常","time":45,"diff":"中等","main":[["米饭","300g"],["鸡腿","2个"],["土豆","1个"],["胡萝卜","半根"],["洋葱","半个"]],"sea":["咖喱块","食用油","盐","料酒"],"steps":["鸡腿去骨切三厘米块，加料酒和半勺盐抓匀，土豆胡萝卜切滚刀块，洋葱切丝。","锅中放油用中火炒洋葱丝到透明发软，下鸡块煎到表面全部变白。","倒土豆和胡萝卜翻炒两分钟，加水没过食材，大火烧开后转中小火煮十五分钟。","关火放入咖喱块搅到完全化开，再开小火煮五分钟，汤汁变稠能挂勺。","米饭盛入盘中压实，把咖喱鸡连汁浇在饭边，趁热拌开吃。"],"tip":"咖喱块要关火后再放，复煮时不停搅底，否则容易糊锅发苦。"},{"name":"西红柿鸡蛋盖浇饭","cat":"主食","region":"家常","time":20,"diff":"简单","main":[["米饭","300g"],["西红柿","2个"],["鸡蛋","3个"]],"sea":["葱","盐","白糖","食用油","淀粉"],"steps":["西红柿顶部划十字，浇开水烫三十秒后剥皮，切成滚刀块，鸡蛋打散加盐搅匀。","热锅倒三勺油烧到微微冒烟，倒入蛋液，中火推炒成大块，刚凝固就盛出。","锅中留底油下西红柿，中火边压边炒三分钟，炒到出红汁、块变软塌。","加半勺白糖和盐，倒小半碗水烧开，淋水淀粉勾薄芡到汤汁微稠。","倒回鸡蛋翻匀，撒葱花关火，连汁一起浇在米饭上。"],"tip":"西红柿先用糖压出汁再勾薄芡，汤汁才挂得住饭，不会渗成汤泡饭。"},{"name":"鱼香肉丝盖饭","cat":"主食","region":"川","time":25,"diff":"中等","main":[["米饭","300g"],["猪里脊","200g"],["木耳","30g"],["胡萝卜","半根"]],"sea":["豆瓣酱","醋","白糖","生抽","淀粉","蒜","姜","葱"],"steps":["猪里脊切细丝，加一勺生抽和半勺淀粉抓匀，淋一勺油封住，腌十分钟。","木耳泡发后切丝，胡萝卜切丝，醋白糖生抽淀粉加三勺清水调成鱼香汁。","锅烧热多放些油，大火滑炒肉丝到变白散开立刻盛出，别在锅里久炒。","留底油用小火炒香蒜姜末和豆瓣酱，出红油后下木耳胡萝卜丝大火炒一分钟。","倒回肉丝，淋鱼香汁大火翻十秒到汁收稠裹住肉丝，撒葱花盖在饭上。"],"tip":"鱼香汁里糖和醋按一比一调，淀粉别多，汁要能裹住肉丝而不流成汤。"},{"name":"麻婆豆腐盖饭","cat":"主食","region":"川","time":20,"diff":"中等","main":[["米饭","300g"],["豆腐","400g"],["猪肉末","100g"]],"sea":["豆瓣酱","花椒粉","蒜","葱","生抽","淀粉","食用油"],"steps":["豆腐切两厘米方块，放入加了盐的沸水焯一分钟，捞出沥干去掉豆腥味。","锅下油中火炒肉末到发干微焦，拨到一边下豆瓣酱和蒜末，小火炒出红油。","加一碗水烧开，轻轻推入豆腐块，中小火煮三分钟让豆腐吃进味。","分两次淋水淀粉，每次都等汤汁变稠再推匀，让汁裹住豆腐不流散。","撒花椒粉和葱花，连汁浇在热米饭上。"],"tip":"豆腐先焯水定形、勾芡分两次，麻辣汁才挂得住，豆腐块也不容易碎。"},{"name":"黄焖鸡米饭","cat":"主食","region":"鲁","time":50,"diff":"中等","main":[["米饭","300g"],["鸡腿","2个"],["香菇","5朵"],["青椒","1个"]],"sea":["姜","干辣椒","生抽","老抽","冰糖","料酒","食用油"],"steps":["鸡腿剁三厘米块，冷水下锅加姜片和料酒煮开，撇净浮沫后捞出冲净。","锅中放少油，小火炒冰糖到起细泡变枣红，倒入鸡块大火翻炒上色。","加姜片干辣椒生抽老抽炒匀，倒开水没过鸡块，大火烧开转中小火炖二十分钟。","下香菇块继续炖八分钟，汤汁收到只剩三分之一、能挂住鸡块。","放青椒块大火翻半分钟至断生，连汤带肉浇在米饭上。"],"tip":"炒糖色全程用小火，糖一冒细泡就下鸡块，颜色红亮还不带苦味。"},{"name":"土豆牛腩盖饭","cat":"主食","region":"家常","time":100,"diff":"较难","main":[["米饭","300g"],["牛腩","400g"],["土豆","2个"],["胡萝卜","1根"]],"sea":["姜","葱","八角","桂皮","生抽","老抽","料酒","盐"],"steps":["牛腩切三厘米块，冷水浸泡二十分钟，冷水下锅加姜片料酒焯到浮沫出净。","锅中少油中火炒香八角桂皮和姜片，倒入牛腩块翻炒到表面收紧。","加生抽老抽炒上色，倒没过牛腩的热水，大火烧开转小火炖一小时。","下土豆和胡萝卜块，加盐，再炖二十分钟到筷子能轻松扎透牛腩。","开大火收汁三分钟至汤汁浓稠挂勺，浇在米饭上撒葱花。"],"tip":"牛腩必须加热水，冷水会让肉纤维骤缩变柴；土豆后放才不煮成泥。"},{"name":"蚝油牛肉饭","cat":"主食","region":"粤","time":25,"diff":"中等","main":[["米饭","300g"],["牛里脊","250g"],["芥蓝","200g"]],"sea":["蚝油","生抽","淀粉","料酒","白糖","食用油","蒜"],"steps":["牛里脊逆纹切薄片，加生抽料酒淀粉和一勺水抓打到发黏，腌十五分钟。","芥蓝削去老皮切段，沸水加盐和几滴油焯一分钟，捞出摆盘垫底。","锅烧到微微冒烟倒油，大火滑炒牛肉片三十秒，变色立刻盛出。","留底油爆香蒜片，倒回牛肉，加蚝油和白糖翻匀，淋两勺水烧开。","勾薄芡到汁浓能挂肉，连牛肉带汁浇在米饭和芥蓝上。"],"tip":"牛肉逆纹切、上浆后大火快炒，下锅到出锅不超过一分钟，久了发柴。"},{"name":"咸肉菜饭","cat":"主食","region":"本帮","time":50,"diff":"中等","main":[["大米","300g"],["腊肉","150g"],["油菜","300g"]],"sea":["盐","猪油","料酒"],"steps":["大米淘净沥干，腊肉切一厘米小丁，油菜洗净切碎，菜梗和菜叶分开放。","锅中放一勺猪油，中火煸腊肉丁到出油、边缘微黄卷起。","下菜梗碎炒一分钟，再下菜叶炒到塌软出水，淋料酒翻匀关火。","大米倒入电饭锅，加比平时少一点的水，把炒好的腊肉青菜连油一起铺上。","按下煮饭键，跳起后焖十分钟，加盐拌匀再焖五分钟。"],"tip":"青菜先炒去水再焖，饭才不湿软；水比平时少一成，粒粒清爽。"},{"name":"豌豆腊肉焖饭","cat":"主食","region":"家常","time":45,"diff":"简单","main":[["大米","300g"],["腊肉","100g"],["豌豆","150g"]],"sea":["盐","生抽","食用油"],"steps":["大米淘洗后浸泡十五分钟，腊肉切小丁，豌豆剥好冲洗沥干。","锅中少放油，中火煸腊肉丁到透明出油，倒豌豆翻炒一分钟至颜色转深绿。","把大米和炒好的腊肉豌豆一起倒进锅里，加水没过米面一指。","大火烧开转小火，盖盖焖十八分钟，听不到水声、表面冒小孔即可。","关火再焖十分钟，淋一勺生抽加盐，从底往上翻拌均匀。"],"tip":"焖饭的水要比平时略少，腊肉和豌豆本身出水，水多就成烂饭。"},{"name":"生滚鱼片粥","cat":"主食","region":"粤","time":55,"diff":"中等","main":[["大米","150g"],["草鱼","300g"]],"sea":["姜","葱","盐","白胡椒","料酒","淀粉","香油"],"steps":["草鱼取净肉斜刀切薄片，加盐料酒淀粉和姜丝抓匀，腌十分钟。","大米淘净拌一勺油，锅中水烧开下米，大火滚开转小火熬三十五分钟至粥底绵滑。","粥底加盐和白胡椒调好味，转大火让整锅粥滚起来。","鱼片一片片摊开下锅，不要搅动，煮一分半到鱼片变白卷边立刻关火。","撒葱花淋香油，静置半分钟让余温把鱼片焖透。"],"tip":"鱼片下锅后千万别搅，一搅就碎；粥要滚着下鱼，肉才嫩而不腥。"},{"name":"猪肝菠菜粥","cat":"主食","region":"粤","time":50,"diff":"中等","main":[["大米","150g"],["猪肝","200g"],["菠菜","150g"]],"sea":["姜","料酒","盐","白胡椒","淀粉","香油"],"steps":["猪肝切薄片，清水反复抓洗到水清，加料酒姜丝和淀粉腌十五分钟。","菠菜入沸水焯二十秒捞出挤干水分切段，去掉草酸和涩味。","大米淘净加水，大火煮开后转小火熬三十分钟，粥面浮起一层米油。","转中火下猪肝片，拨散煮两分钟，肝片变褐、没有血水渗出即可。","放菠菜段，加盐和白胡椒，淋香油搅匀关火。"],"tip":"猪肝洗到水清再腌，粥才不腥；下锅煮两分钟就够，久了发硬。"},{"name":"南瓜粥","cat":"主食","region":"家常","time":45,"diff":"简单","main":[["大米","100g"],["南瓜","300g"]],"sea":["白糖"],"steps":["南瓜去皮去瓤切两厘米块，大米淘洗后浸泡二十分钟。","锅中水烧开下大米，大火煮开后转小火熬二十分钟至米粒开花。","下南瓜块继续煮十五分钟，用勺子把南瓜压成泥，与粥搅匀。","再小火煮五分钟，粥变金黄浓稠、勺子舀起能挂住时加白糖。","搅到糖化开关火，盖盖焖三分钟让粥面结出米油。"],"tip":"南瓜压成泥后再煮五分钟，粥才绵密金黄，大块南瓜容易沉底糊锅。"},{"name":"小米粥","cat":"主食","region":"家常","time":40,"diff":"简单","main":[["小米","100g"]],"sea":[],"steps":["小米用清水轻轻淘洗两遍，别用手搓，搓掉表层米油就不香了。","锅中水烧到锅底冒小泡时下小米，大火煮开，用勺推动防止粘底。","转小火盖半盖熬三十分钟，每隔十分钟顺一个方向搅一圈。","粥变稠、米粒开花浮起米油时关火，盖盖焖十分钟。","盛出后稍放一会儿，表面会结一层米皮，趁热喝最香。"],"tip":"水开再下米不容易糊底；小火慢熬少搅动，浮起来的米油才厚。"},{"name":"八宝粥","cat":"主食","region":"家常","time":90,"diff":"中等","main":[["糯米","50g"],["红豆","50g"],["花生米","30g"],["莲子","30g"],["红枣","8颗"]],"sea":["冰糖"],"steps":["红豆、花生米和莲子提前用清水泡四小时，莲子掰开去掉中间的芯。","锅中水烧开，先下红豆和花生米，大火煮开转小火煮三十分钟。","加糯米、莲子和红枣，继续小火熬四十分钟，期间搅动两三次防粘。","粥变浓稠、豆子一捻就烂时放冰糖，搅到完全化开。","关火焖十分钟，粥面浮起一层黏亮的米油即可。"],"tip":"豆类先泡透先下锅，糯米后放，否则米都化完了豆子还硬。"},{"name":"黑米粥","cat":"主食","region":"家常","time":70,"diff":"简单","main":[["黑米","100g"],["糯米","50g"]],"sea":["冰糖"],"steps":["黑米和糯米一起淘洗两遍，加清水浸泡四小时，泡米水别倒掉。","连泡米水一起倒入锅中，再补足水到米量的十倍，大火煮开。","转小火盖盖熬四十五分钟，每十分钟搅一次锅底，防止黑米沉底糊锅。","米粒开花、粥色深紫发亮时加冰糖，搅到完全化开。","关火焖十五分钟，粥变黏稠挂勺即可盛出。"],"tip":"黑米外皮硬必须泡够四小时，泡米水一起煮，颜色和花青素都不浪费。"},{"name":"粢饭团","cat":"主食","region":"本帮","time":60,"diff":"中等","main":[["糯米","200g"],["榨菜","50g"],["香肠","1根"]],"sea":["白糖","香油"],"steps":["糯米淘净后泡四小时，沥干铺在垫了纱布的蒸笼上，用筷子戳几个孔透气。","水开后大火蒸三十分钟，米粒透明软糯、用手能捏成团即可。","榨菜切细末，香肠蒸熟切条，糯米饭趁热拌入白糖和香油。","保鲜膜上铺一层饭压平，中间放上榨菜末和香肠条。","提起保鲜膜四角收紧，隔着膜把饭团攥成纺锤形，稍凉后切开。"],"tip":"饭要趁热捏才粘得牢，手上蘸凉水或隔保鲜膜操作，都不粘手。"},{"name":"三文鱼饭团","cat":"主食","region":"家常","time":25,"diff":"简单","main":[["米饭","300g"],["三文鱼","150g"],["紫菜","2张"]],"sea":["盐","香油","黑胡椒"],"steps":["三文鱼用厨房纸吸干水，两面抹盐和黑胡椒，腌十分钟。","平底锅烧热不加油，鱼皮朝下中火煎三分钟，翻面再煎两分钟至中心变色。","去掉鱼皮和细刺，用叉子把鱼肉压成粗粒，趁热拌进温热的米饭里。","加半勺盐和一勺香油拌匀，取一小团在手里反复攥压成三角。","紫菜剪成条裹在饭团底部，现做现吃。"],"tip":"三文鱼别煎过火，中心刚变色就起锅，拌进饭里鱼肉才不干散。"},{"name":"八宝饭","cat":"甜点","region":"本帮","time":90,"diff":"较难","main":[["糯米","300g"],["红枣","8颗"],["莲子","30g"],["桂圆","20g"],["花生米","30g"]],"sea":["白糖","猪油"],"steps":["糯米泡四小时，上笼大火蒸三十分钟至软糯，趁热拌入白糖和两勺猪油。","碗内壁抹一层猪油，把红枣莲子桂圆花生米在碗底摆出花样。","铺一层糯米饭压实，中间按出凹坑填入白糖，再盖一层饭压平。","上笼水开后中火蒸四十分钟，让果料的香味渗进饭里。","取出倒扣在盘中，趁热脱模，让果料朝上即成。"],"tip":"碗壁抹猪油既防粘又增香，饭要压实，倒扣脱模才不散。"},{"name":"红糖糍粑","cat":"甜点","region":"川","time":30,"diff":"简单","main":[["糯米粉","200g"]],"sea":["红糖","食用油","白芝麻"],"steps":["糯米粉分次加温水，边加边搅成絮状，揉到不粘手、能捏成团的面团。","面团分成八份，搓圆后压成一厘米厚的圆饼，边缘捏得略薄一点。","平底锅刷薄油，中小火下糍粑煎四分钟，底面金黄鼓起后翻面再煎三分钟。","红糖加两勺水小火熬到冒大泡、能挂住勺子，淋在煎好的糍粑上。","撒白芝麻，趁热吃，外脆内软还能拉丝。"],"tip":"面团揉到耳垂般软度，煎时用中小火慢烘，外皮才脆而不焦。"},{"name":"煎饺","cat":"主食","region":"家常","time":18,"diff":"中等","main":[["饺子皮","20张"],["猪肉末","200g"],["葱","2根"]],"sea":["姜","生抽","盐","食用油","醋","香油"],"steps":["猪肉末加姜末、葱花、生抽、盐和香油，顺一个方向搅打上劲。","饺子皮边缘抹水，放馅对折捏紧，逐个包好摆在撒粉的盘里。","平底锅倒油中火烧热，饺子码入锅中煎2分钟至底部微黄。","沿锅边淋入没过饺子三分之一的热水，盖盖中小火焖8分钟。","水收干后开盖再煎1分钟，底部焦脆出锅，配醋碟食用。"],"tip":"焖的时候别开盖，水汽足饺子皮才软；最后收干再煎才起脆底。"},{"name":"火腿三明治","cat":"主食","region":"家常","time":12,"diff":"简单","main":[["吐司面包","4片"],["火腿","4片"],["鸡蛋","2个"],["生菜","2片"],["芝士片","2片"]],"sea":["食用油","黑胡椒","番茄酱"],"steps":["平底锅刷薄油中小火，磕入鸡蛋煎成两面微焦的荷包蛋，撒黑胡椒。","同一锅中放火腿片煎30秒，边缘卷起即可盛出。","吐司面包放入干锅烘1分钟至两面微脆，取出晾一下。","按吐司、生菜、火腿、芝士片、煎蛋顺序叠好，挤番茄酱盖上吐司。","对角切成两个三角形，用牙签固定住即可装盘。"],"tip":"吐司先烘脆能隔住酱汁不塌软，芝士片夹在热蛋和火腿上才化。"},{"name":"西红柿鸡蛋面","cat":"主食","region":"家常","time":15,"diff":"简单","main":[["西红柿","2个"],["鸡蛋","2个"],["挂面","150g"]],"sea":["葱","盐","食用油","生抽","白糖"],"steps":["西红柿顶部划十字，用开水烫30秒后撕皮切小块；鸡蛋打散。","热锅倒油，中火炒散鸡蛋至刚凝固盛出，锅里留底油。","下葱花爆香，倒入西红柿块中火炒3分钟，压出红汤后加生抽和一点白糖。","加600ml开水大火煮沸，下挂面煮3分钟至面条无硬芯。","倒回炒好的鸡蛋，加盐调味，撒葱花出锅。"],"tip":"西红柿炒出红油再加水，汤才浓；鸡蛋先炒后回锅不会老。"},{"name":"葱油拌面","cat":"主食","region":"本帮","time":15,"diff":"中等","main":[["面条","200g"],["葱","6根"]],"sea":["生抽","老抽","白糖","食用油"],"steps":["葱洗净沥干，切成5厘米长段，葱白葱绿分开。","冷油下葱白，最小火慢炸8分钟，再下葱绿炸到全部焦褐色捞出。","葱油中加生抽、老抽和白糖，小火熬到糖化开、酱汁冒小泡关火。","另起锅水开下面条煮2分钟，捞出沥干直接放进酱汁锅里。","开小火把面和酱汁拌匀，让每根面条裹上酱色，撒炸葱即可。"],"tip":"全程保持小火炸葱才不苦，酱汁熬到微微挂勺、能裹住面条才够味。"},{"name":"小馄饨","cat":"主食","region":"家常","time":15,"diff":"简单","main":[["馄饨皮","20张"],["猪肉末","150g"],["紫菜","5g"],["虾皮","5g"]],"sea":["姜","葱","盐","生抽","香油"],"steps":["猪肉末加姜末、葱花、盐和生抽，顺一个方向搅到发黏。","馄饨皮中间放一小团馅，五指收拢轻轻一捏，不必封严。","碗中放紫菜、虾皮、少许盐和香油，冲入半碗开水做汤底。","锅中水大火烧开下馄饨，煮到全部浮起再煮1分钟，连汤舀入碗中。"],"tip":"馅少皮薄才叫小馄饨，水开下锅浮起即熟，煮久皮会烂。"},{"name":"煎饼果子","cat":"主食","region":"家常","time":18,"diff":"中等","main":[["面粉","100g"],["玉米面","50g"],["鸡蛋","2个"],["生菜","2片"]],"sea":["甜面酱","辣椒油","葱","食用油"],"steps":["面粉和玉米面混合，加250ml清水和少许盐搅成能流动的面糊。","平底锅小火烧热刷薄油，舀一勺面糊用刮板摊成薄圆片。","面糊表面还湿时磕一个鸡蛋摊开，撒葱花，煎到蛋液凝固。","翻面刷甜面酱和辣椒油，铺生菜，从一边卷起对折出锅。"],"tip":"面糊稀一点才摊得薄，锅温别太高，否则没摊开就干了。"},{"name":"煮玉米","cat":"素菜","region":"家常","time":15,"diff":"简单","main":[["玉米","2根"]],"sea":["盐"],"steps":["玉米剥去外层老叶，留最里面两层薄皮，冲净玉米须。","锅中加冷水没过玉米，放一小撮盐，大火烧开。","转中火煮10分钟，中途翻一次面，让玉米受热均匀。","关火后在锅里泡2分钟再捞出，趁热啃最甜。"],"tip":"冷水下锅加一点盐，玉米更甜；留两层内皮煮不易失水。"},{"name":"蒸南瓜","cat":"素菜","region":"家常","time":20,"diff":"简单","main":[["南瓜","400g"]],"sea":["蜂蜜"],"steps":["南瓜去皮去瓤，切成2厘米厚的块，皮朝下码在盘中。","蒸锅加水大火烧开，放入南瓜盘，盖盖中火蒸15分钟。","用筷子能轻松扎透南瓜最厚的部分就说明熟了。","取出稍晾1分钟，淋上一勺蜂蜜即可上桌。"],"tip":"切块厚薄一致才同时蒸透，盘底积水多可以倒掉再淋蜜。"},{"name":"蒸山药","cat":"素菜","region":"家常","time":20,"diff":"简单","main":[["山药","400g"],["枸杞","10粒"]],"sea":["蜂蜜"],"steps":["山药削皮切成段，泡在清水里防止氧化发黑。","蒸锅水大火烧开，山药段码入盘中，中火蒸15分钟。","取筷子扎最粗的一段，能轻松插入就是熟了。","撒上泡软的枸杞，淋蜂蜜，趁热吃口感粉糯。"],"tip":"削山药戴一次性手套防手痒，蒸前泡水可保持颜色洁白。"},{"name":"香煎豆腐","cat":"素菜","region":"家常","time":15,"diff":"简单","main":[["豆腐","400g"]],"sea":["葱","盐","生抽","食用油","白胡椒"],"steps":["老豆腐切成1厘米厚的方片，用厨房纸吸干表面水分。","平底锅中火烧热倒油，豆腐片平铺入锅，别急着翻动。","煎3分钟至底面金黄结壳，再用铲子翻面煎2分钟。","撒盐和白胡椒，沿锅边淋一勺生抽，撒葱花收干出锅。"],"tip":"豆腐一定要吸干水再下锅，煎定型前别翻，才不碎不粘。"},{"name":"鸡蛋羹","cat":"荤菜","region":"家常","time":15,"diff":"简单","main":[["鸡蛋","2个"]],"sea":["盐","生抽","香油","葱"],"steps":["鸡蛋磕入碗中打散，加少许盐和1.5倍温水，顺一个方向搅匀。","蛋液过筛去掉浮沫，倒入浅碗，盖上一层保鲜膜或扣个盘子。","蒸锅水烧开后放入碗，中小火蒸10分钟，关火焖2分钟。","取出淋生抽和香油，撒葱花，用勺子舀着吃。"],"tip":"温水比例约1.5倍，过筛加覆盖，蛋羹才滑如布丁无蜂窝。"},{"name":"水煮荷包蛋","cat":"荤菜","region":"家常","time":10,"diff":"简单","main":[["鸡蛋","2个"]],"sea":["白糖"],"steps":["锅中加500ml水大火烧开，转最小火让水面只冒小泡。","鸡蛋先磕进小碗，贴着水面轻轻滑入锅中，别搅动。","小火煮3分钟，蛋白凝固包住蛋黄，用勺子推一下防粘底。","加一勺白糖搅化，连汤盛入碗中，趁热喝最暖胃。"],"tip":"水微沸不起大泡时下蛋最完整，碗滑入法蛋形更圆。"},{"name":"培根煎蛋","cat":"荤菜","region":"家常","time":12,"diff":"简单","main":[["培根","4片"],["鸡蛋","2个"]],"sea":["黑胡椒","盐"],"steps":["培根切成两段，平底锅不放油中小火下锅，煎2分钟至出油卷边。","把培根拨到锅边，用煎出的油磕入鸡蛋，小火煎3分钟。","蛋白凝固后撒黑胡椒和少许盐，蛋黄半熟时关火。"],"tip":"培根自带咸味，盐要少放；直接用培根煎出的油煎蛋更香更省事。"},{"name":"豆腐脑","cat":"汤羹","region":"家常","time":20,"diff":"中等","main":[["豆腐","400g"],["木耳","20g"],["黄花菜","20g"]],"sea":["生抽","老抽","盐","淀粉","香油"],"steps":["木耳和黄花菜提前用温水泡发，木耳切丝，黄花菜切小段。","嫩豆腐用勺子片成薄片，放入碗中，上锅大火蒸5分钟。","锅中加400ml水烧开，下木耳丝和黄花菜煮3分钟。","加生抽、老抽和盐调色调味，淋水淀粉勾成能挂勺的薄芡。","把卤汁浇在蒸好的豆腐上，滴香油即可。"],"tip":"嫩豆腐蒸过更紧实不散，芡要薄，浇上去能流动才对。"},{"name":"西红柿疙瘩汤","cat":"汤羹","region":"家常","time":20,"diff":"中等","main":[["西红柿","2个"],["面粉","100g"],["鸡蛋","1个"]],"sea":["葱","盐","食用油","香油"],"steps":["面粉放盆里，一边滴入少量清水一边用筷子搅，搅成黄豆大小的面疙瘩。","西红柿烫皮切小块，鸡蛋打散，葱切葱花。","热锅倒油下葱花爆香，倒入西红柿中火炒3分钟至出红汤。","加800ml开水大火烧开，把面疙瘩抖散下锅，边下边搅防粘连。","煮3分钟至疙瘩透明浮起，淋入蛋液，加盐和香油出锅。"],"tip":"水一点一点滴入面粉才搅得出小疙瘩，一次倒水就成死面块。"},{"name":"小葱拌豆腐","cat":"凉菜","region":"家常","time":10,"diff":"简单","main":[["豆腐","400g"],["葱","3根"]],"sea":["盐","香油","生抽"],"steps":["嫩豆腐整块放入盘中，用刀在盘中划成2厘米见方的小块。","撒上盐，静置3分钟让豆腐渗出一点水，把水倒掉。","葱切成细葱花，撒在豆腐上，堆成小山状。","淋一勺生抽和几滴香油，吃前用筷子轻轻拌开。"],"tip":"葱要现切现拌，久放会蔫；盐先杀水，豆腐才不寡淡。"},{"name":"炝拌土豆丝","cat":"凉菜","region":"家常","time":15,"diff":"简单","main":[["土豆","2个"],["青椒","1个"]],"sea":["蒜","干辣椒","花椒","醋","盐","食用油"],"steps":["土豆去皮切细丝，放清水里冲两遍洗掉表面淀粉，泡着备用。","青椒去籽切成细丝，蒜剁成蒜末，干辣椒用剪刀剪成小段。","锅中水大火烧开，下土豆丝焯40秒，再放青椒丝烫10秒，一起捞出过凉水。","土豆丝沥干装碗，加盐、醋和蒜末，把干辣椒段和花椒铺在最上面。","另起锅烧热两勺油，浇在辣椒和花椒上激出香味，拌匀即可。"],"tip":"焯水别超过一分钟，捞出立刻过凉水，土豆丝才脆。"},{"name":"牛奶炖蛋","cat":"甜点","region":"家常","time":20,"diff":"简单","main":[["鸡蛋","2个"],["牛奶","200ml"]],"sea":["白糖"],"steps":["牛奶加白糖小火加热到糖化开，晾到温热不烫手。","鸡蛋打散但不要打起泡，慢慢倒入牛奶搅匀。","蛋奶液过筛两遍，倒进碗中，撇掉表面小气泡。","碗上盖保鲜膜扎几个小孔，水开后中小火蒸12分钟。","关火焖3分钟再取出，晃动碗中间不流动就是熟了。"],"tip":"牛奶不能烫，蛋液过筛去泡，小火蒸出来才滑嫩无孔。"},{"name":"凉拌黄瓜","cat":"凉菜","region":"家常","time":15,"diff":"简单","main":[["黄瓜","2根"],["香菜","1小把"]],"sea":["蒜","盐","生抽","香醋","香油","干辣椒","食用油","白糖"],"steps":["黄瓜洗净拍裂，切成三厘米长的段，撒3g盐拌匀腌5分钟。","腌出的水倒掉，黄瓜段用手轻攥一下，放进深盆里备用。","蒜拍碎剁末，干辣椒剪段，与盐、白糖、生抽、香醋调成料汁。","小锅烧两勺食用油至冒青烟，泼在蒜末辣椒上激出香味。","料汁倒入黄瓜，加香菜段和香油，颠盆拌匀后静置3分钟装盘。"],"tip":"黄瓜先拍后切、撒盐杀水，拌好十分钟内上桌最脆爽。"},{"name":"老醋花生","cat":"凉菜","region":"鲁","time":25,"diff":"中等","main":[["花生米","300g"],["洋葱","半个"],["香菜","2根"]],"sea":["醋","白糖","生抽","盐","食用油","香油"],"steps":["花生米挑去坏粒，用清水冲一遍，摊在厨房纸上晾到表面全干。","冷锅倒食用油，凉油下花生米，中小火慢炸，油面小泡变密时转小火。","炸到噼啪声变少、颜色浅金，立刻捞出摊开晾凉，余温会继续上色。","小锅放醋、白糖、生抽和盐，中小火熬到糖化开、汁略稠，关火晾凉。","洋葱切小丁，香菜切段，与花生米一起倒入晾凉的醋汁，拌开即食。"],"tip":"花生凉油下锅才酥，捞出后会回熟；醋汁一定晾凉再拌。"},{"name":"凉拌腐竹","cat":"凉菜","region":"家常","time":35,"diff":"简单","main":[["腐竹","200g"],["黄瓜","1根"],["胡萝卜","半根"]],"sea":["蒜","生抽","香醋","盐","白糖","辣椒油","香油"],"steps":["腐竹掰成五厘米长段，用温水加一勺盐泡30分钟，泡到中心没有硬芯。","水开下腐竹焯1分钟，捞出过凉水，攥干水分放进盆里。","黄瓜拍裂切段，胡萝卜切薄片，蒜剁末，一起倒入盆中。","碗里放生抽、香醋、盐、白糖和辣椒油搅匀，倒进盆中抓拌。","淋香油拌匀，静置5分钟让腐竹吸味，装盘即可。"],"tip":"温水加盐泡腐竹又快又匀，焯水别超过一分钟否则易碎。"},{"name":"麻酱菠菜","cat":"凉菜","region":"家常","time":15,"diff":"简单","main":[["菠菜","400g"],["粉丝","1小把"]],"sea":["芝麻酱","盐","生抽","醋","白糖","香油","蒜"],"steps":["菠菜择洗干净，切成六厘米长段，粉丝用温水泡软后剪短。","水开先下粉丝煮1分钟，再下菠菜烫30秒，一起捞出过凉水。","菠菜用手轻轻攥干水分，抖散，与粉丝一起装盘。","芝麻酱放碗里，分三次加温水朝一个方向澥开，调成能流动的稀糊。","加入蒜末、生抽、醋、盐、白糖和香油调匀，淋在菠菜上拌开。"],"tip":"澥麻酱只用温水、一次少加，搅到顺滑无疙瘩再调味。"},{"name":"凉拌莴笋丝","cat":"凉菜","region":"家常","time":15,"diff":"简单","main":[["莴笋","1根"],["胡萝卜","半根"]],"sea":["蒜","盐","白糖","白醋","香油"],"steps":["莴笋削去外皮和白色筋膜，先切薄片，再改刀切成细丝。","莴笋丝加3g盐抓匀腌5分钟，倒掉渗出的水，用清水冲一下攥干。","胡萝卜切细丝，蒜切末，与莴笋丝一起放进盆中。","加盐、白糖、白醋和香油，从下往上翻拌均匀，装盘即食。"],"tip":"莴笋丝盐腌后挤水才脆，白醋比陈醋更清亮不发黑。"},{"name":"凉拌藕片","cat":"凉菜","region":"家常","time":20,"diff":"简单","main":[["莲藕","1节"],["尖椒","1个"]],"sea":["姜","蒜","白醋","盐","白糖","辣椒油","香油"],"steps":["莲藕去皮切两毫米薄片，泡在加了白醋的清水里防止氧化发黑。","水开下藕片焯90秒，捞出立刻投入冰水，凉透后沥干水分。","尖椒切圈，姜蒜切末，与藕片一起放入拌菜盆。","加盐、白糖、白醋、辣椒油和香油，颠盆拌匀后冷藏10分钟。"],"tip":"藕片水开下锅、时间别过两分钟，捞出过冰水才白脆。"},{"name":"盐水毛豆","cat":"凉菜","region":"家常","time":40,"diff":"简单","main":[["毛豆","500g"]],"sea":["盐","花椒","八角","桂皮","香叶","干辣椒"],"steps":["毛豆洗净，用剪刀剪掉两头的尖角，剪口才容易吸进咸味。","锅里加足量水，放花椒、八角、桂皮、香叶和干辣椒，大火烧开煮5分钟出香。","下毛豆和30g盐，不盖锅盖大火煮8分钟，煮到豆粒能轻松挤出。","关火后毛豆留在汤里泡20分钟，捞出沥干装盘。"],"tip":"煮毛豆全程不盖盖才翠绿，盐要下重些，泡在汤里更入味。"},{"name":"凉拌金针菇","cat":"凉菜","region":"家常","time":15,"diff":"简单","main":[["金针菇","300g"],["黄瓜","半根"]],"sea":["蒜","生抽","香醋","盐","白糖","辣椒油","香油"],"steps":["金针菇切去老根，撕成小把，用清水冲洗掉根部的杂质。","水开下金针菇焯2分钟，捞出过凉水，攥干水分抖散。","黄瓜切细丝铺在盘底，焯好的金针菇堆在上面。","蒜末加生抽、香醋、盐、白糖和辣椒油调成汁，淋在金针菇上。","最后淋香油，吃前从盘底拌开，让料汁裹匀。"],"tip":"金针菇焯足两分钟断生，攥干再拌才不出一盘汤。"},{"name":"拌三丝","cat":"凉菜","region":"家常","time":20,"diff":"简单","main":[["土豆","1个"],["胡萝卜","1根"],["青椒","1个"]],"sea":["蒜","盐","白醋","白糖","辣椒油","香油","花椒"],"steps":["土豆去皮切细丝，清水冲两遍洗掉表面淀粉，泡在凉水里防变色。","胡萝卜、青椒分别切丝，蒜剁成末，花椒在小碟里备好。","水开先下土豆丝焯1分钟，再下胡萝卜丝和青椒丝烫20秒，一起捞出过凉水。","三丝沥干水分，加蒜末、盐、白糖、白醋和辣椒油抓拌。","淋香油拌匀，装盘后静置5分钟入味再吃。"],"tip":"土豆丝焯水只要一分钟，捞出立刻过凉水才脆不粘连。"},{"name":"皮蛋豆腐","cat":"凉菜","region":"家常","time":10,"diff":"简单","main":[["豆腐","1盒"],["皮蛋","2个"],["香菜","1根"]],"sea":["葱","蒜","生抽","香醋","香油"],"steps":["豆腐连盒在案上轻磕几下，撕开盒口倒扣，整块滑进深盘。","皮蛋剥壳，用一根细线从上往下勒成六瓣，铺在豆腐上面。","葱蒜切末，加生抽、香醋和香油调成料汁，尝起来咸鲜带酸。","料汁浇在皮蛋豆腐上，撒香菜末，静置3分钟让味道渗进去。"],"tip":"皮蛋用细线勒不粘刀，豆腐提前冷藏半小时口感更嫩。"},{"name":"糖醋萝卜","cat":"凉菜","region":"东北","time":150,"diff":"简单","main":[["白萝卜","1根"],["胡萝卜","半根"]],"sea":["盐","白糖","白醋","生抽","干辣椒"],"steps":["白萝卜去皮切两毫米薄片，胡萝卜切薄片，加10g盐抓匀腌20分钟。","腌出的水倒掉，用手把萝卜片攥到发软，再用清水冲一遍攥干。","白糖、白醋、生抽按三比三比一调成汁，放干辣椒段，尝起来酸甜分明。","萝卜片放进干净无油的玻璃罐，倒入糖醋汁没过，冷藏两小时至透亮。"],"tip":"罐子和手都不能沾生水和油，否则两天就起白沫发酸。"},{"name":"蒜泥白肉","cat":"凉菜","region":"川","time":70,"diff":"中等","main":[["五花肉","400g"],["黄瓜","1根"]],"sea":["蒜","葱","姜","生抽","醋","白糖","辣椒油","花椒"],"steps":["五花肉整块冷水下锅，加葱段、姜片和十几粒花椒，大火烧开。","水开后撇净浮沫，转小火煮40分钟，筷子能轻松插入肉皮即熟。","肉块捞出放凉，再连盘入冰箱冷藏20分钟，切出的片才薄。","黄瓜切薄片垫在盘底，五花肉切成两毫米厚的大薄片，卷着黄瓜码好。","蒜捣成泥，加生抽、醋、白糖、辣椒油和两勺煮肉原汤调成蒜泥汁。","蒜泥汁淋在肉片上，静置3分钟入味即可上桌。"],"tip":"肉煮好别急着切，冷藏收紧后再片，薄得透光才不腻。"},{"name":"夫妻肺片","cat":"凉菜","region":"川","time":90,"diff":"较难","main":[["牛肉","300g"],["牛百叶","250g"],["花生米","50g"],["白芝麻","1小勺"]],"sea":["葱","姜","花椒","八角","辣椒油","生抽","白糖","盐"],"steps":["牛肉整块冷水下锅焯3分钟，撇净血沫后捞出冲洗干净。","锅中加水放葱段、姜片、花椒、八角、生抽和盐，下牛肉大火烧开转小火卤60分钟。","牛百叶另起一锅，水开下锅烫40秒，捞出过凉水，切成细条。","卤好的牛肉晾凉切薄片，与百叶条一起放进大盆。","取两勺卤汤，加辣椒油、白糖和生抽调成红油汁，倒入盆中抓拌。","撒上炸香碾碎的花生米和白芝麻，拌匀装盘。"],"tip":"百叶只烫四十秒，多一秒就发韧；牛肉卤好泡在汤里晾更入味。"},{"name":"口水鸡","cat":"凉菜","region":"川","time":55,"diff":"中等","main":[["鸡腿","2个"],["花生米","50g"]],"sea":["葱","姜","蒜","花椒","辣椒油","生抽","醋","白糖"],"steps":["鸡腿剔去多余脂肪，冷水下锅，加葱段、姜片和花椒，大火烧开。","水开转小火，保持水面微沸煮18分钟，关火再焖10分钟。","鸡腿捞出立刻放进冰水泡10分钟，鸡皮收紧后剁成两厘米宽的块。","蒜末、生抽、醋、白糖、辣椒油和两勺煮鸡汤调成红油料汁。","鸡块摆盘，浇上料汁，撒花生碎和葱花，冷藏10分钟更入味。"],"tip":"微沸煮、关火焖、冰水激这三步做到，鸡皮才脆肉才嫩。"},{"name":"白切鸡","cat":"凉菜","region":"粤","time":55,"diff":"中等","main":[["整鸡","1只"],["姜","1块"],["葱","3根"]],"sea":["盐","食用油","生抽","香油","料酒"],"steps":["整鸡洗净沥干，鸡腔里塞姜片和葱段，表面抹薄薄一层盐。","大锅水烧开，提着鸡颈把鸡浸入沸水十秒再提起，重复三次让鸡皮收紧。","鸡整只放入锅中，水要没过鸡身，加料酒，保持水面微沸浸煮25分钟。","关火后再焖15分钟，捞出立刻放进冰水浸10分钟至完全凉透。","姜剁蓉、葱切末加盐，浇上烧到冒烟的热油，再调生抽和香油做蘸碟。","鸡斩件摆盘，骨缝里带一丝红最嫩，配姜葱蘸碟上桌。"],"tip":"三提三放让鸡皮紧实，全程水面微沸不翻滚，肉才嫩而不柴。"},{"name":"醉虾","cat":"凉菜","region":"淮扬","time":25,"diff":"中等","main":[["虾","400g"],["柠檬","半个"]],"sea":["葱","姜","蒜","黄酒","生抽","醋","白糖"],"steps":["活虾剪去虾枪和长须，用牙签从第二节挑出虾线，清水冲两遍沥干。","虾放入深碗，倒黄酒没过虾身，加姜片和葱段，盖盖醉10分钟。","另取小碗，放生抽、醋、白糖、蒜末和柠檬片调成蘸汁。","醉好的虾捞出摆盘，冰镇5分钟，配蘸汁上桌。"],"tip":"虾要选活蹦的才鲜甜，黄酒换成高度白酒杀菌更彻底。"},{"name":"酱牛肉","cat":"凉菜","region":"鲁","time":180,"diff":"较难","main":[["牛肉","800g"],["姜","1块"],["葱","2根"]],"sea":["八角","桂皮","香叶","花椒","生抽","老抽","料酒","冰糖"],"steps":["牛肉整块泡在清水里40分钟，中途换水两次，泡到水色发清。","牛肉冷水下锅，加姜片和料酒，大火煮开撇净浮沫，捞出冲净。","锅中放牛肉，加葱段、姜片、八角、桂皮、香叶和花椒，倒生抽、老抽和冰糖。","加水没过牛肉，大火烧开转小火酱90分钟，中途翻面两次。","筷子能扎透时关火，牛肉继续泡在酱汤里晾凉，凉透后冷藏定型。","取出逆着纹理切薄片，装盘浇一勺过滤的酱汤。"],"tip":"牛肉泡净血水、酱好不回锅，泡在汤里过夜才入味不柴。"},{"name":"猪皮冻","cat":"凉菜","region":"家常","time":180,"diff":"较难","main":[["猪皮","500g"],["姜","1块"]],"sea":["葱","八角","花椒","料酒","盐","生抽","醋","蒜"],"steps":["猪皮冷水下锅，加姜片和料酒煮5分钟，捞出趁热刮净内侧肥油。","刮好的猪皮用温水加盐反复搓洗三遍，直到水清不黏手。","猪皮切细条，加三倍清水、葱段、八角、花椒和盐，大火烧开。","转小火熬90分钟，汤色乳白、汤汁能挂勺时关火，捞出香料。","倒入方盒晾凉，冷藏一小时以上至完全凝固，取出切厚片。","蒜末加生抽和醋调成蘸汁，配皮冻上桌。"],"tip":"肥油刮得越干净皮冻越透亮，水是猪皮的三倍才够Q弹。"},{"name":"盐水鸭","cat":"凉菜","region":"淮扬","time":180,"diff":"较难","main":[["鸭肉","半只"],["姜","1块"],["葱","3根"]],"sea":["花椒","八角","盐","料酒","香油"],"steps":["鸭洗净沥干，用厨房纸擦干表面水分，鸭身内外抹匀30g盐。","花椒和八角放干锅小火炒香，趁热揉进鸭皮，冷藏腌两小时。","腌好的鸭冲掉表面盐粒，冷水下锅，加姜片、葱段和料酒。","大火烧开后转最小火，水面只冒小泡，浸煮40分钟。","关火焖20分钟，捞出晾凉斩块装盘，淋少许香油。"],"tip":"小火浸煮、水面不翻滚，鸭肉才白嫩不柴；盐要抹透鸭腔。"},{"name":"熏鱼","cat":"凉菜","region":"本帮","time":60,"diff":"中等","main":[["草鱼","1条"],["姜","1块"]],"sea":["葱","生抽","老抽","冰糖","料酒","醋","八角","食用油"],"steps":["草鱼去鳞去内脏，切两厘米厚的块，用葱姜、料酒和少许盐腌15分钟。","鱼块用厨房纸吸干水分，锅中油烧到六成热，下鱼块中火炸4分钟。","炸到表面金黄、鱼块发硬，捞出沥油，再复炸30秒逼出油分。","另起锅放生抽、老抽、冰糖、醋、八角和半碗水，小火熬到汤汁挂勺。","趁热把炸好的鱼块浸入卤汁，翻面裹匀，泡3分钟捞出晾凉。"],"tip":"鱼块要炸到发硬再浸汁，外酥里嫩不散；卤汁和鱼都得趁热。"},{"name":"泡椒凤爪","cat":"凉菜","region":"川","time":150,"diff":"中等","main":[["鸡爪","500g"],["柠檬","半个"],["芹菜","1根"]],"sea":["姜","花椒","料酒","盐","白醋","泡椒","白糖"],"steps":["鸡爪剪掉指甲，从中间剖开成两半，用清水泡10分钟去血水。","锅中水加姜片、花椒和料酒烧开，下鸡爪大火煮8分钟，煮到能咬动。","鸡爪捞出立刻放入冰水，泡到完全凉透，捞出沥干。","泡椒连汁倒入大碗，加白醋、盐、白糖和凉白开调成泡汁，尝起来酸辣偏咸。","鸡爪、柠檬片和芹菜段放入泡汁，冷藏两小时以上至入味。"],"tip":"鸡爪煮八分钟足够，过冰水才脆；泡汁要偏咸才吃得进味。"},{"name":"凉拌鱿鱼","cat":"凉菜","region":"家常","time":25,"diff":"简单","main":[["鱿鱼","400g"],["黄瓜","1根"],["香菜","2根"]],"sea":["姜","蒜","料酒","生抽","醋","辣椒油","香油","盐"],"steps":["鱿鱼撕去表面紫膜，去掉内脏和软骨，切成五厘米长的条。","锅中水加姜片和料酒烧开，下鱿鱼条烫40秒，卷曲变白立刻捞出。","鱿鱼过冰水凉透，沥干水分，黄瓜拍裂切段，香菜切段。","所有材料放盆里，加蒜末、生抽、醋、盐、辣椒油和香油抓拌均匀。"],"tip":"鱿鱼只烫四十秒，卷起就捞，过冰水才脆嫩不发橡皮。"},{"name":"捞汁蛤蜊","cat":"凉菜","region":"家常","time":60,"diff":"简单","main":[["蛤蜊","600g"],["尖椒","1个"],["柠檬","半个"]],"sea":["蒜","姜","生抽","醋","白糖","辣椒油","香油","料酒"],"steps":["蛤蜊放淡盐水里滴几滴香油养30分钟吐沙，用手搓洗两遍冲净。","锅中水加姜片和料酒烧开，下蛤蜊大火煮到壳全开，约2分钟，撇去浮沫。","蛤蜊捞出过冰水，连壳摆盘，煮蛤的汤留两勺澄清备用。","蒜末、尖椒圈加生抽、醋、白糖、辣椒油、香油和两勺蛤汤调成捞汁。","捞汁浇在蛤蜊上，放柠檬片，冷藏15分钟入味。"],"tip":"蛤蜊开口就捞，多煮一分钟肉就缩；捞汁略咸才压得住腥。"},{"name":"灯影牛肉","cat":"凉菜","region":"川","time":120,"diff":"较难","main":[["牛里脊","400g"]],"sea":["盐","白糖","花椒粉","辣椒面","料酒","食用油","五香粉","香油"],"steps":["牛里脊顺纹切成大薄片，加盐和料酒抓匀，腌三十分钟逼出血水。","肉片摊在晒架上，通风处晾两小时到表面干爽、边缘微微卷起。","锅内放食用油烧到四成热，下肉片小火慢炸五分钟，炸到红亮透明。","捞出控油，锅内留少许油，下辣椒面、花椒粉、五香粉和白糖炒香。","倒回牛肉片小火翻炒两分钟，让每片都裹上料，淋香油摊凉。"],"tip":"牛肉片要切得透光，晾到表面干爽再下锅炸，才起酥不返软。"},{"name":"开水白菜","cat":"汤羹","region":"川","time":150,"diff":"较难","main":[["娃娃菜","2棵"],["整鸡","半只"],["猪大骨","500g"]],"sea":["姜","葱","料酒","盐","白胡椒"],"steps":["整鸡和猪大骨冷水下锅焯净血沫，冲净后加足量清水，大火烧开。","转小火吊三小时，中途撇两次浮油，汤面保持清亮不翻滚。","捞出鸡骨，汤用细纱布滤两遍，加盐和白胡椒调味，即成清汤。","娃娃菜只取嫩心，纵向切四瓣，放沸水里烫二十秒立刻捞入冰水。","菜心码进汤碗，浇上滚烫清汤没过菜心，上锅蒸十分钟出锅撒葱丝。"],"tip":"吊汤全程小火不滚，汤才清；菜心先焯后蒸，脆嫩不烂。"},{"name":"甜烧白","cat":"甜点","region":"川","time":120,"diff":"较难","main":[["五花肉","300g"],["糯米","150g"],["红豆","100g"]],"sea":["红糖","白糖","猪油","蜂蜜"],"steps":["糯米提前泡两小时，红豆煮到一捏就烂，加白糖压成豆沙。","五花肉整块煮十五分钟至断生，捞出趁热抹蜂蜜，晾到不烫手。","肉切连刀薄片，每两片之间夹一层豆沙，皮朝下码进碗底。","糯米拌红糖和猪油铺在肉上，压实，上锅大火蒸一小时。","出锅倒扣入盘，撒白糖，趁热吃，肉片软糯能拉丝。"],"tip":"肉皮抹蜂蜜再炸再蒸，颜色红亮，夹沙时也不易散。"},{"name":"怪味鸡","cat":"凉菜","region":"川","time":45,"diff":"中等","main":[["鸡腿","2个"],["花生米","50g"]],"sea":["芝麻酱","辣椒油","花椒粉","醋","白糖","生抽","蒜","葱"],"steps":["鸡腿冷水下锅加葱段，水开后小火煮十五分钟，关火再焖十分钟。","捞出放凉，去骨撕成筷子粗的条，整齐摆在盘里。","芝麻酱用两勺温水澥开，加辣椒油、生抽、醋、白糖和花椒粉搅匀。","蒜压成泥拌进料汁，尝起来麻、辣、酸、甜、咸都要有。","料汁淋在鸡条上，撒擀碎的花生米和葱花，拌匀静置十分钟。"],"tip":"芝麻酱要分次加温水慢慢澥开，料汁才顺滑不结块不发苦。"},{"name":"酸菜鱼","cat":"荤菜","region":"川","time":45,"diff":"中等","main":[["草鱼","1条"],["酸菜","300g"]],"sea":["泡椒","干辣椒","花椒","淀粉","料酒","姜","蒜","盐"],"steps":["草鱼片成薄片，鱼骨剁段，鱼片加料酒、盐和淀粉抓匀腌十五分钟。","酸菜切段挤干水，热锅不放油先干煸两分钟，盛出备用。","锅内下食用油，中火炒香姜片、蒜片和泡椒，倒酸菜炒一分钟。","加鱼骨和开水，大火滚八分钟熬到汤发白，捞出酸菜垫在盆底。","转中小火下鱼片，煮到变白浮起约一分钟，连汤倒入盆中。","干辣椒段和花椒撒在鱼片上，烧热两勺油泼上去激出麻味。"],"tip":"酸菜下锅前先干煸两分钟去水汽，酸香更浓，汤也不发涩。"},{"name":"干烧鲫鱼","cat":"荤菜","region":"川","time":35,"diff":"中等","main":[["鲫鱼","2条"],["猪肉末","100g"]],"sea":["豆瓣酱","泡椒","姜","蒜","葱","料酒","白糖","醋"],"steps":["鲫鱼两面各划三刀，抹料酒和少许盐腌十分钟，擦干表面水分。","热锅多放油烧到七成热，下鱼中火煎到两面金黄定型，盛出。","锅内留底油，下猪肉末炒散出油，加豆瓣酱、泡椒末、姜蒜末炒香。","加一碗热水、白糖和醋烧开，放回鲫鱼中小火烧八分钟。","转大火收汁，边收边把料汁浇在鱼身上，汤汁浓亮挂勺即可。"],"tip":"鱼下锅前一定擦干，热锅热油煎定型再动，皮才不破。"},{"name":"辣子鸡","cat":"荤菜","region":"川","time":40,"diff":"中等","main":[["鸡腿","400g"],["干辣椒","50g"]],"sea":["花椒","料酒","生抽","白糖","淀粉","食用油","蒜","姜"],"steps":["鸡腿去骨切两厘米小块，加料酒、生抽、姜末和淀粉抓匀腌二十分钟。","干辣椒剪成段，抖掉部分辣椒籽，蒜切片，花椒备好。","锅中放食用油烧到六成热，下鸡块中火炸四分钟到表面金黄，捞出。","油温升到八成热复炸三十秒，鸡块外壳变脆立刻捞出控油。","锅留少量油，小火炒香干辣椒、花椒和蒜片，倒鸡块大火翻炒一分钟。","撒白糖翻匀，尝一块外酥里嫩，辣椒香而不糊即可出锅。"],"tip":"干辣椒一定要小火慢炒到枣红，火大一点点就会发苦。"},{"name":"虎皮青椒","cat":"素菜","region":"川","time":15,"diff":"简单","main":[["青椒","8个"]],"sea":["蒜","生抽","醋","白糖","盐","食用油"],"steps":["青椒去蒂去籽，用刀背轻拍两下压扁，表面水分擦干。","平底锅烧热不放油，把青椒排进去，中火干烙到两面起皱发软。","烙好的青椒推到锅边，倒一勺食用油，下蒜末小火炒香。","加生抽、醋、白糖和盐，转中火翻炒一分钟，让青椒吸进料汁。","汤汁收干、虎皮斑明显时出锅，趁热吃最香。"],"tip":"先干锅烙出虎皮再放油，皮起皱才入味，也不吸油。"},{"name":"炝炒包菜","cat":"素菜","region":"川","time":12,"diff":"简单","main":[["包菜","半颗"]],"sea":["干辣椒","花椒","蒜","醋","盐","生抽","食用油"],"steps":["包菜撕成大片，梗和叶分开放，洗净后甩干水分。","热锅放食用油烧到冒烟，下干辣椒段、花椒和蒜末小火炸香。","先下包菜梗转大火炒四十秒，再下叶子大火快炒一分钟。","沿锅边淋一勺醋和生抽，加盐，大火翻炒二十秒出锅。"],"tip":"火要最大、手要最快，包菜下锅到出锅不超过两分钟。"},{"name":"担担面","cat":"主食","region":"川","time":30,"diff":"中等","main":[["面条","300g"],["猪肉末","150g"],["花生米","50g"]],"sea":["芝麻酱","辣椒油","生抽","醋","白糖","花椒粉","蒜","葱"],"steps":["猪肉末中火干煸到水分收干出油，加生抽和少许白糖炒成臊子。","花生米小火炸香，摊凉后擀成粗粒，蒜切末，葱切成细花。","碗底放芝麻酱，用两勺面汤澥开，加辣椒油、生抽、醋和花椒粉。","面条下沸水煮到八成熟，捞进碗里，带一点面汤更好拌。","浇上肉臊，撒蒜末、葱花和花生碎，吃前从碗底挑起来拌匀。"],"tip":"碗底调料先用面汤澥开再放面条，不坨不粘，麻辣味也更匀。"},{"name":"酸辣粉","cat":"主食","region":"川","time":25,"diff":"简单","main":[["粉条","200g"],["花生米","50g"],["榨菜","30g"]],"sea":["醋","辣椒油","花椒粉","生抽","白糖","葱","蒜","香菜"],"steps":["粉条用温水泡三十分钟到发软，捞出剪成二十厘米长段。","碗里放蒜末、生抽、醋、辣椒油、花椒粉和白糖，冲入两勺开水调匀。","水开后下粉条，中火煮三分钟到透明，连汤带粉捞进碗里。","花生米炸香、榨菜切末撒在粉上，再撒葱花和香菜段。","静置两分钟让粉条吸味，吃前上下挑匀，酸辣味更足。"],"tip":"醋分两次放，碗底一次、出锅再补一次，酸香更有层次。"},{"name":"红油抄手","cat":"主食","region":"川","time":35,"diff":"中等","main":[["馄饨皮","300g"],["猪肉末","250g"],["鸡蛋","1个"]],"sea":["辣椒油","生抽","醋","白糖","蒜","花椒粉","香油","葱"],"steps":["猪肉末加蛋液、生抽和一勺清水，顺一个方向搅到起胶上劲。","馄饨皮中间放一小勺馅，对折捏紧成元宝形，摆在撒了淀粉的盘上。","碗里放蒜末、生抽、醋、白糖、辣椒油、花椒粉和香油调成红油汁。","水开下抄手，中火煮到浮起再煮一分钟，皮变透明就熟。","捞入碗中，浇两勺煮抄手的汤，撒葱花，拌开趁热吃。"],"tip":"肉馅分次加水顺一个方向搅上劲，抄手才嫩滑不散不柴。"},{"name":"咸烧白","cat":"荤菜","region":"川","time":120,"diff":"较难","main":[["五花肉","400g"],["梅干菜","100g"]],"sea":["生抽","老抽","料酒","白糖","姜","葱","花椒","食用油"],"steps":["梅干菜温水泡二十分钟，反复淘洗到无沙，挤干水分切碎。","五花肉整块冷水下锅，放姜片、葱段和花椒，中火煮二十分钟捞起。","肉皮抹老抽，下七成热油炸到皮起泡呈深红，捞出泡冷水十分钟。","肉切一厘米厚片，加生抽、料酒和白糖抓匀，皮朝下码进碗里。","梅干菜用余油炒香，铺在肉上压实，上锅大火蒸九十分钟。","出锅倒扣入盘，汤汁浓稠挂勺，肉皮朝上即可上桌。"],"tip":"肉皮炸过立刻泡冷水，才会起虎皮纹，蒸出来更软糯。"},{"name":"豉汁蒸排骨","cat":"荤菜","region":"粤","time":50,"diff":"简单","main":[["排骨","500g"],["豆豉","20g"]],"sea":["蒜","姜","生抽","老抽","白糖","淀粉","食用油","葱"],"steps":["排骨剁成3厘米小块，冷水浸泡20分钟去血水，捞出彻底沥干水分。","豆豉和蒜剁成蓉，加生抽、老抽、白糖、淀粉和食用油拌成腌料。","排骨倒入腌料抓匀，冷藏腌20分钟，让每块都裹上一层薄浆。","排骨平铺盘中，水开后大火蒸15分钟，筷子能轻松戳透即可。","出锅撒葱花，趁热上桌，盘底的豉汁用来拌饭最香。"],"tip":"淀粉最后放、抓出黏性，蒸出来才滑嫩不柴，汁也不会散。"},{"name":"清蒸鲈鱼","cat":"荤菜","region":"粤","time":20,"diff":"简单","main":[["鲈鱼","1条约600g"],["葱","3根"]],"sea":["姜","蒸鱼豉油","料酒","食用油","盐"],"steps":["鲈鱼去鳞去鳃，剖开鱼腹洗净黑膜，两面各划三刀深至骨。","鱼身抹盐和料酒，鱼腹塞姜片葱段，腌10分钟去腥。","盘底垫两根葱段架空鱼身，水大开后大火蒸8分钟，关火焖2分钟。","倒掉盘中腥水，拣去姜葱，重新铺上新鲜葱丝和姜丝。","淋两勺蒸鱼豉油，把烧到冒烟的热油浇在葱丝上激香即成。"],"tip":"一斤左右的鱼大火蒸8分钟刚好，肉离骨、鱼眼凸白即熟。"},{"name":"腊味煲仔饭","cat":"主食","region":"粤","time":60,"diff":"中等","main":[["大米","200g"],["腊肉","100g"],["香肠","1根"],["菜心","100g"]],"sea":["生抽","老抽","蚝油","白糖","食用油","姜"],"steps":["大米淘洗后加清水泡30分钟，水量按米与水一比一点二配好。","砂锅内壁刷一层油，倒入米和水，大火烧开后转小火煮8分钟。","腊肉切薄片、香肠斜切片，铺在米饭上，盖盖沿锅边淋一圈油。","小火焖12分钟，听到锅底有轻微噼啪声时关火，不要开盖。","菜心焯熟，把生抽、老抽、蚝油、白糖和两勺清水调成煲仔饭豉油。","开盖铺菜心，淋豉油，拌匀让每粒米都挂上酱色。"],"tip":"沿锅边淋油是起锅巴的关键，焖好后别急着开盖，焗够5分钟。"},{"name":"青红萝卜猪骨汤","cat":"汤羹","region":"粤","time":120,"diff":"简单","main":[["猪大骨","600g"],["胡萝卜","1根"],["白萝卜","1根"],["红枣","4颗"]],"sea":["姜","盐","料酒"],"steps":["猪大骨冷水下锅，加姜片和料酒煮开，撇净血沫后捞出冲净。","胡萝卜和白萝卜去皮切滚刀块，红枣去核洗净。","汤锅加足量清水，放猪骨和姜片，大火烧开转小火煲60分钟。","下两种萝卜和红枣，继续小火煲40分钟，汤色转成奶白。","关火前加盐调味，撇去表面浮油，连汤带料盛出。"],"tip":"水要一次加足，中途加水会让汤色变浑、鲜味散掉。"},{"name":"盐焗鸡","cat":"荤菜","region":"客家","time":85,"diff":"中等","main":[["整鸡","1只约1000g"]],"sea":["盐","姜","葱","料酒","食用油","香油","十三香"],"steps":["整鸡洗净沥干，用厨房纸把鸡皮内外彻底擦干，越干越好。","盐、姜末、十三香和料酒调成糊，抹遍鸡身内外，腌30分钟入味。","鸡腹塞入姜片和葱段，用油纸把整只鸡包严，扎紧收口。","砂锅底铺一层粗盐，放上鸡，再倒盐把鸡完全埋住。","中火焗20分钟后转小火焗25分钟，关火再焖10分钟。","敲开盐壳取出鸡，刷一层香油，斩件装盘。"],"tip":"鸡皮必须擦干再包纸，盐壳受潮会结块，焗出的鸡才够香。"},{"name":"蜜汁叉烧","cat":"荤菜","region":"粤","time":90,"diff":"中等","main":[["猪里脊","500g"],["蜂蜜","3勺"]],"sea":["生抽","老抽","蚝油","白糖","料酒","五香粉","蒜","姜"],"steps":["猪里脊顺长切成4厘米宽的长条，用叉子在表面扎些小孔。","蒜姜切末，加生抽、老抽、蚝油、白糖、料酒和五香粉调成腌汁。","肉条放入腌汁抓匀，冷藏腌至少4小时，隔夜更入味。","烤箱预热200度，肉条放烤架，下层垫烤盘接油，烤20分钟。","取出刷一层蜂蜜，翻面再烤15分钟，中途再刷一次蜜。","表面焦红发亮时取出，稍凉后逆纹切片，淋上烤盘里的蜜汁。"],"tip":"蜂蜜要分次刷，太早刷糖分容易烤黑，最后十分钟上色最好。"},{"name":"蜜汁鸡翅","cat":"荤菜","region":"粤","time":35,"diff":"简单","main":[["鸡翅中","10个"],["蜂蜜","2勺"]],"sea":["生抽","老抽","蚝油","料酒","蒜","姜","食用油"],"steps":["鸡翅中两面各划两刀，冷水下锅焯1分钟，捞出冲净沥干。","生抽、老抽、蚝油、料酒、蒜末和姜片调成料汁，倒入鸡翅腌20分钟。","平底锅少油，鸡翅皮朝下中小火煎3分钟，煎到一面金黄。","翻面再煎2分钟，倒入腌料和半碗水，中小火焖8分钟。","汤汁收浓时淋蜂蜜，大火翻动30秒，让每只鸡翅裹上亮汁。"],"tip":"蜂蜜一定最后放，早放会焦苦，收汁到能挂住勺子最好。"},{"name":"蚝油生菜","cat":"素菜","region":"粤","time":10,"diff":"简单","main":[["生菜","400g"],["蚝油","2勺"]],"sea":["蒜","生抽","白糖","淀粉","盐","食用油"],"steps":["生菜掰开叶片，用流水冲洗干净，大叶从中间撕成两半。","锅中水烧开加少许盐和油，生菜下锅烫15秒立刻捞出沥水。","生菜码入盘中，轻压出多余水分，避免盘底积水。","热锅少油爆香蒜末，加蚝油、生抽、白糖和小半碗水烧开。","淋淀粉水勾成薄芡，汁一浓就浇在生菜上。"],"tip":"生菜焯水只要十几秒，久烫会发黄出水，芡汁要薄而亮。"},{"name":"姜葱炒蟹","cat":"荤菜","region":"粤","time":30,"diff":"中等","main":[["蟹","2只约600g"],["姜","60g"],["葱","4根"]],"sea":["料酒","生抽","白糖","淀粉","盐","食用油"],"steps":["蟹刷洗干净，揭壳去鳃和胃，斩成四块，切口处拍上干淀粉。","姜切厚片，葱切段，葱白和葱绿分开备用。","锅烧热油至六成热，蟹块切口朝下煎到定型变红，盛出。","余油下姜片和葱白，中火爆到姜片边缘卷起出香。","倒回蟹块，沿锅边淋料酒，加生抽、白糖和半碗水，盖盖中火焖5分钟。","开盖大火收汁，撒葱绿翻两下，汁收紧裹住蟹块即可。"],"tip":"蟹切口拍淀粉再煎，蟹黄不会流失，汤汁也更容易挂住。"},{"name":"豉椒炒牛河","cat":"主食","region":"粤","time":25,"diff":"中等","main":[["河粉","400g"],["牛肉","150g"],["尖椒","2个"],["豆豉","15g"]],"sea":["生抽","老抽","淀粉","蒜","白糖","料酒","食用油"],"steps":["牛肉逆纹切薄片，加生抽、淀粉和一点水抓匀，腌15分钟。","河粉提前用手轻轻抖散，黏连的用筷子挑开，别弄断。","锅烧到冒烟下油，牛肉快速滑炒到变色立刻盛出。","余油爆香蒜末、豆豉和尖椒丝，中火炒到尖椒皮起泡。","下河粉，用筷子配合铲子翻拌，沿锅边淋生抽和老抽。","倒回牛肉，加白糖，大火颠炒30秒，粉条上色均匀即出锅。"],"tip":"河粉下锅后少翻多推，锅要够热才不会断粉粘底。"},{"name":"冬瓜盅","cat":"汤羹","region":"粤","time":100,"diff":"较难","main":[["冬瓜","1个约1500g"],["鸭肉","150g"],["火腿","30g"],["干香菇","4朵"],["莲子","30g"]],"sea":["姜","盐","料酒","白胡椒"],"steps":["冬瓜横切去顶三分之一，挖净瓜瓤和籽做成瓜盅，外皮削出花纹。","鸭肉切小丁焯水去腥，火腿切丁，干香菇泡发切丁，莲子泡软。","鸭丁、火腿、香菇、莲子加姜片、料酒、盐和白胡椒拌匀。","馅料填入冬瓜盅，加半碗清汤，盖上瓜顶，放入深盘。","蒸锅水开后大火蒸60分钟，用筷子能轻松扎透瓜壁即可。","取出原盅上桌，汤汁清亮，用勺连瓜肉一起舀食。"],"tip":"瓜盅底部别挖穿，蒸时盘里垫个碗圈固定，形状才不塌。"},{"name":"白灼虾","cat":"荤菜","region":"粤","time":15,"diff":"简单","main":[["虾","500g"]],"sea":["姜","葱","料酒","生抽","盐","食用油"],"steps":["虾剪去虾枪和长须，用牙签从第二节挑出虾线，冲洗干净。","锅中水加姜片、葱段和料酒烧到大滚。","虾全部下锅，大火煮到虾身弯曲变红，约2分钟立刻捞出。","捞出的虾马上过冰水10秒，虾肉更紧实弹牙。","姜末葱花放碟中，浇热油，加生抽调成蘸碟，配虾上桌。"],"tip":"虾一变红弯成C形就捞，煮久了肉会散，冰水一激更爽脆。"},{"name":"豉汁蒸凤爪","cat":"荤菜","region":"粤","time":90,"diff":"较难","main":[["鸡爪","600g"],["豆豉","20g"]],"sea":["蒜","姜","生抽","老抽","蚝油","白糖","淀粉","料酒"],"steps":["鸡爪剪去指甲，剁成两段，冷水下锅加姜片料酒煮8分钟。","捞出沥干水分，趁热在表面抹一层老抽上色。","油烧到七成热，鸡爪下锅炸到表皮起皱发泡，捞出泡冰水30分钟。","豆豉和蒜剁蓉，加生抽、蚝油、白糖、淀粉和少许水调成豉汁。","鸡爪与豉汁拌匀，皮朝上码入盘中，腌10分钟。","水开后大火蒸25分钟，皮肉软糯脱骨即成。"],"tip":"炸完必须泡冰水，虎皮才会起皱吸汁，这是凤爪松软的关键。"},{"name":"咕噜肉","cat":"荤菜","region":"粤","time":40,"diff":"中等","main":[["五花肉","300g"],["彩椒","1个"],["洋葱","半个"],["鸡蛋","1个"]],"sea":["番茄酱","白醋","白糖","淀粉","盐","料酒","食用油"],"steps":["五花肉切2厘米方块，加盐、料酒和蛋液抓匀，腌15分钟。","肉块逐个裹上干淀粉，捏紧按实，静置5分钟让粉回潮。","油烧至六成热，肉块下锅中小火炸4分钟，捞出升高油温复炸30秒。","彩椒和洋葱切菱形块，热锅少油大火炒1分钟盛出。","锅中放番茄酱、白糖、白醋和半碗水，小火熬到糖化汁稠。","倒入肉块和配菜，大火快速翻匀，让糖醋汁裹满表面即出锅。"],"tip":"复炸一次外壳才脆，糖醋汁熬到起大泡再下肉，挂汁才不稀。"},{"name":"蒜蓉粉丝蒸扇贝","cat":"荤菜","region":"粤","time":25,"diff":"简单","main":[["扇贝","8只"],["粉丝","1把"],["蒜","1头"]],"sea":["生抽","蚝油","白糖","盐","葱","食用油"],"steps":["扇贝用刷子刷净壳面，撬开取出贝肉，去掉黑色内脏洗净。","粉丝用温水泡10分钟至软，剪成两段，铺在扇贝壳内。","蒜剁成蓉，一半用温油小火炒香，与另一半生蒜蓉混合。","蒜蓉加生抽、蚝油、白糖和盐拌匀，铺在贝肉上。","水开后大火蒸6分钟，贝肉刚变白卷边即可，久蒸会老。","出锅撒葱花，淋一勺烧到冒烟的热油激香。"],"tip":"生熟蒜各半最香，蒸的时间按贝大小控制在五到七分钟。"},{"name":"咸鱼蒸肉饼","cat":"荤菜","region":"粤","time":30,"diff":"简单","main":[["猪肉末","300g"],["咸鱼","60g"],["荸荠","3个"]],"sea":["姜","葱","生抽","白糖","淀粉","料酒","白胡椒","食用油"],"steps":["咸鱼去骨切成小粒，用料酒泡5分钟去腥，沥干备用。","荸荠拍碎切细粒，姜切末，葱切花备用。","猪肉末加荸荠、姜末、生抽、白糖、淀粉、白胡椒和两勺水。","顺一个方向搅打5分钟到起胶，再拌入一半咸鱼粒。","肉馅铺进浅盘压成一厘米厚的饼，撒上剩余咸鱼粒。","水开后中火蒸15分钟，出锅撒葱花，淋一勺热油。"],"tip":"肉馅要打到起胶再上锅，蒸出的肉饼才弹牙不散。"},{"name":"滑蛋虾仁","cat":"荤菜","region":"粤","time":20,"diff":"中等","main":[["虾仁","200g"],["鸡蛋","4个"],["葱","2根"]],"sea":["盐","淀粉","料酒","白胡椒","食用油","香油"],"steps":["虾仁开背挑去虾线，加盐、淀粉和料酒抓匀，腌10分钟。","鸡蛋打散，加盐、白胡椒和一勺水淀粉搅匀，蛋液更嫩。","锅烧热油，虾仁中火滑炒到卷曲变红，盛出放凉。","虾仁倒入蛋液，加葱花拌匀，让虾仁裹上蛋液。","锅烧到微热下油，倒入蛋液，中小火用铲子从边缘往中间推。","蛋液七成凝固、表面还带湿润时关火，淋几滴香油出锅。"],"tip":"蛋液半熟就关火，余温会继续凝固，炒老了就不滑。"},{"name":"支竹羊腩煲","cat":"荤菜","region":"粤","time":120,"diff":"中等","main":[["羊肉","600g"],["腐竹","100g"],["白萝卜","1根"]],"sea":["姜","蒜","生抽","老抽","料酒","冰糖","八角","桂皮"],"steps":["腐竹用温水泡软，切成5厘米段，白萝卜去皮切大块。","羊肉切块冷水下锅，加姜片和料酒煮开，撇沫后捞出冲净。","热锅下油爆香姜片、蒜和八角桂皮，倒入羊肉大火炒到表面微焦。","沿锅边淋料酒，加生抽、老抽、冰糖和没过羊肉的热水。","大火烧开转小火焖60分钟，下白萝卜再焖20分钟。","放腐竹煮8分钟，汤汁收浓挂勺时转入砂锅上桌。"],"tip":"腐竹最后放，煮久了会烂成糊，用热水焖肉不发柴。"},{"name":"椒丝腐乳炒通菜","cat":"素菜","region":"粤","time":12,"diff":"简单","main":[["空心菜","400g"],["豆腐乳","2块"],["尖椒","1个"]],"sea":["蒜","白糖","盐","食用油"],"steps":["通菜掐去老梗，留嫩茎和叶，洗净后沥干，切成两段。","豆腐乳连汁压成泥，加白糖和两勺清水调开。","尖椒去籽切成细丝，蒜拍扁后剁成粗末，分开放着备用。","锅烧到冒烟下油，爆香蒜末和椒丝，火要大。","通菜下锅大火快炒40秒，叶片刚塌软就淋腐乳汁。","翻炒20秒让腐乳汁裹匀，汁一收立刻出锅。"],"tip":"通菜下锅要全程大火快炒，动作慢了会发黑出一盘水。"},{"name":"姜撞奶","cat":"甜点","region":"粤","time":20,"diff":"中等","main":[["牛奶","400ml"],["姜","80g"]],"sea":["白糖"],"steps":["姜去皮磨成泥，用纱布包住挤出姜汁，平均分装进三个碗里。","牛奶加白糖倒入小锅，中小火加热到边缘冒小泡约75度。","热牛奶从20厘米高处一次性冲入姜汁碗，冲完不要搅拌。","碗静置5分钟，表面凝固成豆花状、勺子放上去不下沉即成。"],"tip":"牛奶温度在七十到八十度之间最易凝，姜汁必须现挤现用。"},{"name":"芝麻糊","cat":"甜点","region":"粤","time":30,"diff":"简单","main":[["黑芝麻","100g"],["糯米","50g"]],"sea":["白糖"],"steps":["黑芝麻淘洗后沥干，干锅小火炒5分钟，炒到噼啪响有香气。","糯米提前用清水泡1小时，与炒好的芝麻混合。","加600毫升清水，用料理机打成细腻的浆，过筛去渣。","芝麻浆倒入锅中，中小火不停搅拌，煮到冒泡变稠。","加白糖搅匀，煮到能挂住勺背的稠度即关火。"],"tip":"炒芝麻要小火，一焦就发苦；煮浆必须一直搅防糊底。"},{"name":"皮蛋瘦肉粥","cat":"主食","region":"粤","time":70,"diff":"简单","main":[["大米","150g"],["皮蛋","2个"],["猪里脊","150g"]],"sea":["姜","葱","盐","白胡椒","料酒","淀粉","香油","食用油"],"steps":["大米淘净，加一勺油和少许盐拌匀，腌20分钟更容易开花。","猪里脊切细丝，加盐、料酒和淀粉抓匀腌10分钟。","锅中水烧开，下大米大火煮开，转小火熬40分钟，中途搅动防粘底。","皮蛋切小块，一半在粥将稠时下锅，与米同煮出绵滑口感。","另起锅把肉丝烫熟，连姜丝一起下粥，煮3分钟。","加剩余皮蛋、盐和白胡椒，搅匀出锅，撒葱花淋香油。"],"tip":"米先用油盐腌过再煮，粥底更绵滑；皮蛋分两次放味道更浓。"},{"name":"糯米鸡","cat":"主食","region":"粤","time":90,"diff":"中等","main":[["糯米","300g"],["鸡腿","2个"],["干香菇","5朵"],["咸鸭蛋","2个"]],"sea":["生抽","老抽","蚝油","白糖","淀粉","姜","盐","食用油"],"steps":["糯米提前泡4小时，沥干后铺在垫布的蒸屉上，大火蒸25分钟。","鸡腿去骨切小块，加生抽、蚝油、白糖、淀粉和姜末腌20分钟。","干香菇泡发切丁，咸鸭蛋蒸熟取蛋黄，一分为四。","热锅少油，鸡块和香菇丁中火炒到变色，加小半碗水焖5分钟收汁。","蒸好的糯米趁热加生抽、老抽和油拌匀，分成六份压平。","糯米摊开包入鸡肉、香菇和蛋黄，团成球，上锅大火蒸20分钟。"],"tip":"糯米要趁热包才粘得住，垫荷叶蒸出来更清香不粘手。"},{"name":"上汤娃娃菜","cat":"汤羹","region":"粤","time":20,"diff":"简单","main":[["娃娃菜","2棵"],["皮蛋","1个"],["咸鸭蛋","1个"],["蒜","5瓣"]],"sea":["盐","白胡椒","食用油"],"steps":["娃娃菜纵向切成四瓣，冲洗干净，根部连着不散开。","皮蛋和咸鸭蛋剥壳切小丁，蒜拍扁去皮。","锅下油，蒜瓣中小火煎到表面金黄，加两碗清水烧开。","下皮蛋丁和咸蛋丁，中火煮3分钟，汤色变白。","娃娃菜放入汤中，盖盖中火煮6分钟，煮到菜梗透明变软。","加盐和白胡椒调味，连汤盛碗，蒜香浓郁即可。"],"tip":"蒜先煎黄再煮汤，汤才够香够白，咸蛋本身咸，盐要少放。"},{"name":"猪脚姜","cat":"荤菜","region":"粤","time":150,"diff":"中等","main":[["猪蹄","800g"],["鸡蛋","4个"],["姜","200g"]],"sea":["醋","冰糖","盐","食用油"],"steps":["猪蹄刮净毛，斩块，冷水下锅加姜片煮5分钟，撇沫捞出冲净。","姜去皮切厚片，干锅小火煸到两面微干，去掉辛辣水汽。","鸡蛋冷水下锅煮8分钟，捞出过冷水剥壳。","砂锅下油炒香姜片，倒入醋和冰糖，大火烧开。","放入猪蹄，小火煲60分钟，再放鸡蛋继续煲40分钟。","汤汁收到浓稠发亮、猪皮软糯脱骨时，加少许盐调味即可。"],"tip":"姜要先煸干水汽，醋和冰糖约三比一，隔天回锅更入味。"},{"name":"葱烧海参","cat":"荤菜","region":"鲁","time":45,"diff":"较难","main":[["海参","6只"],["葱","3根"]],"sea":["姜","生抽","老抽","蚝油","白糖","料酒","淀粉","食用油"],"steps":["海参剪开腹部去掉沙嘴和内壁白膜，冷水下锅，加姜片和料酒小火煮5分钟去腥，捞出沥干。","大葱只取葱白，切成6厘米长段；锅中放食用油，中小火把葱段煎到两面金黄、边缘发皱，盛出备用。","用余油下姜末爆香，加生抽、老抽、蚝油、白糖和半碗清水烧开，放入海参和葱段，中小火烧8分钟。","汤汁收到剩三分之一时转大火，淋入水淀粉勾薄芡，晃锅让芡汁裹匀，淋半勺食用油提亮出锅。"],"tip":"葱白要用中小火慢煎到金黄出香，火大易发苦，葱香是这道菜的灵魂。"},{"name":"糖醋鲤鱼","cat":"荤菜","region":"鲁","time":50,"diff":"较难","main":[["鲤鱼","1条"]],"sea":["葱","姜","盐","食用油","白糖","醋","料酒","淀粉"],"steps":["鲤鱼去鳞去内脏洗净，两面各斜剞五刀深至鱼骨，用盐和料酒抹遍鱼身，腌15分钟去腥。","淀粉加水调成能挂住鱼身的稠糊，手提鱼尾把糊均匀浇满鱼身，刀口处也要塞进糊。","锅中倒食用油烧到七成热，提鱼尾先炸鱼头定型，再整条滑入，中大火炸6分钟至金黄硬挺，捞出摆盘。","另起锅放少许油，下葱姜末爆香，加白糖、醋、料酒和半碗清水烧开，勾芡到能挂勺。","把滚烫的糖醋汁快速浇在鱼身上，趁热上桌，听到滋滋声说明油温和火候都到位。"],"tip":"复炸一次油温升到八成，鱼壳才够脆；糖醋汁要烧滚再浇，芡汁才亮。"},{"name":"熘肝尖","cat":"荤菜","region":"鲁","time":25,"diff":"中等","main":[["猪肝","300g"],["青椒","1个"],["木耳","1小把"]],"sea":["葱","姜","蒜","醋","料酒","生抽","淀粉","食用油"],"steps":["猪肝切3毫米厚的片，清水泡10分钟挤出血水，加料酒和淀粉抓匀腌5分钟。","青椒切菱形片，木耳撕小朵；生抽、醋、淀粉加两勺清水调成碗汁。","锅烧热倒食用油滑满锅壁，油温五成热下肝片，大火滑散到表面变色立刻捞出。","余油爆香葱姜蒜，下青椒和木耳大火炒1分钟，倒回肝片，淋碗汁快速翻匀。","见芡汁裹住肝片、锅底不见汤汁就关火，整个过程不超过两分钟。"],"tip":"肝片切得厚薄一致才好同时熟；下锅前再上浆，滑油时间长了会发柴。"},{"name":"干炸丸子","cat":"荤菜","region":"鲁","time":30,"diff":"中等","main":[["猪肉末","400g"],["鸡蛋","1个"]],"sea":["葱","姜","淀粉","料酒","盐","白胡椒","花椒粉","食用油"],"steps":["葱姜切碎泡半碗水滤出葱姜水；肉末加盐、料酒、白胡椒，顺一个方向搅到发黏拉丝。","分三次倒入葱姜水，每次都搅到完全吸收，再加鸡蛋和淀粉搅匀，把肉馅摔打十几下上劲。","锅中倒食用油烧到五成热，虎口挤出丸子用勺子刮入油锅，中火炸4分钟定型捞出。","油温升到七成热，丸子回锅复炸1分钟，外壳金黄敲起来发脆就捞出控油。","装盘后趁热撒上花椒粉，外皮酥脆、里面还带汁水时最好吃。"],"tip":"肉馅要摔打起劲丸子才不散；先五成热炸熟、再高温复炸上色才外酥里嫩。"},{"name":"四喜丸子","cat":"荤菜","region":"鲁","time":60,"diff":"中等","main":[["猪肉末","500g"],["荸荠","4个"],["鸡蛋","1个"]],"sea":["葱","姜","淀粉","生抽","老抽","料酒","八角","食用油"],"steps":["荸荠去皮切成绿豆大的碎粒，和猪肉末、鸡蛋、葱姜末、料酒、生抽、淀粉一起顺一个方向搅到起胶。","手上蘸水，把肉馅团成四个拳头大的丸子，双手来回摔打十几下排出空气，丸子才不散。","锅中倒食用油烧到六成热，下丸子中火炸5分钟，表面结壳金黄时捞出。","砂锅底垫葱段姜片，放入丸子，加生抽、老抽、八角和没过一半的热水，大火烧开转小火炖40分钟。","丸子先盛出摆盘，原汤滤去料渣后大火收浓到能挂勺，浇在丸子上撒葱末。"],"tip":"肉馅里加荸荠粒能解腻增脆；丸子先炸定型再炖，久炖也不散。"},{"name":"锅塌豆腐","cat":"素菜","region":"鲁","time":25,"diff":"中等","main":[["豆腐","1块"],["鸡蛋","2个"],["面粉","2勺"]],"sea":["葱","姜","料酒","生抽","盐","食用油","香油"],"steps":["豆腐切1厘米厚、5厘米长的片，平铺在盘里撒少许盐腌5分钟，用厨房纸吸干表面水。","豆腐片先两面拍一层面粉，再裹上打散的蛋液，摆回盘里备用。","平底锅倒食用油铺满锅底，中小火把豆腐片煎到两面金黄、边缘发硬，盛出。","锅里下葱姜末爆香，加生抽、料酒和小半碗清水烧开，放回豆腐，中小火塌3分钟。","汤汁快收干时沿锅边淋香油，晃锅让豆腐裹上汁，整片盛出装盘。"],"tip":"豆腐先拍粉再裹蛋液才挂得住；塌的时候少翻动，晃锅代替铲子不易碎。"},{"name":"油焖大虾","cat":"荤菜","region":"鲁","time":20,"diff":"中等","main":[["虾","500g"]],"sea":["葱","姜","蒜","白糖","醋","料酒","生抽","食用油"],"steps":["大虾剪去虾枪虾须，从背部剪开挑出虾线，用料酒抓匀腌5分钟。","锅中倒食用油烧到六成热，下虾中火煎2分钟，两面变红、虾壳发脆时盛出，虾油留在锅里。","用虾油下葱姜蒜末小火炒香，加白糖、醋、生抽和两勺清水烧开。","倒回大虾，中火焖3分钟，中途翻一次面，让虾身吸饱汤汁。","转大火收汁，用铲子按压虾头挤出虾脑，汤汁浓稠发亮裹住虾身时出锅。"],"tip":"一定要用煎虾出的红油炒料，颜色和鲜味全靠它；收汁时压虾头更香。"},{"name":"葱爆羊肉","cat":"荤菜","region":"鲁","time":15,"diff":"简单","main":[["羊肉","300g"],["葱","3根"]],"sea":["姜","蒜","醋","生抽","料酒","淀粉","食用油","香油"],"steps":["羊肉逆着纹路切薄片，加料酒、生抽、淀粉抓匀，最后淋半勺食用油封住水分，腌10分钟。","大葱斜切成马耳段，葱白葱绿分开；姜蒜切末备用。","锅烧到微微冒烟，倒食用油晃满锅壁，下羊肉片大火爆炒40秒，变色立即盛出。","余油下姜蒜末和葱白段大火炒20秒，倒回羊肉，加葱绿段，沿锅边淋醋和生抽。","大火快翻十下，葱段刚变软就淋香油出锅，全程不超过两分钟。"],"tip":"羊肉片冷冻半小时更好切薄；全程大火快炒，葱一塌就出锅，久炒出汤。"},{"name":"芫爆肚丝","cat":"荤菜","region":"鲁","time":20,"diff":"中等","main":[["猪肚","300g"],["香菜","1把"]],"sea":["葱","姜","蒜","醋","料酒","白胡椒","盐","食用油"],"steps":["熟猪肚切成筷子粗的丝，冷水下锅加葱段姜片和料酒，水开后煮3分钟去味，捞出沥干。","香菜只留梗和嫩叶，切成4厘米长的段；蒜切末，葱姜切丝。","锅烧热放食用油，下葱姜丝和蒜末大火爆香，倒肚丝快速翻炒1分钟。","沿锅边淋醋，加盐和白胡椒炒匀，倒入香菜段，大火翻三下马上关火。","装盘要快，香菜断生带脆、颜色碧绿时口感最好。"],"tip":"香菜最后下锅，翻两三下就出锅，炒久了发黄出水，芫爆的香就没了。"},{"name":"奶汤鲫鱼","cat":"汤羹","region":"鲁","time":30,"diff":"中等","main":[["鲫鱼","1条"]],"sea":["葱","姜","料酒","盐","白胡椒","猪油","食用油"],"steps":["鲫鱼去鳞去腮去内脏，撕掉腹内黑膜，用料酒和盐里外抹匀，腌10分钟去腥。","锅烧热先用姜片擦一遍锅底，放猪油化开，下鲫鱼中小火煎到两面金黄。","冲入滚开的开水，水量一次加足，放葱段姜片，保持大火滚10分钟，汤色变奶白。","转中火再煮8分钟，加盐和白胡椒调味，撇掉表面浮油，出锅前撒葱末。"],"tip":"锅热后用姜擦锅再煎鱼不破皮；必须一次加足滚水并保持大火，汤才奶白。"},{"name":"猪肉炖粉条","cat":"荤菜","region":"东北","time":70,"diff":"中等","main":[["五花肉","400g"],["粉条","1把"]],"sea":["葱","姜","八角","生抽","老抽","料酒","盐","冰糖"],"steps":["五花肉切3厘米见方的块，冷水下锅加姜片料酒焯3分钟，撇去浮沫捞出，用温水冲净。","锅中不放油，下五花肉小火煸5分钟，煸出油脂、肉块边缘变黄卷起。","加冰糖炒到化开裹住肉块，放葱段、姜片、八角炒香，烹入料酒。","加生抽、老抽翻匀上色，倒热水没过肉块两指，大火烧开转小火炖40分钟。","粉条提前泡软，放进锅中再炖10分钟，加盐，汤汁浓厚挂勺即可。"],"tip":"五花肉先干煸出油不用另放油；粉条泡到能弯不软烂，最后十分钟再下锅。"},{"name":"酸菜白肉","cat":"荤菜","region":"东北","time":80,"diff":"中等","main":[["酸菜","500g"],["五花肉","300g"],["粉条","1把"]],"sea":["葱","姜","蒜","花椒","八角","盐","白胡椒","食用油"],"steps":["五花肉整块冷水下锅，加葱段姜片和花椒，大火烧开撇沫，转小火煮30分钟，捞出晾凉切薄片。","酸菜片薄后切细丝，清水抓洗两遍挤干水，酸味太冲就多洗一次，先尝一下酸度。","锅中放少许食用油，下葱姜蒜和八角炒香，倒酸菜丝中火炒5分钟，炒干水汽出酸香。","倒入煮肉的原汤和热水，放白肉片，大火烧开转小火炖25分钟。","粉条泡软后下锅再炖8分钟，加盐和白胡椒，汤浓酸香时撒蒜末出锅。"],"tip":"白肉煮好放凉再切才不散；酸菜一定要先炒干水汽，汤才香不寡淡。"},{"name":"溜肉段","cat":"荤菜","region":"东北","time":30,"diff":"中等","main":[["猪里脊","350g"],["青椒","2个"]],"sea":["葱","姜","蒜","生抽","醋","白糖","淀粉","食用油"],"steps":["猪里脊切2厘米见方的段，加生抽抓匀腌10分钟，再拌入湿淀粉，让每段都裹上厚糊。","青椒切菱形块；碗里放生抽、醋、白糖、淀粉和半碗清水，调成芡汁。","锅中倒食用油烧到六成热，下肉段中火炸4分钟，外壳定型金黄时捞出。","油温升到八成热复炸40秒，表面脆硬时捞出控油。","锅留底油爆香葱姜蒜，下青椒炒30秒，倒入芡汁烧开，回锅肉段大火翻匀，汁紧裹住肉段即可。"],"tip":"糊要厚到看不见肉，复炸一次才脆；芡汁烧开再下肉段，否则外壳回软。"},{"name":"杀猪菜","cat":"荤菜","region":"东北","time":90,"diff":"较难","main":[["五花肉","300g"],["酸菜","500g"],["猪肝","150g"],["猪大肠","200g"],["粉条","1把"]],"sea":["葱","姜","蒜","花椒","八角","生抽","盐","食用油"],"steps":["五花肉整块冷水下锅，加葱姜八角和花椒，小火煮35分钟，捞出切薄片，煮肉汤留用。","猪大肠提前煮熟切段，猪肝切薄片用清水泡出血水，粉条温水泡软。","酸菜切细丝，反复抓洗后挤干，锅中放食用油下葱姜蒜炒香，倒酸菜炒8分钟。","倒入煮肉原汤和热水，放白肉片和大肠，大火烧开转小火炖40分钟。","下粉条煮8分钟，最后放猪肝片汆1分钟，变色就关火，加盐和生抽调味。"],"tip":"猪肝最后下锅汆熟，久煮会发硬；用煮白肉的原汤炖酸菜，味道才厚。"},{"name":"东北乱炖","cat":"荤菜","region":"东北","time":60,"diff":"中等","main":[["排骨","400g"],["豆角","300g"],["土豆","2个"],["茄子","1个"],["玉米","1根"]],"sea":["葱","姜","蒜","八角","生抽","老抽","盐","食用油"],"steps":["排骨剁段冷水下锅，加姜片焯2分钟去血沫，捞出冲净；豆角掐去两头掰成段。","锅中放食用油，下葱姜蒜八角炒香，倒排骨中火煸炒3分钟至表面微焦，加生抽老抽上色。","加开水没过排骨，大火烧开转小火炖20分钟。","放土豆块、玉米段和豆角，中火炖12分钟，土豆能用筷子轻松插透。","最后放茄子块再炖6分钟，加盐，大火收一收汤，汤宽一点才好拌饭。"],"tip":"按耐煮程度分批下锅：排骨先炖，土豆豆角居中，茄子最后放才不烂成泥。"},{"name":"酱大骨","cat":"荤菜","region":"东北","time":90,"diff":"中等","main":[["猪大骨","1500g"]],"sea":["葱","姜","八角","桂皮","黄豆酱","生抽","冰糖","食用油"],"steps":["猪大骨冷水浸泡1小时去血水，再冷水下锅加葱段姜片，大火烧开撇净浮沫，煮5分钟捞出洗净。","锅中放食用油下冰糖，小火炒到融化起小泡，倒入大骨翻炒到表面均匀挂上糖色。","加黄豆酱、生抽、八角、桂皮炒出酱香，倒入没过大骨的热水。","大火烧开转小火炖70分钟，中途翻动两次，让每根骨头都吸到酱汁。","汤汁收到剩三分之一，筷子能轻松插入肉里就关火，在汤里泡20分钟更入味。"],"tip":"炒糖色只到浅琥珀色就下骨头，颜色深了发苦；关火后泡着比猛收汁更入味。"},{"name":"排骨炖豆角","cat":"荤菜","region":"东北","time":45,"diff":"简单","main":[["排骨","500g"],["豆角","500g"]],"sea":["葱","姜","蒜","八角","生抽","老抽","盐","食用油"],"steps":["排骨冷水下锅，加姜片和葱段焯3分钟，撇去血沫捞出，用温水冲净。","豆角掐头尾去筋，掰成6厘米长的段，洗净后彻底沥干水，避免下锅溅油。","锅中放食用油，下排骨中火煸到表面微黄，加葱姜蒜八角炒香，烹生抽老抽上色。","倒热水没过排骨，大火烧开转中小火炖30分钟。","放豆角铺在排骨上，中火炖15分钟，加盐，汤汁收浓、豆角起皱软烂即可。"],"tip":"豆角必须炖到起皱软烂才没有豆腥味；水一次加够，中途添水汤就寡了。"},{"name":"尖椒干豆腐","cat":"素菜","region":"东北","time":15,"diff":"简单","main":[["豆皮","300g"],["尖椒","2个"]],"sea":["葱","姜","蒜","生抽","蚝油","淀粉","盐","食用油"],"steps":["干豆腐切1厘米宽的条，尖椒去籽切斜丝，蒜切片，葱姜切末。","锅中烧水，水开后下干豆腐条汆1分钟去掉豆腥味，捞出沥干。","锅烧热放食用油，下葱姜蒜爆香，倒尖椒丝大火炒40秒至闻到辣香。","倒入干豆腐，加生抽、蚝油和半碗清水，中火烧3分钟让豆腐吸味。","加盐，淋水淀粉勾薄芡，汤汁挂住豆腐条时出锅。"],"tip":"干豆腐先汆水去豆腥且更软；要带点汤汁，勾薄芡才滑嫩不干。"},{"name":"东北大拉皮","cat":"凉菜","region":"东北","time":20,"diff":"中等","main":[["拉皮","300g"],["黄瓜","1根"],["胡萝卜","半根"]],"sea":["蒜","香菜","芝麻酱","醋","生抽","白糖","盐","辣椒油"],"steps":["拉皮切1厘米宽的条，清水冲一下沥干，铺在盘底。","黄瓜、胡萝卜切细丝，香菜切段，蒜捣成泥。","芝麻酱先用温水一点点澥开，调到能流动的稠度，加生抽、醋、白糖、盐拌匀。","把黄瓜丝和胡萝卜丝码在拉皮上，淋上麻酱汁和辣椒油。","最后撒蒜泥和香菜段，吃前用筷子从底往上挑拌，让麻酱汁挂满拉皮。"],"tip":"麻酱要用温水分次澥，一次加会结块；拉皮拌前冲水才不粘连。"},{"name":"老虎菜","cat":"凉菜","region":"东北","time":10,"diff":"简单","main":[["尖椒","3个"],["黄瓜","1根"],["葱","2根"],["香菜","1把"]],"sea":["蒜","生抽","醋","盐","白糖","香油","辣椒油"],"steps":["尖椒去籽切细丝，黄瓜切粗丝，葱白切丝，香菜切段。","尖椒丝放碗里撒盐抓匀腌5分钟，倒掉杀出的水，辣味会柔和一些。","所有菜丝放进大碗，加蒜末、生抽、醋和白糖。","淋香油和辣椒油，用筷子从下往上挑拌20下，让每根菜丝都沾上汁。","拌好立即装盘，放久了会出水，现拌现吃最脆。"],"tip":"尖椒用盐杀一下水更脆也不呛；所有料切得粗细一致，口感才好。"},{"name":"拔丝地瓜","cat":"甜点","region":"东北","time":25,"diff":"较难","main":[["地瓜","500g"]],"sea":["白糖","淀粉","食用油","白芝麻"],"steps":["地瓜去皮切滚刀块，清水冲一遍沥干，撒上薄薄一层淀粉裹匀。","锅中倒食用油烧到六成热，下地瓜块中火炸5分钟，筷子能轻松插透就捞出。","油温升到八成热复炸30秒，外壳变硬金黄，捞出控油。","另起净锅，放白糖和两勺清水，小火慢熬，糖液由大泡变小泡、颜色转浅黄时立刻关小火。","倒入地瓜块快速翻匀，让每块都裹上糖浆，撒白芝麻，装入抹了油的盘中，配一碗凉水蘸着吃。"],"tip":"熬糖全程小火别搅动，糖色浅黄就下料；盘底抹油才不粘，蘸凉水更脆。"},{"name":"东坡肉","cat":"荤菜","region":"浙","time":150,"diff":"中等","main":[["五花肉","800g"]],"sea":["葱","姜","黄酒","冰糖","生抽","老抽"],"steps":["五花肉整块冷水下锅，加姜片和料酒大火煮十分钟，捞出冲净切成五厘米方块，用棉线十字扎紧。","砂锅底部铺满葱段姜片，肉块皮朝下码好，撒上冰糖，淋黄酒、生抽和老抽。","倒黄酒到肉块三分之二的高度，不加一滴水，大火烧开转最小火加盖焖一百分钟。","中途翻面一次让皮朝上，最后大火收汁到汤汁浓稠发亮，剪掉棉线装盘。"],"tip":"全程只加黄酒不加水，火要压到最小，肉才酥而不散。"},{"name":"西湖醋鱼","cat":"荤菜","region":"浙","time":30,"diff":"中等","main":[["草鱼","1条"]],"sea":["姜","醋","白糖","生抽","淀粉","料酒"],"steps":["草鱼宰杀洗净，从背部下刀剖成两半相连的整片，鱼身斜划三刀方便入味。","锅中水烧开加姜片和料酒，拎住鱼尾把鱼滑入，中火煮四分钟，鱼眼发白、鱼肉能戳透即捞出装盘。","另起锅放煮鱼原汤小半碗，加醋、白糖、生抽烧开，淋淀粉水勾薄芡。","芡汁熬到透明微稠，浇在鱼身上，撒姜末即可上桌。"],"tip":"水微沸时下鱼，只煮四分钟，肉才嫩；芡汁宁薄勿厚。"},{"name":"龙井虾仁","cat":"荤菜","region":"浙","time":25,"diff":"中等","main":[["虾仁","300g"]],"sea":["龙井茶","鸡蛋","淀粉","料酒","盐","食用油"],"steps":["虾仁挑去虾线，用清水反复冲到水清，加盐抓匀再冲洗一遍，挤出水分吸干。","虾仁加蛋清、淀粉和料酒抓匀上浆，冷藏静置十五分钟。","龙井茶用八十度热水泡开，留茶汤和茶叶。","锅烧热放油，四成油温下虾仁滑散，虾仁变白立刻捞出控油。","锅中留底油，倒回虾仁、茶叶和两勺茶汤，加盐大火翻两下出锅。"],"tip":"虾仁上浆后冷藏，滑油油温别高，色白发亮才够嫩。"},{"name":"腌笃鲜","cat":"荤菜","region":"本帮","time":120,"diff":"简单","main":[["排骨","400g"],["竹笋","2根"],["火腿","50g"]],"sea":["葱","姜","料酒","盐"],"steps":["排骨冷水下锅，加姜片和料酒大火煮开，撇净浮沫后捞出用温水冲净。","火腿切厚片，竹笋去壳切滚刀块，入开水锅焯三分钟去掉涩味。","砂锅放排骨、火腿和姜片，加足量冷水，大火烧开转小火炖一小时。","下笋块继续小火炖三十分钟，汤呈奶白时加盐调味，撒葱段关火。"],"tip":"火腿本身带咸，盐要最后放；笋先焯水，汤才清鲜不涩。"},{"name":"油焖笋","cat":"素菜","region":"浙","time":20,"diff":"简单","main":[["竹笋","500g"]],"sea":["生抽","老抽","白糖","食用油","香油"],"steps":["竹笋剥壳切去老根，切成滚刀块，入开水锅焯三分钟捞出沥干。","炒锅放油比平时多些，下笋块中火煎到表面微黄起皱。","加生抽、老抽和白糖翻匀，倒小半碗水，转小火加盖焖八分钟。","开盖转大火收汁，汤汁裹满笋块、油亮时淋香油出锅。"],"tip":"笋要煎到起皱再焖，油给足、糖少放，笋才不涩而且鲜香。"},{"name":"狮子头","cat":"荤菜","region":"淮扬","time":60,"diff":"较难","main":[["猪肉末","500g"],["荸荠","4个"],["鸡蛋","1个"],["油菜","4棵"]],"sea":["葱","姜","淀粉","料酒","盐","白胡椒","生抽"],"steps":["荸荠去皮拍碎剁成小粒，葱姜切碎泡小半碗水，挤成葱姜水。","猪肉末加盐、料酒、白胡椒、蛋清和淀粉，分三次加葱姜水，顺一个方向搅打上劲。","拌入荸荠粒，手上沾水把肉馅团成四个大丸子，双手来回摔打十几次排出空气。","油锅六成热下丸子，中火炸到表面金黄定型，捞出沥油。","丸子放进砂锅，加生抽和热水至没过一半，小火炖四十分钟，放油菜再煮两分钟。"],"tip":"肉馅要摔打上劲、炖时只用小火，丸子才松软不散。"},{"name":"大煮干丝","cat":"汤羹","region":"淮扬","time":35,"diff":"较难","main":[["豆干","300g"],["虾仁","50g"],["火腿","30g"],["油菜","2棵"]],"sea":["猪油","盐","料酒","淀粉","葱"],"steps":["豆干片成薄片再切细丝，放进清水泡十分钟，中间换两次水去掉豆腥味。","虾仁加盐、料酒和淀粉抓匀腌十分钟，火腿切细丝。","锅中放猪油化开，下葱段煸香，倒入两碗猪骨汤或清水烧开。","下干丝小火煮八分钟，汤色转白时加盐和火腿丝。","放虾仁和油菜煮两分钟，虾仁变红卷曲即可连汤装碗。"],"tip":"干丝切得越细越入味，全程小火慢煮并不停撇沫，汤才清而不浑。"},{"name":"清炒虾仁","cat":"荤菜","region":"苏","time":20,"diff":"中等","main":[["虾仁","400g"]],"sea":["鸡蛋","淀粉","料酒","盐","食用油","香油"],"steps":["虾仁挑去虾线，用盐抓洗两遍冲净，用厨房纸吸干水分。","加蛋清、淀粉和料酒抓匀上浆，冷藏静置二十分钟。","锅烧热倒油，四成油温下虾仁，用筷子轻轻滑散，变白立刻捞出。","锅中留少许底油，回锅虾仁加盐，大火快炒三十秒，淋香油出锅。"],"tip":"虾仁吸干水再上浆，滑油时间要短，口感才脆嫩弹牙。"},{"name":"叫花鸡","cat":"荤菜","region":"苏","time":150,"diff":"较难","main":[["整鸡","1只"]],"sea":["葱","姜","生抽","老抽","料酒","盐","白糖","荷叶"],"steps":["整鸡洗净擦干，用盐、生抽、老抽、料酒和白糖里外抹匀，塞入葱段姜片腌两小时。","荷叶用开水烫软，把鸡连腌汁一起包好，外面再裹一层锡纸。","面粉加水和成不粘手的硬面团，擀成大片把鸡整个包住，收口捏紧。","烤箱二百度预热，面团鸡放烤盘烤一百分钟，面壳敲起来发硬即可。","出炉敲开面壳和荷叶，取出整鸡斩块装盘。"],"tip":"面团要厚实包严，蒸汽锁在里面，鸡肉才酥烂脱骨。"},{"name":"生煎","cat":"主食","region":"本帮","time":90,"diff":"中等","main":[["面粉","300g"],["猪肉末","250g"]],"sea":["酵母","葱","姜","生抽","白糖","料酒","白芝麻","食用油"],"steps":["面粉加酵母和温水揉成光滑面团，盖布发酵到两倍大。","猪肉末加生抽、白糖、料酒和葱姜水，顺一个方向搅到起黏。","面团排气搓条，切成小剂子擀成圆皮，包入肉馅捏紧，收口朝下。","平底锅刷油，包子收口朝下摆入，中火煎两分钟至底部微黄。","倒入没过包子三分之一的面水，加盖中火焖八分钟，水干后撒芝麻葱花。"],"tip":"面水沿锅边倒入，最后开盖再煎一分钟，底壳才脆。"},{"name":"葱油面","cat":"主食","region":"本帮","time":25,"diff":"简单","main":[["面条","200g"]],"sea":["葱","生抽","老抽","白糖","食用油"],"steps":["葱洗净沥干水，切成长段，把葱白和葱绿分开摆放。","冷油下葱白，小火慢炸五分钟，再下葱绿炸到焦黄干瘪，捞出葱段留油。","葱油中加生抽、老抽和白糖，小火熬到糖化开、微微冒泡，关火做成葱油汁。","面条下开水锅煮三分钟，捞出沥干，趁热拌两勺葱油汁，撒上炸葱。"],"tip":"炸葱全程用小火，葱段焦黄不糊，熬出的油才香而不苦。"},{"name":"蟹粉豆腐","cat":"荤菜","region":"本帮","time":30,"diff":"中等","main":[["蟹","2只"],["豆腐","400g"]],"sea":["姜","猪油","淀粉","料酒","盐","白胡椒"],"steps":["蟹洗净上锅大火蒸十二分钟，拆出蟹黄蟹肉，姜切细末。","豆腐切小方块，入加盐的开水锅焯两分钟，捞出沥水去豆味。","锅放猪油，下姜末和蟹粉小火炒出黄油，烹料酒去腥。","加半碗水烧开，下豆腐轻推，中小火煮三分钟，加盐和白胡椒。","淋淀粉水勾芡，晃锅至汤汁裹住豆腐，撒姜末出锅。"],"tip":"蟹粉要连蟹黄一起炒出红油，豆腐别用铲翻，晃锅才不碎。"},{"name":"糖醋小排","cat":"荤菜","region":"本帮","time":50,"diff":"中等","main":[["排骨","500g"]],"sea":["冰糖","醋","生抽","老抽","料酒","姜","食用油"],"steps":["排骨斩成小段，冷水下锅加姜片和料酒，大火煮开撇沫，捞出冲净沥干。","锅中放油，下排骨中火煎到四面微黄，盛出。","锅内留底油，下冰糖小火炒化，倒回排骨翻炒裹上糖色。","加料酒、生抽、老抽和热水没过排骨，大火烧开转小火焖二十五分钟。","加醋转大火收汁，汤汁黏稠裹住排骨、色泽红亮时出锅。"],"tip":"醋分两次放，焖时放一半、收汁前再补一勺，酸甜味才立得住。"},{"name":"响油鳝糊","cat":"荤菜","region":"本帮","time":25,"diff":"较难","main":[["黄鳝","500g"]],"sea":["蒜","姜","葱","生抽","白糖","淀粉","香油","猪油"],"steps":["鳝丝洗净沥干，切成五厘米长段，蒜切末，姜切丝。","锅烧热放猪油，下姜丝煸香，倒鳝丝大火快炒到变硬出香。","加生抽、白糖和两勺水，中火烧两分钟，淋淀粉水勾薄芡。","盛入盘中，中间扒出一个小窝，放入蒜末和葱花。","另起锅把香油烧到冒烟，滚油浇在蒜末上，听到响声即成。"],"tip":"油必须烧到冒青烟再浇，蒜香被激出来才叫响油。"},{"name":"油爆虾","cat":"荤菜","region":"本帮","time":20,"diff":"简单","main":[["虾","400g"]],"sea":["葱","姜","生抽","白糖","料酒","食用油"],"steps":["虾剪去虾枪和虾须，从背部挑出虾线，冲洗后擦干。","锅倒宽油烧到七成热，下虾大火炸四十秒，外壳变红立刻捞出。","油温再升高，回锅复炸二十秒，虾壳酥脆捞出。","锅中留少许油，下葱段姜片煸香，加生抽、白糖和料酒烧开。","倒入炸虾大火快速翻裹，汁水收干挂在虾壳上即可。"],"tip":"复炸一次虾壳才酥，调味汁要少而稠，裹匀后马上出锅。"},{"name":"文思豆腐","cat":"汤羹","region":"淮扬","time":30,"diff":"较难","main":[["豆腐","300g"],["火腿","20g"],["香菇","2朵"],["鸡蛋","1个"]],"sea":["盐","淀粉","白胡椒","香油","葱"],"steps":["豆腐先片成薄片，再切成火柴梗粗的细丝，泡在清水里轻轻晃散。","火腿、香菇切同样粗细的丝，鸡蛋摊成蛋皮切丝。","锅中加两碗清汤烧开，下香菇丝和火腿丝小火煮五分钟出味。","豆腐丝连水轻轻滑入锅中，用勺背推散，中小火煮三分钟。","加盐和白胡椒，淋淀粉水勾薄芡，撒蛋皮丝和葱花，点香油出锅。"],"tip":"切豆腐丝刀要沾水，下锅只推不搅，丝才不碎汤才清。"},{"name":"虾籽大乌参","cat":"荤菜","region":"本帮","time":120,"diff":"较难","main":[["海参","4只"],["虾皮","15g"]],"sea":["葱","姜","生抽","老抽","白糖","料酒","猪油","淀粉"],"steps":["海参提前泡发洗净，冷水下锅加姜片和料酒煮五分钟去腥，捞出沥干。","虾皮用干锅小火焙香，倒出碾成碎末代替虾籽。","锅中放猪油，下葱段姜片炸到焦黄捞出，留葱油。","海参下锅小火两面煎透，加料酒、生抽、老抽、白糖和两碗热水。","小火煨四十分钟至海参软糯，撒虾皮末，淋淀粉水收浓汤汁。"],"tip":"海参先煎后煨胶质才出，葱油一定要炸足，香气才够厚。"},{"name":"桂花糖藕","cat":"甜点","region":"苏","time":120,"diff":"中等","main":[["莲藕","2节"],["糯米","150g"]],"sea":["冰糖","红糖","桂花","蜂蜜"],"steps":["糯米提前泡两小时沥干水，莲藕去皮，从一头切下两厘米厚片做盖。","把糯米一点点灌进藕孔，用筷子戳实，盖上藕盖用牙签固定。","藕放入砂锅，加冰糖、红糖和没过藕的清水，大火烧开转小火煮九十分钟。","煮到筷子能轻松扎透，关火让藕在糖水里泡一小时。","取出切厚片装盘，淋上浓缩的糖汁，撒桂花和蜂蜜。"],"tip":"糯米只灌到八分满，煮时米粒膨胀，才不会顶破藕身。"},{"name":"酒酿圆子","cat":"甜点","region":"本帮","time":25,"diff":"简单","main":[["糯米粉","150g"],["酒酿","200g"]],"sea":["白糖","枸杞","鸡蛋","淀粉"],"steps":["糯米粉加温水揉成软硬适中的团，搓成长条揪成小剂子，搓成小圆子。","锅中水烧开，下圆子中火煮到全部浮起，再煮一分钟。","加入酒酿和白糖，转小火煮两分钟，别让汤大滚。","鸡蛋打散，沿锅边淋入蛋液，静置五秒再轻推成蛋花。","淋少许淀粉水让汤微稠，撒泡软的枸杞关火。"],"tip":"酒酿下锅后只能用小火，滚久了酒香散尽，汤还会发酸。"},{"name":"罗宋汤","cat":"汤羹","region":"本帮","time":90,"diff":"中等","main":[["牛腩","400g"],["西红柿","3个"],["土豆","1个"],["包菜","半棵"],["洋葱","1个"]],"sea":["黄油","面粉","番茄酱","盐","白糖","白胡椒"],"steps":["牛腩切块冷水下锅焯水，撇沫后捞出，换清水加姜片小火炖一小时。","西红柿切块，土豆切滚刀块，包菜切片，洋葱切丝。","锅中放黄油化开，下洋葱丝小火炒软，加面粉炒到微黄，再下番茄酱炒出红油。","把炒好的料倒进牛肉汤，加西红柿和土豆，中火煮二十分钟。","下包菜再煮十分钟，加盐、白糖和白胡椒，汤浓稠挂勺即可。"],"tip":"面粉要用黄油炒熟炒散再冲入汤中，汤才浓稠又不结块。"},{"name":"毛蟹炒年糕","cat":"荤菜","region":"本帮","time":35,"diff":"中等","main":[["蟹","4只"],["年糕","300g"]],"sea":["葱","姜","生抽","老抽","白糖","淀粉","食用油","料酒"],"steps":["蟹刷净去脐去鳃，对半斩开，切口蘸一层干淀粉封住蟹黄。","年糕片放进温水泡十分钟，泡到能弯折，捞出沥干水。","锅中放油烧热，蟹切口朝下中火煎到定型金黄，加姜片和料酒。","下年糕片，加生抽、老抽、白糖和小半碗水，加盖中火焖六分钟。","开盖大火翻炒到汤汁浓稠裹住年糕，撒葱段出锅。"],"tip":"蟹切口蘸一层干淀粉再煎，蟹黄不流失，汤汁也更鲜。"},{"name":"雪菜冬笋","cat":"素菜","region":"浙","time":20,"diff":"简单","main":[["雪里蕻","200g"],["竹笋","300g"]],"sea":["白糖","食用油","盐","香油"],"steps":["雪里蕻洗净挤干水，切成碎末，竹笋去壳切细丝。","笋丝入开水锅焯三分钟，捞出沥干去涩。","锅烧热放油，下笋丝中火煸炒两分钟至边缘微焦。","倒入雪菜末，转大火快炒三分钟，加白糖和少许盐。","炒到雪菜干香、笋丝入味，淋香油翻匀出锅。"],"tip":"雪菜本身很咸，先尝味再放盐；加一点糖提鲜还能压咸。"},{"name":"糟毛豆","cat":"凉菜","region":"本帮","time":20,"diff":"简单","main":[["毛豆","500g"]],"sea":["糟卤","盐","八角","花椒"],"steps":["毛豆搓洗干净，剪去两头尖角，方便入味。","锅中水烧开，加盐、八角和花椒，下毛豆大火煮八分钟。","捞出毛豆立刻放进冰水里过凉，颜色才能保持翠绿。","毛豆沥干放入保鲜盒，倒糟卤没过，冷藏浸泡四小时。","捞出沥干装盘，再浇一小勺冰镇糟卤，凉吃最爽口。"],"tip":"毛豆煮好立刻过冰水颜色才翠绿，泡足四小时更入味。"},{"name":"四喜烤麸","cat":"凉菜","region":"本帮","time":40,"diff":"中等","main":[["烤麸","300g"],["香菇","4朵"],["木耳","1把"],["花生米","50g"]],"sea":["生抽","老抽","冰糖","香油","食用油","八角"],"steps":["烤麸切小方块，冷水泡十分钟后挤干，入开水锅煮三分钟去酸味。","木耳和香菇提前泡发，香菇切块，花生米煮十分钟。","锅中放油，下烤麸中火煎到四面金黄发硬，盛出。","锅内留油，下香菇、木耳、花生米炒香，加生抽、老抽、冰糖和八角。","倒回烤麸，加两碗水小火焖十五分钟，大火收汁到浓稠，淋香油晾凉。"],"tip":"烤麸必须挤干水分再煎，烧出来才有嚼劲，不会发烂。"},{"name":"阳春面","cat":"主食","region":"苏","time":20,"diff":"简单","main":[["面条","200g"]],"sea":["葱","猪油","生抽","盐"],"steps":["碗中放生抽、盐和一小勺猪油，冲入两勺滚烫的开水化开。","葱切成细末，一半撒进碗里，一半留到最后再撒。","面条下宽水锅，大火煮三分钟，煮到面芯刚断生。","捞出面条沥干，放进碗中，用筷子挑松。","撒上剩余葱花，趁热先喝一口汤，再连汤带面吃。"],"tip":"猪油要用滚开水先冲开，汤才清亮味厚，葱香也浮得上来。"},{"name":"蜜汁火方","cat":"荤菜","region":"苏","time":180,"diff":"较难","main":[["火腿","500g"],["莲子","50g"]],"sea":["冰糖","料酒","蜂蜜","淀粉"],"steps":["火腿用温水刷洗干净，切去外皮和硬边，修成方形大方块。","火腿放碗中加料酒和清水，上锅大火蒸四十分钟，倒掉咸汁，如此重复两次。","莲子用温水泡软，挑掉中间的莲芯，入锅煮十分钟。","火腿加冰糖和清水上锅再蒸一小时，蒸到筷子能轻松插入。","火腿装盘，蒸出的汁加蜂蜜烧开，淋淀粉水勾薄芡浇上，围上莲子。"],"tip":"反复蒸两遍并倒掉咸汁，火腿才不齁，甜味才进得去。"},{"name":"剁椒鱼头","cat":"荤菜","region":"湘","time":45,"diff":"中等","main":[["鱼头","1个(约800g)"],["剁椒","4大勺"]],"sea":["姜","蒜","葱","料酒","蒸鱼豉油","食用油"],"steps":["鱼头从下巴处剖开摊平，去净鱼鳃，用料酒和姜片里外抹一遍，腌10分钟去腥。","盘底垫几根葱段和姜片，鱼头皮朝上摆好，把剁椒连汁铺满整个鱼头表面。","蒸锅水大开后放入，大火蒸12分钟，关火再焖2分钟才取出。","倒掉盘里的腥水，淋两勺蒸鱼豉油，撒上蒜末和葱花。","另起锅大火烧三勺油到冒青烟，趁热浇在蒜末葱花上激出香味。"],"tip":"蒸前倒一次鱼头渗出的血水，蒸好再倒一次盘底汤水，腥味全无。"},{"name":"农家小炒肉","cat":"荤菜","region":"湘","time":20,"diff":"简单","main":[["五花肉","250g"],["尖椒","4个"]],"sea":["蒜","豆豉","生抽","老抽","盐","食用油"],"steps":["五花肉带皮切薄片，肥瘦分开放；尖椒斜切滚刀块，蒜拍碎。","锅烧热不放油，下肥肉片用中小火煸2分钟，逼出油脂至肉片微卷。","下瘦肉片、蒜和豆豉，转大火炒到肉片变色出香。","把肉拨到一边，下尖椒块大火干煸1分钟，炒到表皮起虎皮斑。","转大火，加生抽、少许老抽和盐，与肉片合炒30秒，汤汁收干即出锅。"],"tip":"肥肉先干煸出油，全程不用另加多少油，香味才够浓。"},{"name":"毛氏红烧肉","cat":"荤菜","region":"湘","time":90,"diff":"较难","main":[["五花肉","600g"]],"sea":["冰糖","干辣椒","八角","桂皮","姜","葱","料酒","生抽"],"steps":["五花肉切3厘米见方的块，冷水下锅加姜片和料酒，大火煮开撇沫后捞出沥干。","锅里放少许油和冰糖，小火慢熬到糖色枣红、冒起细密小泡。","倒入肉块中火翻炒，让每块都裹上糖色，再下干辣椒、八角、桂皮和姜片炒香。","烹料酒、加生抽和葱结，倒热水没过肉面，大火烧开转小火加盖炖60分钟。","开盖转大火收汁，边收边翻动，汤汁浓稠挂勺、肉皮发亮时加盐翻匀出锅。"],"tip":"炒糖色只到枣红就下肉，再晚一秒就发苦，宁可炒浅一点。"},{"name":"腊味合蒸","cat":"荤菜","region":"湘","time":60,"diff":"简单","main":[["腊肉","200g"],["香肠","150g"]],"sea":["干辣椒","豆豉","姜","料酒","白糖"],"steps":["腊肉用温水泡20分钟刷洗干净，和香肠一起上锅大火蒸10分钟取出。","腊肉切厚片，香肠斜切片，姜切细丝，干辣椒剪成小段。","肉片和香肠片间隔码进碗里，皮朝下压紧，撒姜丝、豆豉和干辣椒。","淋一勺料酒、撒少许白糖，上锅大火蒸40分钟至肉片透明软烂。","取出倒扣在盘中，把碗底蒸出的原汁浇回肉上即可。"],"tip":"腊味先整块蒸一遍再切片，肉回软不柴，咸味也淡一些。"},{"name":"擂辣椒皮蛋","cat":"凉菜","region":"湘","time":15,"diff":"简单","main":[["青椒","5个"],["皮蛋","2个"]],"sea":["蒜","生抽","香醋","香油","盐","白糖"],"steps":["青椒去蒂，整只放进干锅用中火干煸，边压边翻，煸到表皮焦黑起泡。","趁热装入碗中盖住焖3分钟，让焦皮回软，再撕掉黑皮和籽。","皮蛋剥壳切瓣，蒜拍碎，青椒撕成粗条，一起放进擂钵。","加生抽、香醋、盐、白糖和香油，用擂槌捣20下，捣到青椒出汁、味道融合。"],"tip":"青椒要干锅煸到起黑泡再盖住焖，那股焦香是这道菜的魂。"},{"name":"口味虾","cat":"荤菜","region":"湘","time":50,"diff":"中等","main":[["小龙虾","1000g"]],"sea":["干辣椒","花椒","白糖","姜","蒜","豆瓣酱","料酒","生抽"],"steps":["小龙虾用刷子逐只刷净腹部，剪去虾头前端、抽出虾线，冲洗两遍沥干。","锅放宽油烧到六成热，下小龙虾大火炸2分钟至壳变红，捞出控油。","锅留底油，下姜蒜、干辣椒和花椒小火炒香，加豆瓣酱炒出红油。","倒回小龙虾大火翻炒，烹料酒、加生抽和白糖，倒入半碗热水烧开。","转中火烧8分钟，再大火收汁，汤汁裹满虾壳、锅中只剩红油时出锅。"],"tip":"虾线从尾部中间一拧就出，剪头时留住虾黄，鲜味全在黄里。"},{"name":"发丝牛百叶","cat":"荤菜","region":"湘","time":25,"diff":"较难","main":[["牛百叶","400g"],["蒜苗","2根"]],"sea":["干辣椒","姜","蒜","白醋","盐","淀粉","料酒","食用油"],"steps":["牛百叶洗净，切成长约8厘米的细丝，越细越好，泡在清水里备用。","锅中水烧开，加料酒和姜片，下百叶丝汆10秒立刻捞出过凉水。","蒜苗切段，姜蒜切末，干辣椒剪丝；用白醋、盐、淀粉和两勺水调成碗汁。","锅烧热下油，爆香姜蒜和干辣椒丝，下百叶丝大火快炒20秒。","淋入碗汁、下蒜苗段，大火快速颠翻到汁收亮，马上出锅。"],"tip":"百叶焯水和爆炒都要快，前后不到一分钟，久了就老得嚼不动。"},{"name":"土匪猪肝","cat":"荤菜","region":"湘","time":20,"diff":"中等","main":[["猪肝","300g"],["尖椒","3个"],["蒜苗","1根"]],"sea":["姜","蒜","料酒","淀粉","生抽","豆瓣酱","食用油","盐"],"steps":["猪肝切薄片，用清水抓洗两遍去血水，泡10分钟后挤干。","加料酒、淀粉和少许生抽抓匀腌10分钟，表面再封一层薄油锁住水分。","锅烧到冒烟下油，猪肝大火滑炒30秒，刚变色就盛出。","锅留底油，下姜蒜和豆瓣酱小火炒出红油，加尖椒段大火炒1分钟。","倒回猪肝，下蒜苗段和盐，大火颠炒20秒出锅。"],"tip":"猪肝切薄、抓洗去血水再快炒，滑嫩不腥，切忌久煮。"},{"name":"长沙臭豆腐","cat":"素菜","region":"湘","time":30,"diff":"中等","main":[["豆腐","400g"],["豆腐乳","2块"]],"sea":["蒜","辣椒油","生抽","白糖","香油","葱","食用油","淀粉"],"steps":["豆腐切3厘米见方、1.5厘米厚的块，用厨房纸吸干表面水分。","豆腐乳连汁压成糊，加生抽、白糖、蒜末、辣椒油和两勺水调成酱汁。","锅中油中火烧到六成热，豆腐块薄薄拍一层淀粉，逐块下锅炸。","中火炸4分钟至外壳金黄鼓起，捞起后升高油温复炸30秒逼出油分。","炸好的豆腐用筷子在中间戳个洞，浇上酱汁，撒葱花、淋香油。"],"tip":"豆腐一定吸干水再拍粉，下锅不溅油，外壳才脆得起来。"},{"name":"糖油粑粑","cat":"甜点","region":"湘","time":30,"diff":"简单","main":[["糯米粉","250g"],["红糖","80g"]],"sea":["食用油","蜂蜜"],"steps":["糯米粉加温水，边加边搅成絮状，揉成不粘手的光滑面团。","面团搓成小球，再按成2厘米厚的圆饼，中间按出一个小坑。","锅中放油和红糖，中小火熬到糖化开、冒起细密小泡。","下糯米饼，中小火两面各煎3分钟，煎到表面金黄微鼓。","加半碗热水盖盖中火焖5分钟，开盖收汁到糖浆挂满饼身，淋蜂蜜出锅。"],"tip":"糖和油一起下锅小火熬，糖色才亮，边煎边舀糖汁往饼上浇。"},{"name":"常德米粉","cat":"主食","region":"湘","time":30,"diff":"中等","main":[["米粉","300g"],["猪肉末","150g"]],"sea":["豆瓣酱","姜","蒜","生抽","老抽","盐","食用油","葱"],"steps":["米粉用温水泡20分钟，泡到软而不烂，捞出沥干。","锅中放油，下猪肉末中火炒散，炒到肉末微干、锅底出油。","加姜蒜末和豆瓣酱炒出红油，加生抽、老抽和盐，倒一碗水大火煮开成臊子。","另起锅烧开水，米粉下锅烫1分钟，捞起装碗。","舀两勺臊子带汤汁浇在粉上，撒葱花，吃前从碗底挑起来拌开。"],"tip":"米粉只泡不煮，最后烫一下就行，这样才爽滑不糊汤。"},{"name":"剁椒蒸芋头","cat":"素菜","region":"湘","time":35,"diff":"简单","main":[["芋头","500g"],["剁椒","3大勺"]],"sea":["蒜","葱","生抽","食用油","盐","白糖"],"steps":["芋头去皮切滚刀块，全程戴手套防手痒，块大小切均匀些好熟。","芋头铺在盘里，撒少许盐和白糖，上锅大火蒸20分钟至筷子能轻松戳透。","蒜切末，与剁椒拌在一起，加生抽和半勺油调匀。","把剁椒蒜末铺在芋头上，大火再蒸5分钟，让咸鲜味渗进芋头里。","出锅撒葱花，另烧一勺热油浇在葱花上激香。"],"tip":"芋头先蒸软再铺剁椒，咸味才不会压过芋头的粉糯清甜。"},{"name":"热干面","cat":"主食","region":"鄂","time":25,"diff":"中等","main":[["面条","250g"],["芝麻酱","4大勺"],["榨菜","30g"]],"sea":["香油","生抽","醋","辣椒油","葱","盐","白糖"],"steps":["芝麻酱放碗里，分四次加温水，每次都顺一个方向搅到完全吸收。","调好的麻酱加香油、生抽、醋、盐和白糖拌匀，稀到能缓缓流动。","榨菜切碎，葱切葱花；锅中水大开，面条下锅煮2分钟，刚断生就捞出。","面条摊在案板上，淋一勺香油拌匀，边拌边抖散吹凉到不烫手。","吃前把面在沸水里烫15秒，捞干装碗，浇麻酱、撒榨菜葱花、淋辣椒油拌开。"],"tip":"麻酱要用温水一点点澥开，一次加太多水就会结块澥不动。"},{"name":"三鲜豆皮","cat":"主食","region":"鄂","time":50,"diff":"较难","main":[["豆皮","2张"],["糯米","300g"],["猪肉末","100g"],["鸡蛋","2个"],["香菇","4朵"]],"sea":["生抽","老抽","盐","食用油","葱","姜","白胡椒"],"steps":["糯米提前泡4小时，铺在纱布上大火蒸25分钟至熟透，拌少许油和盐。","香菇切小丁，猪肉末加姜末炒散，下香菇丁、生抽、老抽和盐炒成馅。","鸡蛋打散，豆皮摊平抹一层蛋液，把糯米压成1厘米厚的方片铺上去。","糯米上铺一层肉馅，用锅铲压紧，四边折起包成长方块。","平底锅刷油，豆皮块蛋液面朝下中小火煎3分钟，翻面再煎2分钟至两面金黄。","出锅切成5厘米见方的块，撒上葱花和白胡椒，趁热吃最香。"],"tip":"糯米要压紧实再折边，煎的时候才不散，蛋液是粘住豆皮的关键。"},{"name":"清蒸武昌鱼","cat":"荤菜","region":"鄂","time":25,"diff":"中等","main":[["武昌鱼","1条(约600g)"]],"sea":["姜","葱","料酒","蒸鱼豉油","食用油","盐"],"steps":["鱼去鳞去鳃去内脏，刮净腹内黑膜，两面各斜划三刀。","用料酒和盐把鱼里外抹一遍，鱼腹里塞几片姜和葱段，腌10分钟。","盘底垫葱段姜片，鱼放上去，蒸锅水大开后大火蒸8分钟。","关火焖2分钟取出，倒掉盘中汤水，拣去姜葱，铺上新的葱丝姜丝。","淋两勺蒸鱼豉油，烧一勺热油浇在葱丝上即可。"],"tip":"一斤左右的鱼大火蒸8分钟正好，再焖2分钟，鱼肉能骨边脱开。"},{"name":"沔阳三蒸","cat":"荤菜","region":"鄂","time":60,"diff":"较难","main":[["五花肉","200g"],["草鱼","300g"],["南瓜","200g"],["米粉","80g"]],"sea":["姜","葱","料酒","生抽","盐","白胡椒","食用油"],"steps":["五花肉切厚片，草鱼切块，南瓜切厚片，分别加姜末、料酒、生抽和盐腌15分钟。","米粉用干锅小火炒2分钟至微黄出香，倒出后加盐和白胡椒拌匀。","三样主料分别裹上炒米粉，肉片和鱼块每面都沾匀，再抖掉多余的粉。","蒸笼垫姜片和葱段，先铺南瓜，再摆肉片和鱼块，不要叠得太厚。","大火蒸35分钟，出锅淋一勺热油，撒葱花。"],"tip":"米粉先炒香再裹，蒸出来颗粒分明，不会糊成一坨。"},{"name":"炸藕夹","cat":"荤菜","region":"鄂","time":40,"diff":"中等","main":[["莲藕","400g"],["猪肉末","200g"],["鸡蛋","1个"],["面粉","100g"]],"sea":["姜","葱","生抽","盐","白胡椒","食用油","淀粉"],"steps":["猪肉末加姜末、葱花、生抽、盐和白胡椒，顺一个方向搅到发黏上劲。","莲藕去皮，切第一刀不断、第二刀断开的夹刀片，厚约半厘米。","把肉馅夹进藕片中间，轻轻压平，边缘抹干净，全部做好备用。","面粉加鸡蛋、淀粉和清水，调成能挂住勺背的稠糊，加少许盐。","油烧到六成热，藕夹裹匀面糊下锅，中火炸4分钟至浅黄捞出。","油温升到八成，回锅复炸1分钟至金黄酥脆，捞出沥油。"],"tip":"面糊调到能挂住勺背就够稠，稀了挂不住，藕夹会吃进很多油。"},{"name":"珍珠丸子","cat":"荤菜","region":"鄂","time":50,"diff":"中等","main":[["猪肉末","300g"],["糯米","150g"],["鸡蛋","1个"]],"sea":["姜","葱","生抽","料酒","盐","淀粉","白胡椒"],"steps":["糯米提前泡3小时，捞出沥干，摊在盘里晾到表面不滴水。","猪肉末加姜末、葱花、生抽、料酒、盐、白胡椒和淀粉，再打入鸡蛋。","顺一个方向搅5分钟，搅到肉馅抱团发黏、能整团提起来。","手上蘸水，把肉馅挤成乒乓球大的丸子，滚一圈糯米让米粒裹满。","丸子摆进蒸笼、间隔留够，大火蒸25分钟至米粒透明挺立。"],"tip":"糯米泡到能用手指碾碎就行，泡过头蒸出来会塌成一团糊。"},{"name":"荆州鱼糕","cat":"荤菜","region":"鄂","time":60,"diff":"较难","main":[["草鱼","600g"],["鸡蛋","3个"],["淀粉","60g"]],"sea":["姜","葱","料酒","盐","白胡椒","猪油","食用油"],"steps":["草鱼去骨去皮，取净肉切小块，用清水漂洗两遍去血水，挤干水分。","鱼肉加姜末、葱白、料酒、盐和白胡椒，分次加少量冰水打成细腻鱼茸。","鱼茸加淀粉和一勺猪油，顺一个方向搅10分钟，搅到能拉出短丝。","蛋黄蛋白分开，蛋白拌进鱼茸，倒进抹了油的方模，刮平表面。","大火蒸20分钟定型，取出抹一层蛋黄液，再蒸5分钟至表面金黄。","晾凉后切成半厘米厚的片，可直接冷吃，也能下汤中火煮2分钟。"],"tip":"鱼茸要打到上劲、插根筷子能立住，蒸出来才弹，切片不散。"},{"name":"洪山菜薹炒腊肉","cat":"荤菜","region":"鄂","time":20,"diff":"简单","main":[["菜薹","400g"],["腊肉","150g"]],"sea":["蒜","干辣椒","盐","食用油","生抽","白糖"],"steps":["菜薹掰去老皮和花苞，掐成5厘米长的段，粗梗从中间剖开。","腊肉先蒸10分钟回软，切成薄片，蒜拍碎，干辣椒剪段。","锅中放少许油，下腊肉片小火煸2分钟，煸到肥肉透明、油渗出来。","下蒜和干辣椒炒香，转大火倒入菜薹，快速翻炒1分半。","菜薹梗变翠绿微软时加盐、生抽和白糖，大火再炒20秒出锅。"],"tip":"菜薹粗梗先剖开，全程大火、时间要短，才脆嫩不发黄。"},{"name":"襄阳牛肉面","cat":"主食","region":"鄂","time":120,"diff":"较难","main":[["牛肉","500g"],["面条","300g"],["豆芽","150g"]],"sea":["豆瓣酱","干辣椒","花椒","八角","姜","生抽","料酒","盐"],"steps":["牛肉切大块，冷水下锅加姜片和料酒焯水，撇净浮沫后捞出冲干净。","锅中放油，下豆瓣酱、干辣椒、花椒、八角和姜片，小火炒出红油。","下牛肉块中火翻炒上色，加生抽和料酒，倒入热水没过牛肉。","大火烧开转小火炖90分钟，炖到筷子能轻松插入，汤留作浇头。","另起锅烧水，豆芽烫30秒垫在碗底，面条大火煮2分钟捞进碗里。","牛肉切片铺在面上，浇两勺滚热的牛肉汤，按口味补一点盐。"],"tip":"牛肉整块炖透再切片，切得薄而不断，浇热汤时肉才不柴。"},{"name":"糊汤粉","cat":"主食","region":"鄂","time":40,"diff":"较难","main":[["鲫鱼","400g"],["米粉","250g"],["榨菜","30g"]],"sea":["姜","葱","白胡椒","盐","料酒","淀粉","食用油"],"steps":["鲫鱼去鳞去内脏，撕净腹内黑膜，用料酒和姜片腌10分钟。","锅中放油，鲫鱼两面各煎3分钟至微黄，冲入滚开水大火熬10分钟。","汤色奶白后转小火再熬15分钟，用铲子把鱼身压碎，让肉骨化进汤里。","用细筛把鱼汤过滤一遍，用力压出汤汁，鱼渣丢掉。","鱼汤回锅烧开，淀粉加水调匀后分三次淋入，边淋边搅到汤浓稠挂勺。","米粉烫1分钟装碗，浇上鱼糊汤，撒白胡椒、榨菜末和葱花。"],"tip":"煎鱼后必须冲滚开水汤才白，淀粉水分三次淋，糊才细滑。"},{"name":"米酒汤圆","cat":"甜点","region":"鄂","time":20,"diff":"简单","main":[["糯米粉","150g"],["米酒","200g"],["鸡蛋","1个"]],"sea":["白糖"],"steps":["糯米粉加温水揉成软硬适中的面团，搓成小指粗的条，再揪成小粒搓圆。","锅中加两碗水烧开，下小汤圆，中火煮到全部浮起。","转小火，倒入米酒轻轻推散，加白糖搅到化开。","鸡蛋打散，沿锅边细细淋入，静等5秒再推散成蛋花。","汤再滚起就关火，盛出趁热喝，凉了米酒的酒香就散尽了。"],"tip":"米酒最后下、一滚就关火，酒香才不跑，汤也不会发酸。"},{"name":"酸辣藕丁","cat":"素菜","region":"鄂","time":20,"diff":"简单","main":[["莲藕","400g"],["尖椒","2个"]],"sea":["蒜","干辣椒","白醋","盐","白糖","食用油","生抽"],"steps":["莲藕去皮切1厘米见方的丁，泡进加了白醋的水里防止发黑。","尖椒切圈，蒜切末，干辣椒剪段，藕丁捞出沥干水分。","锅烧热下油，爆香蒜末和干辣椒，下藕丁大火快炒2分钟。","沿锅边淋一勺白醋，加盐、白糖和生抽，继续大火炒1分钟。","下尖椒圈大火炒30秒，藕丁断生还脆时立刻出锅。"],"tip":"藕丁泡醋水再大火快炒，颜色雪白，咬起来才脆生生。"},{"name":"蛋酒","cat":"汤羹","region":"鄂","time":15,"diff":"简单","main":[["鸡蛋","2个"],["米酒","250g"]],"sea":["白糖"],"steps":["鸡蛋磕入碗中，用筷子打散到蛋液均匀、没有成块的蛋清。","小锅加一碗半水烧开，倒入米酒再次烧到锅边冒小泡。","转小火，把蛋液沿锅边转圈淋入，静置5秒让蛋液凝成片。","转小火，用勺轻轻推散成蛋花，加白糖搅化，汤一滚就关火。","盛入碗中趁热喝，喜酒味重的可关火后再添一勺米酒。"],"tip":"蛋液淋进去别马上搅，等它凝成片再推，蛋花才大片又嫩。"},{"name":"肉夹馍","cat":"主食","region":"陕西","time":180,"diff":"较难","main":[["五花肉","500g"],["面粉","500g"],["酵母","5g"]],"sea":["葱","姜","八角","桂皮","香叶","生抽","老抽","冰糖"],"steps":["五花肉整块冷水下锅焯5分钟，捞出冲净浮沫，切成拳头大的块。","砂锅放肉，加葱段姜片八角桂皮香叶，倒生抽老抽和冰糖，加水没过肉块两指。","大火烧开转小火炖90分钟，筷子能轻松扎透、汤汁剩一半时加盐，关火焖20分钟。","面粉加酵母和温水揉成硬面团，盖布醒发40分钟，揪成剂子擀成圆饼。","平底锅中小火烙饼，每面3分钟，烙到两面起虎皮斑、边缘发干。","饼横刀片开但不切断，塞入剁碎的卤肉，浇一勺卤汁即可。"],"tip":"面团要比馒头面硬些，烙饼时锅里不刷油，饼皮才能又脆又干。"},{"name":"羊肉泡馍","cat":"主食","region":"陕西","time":180,"diff":"较难","main":[["羊肉","600g"],["面粉","400g"],["粉丝","1把"],["木耳","20g"],["黄花菜","20g"]],"sea":["葱","姜","花椒","八角","桂皮","盐","白胡椒","香菜"],"steps":["羊肉切大块冷水浸泡1小时去血水，再冷水下锅焯净浮沫。","换清水加葱姜花椒八角桂皮，大火烧开转小火炖150分钟，肉能用筷子夹散。","面粉加温水揉成偏硬面团，醒30分钟后擀成厚饼，小火烙到两面微黄后掰成指甲盖大的馍粒。","羊肉汤舀入锅中烧开，下泡发的粉丝木耳黄花菜煮3分钟。","倒入馍粒中火煮2分钟，加盐和白胡椒，出锅撒香菜。"],"tip":"馍粒要掰得小而匀，边缘带毛茬，才能吸饱汤又不泡烂。"},{"name":"油泼面","cat":"主食","region":"陕西","time":40,"diff":"中等","main":[["面粉","300g"],["油菜","3棵"],["豆芽","100g"]],"sea":["蒜","葱","辣椒面","花椒粉","醋","生抽","盐","食用油"],"steps":["面粉加2g盐和160ml温水揉成光滑面团，抹油盖膜醒40分钟。","面团搓成长条切成小剂子，再抹油醒10分钟，擀成宽片并在中间压一道印。","双手捏住面片两端轻轻抖长，从压印处撕成两条，水开下面煮3分钟。","面快熟时下油菜和豆芽烫30秒，一起捞进碗里。","面上铺蒜末葱花辣椒面花椒粉，加盐和生抽，泼上烧到冒青烟的油，淋醋拌匀。"],"tip":"泼的油必须烧到微微冒烟，辣椒面才能激出红油香。"},{"name":"臊子面","cat":"主食","region":"陕西","time":60,"diff":"中等","main":[["五花肉","300g"],["面条","400g"],["胡萝卜","1根"],["土豆","1个"],["豆腐","200g"]],"sea":["葱","姜","蒜","干辣椒","八角","醋","生抽","盐"],"steps":["五花肉切小丁，锅里不放油小火煸5分钟，煸到肉丁出油、边缘微焦。","下葱姜蒜末干辣椒和八角炒香，倒醋和生抽，小火焖20分钟成臊子。","胡萝卜土豆切小丁，豆腐切丁下锅煎到表面金黄。","另起锅把臊子连汤倒入，加开水烧开，下三种丁中火煮8分钟，加盐调成酸汤。","面条煮熟捞入碗中，浇上臊子和汤，撒葱花。"],"tip":"醋要在炒臊子时就放，随小火焖进肉里，酸香才不冲口。"},{"name":"凉皮","cat":"凉菜","region":"陕西","time":90,"diff":"较难","main":[["面粉","500g"],["黄瓜","1根"],["豆芽","100g"]],"sea":["蒜","醋","生抽","辣椒油","芝麻酱","盐","香油"],"steps":["面粉加水和成软面团，盖布醒30分钟，放进盆里加清水反复抓洗。","洗到水变清、手里只剩一团有弹性的面筋，把洗出的面浆静置4小时。","倒掉上层清水搅匀面浆，舀一勺倒进刷油的平盘，上汽蒸3分钟至鼓起大泡。","平盘取出放冷水上降温，揭下凉皮刷油叠放，切成两指宽的条。","面筋上锅蒸15分钟切块，黄瓜切丝，与凉皮加蒜水醋生抽辣椒油芝麻酱拌匀。"],"tip":"面浆浓度以挂勺后能缓慢流下为准，太稀蒸不成形。搅拌要用勺子兜底搅匀。"},{"name":"葫芦头","cat":"汤羹","region":"陕西","time":180,"diff":"较难","main":[["猪大肠","500g"],["猪肚","300g"],["面粉","300g"],["粉丝","1把"]],"sea":["葱","姜","蒜苗","花椒","八角","盐","白胡椒","醋"],"steps":["猪大肠翻面撕掉油膜，用盐和醋反复搓洗三遍，搓到不滑不腥。","大肠和猪肚冷水下锅，加花椒葱姜煮10分钟，捞出切成一指长的段。","砂锅加水放肠肚和葱姜八角，大火烧开转小火炖120分钟至筷子能扎透。","面粉加温水揉团擀成饼，平底锅小火烙熟，掰成小块。","原汤烧开下粉丝和馍块煮3分钟，加盐白胡椒，撒蒜苗。"],"tip":"大肠用盐醋干搓比水洗去腥彻底，搓到发黏再冲净。"},{"name":"大盘鸡","cat":"荤菜","region":"新疆","time":70,"diff":"中等","main":[["整鸡","1只"],["土豆","2个"],["青椒","2个"],["洋葱","1个"]],"sea":["干辣椒","花椒","八角","姜","蒜","豆瓣酱","生抽","白糖"],"steps":["整鸡剁成核桃大的块，冷水下锅焯3分钟，捞出沥干水分。","锅里放油和白糖，小火炒到糖色变枣红起小泡，倒入鸡块大火翻炒上色。","下姜蒜花椒八角干辣椒和豆瓣酱炒出红油，加生抽翻匀。","倒入没过鸡块的热水，大火烧开转中火炖20分钟。","下土豆块继续炖15分钟，炖到土豆边缘发糊、汤汁剩一半。","放青椒块和洋葱块大火收汁3分钟，汤汁浓稠挂勺即可。"],"tip":"土豆后放并切大块，炖到起沙才不散，剩下的汤汁拌面最香。"},{"name":"拉条子","cat":"主食","region":"新疆","time":60,"diff":"中等","main":[["面粉","400g"],["羊肉","200g"],["西红柿","1个"],["青椒","1个"],["洋葱","半个"]],"sea":["蒜","番茄酱","生抽","醋","盐","食用油","孜然"],"steps":["面粉加3g盐和200ml温水揉成软硬适中的面团，抹油盖膜醒1小时。","面团搓成手指粗的长条，盘在抹油的盆里再醒20分钟。","水开后把面剂子拉细下锅，煮2分钟浮起即捞，过一遍凉水沥干。","热锅热油下羊肉片大火炒到变色、边缘微焦，加蒜末和洋葱丝炒香。","下西红柿块炒出汁，加番茄酱生抽和少许水，煮2分钟成浓汁。","倒入煮好的面和青椒丝大火翻炒1分钟，加盐和孜然，沿锅边淋醋出锅。"],"tip":"面和得比饺子面软，醒够时间拉的时候才不会回缩断条。"},{"name":"手抓饭","cat":"主食","region":"新疆","time":90,"diff":"中等","main":[["大米","400g"],["羊肉","500g"],["胡萝卜","2根"],["洋葱","1个"]],"sea":["孜然","盐","食用油","花椒"],"steps":["大米淘洗后温水泡30分钟，捞出沥干；胡萝卜切粗条，洋葱切丝。","锅里多放油，下羊肉块中火煎8分钟，煎到表面金黄出油。","下洋葱丝炒到透明，再下胡萝卜条翻炒5分钟至变软。","加盐和孜然炒匀，倒入没过食材的开水，大火烧开转小火煮15分钟。","把泡好的米平铺在肉上，用筷子戳几个洞，水面刚好高过米一指。","盖盖小火焖40分钟，关火再焖10分钟，从锅底翻拌均匀。"],"tip":"焖的时候别搅动，靠蒸汽把米焖熟，最后翻拌才不会夹生。"},{"name":"馕包肉","cat":"荤菜","region":"新疆","time":90,"diff":"中等","main":[["羊排","600g"],["馕","1个"],["土豆","1个"],["胡萝卜","1根"]],"sea":["干辣椒","花椒","姜","蒜","生抽","老抽","孜然","盐"],"steps":["羊排剁成段，冷水下锅焯5分钟去血沫，捞出用温水冲净。","锅里放油下姜蒜花椒干辣椒炒香，倒入羊排中火煸到表面微黄。","加生抽老抽和盐，倒开水没过羊排，大火烧开转小火炖40分钟。","下土豆块和胡萝卜块再炖15分钟，到羊排能脱骨、汤汁剩三分之一。","馕切成三角块垫在盘底，连汤带肉浇上去，撒孜然焖2分钟。"],"tip":"馕要最后浇汁，泡久了会散，垫在盘底吸汁最入味。"},{"name":"拌面","cat":"主食","region":"新疆","time":45,"diff":"中等","main":[["面条","400g"],["牛肉","200g"],["青椒","1个"],["洋葱","半个"],["木耳","20g"]],"sea":["蒜","番茄酱","生抽","醋","盐","淀粉","食用油"],"steps":["牛肉逆纹切薄片，加生抽淀粉和一勺水抓匀，腌15分钟。","面条煮到八分熟捞出，过凉水沥干，拌少许食用油防粘。","热锅热油下牛肉片大火滑炒1分钟到变色，盛出备用。","锅里留油下蒜末洋葱丝炒香，加青椒木耳大火炒2分钟。","倒回牛肉，加番茄酱生抽和半碗水，中火煮2分钟到汤汁浓稠。","下面条大火翻拌1分钟，加盐，沿锅边淋醋出锅。"],"tip":"面只煮八分熟再回锅拌，吸汁后口感筋道不软烂。"},{"name":"揪面片","cat":"主食","region":"陕西","time":45,"diff":"中等","main":[["面粉","300g"],["羊肉","150g"],["西红柿","1个"],["土豆","1个"],["菠菜","1把"]],"sea":["葱","姜","蒜","生抽","盐","醋","食用油"],"steps":["面粉加少许盐和温水揉成偏软面团，盖布醒30分钟。","羊肉切片，土豆切小丁，西红柿切块，菠菜洗净切段。","热锅热油下羊肉片炒到变色，加葱姜蒜末炒香，下西红柿炒出红汁。","加土豆丁翻炒2分钟，倒开水烧开，中火煮8分钟到土豆软烂。","面团擀成厚片切成宽条，用手揪成指甲盖大的面片下进滚汤。","面片全部浮起后再煮2分钟，放菠菜加盐，淋醋出锅。"],"tip":"揪面片时手指蘸水，面片才不粘手，下锅也不粘连。"},{"name":"羊肉汤","cat":"汤羹","region":"陕西","time":150,"diff":"简单","main":[["羊肉","500g"],["羊排","300g"],["白萝卜","1根"],["粉丝","1把"]],"sea":["葱","姜","花椒","白胡椒","盐","香菜","醋"],"steps":["羊肉和羊排冷水浸泡2小时，中途换两次水，泡到肉色发白。","冷水下锅，大火烧开后撇净浮沫，反复撇到汤面清亮。","放葱段姜片和花椒，转小火保持微沸炖120分钟。","白萝卜切滚刀块下锅，再炖20分钟到萝卜透明。","下粉丝煮3分钟，加盐和白胡椒，盛出撒香菜，配醋碟上桌。"],"tip":"全程小火微沸不翻滚，汤才清亮不浑，腥味也散得干净。"},{"name":"洋芋擦擦","cat":"素菜","region":"陕西","time":40,"diff":"简单","main":[["土豆","3个"],["面粉","100g"]],"sea":["葱","蒜","干辣椒","辣椒面","醋","盐","食用油"],"steps":["土豆去皮擦成粗条，清水冲一遍后彻底沥干，表面不能带水。","土豆条拌入面粉用手抓散，让每一根都裹上薄薄一层干粉。","蒸屉铺湿布，把土豆条松散铺开，水开上汽后蒸12分钟。","蒸好倒出趁热抖散，摊开晾2分钟散掉水汽。","热锅热油爆香蒜末干辣椒，倒入土豆条大火炒2分钟到边缘微焦。","加盐和辣椒面翻匀，撒葱花，沿锅边淋醋出锅。"],"tip":"土豆条必须沥干再拌粉，粉裹得薄，蒸出来才根根分明。"},{"name":"甑糕","cat":"甜点","region":"陕西","time":180,"diff":"较难","main":[["糯米","500g"],["红枣","300g"],["红豆","100g"]],"sea":["红糖","白糖","蜂蜜"],"steps":["糯米和红豆分别用清水泡6小时，泡到米粒能用手捻碎。","红枣去核，一半铺在盆底，上面撒一层红糖。","铺一层糯米压实，再铺红枣和红豆，重复铺到八分满，最上层是枣。","沿盆边缓缓注入清水，水面高出米面两指，盖盘上锅。","大火烧开转小火蒸150分钟，中途补一次开水，蒸到米枣黏成一团。","关火焖30分钟，倒扣出来切块，撒白糖或淋蜂蜜。"],"tip":"水一次加够但别淹过枣面，小火久蒸才能让米和枣融成糯团。"},{"name":"水盆羊肉","cat":"汤羹","region":"陕西","time":180,"diff":"较难","main":[["羊肉","600g"],["羊排","400g"],["粉丝","1把"],["面粉","300g"]],"sea":["葱","姜","花椒","桂皮","盐","白胡椒","香菜"],"steps":["羊肉羊排冷水泡2小时去血水，冷水下锅焯5分钟，撇净浮沫。","换清水加葱姜花椒桂皮，大火烧开转小火炖150分钟，汤色发乳白。","面粉加温水揉成软面团，醒30分钟后擀成小圆饼，平底锅烙熟成月牙饼。","羊肉捞出晾到不烫手，切成薄片，粉丝用温水泡到发软。","舀两勺原汤烧开，下粉丝煮2分钟，再放羊肉片烫1分钟。","加盐和白胡椒，撒香菜葱花，配月牙饼掰着泡吃。"],"tip":"汤要一直小火养着，大火滚会浑汤，肉也容易发柴。"},{"name":"手抓羊肉","cat":"荤菜","region":"新疆","time":100,"diff":"简单","main":[["羊肉","1000g"],["洋葱","1个"]],"sea":["姜","花椒","盐","葱","蒜","醋","辣椒油"],"steps":["带骨羊肉剁成大块，冷水浸泡1小时，中途换一次水。","冷水下锅，大火烧开撇净浮沫，撇到汤面干净无沫。","放姜片葱段和花椒，转小火煮70分钟，筷子能轻松插透即可。","出锅前十分钟撒盐，关火焖两分钟，让咸味吃进肉里。","洋葱切丝垫盘，羊肉捞出趁热摆上，浇一勺原汤。","蒜末加醋和辣椒油调成蘸碟，配肉上桌。"],"tip":"盐一定在出锅前才放，早放肉会发紧，久煮也不香。"},{"name":"椒麻鸡","cat":"凉菜","region":"新疆","time":90,"diff":"中等","main":[["整鸡","1只"],["洋葱","1个"],["尖椒","2个"]],"sea":["花椒","葱","姜","辣椒油","醋","盐","香油","生抽"],"steps":["整鸡洗净冷水下锅加葱姜，大火烧开转小火煮25分钟，关火再焖20分钟。","捞出立刻放进冰水里浸10分钟，鸡皮收紧后剁成块。","花椒用温水泡5分钟捞出沥干，冷油下锅小火炸3分钟成花椒油。","花椒油连花椒倒出，加辣椒油生抽醋盐和香油调成椒麻汁。","洋葱切丝，尖椒切圈，和鸡块一起放大盆。","浇上椒麻汁抓拌均匀，冷藏20分钟入味。"],"tip":"鸡煮好必须过冰水，鸡皮才脆爽，椒麻汁也挂得住。"},{"name":"羊肉焖饼子","cat":"荤菜","region":"新疆","time":100,"diff":"中等","main":[["羊肉","600g"],["面粉","300g"],["土豆","2个"],["胡萝卜","1根"]],"sea":["干辣椒","花椒","姜","蒜","生抽","老抽","盐","食用油"],"steps":["羊肉剁块冷水焯5分钟，捞出冲净浮沫沥干。","热锅热油下姜蒜花椒干辣椒炒香，倒羊肉中火煸8分钟到出油微焦。","加生抽老抽和盐翻匀，倒开水没过羊肉，大火烧开转小火炖30分钟。","面粉加温水揉成软面团，醒20分钟后擀成薄饼，切成手掌大的片。","下土豆块和胡萝卜块煮10分钟，把饼片一张张贴在汤面上。","盖盖小火焖15分钟，饼吸饱汤汁变软，撒蒜末出锅。"],"tip":"饼要擀得薄，贴着汤面焖，一半吸汁一半筋道最好吃。"},{"name":"丁丁炒面","cat":"主食","region":"新疆","time":45,"diff":"中等","main":[["面条","400g"],["牛肉","200g"],["西红柿","1个"],["青椒","1个"],["洋葱","半个"]],"sea":["蒜","番茄酱","生抽","醋","盐","食用油"],"steps":["面条煮到八分熟捞出过凉水，切成两厘米长的短段。","牛肉切小丁加生抽抓匀腌10分钟；西红柿青椒洋葱都切成丁。","热锅热油下牛肉丁大火炒2分钟到变色微焦，盛出。","下蒜末洋葱丁炒香，加西红柿丁炒出红汁，放番茄酱炒匀。","倒面段和牛肉丁，加青椒丁大火翻炒2分钟到汤汁裹匀。","加盐，沿锅边淋一勺醋，大火翻炒半分钟即可出锅。"],"tip":"面煮好过凉水再切，切段不粘刀，回锅炒也不成坨。"},{"name":"裤带面","cat":"主食","region":"陕西","time":50,"diff":"中等","main":[["面粉","400g"],["油菜","4棵"],["豆芽","100g"]],"sea":["蒜","葱","辣椒面","醋","生抽","盐","食用油"],"steps":["面粉加3g盐，分次倒入210ml温水揉成硬面团，盖布醒30分钟。","面团再揉5分钟至光滑，搓成粗条切成剂子，抹油醒1小时。","取剂子按扁擀成牛舌状，双手托住两端在案板上摔打抻长。","扯到约两指宽一米长，水开下锅煮2分钟，中间点一次凉水。","面快熟时下油菜和豆芽烫30秒，一起捞入碗中。","面上放蒜末葱花辣椒面，加盐生抽，泼一勺滚油，淋醋拌匀。"],"tip":"醒面时间宁长勿短，面醒透了摔打时才不回缩、不断条。"},{"name":"麻食","cat":"主食","region":"陕西","time":60,"diff":"中等","main":[["面粉","300g"],["西红柿","2个"],["土豆","1个"],["鸡蛋","2个"],["木耳","20g"]],"sea":["葱","姜","蒜","生抽","盐","醋","食用油"],"steps":["面粉加水和成偏硬面团，盖布醒30分钟，揉到表面光滑。","面团搓成筷子粗的条，切成小丁，用拇指在案板上捻成猫耳状。","西红柿切块，土豆切丁，木耳泡发撕小朵，鸡蛋打散。","热锅热油炒散鸡蛋盛出，下葱姜蒜末炒香，加西红柿炒出红汁。","下土豆丁和木耳翻炒2分钟，倒开水烧开，中火煮8分钟。","下麻食煮5分钟浮起，倒回鸡蛋，加盐淋醋出锅。"],"tip":"麻食捻得薄一点、中间留个小窝，才容易煮熟也挂得住汤。"},{"name":"荞面饸饹","cat":"主食","region":"陕西","time":50,"diff":"中等","main":[["荞麦面","300g"],["面粉","100g"],["黄瓜","1根"],["豆芽","100g"]],"sea":["蒜","醋","生抽","辣椒油","盐","香油"],"steps":["荞麦面和面粉按三比一混合，加2g盐，分次加温水搅成絮状。","揉成稍硬的面团，盖布醒30分钟，中间再揉两次。","面团塞进饸饹床，水开后压成细条直接入锅，煮3分钟浮起。","捞出过两遍凉水，沥干后拌少许香油防粘。","黄瓜切丝，豆芽焯30秒过凉，一起铺在饸饹上。","蒜末加醋生抽盐和辣椒油调成汁浇上，拌匀即可。"],"tip":"荞面没有筋性，掺两成白面才压得成条，水大开再压不粘床。"},{"name":"烤包子","cat":"主食","region":"新疆","time":90,"diff":"中等","main":[["面粉","400g"],["羊肉","400g"],["洋葱","2个"]],"sea":["孜然","黑胡椒","盐","食用油","花椒粉"],"steps":["面粉加2g盐和温水揉成偏硬面团，盖布醒40分钟。","羊肉切成小方丁，洋葱切碎，用手把洋葱汁挤进羊肉里。","加孜然黑胡椒花椒粉和盐拌匀，腌20分钟成馅。","面团搓条下剂，擀成薄方片，中间放馅，四边折起捏成方包。","烤盘刷油摆上包子，表面再刷一层油，烤箱220度烤25分钟。","烤到表面金黄鼓起、底部焦脆即可出炉。"],"tip":"馅里别加水，靠洋葱汁和羊油出汤，包子才不破皮漏汁。"},{"name":"油茶麻花","cat":"汤羹","region":"陕西","time":50,"diff":"中等","main":[["面粉","300g"],["花生米","50g"],["白芝麻","30g"]],"sea":["盐","花椒粉","五香粉","食用油","猪油"],"steps":["取一半面粉放干锅里小火炒20分钟，不停翻动到颜色发黄、闻到麦香。","另一半面粉加水和成软面团，搓条拧成麻花，醒15分钟。","油烧到六成热下麻花，中小火炸3分钟到金黄酥脆，捞出沥油。","锅里放猪油和食用油，下炒好的面粉小火炒2分钟，加盐花椒粉五香粉炒匀。","分次倒入开水，边倒边搅，中火煮5分钟到浓稠能挂勺。","撒入炒香的花生米和白芝麻，盛碗后放上麻花。"],"tip":"炒面要用小火慢炒到发黄，急火会外糊里生，冲出来发苦。"},{"name":"灰豆子","cat":"甜点","region":"甘肃","time":120,"diff":"简单","main":[["豌豆","300g"],["红枣","100g"],["冰糖","80g"]],"sea":["白糖"],"steps":["豌豆洗净用清水泡8小时，泡到豆子鼓胀、用手能按出印。","砂锅加水放豌豆，大火烧开撇净浮沫，转小火煮40分钟。","用勺背把部分豌豆压碎，让汤变稠，加红枣继续煮30分钟。","放冰糖小火煮15分钟，煮到豆子起沙、汤汁发暗红变浓。","关火后晾到温热不烫嘴，盛碗时撒一层白糖。"],"tip":"豆子要泡足并煮到起沙，压碎一部分汤才浓稠不发清。"},{"name":"过桥米线","cat":"主食","region":"云南","time":120,"diff":"中等","main":[["米线","300g"],["猪大骨","500g"],["鸡胸肉","150g"],["猪里脊","150g"],["鹌鹑蛋","4个"]],"sea":["葱","姜","盐","白胡椒","香油"],"steps":["猪大骨冷水下锅焯去血沫，转入汤锅加足量清水和姜片，大火烧开转小火熬90分钟至汤色乳白。","鸡胸肉和猪里脊逆着纹路切薄片，越薄越好；鹌鹑蛋煮熟剥壳，韭菜切段，豆芽洗净备用。","米线放入沸水中烫2分钟至软透，捞出沥干水分，分装进大碗里备用。","大碗先用开水烫热，碗底铺平猪里脊片和鸡胸片，冲入滚沸的高汤，加盖焖2分钟至肉片变白。","下米线和鹌鹑蛋，放入豆芽、韭菜段烫30秒，加盐和白胡椒调味，淋几滴香油。"],"tip":"汤必须滚沸冲进烫热的碗，肉片切得越薄越容易被烫熟，厚了就发柴。"},{"name":"酸汤鱼","cat":"汤羹","region":"贵州","time":45,"diff":"中等","main":[["草鱼","1条"],["西红柿","3个"],["泡椒","50g"],["豆芽","150g"]],"sea":["姜","蒜","盐","白醋","料酒","白糖"],"steps":["草鱼去骨片成厚片，鱼头鱼骨剁成块，加料酒和盐抓匀腌10分钟去腥。","西红柿切小块，中火下锅放油炒5分钟，炒到软烂出红汁，再加泡椒碎和蒜末炒香。","倒入1500毫升清水大火烧开，放鱼头鱼骨煮10分钟，汤色转红变浓。","豆芽垫在盆底，鱼片逐片滑入锅中，中火煮2分钟至鱼片变白卷边。","加盐、白醋和少许白糖调出酸辣味，连汤带鱼盛入深盆，撒上姜丝和香菜段。"],"tip":"西红柿一定炒到出沙再加水，汤才红亮酸香，鱼片最后下锅才嫩。"},{"name":"螺蛳粉","cat":"主食","region":"广西","time":90,"diff":"较难","main":[["米粉","200g"],["田螺","500g"],["酸笋","100g"],["腐竹","50g"],["花生米","50g"]],"sea":["姜","蒜","干辣椒","八角","桂皮","盐","辣椒油","料酒"],"steps":["田螺提前养一天吐沙，用刷子刷净外壳，剪掉尾部，冷水下锅加料酒焯2分钟捞出。","锅中放油，中火炒香姜片、蒜、干辣椒、八角和桂皮，下田螺翻炒3分钟。","加2000毫升开水大火烧开，转小火熬60分钟，汤色转浓、螺味透出后加盐调味。","酸笋切丝放干锅中小火煸2分钟去涩，腐竹泡软切段，米粉煮3分钟至软透。","米粉装碗浇上滚烫螺汤，铺酸笋丝、腐竹段和炸花生米，淋一勺辣椒油。"],"tip":"酸笋先干锅煸过，臭味变成香气；螺汤要小火久熬，味才厚不腥。"},{"name":"老友粉","cat":"主食","region":"广西","time":25,"diff":"中等","main":[["河粉","250g"],["猪肉末","100g"],["酸笋","80g"],["尖椒","2个"]],"sea":["蒜","豆豉","生抽","盐","食用油","醋"],"steps":["酸笋切细丝，放干锅里中小火煸3分钟，煸到水汽干、酸味变柔和后盛出。","热锅下油，中火爆香蒜末、豆豉和尖椒圈，炒到豆豉散出浓郁酱香。","下猪肉末大火炒散至全部变白，加酸笋丝翻炒1分钟，沿锅边淋入生抽炒匀。","倒入600毫升开水大火烧开，下河粉煮1分钟至软，加盐和几滴醋调味，连汤盛出。"],"tip":"酸笋先干煸去涩，豆豉要炒出酱香，这两步决定老友粉的酸辣底味。"},{"name":"菠萝饭","cat":"主食","region":"云南","time":60,"diff":"中等","main":[["菠萝","1个"],["糯米","200g"],["白糖","30g"]],"sea":["白糖"],"steps":["糯米提前用清水泡4小时，捞出沥干，铺在垫了纱布的蒸屉上，中火蒸30分钟至米粒透明。","菠萝从三分之一处横切开，挖出果肉切成小丁，菠萝壳留着当容器，开口边缘修整齐。","蒸好的糯米趁热加白糖和菠萝丁拌匀，拌到每粒米都裹上果汁、甜度微甜。","把拌好的糯米装回菠萝壳，只装八分满，盖上菠萝盖，中火再蒸15分钟让果香渗进米里。"],"tip":"糯米要泡透再蒸，装壳只装八分满，蒸时米粒膨胀才不会顶开盖子。"},{"name":"香茅烤鱼","cat":"荤菜","region":"云南","time":50,"diff":"中等","main":[["草鱼","1条"],["香茅","4根"],["柠檬","1个"],["尖椒","3个"]],"sea":["蒜","鱼露","盐","食用油"],"steps":["草鱼从背部剖开成相连的两片，去内脏洗净，用盐和鱼露里外抹匀腌20分钟。","香茅拍扁切段，尖椒和蒜切碎，一半塞进鱼腹，一半铺在烤盘底部垫底。","烤箱200度预热，鱼皮朝上放在烤盘上，表面刷一层油，烤20分钟至表皮金黄起皱。","取出挤上柠檬汁，撒香菜碎，再回炉烤2分钟，让柠檬香和香茅味融进鱼肉。"],"tip":"香茅要拍扁再塞，香味才出得来；鱼背剖开受热均匀，肉不易烤老。"},{"name":"火腿炒豌豆","cat":"荤菜","region":"云南","time":20,"diff":"简单","main":[["火腿","100g"],["豌豆","300g"]],"sea":["蒜","盐","食用油","白糖"],"steps":["火腿切小丁，豌豆剥出豆粒洗净，蒜切成薄片备用。","锅中水烧开，下豌豆焯2分钟，捞出立刻过凉水，保持翠绿不发黄。","热锅放少许油，中小火煸火腿丁2分钟，煸到肥肉透明、咸香散出。","下蒜片和豌豆转大火炒1分钟，加少许白糖和盐炒匀，豌豆表面起皱即可出锅。"],"tip":"火腿本身很咸，盐要最后少放；豌豆焯水后大火快炒才嫩绿。"},{"name":"凉拌折耳根","cat":"凉菜","region":"贵州","time":15,"diff":"简单","main":[["折耳根","300g"],["花生米","50g"]],"sea":["蒜","干辣椒","辣椒面","香醋","生抽","盐","白糖","香油"],"steps":["折耳根掐去老根和须，只留嫩茎，洗净后掰成5厘米长的段，用凉开水冲一遍沥干。","花生米装袋用刀背压成粗碎，干辣椒剪成段，蒜剁成细末。","碗中放蒜末和辣椒面，浇一勺烧到冒烟的热油激香，加香醋、生抽、盐和白糖调匀。","折耳根加料汁抓拌，撒上花生碎，淋香油，腌5分钟入味后装盘。"],"tip":"折耳根千万别焯水，一焯就软塌失脆；热油激辣椒面是香味关键。"},{"name":"丝娃娃","cat":"素菜","region":"贵州","time":40,"diff":"中等","main":[["春卷皮","10张"],["豆芽","100g"],["黄瓜","1根"],["胡萝卜","1根"],["海带","100g"]],"sea":["蒜","香醋","生抽","辣椒油","白糖","盐"],"steps":["豆芽焯水1分钟捞出过凉，黄瓜和胡萝卜切细丝，海带切丝后焯2分钟捞出沥干。","粉丝用温水泡软再焯1分钟，剪成短段；折耳根切碎，和粉丝一起备用。","蒜末加香醋、生抽、辣椒油、白糖和盐，兑两勺凉开水调成蘸水。","春卷皮上锅蒸3分钟回软，取一张摊平，放上各色丝料，从一侧卷成小卷。","卷好的丝娃娃在蘸水里滚一圈再吃，一次别放太多料，免得皮撑破。"],"tip":"春卷皮蒸软才好卷，丝料一定沥干水，皮一湿就破，蘸水要调得偏酸。"},{"name":"桂林米粉","cat":"主食","region":"广西","time":120,"diff":"较难","main":[["米粉","300g"],["牛肉","300g"],["酸菜","80g"],["花生米","50g"]],"sea":["八角","桂皮","香叶","姜","蒜","生抽","老抽","盐"],"steps":["牛肉整块冷水下锅焯5分钟去血水，撇净浮沫后捞出用温水冲净表面。","锅中放油，中火炒香姜蒜、八角、桂皮和香叶，加生抽、老抽和清水烧开成卤水。","放入牛肉转小火卤60分钟，卤到筷子能轻松插入，捞出放凉后切薄片。","米粉在沸水中烫1分钟至软，捞出装碗，浇上两勺滚热的卤水。","铺牛肉片、酸菜末和炸花生米，淋一勺辣椒油，吃前从碗底拌开。"],"tip":"卤过牛肉的汤留着当卤水是灵魂，米粉只烫不煮才弹牙不糊。"},{"name":"香辣烤鱼","cat":"荤菜","region":"贵州","time":70,"diff":"中等","main":[["草鱼","1条"],["土豆","2个"],["莲藕","1节"],["豆芽","150g"]],"sea":["干辣椒","花椒","豆瓣酱","姜","蒜","料酒","盐","食用油"],"steps":["草鱼从背部剖开摊平，用料酒和盐抹匀腌20分钟，再用厨房纸把表面水分彻底擦干。","烤箱220度预热，鱼身刷一层油放烤盘，烤25分钟至表皮焦脆、边缘微卷。","土豆和莲藕切薄片，沸水中焯3分钟捞出，焯到七成熟备用。","锅中放油，中火爆香姜蒜、干辣椒段和花椒，下豆瓣酱小火炒出红油。","下土豆片、藕片和豆芽翻炒2分钟，加一碗水烧开，浇在烤鱼上，回炉再烤8分钟。"],"tip":"鱼身擦干再烤才起脆皮，浇汁后回炉让配菜吸足辣汤，别省这一步。"},{"name":"贵州辣子鸡","cat":"荤菜","region":"贵州","time":50,"diff":"中等","main":[["鸡腿","4个"],["泡椒","100g"],["干辣椒","30g"]],"sea":["姜","蒜","花椒","豆瓣酱","料酒","生抽","盐","食用油"],"steps":["鸡腿剁成3厘米见方的块，加料酒、盐和姜片抓匀腌15分钟入味。","干辣椒剪段，泡椒剁碎，两样混在一起加一勺油拌成湿润的糍粑辣椒。","锅中多放油烧至六成热，下鸡块中火炸5分钟，炸到表皮金黄收紧后捞出。","锅留底油，中小火炒糍粑辣椒3分钟至出红油，加姜蒜末和花椒炒香。","倒回鸡块大火翻炒2分钟，淋生抽，加半碗水转小火焖10分钟收浓汤汁。"],"tip":"泡椒和干辣椒剁茸炒出红油，是贵州辣子鸡区别于川版辣子鸡的关键。"},{"name":"腊排骨火锅","cat":"汤羹","region":"云南","time":100,"diff":"中等","main":[["腊排骨","600g"],["白萝卜","1根"],["土豆","2个"],["蒜苗","2根"]],"sea":["姜","干辣椒","花椒","盐","料酒"],"steps":["腊排骨剁成段，冷水浸泡2小时泡出部分咸味，中途换两次水。","排骨冷水下锅加料酒焯5分钟，撇去浮沫后捞出，用温水冲净表面。","砂锅加足量开水，放排骨、姜片、干辣椒和花椒，大火烧开转小火炖60分钟。","白萝卜和土豆切滚刀块下锅，中火再煮20分钟，煮到萝卜透明、一戳就烂。","尝味后少量加盐，撒蒜苗段，边煮边吃，汤少了续开水再涮蔬菜。"],"tip":"腊排骨先泡再焯，咸味才不压汤；炖时只添开水，汤才清亮不浑。"},{"name":"鬼鸡","cat":"荤菜","region":"云南","time":60,"diff":"中等","main":[["整鸡","半只"],["柠檬","2个"],["尖椒","5个"],["香菜","1把"]],"sea":["蒜","姜","鱼露","盐","白糖"],"steps":["整鸡冷水下锅加姜片，大火烧开转中小火煮25分钟，筷子插腿根无血水即熟。","捞出自然放凉，晾到不烫手后把鸡肉连皮撕成细条，鸡骨不用。","尖椒切圈，蒜切末，香菜切段，柠檬挤汁并刮少许黄色皮屑。","柠檬汁、鱼露、盐和白糖调成料汁，尝起来酸咸带一点回甜。","鸡丝加尖椒、蒜末和香菜，倒入料汁抓拌2分钟，腌10分钟入味。"],"tip":"鸡煮熟自然放凉再撕肉才不散，柠檬皮只刮黄色部分，白瓤发苦。"},{"name":"老奶洋芋","cat":"素菜","region":"云南","time":25,"diff":"简单","main":[["土豆","4个"],["葱","2根"]],"sea":["干辣椒","花椒粉","蒜","盐","食用油"],"steps":["土豆去皮切大块，上锅大火蒸20分钟，蒸到筷子一戳就透。","趁热用勺子把土豆压成粗泥，故意留一些小块，口感更有层次。","锅中放油，中小火爆香干辣椒段和蒜末，炒到辣椒颜色变深。","下土豆泥翻炒3分钟，边炒边用铲子压，加盐和花椒粉炒匀，撒葱花出锅。"],"tip":"土豆蒸透趁热压泥，炒时火别大，勤翻动才不会糊底发苦。"},{"name":"阳朔啤酒鱼","cat":"荤菜","region":"广西","time":40,"diff":"中等","main":[["鲤鱼","1条"],["啤酒","1罐"],["西红柿","2个"],["尖椒","3个"]],"sea":["姜","蒜","生抽","盐","食用油"],"steps":["鲤鱼去鳞去内脏，两面各划三刀，用盐抹匀腌15分钟，再用厨房纸擦干水分。","平底锅放油烧热，中火把鱼两面各煎3分钟，煎到金黄定型后盛出。","锅留底油，爆香姜蒜和尖椒段，下西红柿块炒3分钟至软烂出汁。","鱼回锅，倒入整罐啤酒没过鱼身一半，加生抽，大火烧开转中火炖15分钟。","汤汁收到浓稠能挂住勺背，加盐调味，连汁一起浇在鱼身上。"],"tip":"全程用啤酒代水，鱼先煎定型再炖，肉才紧实不散、汤才带麦香。"},{"name":"柠檬鸭","cat":"荤菜","region":"广西","time":50,"diff":"中等","main":[["鸭肉","800g"],["柠檬","2个"],["泡椒","50g"],["酸笋","80g"]],"sea":["蒜","姜","白糖","生抽","料酒","盐"],"steps":["鸭肉剁成块，冷水下锅加料酒焯5分钟，撇净浮沫后捞出沥干。","炒锅不放油，中火干煸鸭块5分钟，煸出鸭油至表皮微黄收紧。","下蒜、姜片和泡椒炒香，加酸笋丝翻炒2分钟，炒到酸香散出。","加生抽、白糖和一碗开水，大火烧开后转小火焖25分钟至鸭肉软烂。","柠檬挤汁入锅，再放两片带皮柠檬，大火收汁2分钟，加盐调味。"],"tip":"鸭肉先干煸出油才不腥，柠檬最后放，久煮皮会发苦。"},{"name":"荔浦芋头扣肉","cat":"荤菜","region":"广西","time":120,"diff":"较难","main":[["五花肉","500g"],["芋头","500g"]],"sea":["豆腐乳","生抽","老抽","白糖","八角","蒜","盐"],"steps":["五花肉整块冷水下锅煮20分钟至七成熟，捞出趁热在肉皮上抹一层老抽。","锅中放油烧至六成热，肉皮朝下炸2分钟至起泡呈虎皮色，捞出立刻泡进凉水。","芋头去皮切厚片，用锅中余油中火炸2分钟，炸到表面结壳不易烂。","豆腐乳、生抽、白糖、蒜末和少许盐调成酱汁，肉切厚片与芋头片交替码进碗里。","淋上酱汁放一颗八角，上锅大火蒸60分钟至肉酥，倒扣盘中，原汁勾薄芡浇上。"],"tip":"肉皮炸后立刻泡凉水才起虎皮皱，蒸足一小时肉才能入口即化。"},{"name":"凉米线","cat":"凉菜","region":"云南","time":25,"diff":"简单","main":[["米线","300g"],["黄瓜","1根"],["胡萝卜","半根"],["花生米","50g"]],"sea":["蒜","香醋","生抽","辣椒油","芝麻酱","白糖","盐","香油"],"steps":["米线在沸水中烫1分钟，捞出立刻过凉水，沥干后拌少许香油防止粘连。","黄瓜和胡萝卜切细丝，花生米冷油小火炸3分钟，捞出压成粗碎。","芝麻酱先用温水慢慢调开至能流动，加蒜末、香醋、生抽、白糖和盐拌匀。","米线铺在盘底，码上黄瓜丝和胡萝卜丝，淋芝麻酱汁和一勺辣椒油。","撒上花生碎和香菜段，吃前从盘底拌开，让每根米线都裹上酱汁。"],"tip":"米线烫后必须过凉水才爽滑，芝麻酱先用温水澥开，否则结块拌不开。"},{"name":"肠旺面","cat":"主食","region":"贵州","time":60,"diff":"较难","main":[["面条","300g"],["猪大肠","300g"],["猪血","200g"],["五花肉","100g"],["豆芽","100g"]],"sea":["豆瓣酱","辣椒油","姜","蒜","料酒","盐","生抽"],"steps":["猪大肠用盐和面粉反复搓洗，冷水下锅加料酒和姜片煮40分钟至软，捞出切段。","五花肉切小丁，冷锅小火慢炸8分钟，炸到丁状酥脆成脆哨后盛出。","猪血切块，在沸水中焯1分钟去腥，捞出泡在凉水里备用。","锅中放油，中火炒香姜蒜末和豆瓣酱，加高汤烧开，下大肠段和猪血煮5分钟。","面条煮2分钟捞入碗中，浇上红汤，放烫熟的豆芽，撒脆哨，淋一勺辣椒油。"],"tip":"大肠要煮到筷子能穿透，脆哨必须小火慢炸才酥，红汤撇净浮沫才亮。"},{"name":"恋爱豆腐果","cat":"素菜","region":"贵州","time":35,"diff":"中等","main":[["豆腐","400g"],["折耳根","50g"]],"sea":["辣椒面","花椒粉","蒜","生抽","香醋","盐","食用油"],"steps":["老豆腐切成3厘米见方的块，用厨房纸把表面水分彻底吸干。","平底锅放油，中小火煎8分钟，六个面都翻到，煎至外壳金黄鼓胀。","折耳根切碎，蒜切末，加辣椒面、花椒粉、生抽、香醋和盐调成蘸水。","煎好的豆腐用刀从侧面划开一道口，把折耳根蘸水料塞进去。","趁热吃，外脆内嫩，蘸水放得多的可以再蘸一遍更够味。"],"tip":"豆腐必须吸干水再煎，小火慢煎到鼓泡，里面才嫩得像豆花。"},{"name":"酸笋炒肉","cat":"荤菜","region":"广西","time":20,"diff":"简单","main":[["猪里脊","250g"],["酸笋","150g"],["尖椒","2个"]],"sea":["蒜","生抽","料酒","盐","食用油","淀粉"],"steps":["猪里脊逆纹切薄片，加料酒、生抽和淀粉抓匀腌10分钟上浆。","酸笋切细丝，放干锅中中小火煸3分钟，煸到水汽收干、酸味变柔和。","热锅放油烧至五成热，大火下肉片滑炒1分钟至变白，立刻盛出。","锅留底油，爆香蒜末和尖椒丝，下酸笋大火炒2分钟出香。","倒回肉片炒匀，加盐和少许生抽，炒到汁水收干即可出锅。"],"tip":"酸笋先干煸去涩，肉片上浆滑炒断生就盛出，回锅才不会老。"},{"name":"田螺酿","cat":"荤菜","region":"广西","time":60,"diff":"较难","main":[["田螺","500g"],["猪肉末","200g"]],"sea":["蒜","姜","豆豉","料酒","生抽","盐","食用油"],"steps":["田螺养一天吐净泥沙，刷净外壳剪去尾部，用牙签挑出螺肉，螺壳洗净留用。","螺肉剁碎，与猪肉末混合，加姜末、料酒、生抽和盐顺一个方向搅打上劲。","把肉馅塞回螺壳，只塞八分满，塞口朝上整齐码在深盘里。","锅中放油爆香蒜末和豆豉，加一碗水烧开，连汁浇在田螺上。","上锅大火蒸15分钟，蒸到肉馅鼓起、螺香透出即可端出。"],"tip":"螺肉剁碎和肉末一起搅上劲，塞八分满，蒸时馅才不缩不散。"},{"name":"糟辣脆皮鱼","cat":"荤菜","region":"贵州","time":45,"diff":"中等","main":[["草鱼","1条"],["泡椒","80g"],["西红柿","1个"]],"sea":["姜","蒜","辣椒面","白糖","醋","淀粉","盐","食用油"],"steps":["草鱼去鳞去内脏，两面打十字花刀，用盐抹匀腌15分钟去腥入味。","鱼身拍一层干淀粉，抖掉多余的粉，保证每条刀口里都拍到粉。","锅中油烧至七成热，中火下鱼炸6分钟，两面翻动至外壳金黄酥脆，捞出装盘。","锅留底油，小火炒泡椒碎、姜蒜末和辣椒面2分钟出红油，下西红柿丁炒软。","加白糖、醋和小半碗水烧开，勾薄芡至能挂勺，趁热浇在鱼身上。"],"tip":"淀粉要拍匀抖干，七成热油下锅才起脆壳，浇汁要快否则回软。"},{"name":"豆腐圆子","cat":"素菜","region":"贵州","time":40,"diff":"中等","main":[["豆腐","500g"],["淀粉","50g"],["折耳根","30g"]],"sea":["辣椒面","花椒粉","蒜","生抽","香醋","盐","食用油"],"steps":["老豆腐用纱布包住挤干水分，越干越好，掰碎后加淀粉和盐反复揉成团。","揉到豆腐泥能捏成球不散，分成乒乓球大小的剂子，搓圆后中间按一个小窝。","锅中油烧至六成热，中小火下圆子炸5分钟，炸到外壳金黄鼓起、浮起油面。","折耳根切碎，加蒜末、辣椒面、花椒粉、生抽和香醋调成蘸水。","圆子捞出沥油，趁热掰开舀入蘸水，或整个蘸着吃。"],"tip":"豆腐一定要挤干水，加淀粉才抱团；六成热油下锅才外脆内空。"},{"name":"佛跳墙","cat":"汤羹","region":"闽","time":180,"diff":"较难","main":[["排骨","500g"],["猪蹄","1只"],["海参","2条"],["鹌鹑蛋","10个"],["干香菇","8朵"]],"sea":["姜","葱","料酒","盐","冰糖","生抽"],"steps":["干香菇提前用温水泡发两小时，泡菇水静置沉淀后留上层清液，鹌鹑蛋煮熟剥壳备用。","排骨和猪蹄斩成块，冷水下锅加姜片料酒焯五分钟，撇净浮沫后捞出用温水冲洗干净。","砂锅底部垫姜片葱段，码入排骨和猪蹄，倒入泡菇水和清水到八分满，大火烧开。","转小火炖一小时后放海参、香菇、鹌鹑蛋，加冰糖生抽盐，继续小火煨四十分钟。","汤汁收到略稠、能挂住勺背时关火，挑出葱段姜片，原锅直接上桌。"],"tip":"泡菇水是鲜味来源，务必沉淀去渣再用；海参最后放，久煮会缩水发硬。"},{"name":"荔枝肉","cat":"荤菜","region":"闽","time":40,"diff":"中等","main":[["猪里脊","400g"],["荸荠","8个"]],"sea":["盐","白糖","醋","番茄酱","生抽","淀粉","蒜","食用油"],"steps":["猪里脊片成三厘米厚的大片，两面剞十字花刀再切成长条，加盐抓匀腌十分钟。","荸荠削皮切滚刀块；肉条拍匀干淀粉，抖掉多余粉，静置五分钟让粉回潮。","油烧到六成热下肉条，中火炸两分钟定型捞出，升温复炸三十秒至外壳金黄酥硬。","锅留底油小火炒香蒜末，下番茄酱白糖醋生抽和半碗水，熬到起泡能拉丝。","倒入肉条和荸荠，大火颠锅十秒裹匀酱汁，汁浓挂勺立即出锅。"],"tip":"花刀要切到肉的三分之二深，炸后才卷成荔枝状；复炸一遍是酥脆的关键。"},{"name":"海蛎煎","cat":"荤菜","region":"闽","time":25,"diff":"中等","main":[["生蚝","300g"],["鸡蛋","3个"],["蒜苗","2根"]],"sea":["淀粉","盐","白胡椒","鱼露","食用油"],"steps":["生蚝用淡盐水轻轻淘洗两遍，挑净碎壳，沥干水分，动作要轻以免弄破蚝肚。","蒜苗切碎，加淀粉、盐、白胡椒和半碗水调成稀糊，静置五分钟。","平底锅烧热放油，倒入粉糊转锅摊成薄饼，中火煎到边缘透明定型。","把生蚝均匀铺在饼上，淋鱼露，浇上打散的蛋液，中小火煎三分钟。","底面金黄时整张翻面再煎两分钟，蛋液凝固、边缘微焦即可盛出。"],"tip":"粉糊要稀、摊得薄，才外脆内嫩；生蚝最后铺，煎久了会缩水出汤。"},{"name":"沙茶面","cat":"主食","region":"闽","time":35,"diff":"中等","main":[["面条","300g"],["虾","200g"],["鱿鱼","1条"],["豆芽","150g"],["猪里脊","150g"]],"sea":["沙茶酱","芝麻酱","生抽","盐","蒜","食用油"],"steps":["猪里脊逆纹切薄片用生抽抓匀；虾剪须开背，鱿鱼切圈，豆芽洗净沥干。","锅下油小火炒香蒜末，加三勺沙茶酱和一勺芝麻酱，慢炒到出红油、香味浓。","倒入清水烧开，加生抽盐调味，转中小火熬十分钟成沙茶汤底。","另起锅水开下面条煮到八分熟捞入碗中，豆芽在面汤里烫二十秒垫底。","沙茶汤大火烧滚，下肉片虾鱿鱼烫到变色卷曲，连汤浇在面上即可。"],"tip":"沙茶酱要用小火炒透去生味，汤才香；海鲜最后烫，久煮发老。"},{"name":"三杯鸡","cat":"荤菜","region":"台","time":40,"diff":"中等","main":[["鸡腿","4只"],["九层塔","1把"]],"sea":["香油","生抽","老抽","料酒","冰糖","蒜","姜","干辣椒"],"steps":["鸡腿剁成四厘米见方的块，冷水下锅焯两分钟去血水，捞出沥干。","砂锅放半碗香油，小火下整粒蒜和厚姜片，煸到姜片卷边、蒜粒微黄。","转大火下鸡块，煎到表面金黄出油，淋三勺料酒、两勺生抽、半勺老抽。","加六粒冰糖和干辣椒，翻匀后加盖中小火焖十五分钟，中途翻动两次。","开盖大火收汁，汁浓裹住鸡块时关火，撒一大把九层塔焖一分钟出锅。"],"tip":"全程不加水，靠料酒和鸡自身水汽焖熟；九层塔关火后放才保香。"},{"name":"卤肉饭","cat":"主食","region":"台","time":100,"diff":"中等","main":[["五花肉","500g"],["米饭","4碗"],["鸡蛋","3个"],["干香菇","4朵"]],"sea":["生抽","老抽","冰糖","五香粉","料酒","蒜","食用油","盐"],"steps":["五花肉连皮切成小拇指粗的条，干香菇泡软切丁，鸡蛋煮熟剥壳。","锅不放油下肉条，中小火煸八分钟，煸到肥肉透明、锅底积出猪油。","下蒜末和香菇丁炒香，加冰糖炒到化开，淋料酒生抽老抽和五香粉。","倒入泡菇水和热水没过肉，放入鸡蛋，大火烧开转小火卤一小时。","肉皮软糯、汤汁浓稠挂勺时加盐调味，连汁浇在热米饭上。"],"tip":"肉要切小条不能剁碎，卤时只冒小泡，火大汤汁会浑。"},{"name":"客家酿豆腐","cat":"荤菜","region":"客家","time":45,"diff":"中等","main":[["豆腐","4块"],["猪肉末","250g"],["香菇","3朵"]],"sea":["生抽","盐","淀粉","白胡椒","香油","葱","食用油","蚝油"],"steps":["老豆腐切五厘米见方的块，用勺子在中间挖出小洞，挖出的碎豆腐留用。","肉末加香菇末、碎豆腐、盐生抽白胡椒淀粉，顺一个方向搅到起胶发黏。","洞里撒一层薄淀粉，把肉馅塞满抹平，表面再拍点淀粉封口。","平底锅热油，肉面朝下中小火煎三分钟，煎到金黄定型再翻面煎豆腐。","加生抽蚝油和半碗热水，加盖小火焖八分钟，淋淀粉水收汁撒葱花。"],"tip":"洞里拍淀粉能让肉馅粘牢；先煎肉面定型，别急着翻动。"},{"name":"咸水鸭","cat":"凉菜","region":"闽","time":120,"diff":"中等","main":[["鸭肉","1只"]],"sea":["盐","花椒","八角","姜","葱","料酒"],"steps":["花椒和盐下干锅小火炒到盐微黄、花椒出香，趁热抹遍鸭身内外。","鸭子放冰箱冷藏腌四小时，中途翻一次面，让盐分均匀渗入。","锅中放冷水没过鸭身，加姜片葱段八角料酒，大火烧到水面冒小泡。","转最小火保持水面不滚，浸煮四十分钟，关火再焖二十分钟。","捞出晾到完全凉透，斩件装盘，淋少许煮鸭原汤。"],"tip":"水面只冒虾眼泡不能大滚，鸭肉才嫩；凉透再斩才不散。"},{"name":"肉燕","cat":"主食","region":"闽","time":90,"diff":"较难","main":[["猪里脊","500g"],["猪肉末","250g"],["淀粉","100g"]],"sea":["盐","生抽","料酒","白胡椒","葱","姜","香油"],"steps":["猪里脊剔净筋膜切小块，用木槌反复捶四十分钟，捶成细腻无颗粒的肉泥。","肉泥加盐和一半淀粉揉匀，边揉边撒剩余淀粉，揉到面团光滑不粘手。","面团擀成薄如纸的大片，切成八厘米方块，盖湿布防止风干。","肉末加生抽料酒白胡椒葱花姜末香油搅上劲，取少许包入燕皮捏成小圆球。","水烧到微沸下肉燕，煮到浮起后再煮两分钟，连汤舀入碗中撒葱花。"],"tip":"肉要趁冷捶，中途刮下粘槌的肉；燕皮薄透，馅别放多。"},{"name":"锅边糊","cat":"主食","region":"闽","time":60,"diff":"较难","main":[["大米","200g"],["蛤蜊","300g"],["虾","150g"],["香菇","4朵"]],"sea":["盐","生抽","白胡椒","葱","食用油","姜"],"steps":["大米淘净泡三小时，加清水磨成能挂住勺的稀米浆，加少许盐搅匀。","蛤蜊吐净沙后冷水下锅，加姜片煮到开口，取汤滤净，蛤蜊肉留用。","蛤蜊汤烧滚，下香菇丝和虾煮三分钟，加生抽白胡椒调底味。","锅边烧热抹油，舀一勺米浆沿锅边淋一圈，盖盖焖三十秒至米浆凝固卷边。","用铲子把米皮铲进汤里，重复淋浆三到四次，煮两分钟后撒葱花出锅。"],"tip":"米浆要稀，锅要够热才挂得住；每张皮只焖半分钟，久了发硬。"},{"name":"客家小炒","cat":"荤菜","region":"客家","time":30,"diff":"中等","main":[["五花肉","250g"],["豆干","4块"],["鱿鱼","1条"],["芹菜","2根"],["蒜苗","2根"]],"sea":["生抽","料酒","盐","食用油","蒜","干辣椒"],"steps":["干鱿鱼提前泡软切条；五花肉切薄片，豆干切条，芹菜和蒜苗切段。","锅烧热不放油，下五花肉中火煸五分钟，煸到出油卷边后盛出。","用煸出的猪油下豆干条，中火煎到两面金黄起小泡，盛出备用。","下蒜末干辣椒爆香，倒鱿鱼条大火炒一分钟，淋料酒去腥。","倒回五花肉和豆干，加生抽盐，下芹菜蒜苗大火翻炒四十秒断生即可。"],"tip":"豆干要煎到起泡才吸味；芹菜蒜苗最后下，保持脆口不塌。"},{"name":"封肉","cat":"荤菜","region":"闽","time":180,"diff":"较难","main":[["五花肉","1000g"],["香菇","6朵"],["虾皮","20g"]],"sea":["生抽","老抽","冰糖","八角","桂皮","料酒","盐","食用油"],"steps":["整块带皮五花肉修成方形，冷水下锅煮十五分钟，捞出擦干，皮上抹老抽。","锅中放油烧到六成热，肉皮朝下炸三分钟，炸到表皮起虎皮色捞出。","香菇泡软后与虾皮一起下锅炒香，加生抽冰糖料酒和泡菇水煮开。","肉块放在纱布上，香菇虾皮铺在肉面，包紧扎口成方包。","砂锅垫葱姜放肉包，倒入料汁和热水没过，小火炖两小时至筷子一插即透。","拆包切厚片装盘，原汁过滤后大火收浓浇在肉上。"],"tip":"肉要炸出虎皮再炖才不腻；纱布包紧能定型，切时不易散。"},{"name":"醉排骨","cat":"荤菜","region":"闽","time":45,"diff":"中等","main":[["排骨","500g"],["荸荠","8个"]],"sea":["番茄酱","白糖","醋","生抽","淀粉","蒜","料酒","食用油"],"steps":["排骨斩成四厘米段，加生抽料酒抓匀腌二十分钟，再拍匀干淀粉。","荸荠削皮切块；油烧到六成热下排骨，中火炸四分钟捞出。","升高油温复炸三十秒，炸到排骨外壳硬脆、筷子敲之有响声。","锅留底油小火炒蒜末，下番茄酱白糖醋生抽和半碗水，熬到汁稠冒大泡。","倒入排骨和荸荠，大火翻炒十秒裹匀酱汁，汁浓即出锅。"],"tip":"排骨炸两遍才酥；糖醋汁熬到起大泡再下排骨，挂汁才亮。"},{"name":"南煎肝","cat":"荤菜","region":"闽","time":25,"diff":"中等","main":[["猪肝","400g"],["荸荠","6个"]],"sea":["生抽","料酒","白糖","醋","淀粉","蒜","葱","食用油"],"steps":["猪肝切半厘米厚片，清水泡二十分钟去血水，中途换两次水，捞出沥干。","肝片加料酒生抽淀粉抓匀上浆，静置十分钟；荸荠切片，葱切段。","锅烧到冒烟倒油，下肝片摊平，大火煎四十秒至边缘微焦再翻面。","下蒜末和荸荠片同炒，沿锅边淋料酒，加白糖醋生抽和两勺水。","大火快炒二十秒，汁刚裹住肝片时下葱段，立刻出锅。"],"tip":"猪肝泡去血水才不腥，全程大火快煎，炒久了发硬发粉。"},{"name":"白斩河田鸡","cat":"凉菜","region":"客家","time":45,"diff":"中等","main":[["整鸡","1只"]],"sea":["盐","姜","葱","料酒","香油","生抽"],"steps":["整鸡洗净，鸡腹塞姜片葱段，冷水下锅加料酒，水量要没过鸡身。","大火烧到水刚沸就转最小火，保持水面微颤浸十八分钟。","关火再焖十分钟，用筷子扎鸡腿最厚处，无血水冒出即熟。","捞出立刻投入冰水浸十分钟，鸡皮收紧发亮后捞出沥干。","斩件摆盘，姜末葱花加盐和烧热的油调成姜葱汁，淋香油生抽蘸食。"],"tip":"水只冒小泡浸熟，肉才嫩滑；冰水一激鸡皮脆爽不腻。"},{"name":"客家黄酒鸡","cat":"汤羹","region":"客家","time":40,"diff":"中等","main":[["鸡腿","4只"]],"sea":["黄酒","姜","香油","盐","冰糖"],"steps":["鸡腿剁成块，冷水下锅焯两分钟去血沫，捞出用温水冲净沥干。","砂锅放香油小火烧热，下大量姜片煸到卷边出香，倒入鸡块中火翻炒。","炒到鸡皮微黄收紧，倒入黄酒五百毫升，加冰糖，全程不再加水。","大火烧开转小火加盖焖二十五分钟，焖到鸡肉能用筷子扎透。","开盖加盐调味，中火再煮三分钟散掉酒气，汤汁微甜带酒香即可。"],"tip":"全程用黄酒代水，一滴水不加；小火慢焖酒香才不冲鼻。"},{"name":"三及第汤","cat":"汤羹","region":"客家","time":45,"diff":"中等","main":[["猪肝","150g"],["猪里脊","150g"],["猪大肠","200g"]],"sea":["盐","白胡椒","料酒","淀粉","姜","葱","香油","枸杞"],"steps":["猪大肠用盐和淀粉反复揉搓三遍，冲净后冷水下锅煮二十分钟切段。","猪肝切薄片泡水十分钟，猪里脊切薄片，分别加料酒淀粉抓匀。","锅中水烧开加姜丝，先下大肠段煮五分钟，撇去浮沫。","转中火下肉片和肝片，用筷子拨散，煮到肝片变色卷起约一分钟。","加盐白胡椒调味，撒枸杞葱花，淋香油后关火。"],"tip":"肝片最后下锅，一变色立刻关火，久煮会老硬发苦，汤也会发浑。"},{"name":"福州鱼丸","cat":"汤羹","region":"闽","time":60,"diff":"较难","main":[["草鱼","1条"],["猪肉末","150g"],["淀粉","50g"]],"sea":["盐","白胡椒","葱","姜","香油","料酒","生抽"],"steps":["草鱼去骨取净肉，用勺子刮成鱼蓉，挑净细刺，加姜汁和盐。","鱼蓉顺一个方向搅打十五分钟，打到发白起胶、能整团离手。","分次加淀粉和少量冰水继续搅，搅到鱼浆稠厚有弹性。","肉末加葱花生抽香油拌成馅，虎口挤鱼浆包入馅心，用勺舀入冷水盆。","鱼丸冷水下锅，小火加热到微沸，浮起后再煮三分钟，加盐白胡椒葱花。"],"tip":"鱼浆打到起胶才弹牙；水温不能滚，一滚鱼丸就裂口。"},{"name":"客家腌面","cat":"主食","region":"客家","time":20,"diff":"简单","main":[["面条","300g"],["蒜","5瓣"],["葱","3根"]],"sea":["猪油","生抽","盐","食用油","白胡椒"],"steps":["蒜切末，葱切葱花；小碗里放生抽、盐和少许白胡椒调成味汁。","锅烧热放两大勺猪油化开，下蒜末小火炸到金黄，连油一起倒入味汁。","水开下面条，煮到八分熟、中间还留一点白芯时捞出。","面条抖散摊开晾三十秒散去水汽，再拨入碗中。","浇上蒜油味汁，撒葱花，用筷子从下往上挑拌到每根面油亮。"],"tip":"面煮八分熟就捞，靠余温焖熟；猪油是腌面的魂，别换植物油。"},{"name":"白菜卤","cat":"素菜","region":"台","time":35,"diff":"简单","main":[["大白菜","半颗"],["干香菇","4朵"],["胡萝卜","半根"],["虾皮","20g"]],"sea":["生抽","盐","白胡椒","蒜","食用油","淀粉","白糖"],"steps":["干香菇温水泡软切丝，泡菇水留用；胡萝卜切薄片，大白菜帮叶分开切块。","锅中放油下蒜末、香菇丝和虾皮，小火炒到香味出来、虾皮微黄。","下白菜帮和胡萝卜，中火炒两分钟到帮子变半透明。","倒入泡菇水和一碗热水，加生抽白糖，加盖中小火焖十五分钟。","下白菜叶再焖五分钟，加盐白胡椒，淋淀粉水勾薄芡，汤汁能挂勺即可。"],"tip":"帮先下叶后下，久焖不烂；泡菇水沉淀后倒回锅里增鲜。"},{"name":"蒜蓉丝瓜","cat":"素菜","region":"闽","time":12,"diff":"简单","main":[["丝瓜","2根"],["蒜","5瓣"]],"sea":["盐","食用油","淀粉","白胡椒"],"steps":["丝瓜刮去外皮切滚刀块，泡在淡盐水里防氧化，下锅前捞出沥干。","蒜切末分成两份，锅放油小火烧热，下一半蒜末炸到微黄。","转中火下丝瓜翻炒，炒到出水变软约两分钟。","加盐白胡椒和两勺水，加盖焖一分钟至丝瓜变透明。","淋淀粉水收薄芡，关火撒剩下的生蒜末拌匀。"],"tip":"蒜末分两次放，一半炸香一半生香；丝瓜别炒过头，透明就起锅。"},{"name":"福州芋泥","cat":"甜点","region":"闽","time":70,"diff":"中等","main":[["芋头","600g"]],"sea":["白糖","猪油","白芝麻","红枣"],"steps":["芋头去皮切厚片，上锅大火蒸四十分钟，蒸到筷子一插就散。","趁热用刀面把芋头压成泥，再过一遍筛网，去掉粗粒。","锅小火化开猪油，倒入芋泥不停翻炒十分钟，炒到芋泥发亮不粘锅。","分三次加白糖继续炒五分钟，糖化开后芋泥变得更稠更滑。","装碗压平，撒白芝麻和红枣碎，上锅再蒸十分钟即可。"],"tip":"芋泥要趁热压筛才细；炒时全程小火，火大容易糊底发苦。"},{"name":"花生汤","cat":"甜点","region":"闽","time":100,"diff":"简单","main":[["花生米","300g"]],"sea":["白糖","红枣"],"steps":["花生米用开水泡十分钟，搓去红衣，挑出瘪粒和坏粒。","花生加五倍清水，大火烧开后转小火煮一小时。","煮到花生一捏就烂、汤色乳白时，加白糖搅到完全化开。","放红枣再煮十分钟，汤汁略稠、花生浮起即可。"],"tip":"去皮花生汤才白；小火慢煮，中途别加冷水，否则花生发硬。"},{"name":"芋圆","cat":"甜点","region":"台","time":60,"diff":"中等","main":[["芋头","300g"],["淀粉","150g"],["红豆","100g"]],"sea":["白糖","椰浆"],"steps":["芋头去皮切块，大火蒸二十五分钟，趁热压成细泥。","芋泥趁热加白糖和一半淀粉揉成团，余下淀粉分次加入防粘。","揉到面团不粘手、能搓成条不断裂，再分成小剂子。","搓成长条切小丁，撒干淀粉滚匀，防止互相粘连。","水开下芋圆，中火煮到全部浮起后再煮两分钟，捞出过冰水。","红豆煮烂加糖成汤，放入芋圆，淋少许椰浆。"],"tip":"芋泥要趁热揉粉，凉了就揉不光滑；煮好过冰水才弹牙。"},{"name":"双皮奶","cat":"甜点","region":"粤","time":40,"diff":"中等","main":[["牛奶","500ml"],["鸡蛋","2个"]],"sea":["白糖"],"steps":["牛奶倒进小锅，中小火加热到锅边起小泡就关火，分装两碗静置结出第一层奶皮。","鸡蛋只取蛋白，加白糖搅到糖完全化开，动作要轻别打出泡沫。","用筷子在奶皮边缘划开小口，把碗里的牛奶慢慢倒出，奶皮留在碗底。","牛奶和蛋白液拌匀过筛，沿碗边缓缓倒回，让奶皮自己浮起来。","碗口盖保鲜膜扎几个小孔，水开后中小火蒸12分钟，关火焖3分钟取出。"],"tip":"蛋奶液一定要过筛去泡沫，蒸时盖膜扎孔，表面才平整如镜。"},{"name":"红豆沙","cat":"甜点","region":"粤","time":90,"diff":"中等","main":[["红豆","300g"]],"sea":["红糖","冰糖","猪油"],"steps":["红豆挑掉坏豆，冷水泡4小时以上，泡到豆皮发皱、捏着能扁。","连水倒进锅里，大火烧开转小火煮40分钟，煮到豆子开花一捏就烂。","用勺子背把豆子压成泥，留一小部分整粒豆，口感更有层次。","锅里放猪油化开，下豆泥中小火不停翻炒10分钟，炒到豆沙变干能抱团。","加红糖和冰糖继续炒5分钟，糖化开后豆沙油亮不粘铲即可。"],"tip":"炒豆沙要始终中小火翻底，糖后放不易糊；猪油是起沙发亮的关键。"},{"name":"绿豆汤","cat":"甜点","region":"家常","time":45,"diff":"简单","main":[["绿豆","200g"]],"sea":["冰糖"],"steps":["绿豆淘洗干净，用清水泡1小时，泡到豆子涨大、表皮发皱。","绿豆连水倒进锅里，水是豆子的8倍，大火煮开撇掉浮沫。","转中小火煮25分钟，煮到豆子刚开花、汤色还清亮时最好喝。","加冰糖搅到化开，再煮5分钟关火，放凉后喝更解暑。"],"tip":"想汤清就别久煮，豆刚开花就关火；用纯净水煮汤色不易发红。"},{"name":"杨枝甘露","cat":"甜点","region":"粤","time":30,"diff":"中等","main":[["芒果","2个"],["西米","50g"],["椰浆","200ml"],["牛奶","100ml"]],"sea":["白糖"],"steps":["水烧开下西米，中火煮12分钟，边煮边搅，煮到中间只剩一个小白点时关火焖5分钟。","西米捞出过凉水，洗掉表面黏液，沥干备用，粒粒透明有弹性。","芒果去皮切块，一半加牛奶和椰浆打成顺滑的芒果奶浆。","奶浆加白糖搅匀，倒入西米和剩下的芒果块，冷藏30分钟再吃。"],"tip":"西米煮后必须过凉水冲掉黏液，口感才弹；奶浆别打太久以免起泡。"},{"name":"糖葫芦","cat":"甜点","region":"家常","time":30,"diff":"中等","main":[["山楂","300g"]],"sea":["冰糖","白芝麻"],"steps":["山楂洗净去蒂，用筷子从中间捅出核，五个一串串好，晾到表面完全干。","冰糖加等量清水，小火慢慢熬，全程别搅动，熬到糖液冒细密小泡。","糖液滴进凉水里能立刻凝成脆片，说明火候到了，撒白芝麻拌匀。","把山楂串快速滚一圈糖浆，甩掉多余的糖，放在抹油的盘子上晾10分钟定型。"],"tip":"山楂必须擦干，带水糖会返砂；糖浆熬到能成脆片就离火，别熬成焦色。"},{"name":"驴打滚","cat":"甜点","region":"家常","time":60,"diff":"中等","main":[["糯米粉","200g"],["红豆","150g"],["黄豆","80g"]],"sea":["白糖","食用油"],"steps":["黄豆洗净晾干，干锅小火炒8分钟，炒到豆皮裂开、闻到豆香，晾凉磨成黄豆面。","红豆煮烂压成泥，加白糖炒到能抱团，做成豆沙馅放凉。","糯米粉加温水调成稀糊，倒进抹油的盘子，水开后中火蒸20分钟至透明。","蒸好的糯米团晾到不烫手，案板撒黄豆面，擀成半厘米厚的长片。","抹一层豆沙卷起，切成4厘米的段，表面再滚一层黄豆面即可。"],"tip":"糯米团趁温热擀开才不裂，凉了发硬；黄豆面要小火慢炒，糊了会苦。"},{"name":"炸鲜奶","cat":"甜点","region":"粤","time":40,"diff":"较难","main":[["牛奶","400ml"],["淀粉","60g"],["鸡蛋","1个"]],"sea":["面粉","白糖","食用油"],"steps":["牛奶加淀粉和白糖倒进不粘锅，小火不停搅拌，搅到变成浓稠糊状、能挂住勺子。","奶糊倒进抹了油的方盘，抹平表面，冷藏2小时到完全凝固定型。","取出切成小长条，先滚一层干淀粉，再蘸蛋液，最后裹一层面粉。","油烧到五成热，下奶条中小火炸2分钟，炸到外壳金黄浮起就捞出控油。"],"tip":"奶糊要熬到浓稠挂勺，冷藏够久才切得整；油温别高，否则外焦里流。"},{"name":"黑芝麻糊","cat":"甜点","region":"家常","time":30,"diff":"简单","main":[["黑芝麻","100g"],["大米","50g"]],"sea":["白糖","猪油"],"steps":["大米淘净泡2小时，黑芝麻挑去杂质，干锅小火炒3分钟炒出香味。","大米和黑芝麻一起倒进料理机，加两倍清水打成细腻米浆，过筛一遍。","米浆倒进锅里，中小火边煮边搅，煮到冒泡变稠，全程别停手防糊底。","加白糖和一小块猪油搅匀，煮到能挂住勺背就关火。"],"tip":"打好的浆必须过筛，口感才细；煮时全程中小火不停搅，一停就糊。"},{"name":"烤冷面","cat":"主食","region":"东北","time":20,"diff":"简单","main":[["冷面","2张"],["鸡蛋","2个"],["香肠","1根"]],"sea":["甜面酱","醋","白糖","葱","香菜","食用油"],"steps":["平底锅刷薄油烧热，中小火放一张冷面，用铲子压平，煎1分钟到边缘变软。","打一个鸡蛋摊开铺满面皮，撒葱花香菜，等蛋液半凝固再翻面。","刷甜面酱，摆上切开的香肠，撒白糖再淋几滴醋提味。","从一头卷起，用铲子压两下让它定型，切成小段装盘。"],"tip":"冷面下锅前喷点水不易裂；糖醋一起刷，酸甜味才像街边摊。"},{"name":"麻辣烫","cat":"主食","region":"川","time":30,"diff":"中等","main":[["粉条","200g"],["豆腐","200g"],["金针菇","150g"],["生菜","100g"],["鱼丸","100g"]],"sea":["豆瓣酱","干辣椒","花椒","蒜","芝麻酱","盐","食用油"],"steps":["粉条提前用温水泡软20分钟，金针菇撕散洗净，豆腐切成厚片。","锅里放油，中小火炒香蒜末、干辣椒和花椒，再加一勺豆瓣酱炒出红油。","加清水大火烧开，放豆腐和鱼丸煮5分钟，让豆腐吸饱汤汁。","下粉条和金针菇煮3分钟，最后放生菜烫30秒，加盐调味。","盛出淋一勺用温水调开的芝麻酱，撒葱花趁热吃。"],"tip":"芝麻酱先用温水调稀再淋，香味才挂得住；生菜最后放，久煮发黄。"},{"name":"干炒牛河","cat":"主食","region":"粤","time":20,"diff":"较难","main":[["河粉","400g"],["牛肉","150g"],["豆芽","100g"]],"sea":["葱","生抽","老抽","蚝油","淀粉","食用油","盐"],"steps":["牛肉逆纹切薄片，加生抽、淀粉和一勺食用油抓匀，腌15分钟。","河粉用手轻轻抖散，别弄断，豆芽掐去头尾洗净沥干。","锅烧到冒烟倒油，下牛肉大火滑炒30秒，一变颜色就盛出。","锅留底油下河粉，中大火快速翻炒，用铲子推散，加老抽上色。","放豆芽和葱段，淋生抽和蚝油，倒回牛肉大火翻10秒出锅。"],"tip":"河粉别用铲子压，一压就断；锅必须够热，全程快炒才有锅气。"},{"name":"卤鸡爪","cat":"荤菜","region":"家常","time":60,"diff":"中等","main":[["鸡爪","500g"]],"sea":["八角","桂皮","香叶","干辣椒","生抽","老抽","冰糖","料酒"],"steps":["鸡爪剪掉指甲，冷水下锅中火煮3分钟，撇净浮沫后捞出用温水冲净。","锅里放少量油，小火炒冰糖到化成枣红色，冲入一碗热水做成糖色。","加生抽、老抽、料酒和所有香料，大火烧开转小火熬10分钟出味。","下鸡爪小火卤30分钟，中途翻两次，煮到皮能轻松掐破。","关火后让鸡爪泡在卤汁里2小时，捞出更入味，卤汁留着下次用。"],"tip":"鸡爪焯水后用温水冲，遇冷水皮会紧；卤好别急着捞，泡着才入味。"},{"name":"炸鸡柳","cat":"荤菜","region":"家常","time":40,"diff":"中等","main":[["鸡胸肉","300g"],["鸡蛋","1个"]],"sea":["淀粉","面粉","白胡椒","盐","料酒","食用油"],"steps":["鸡胸肉顺纹切成小指粗的条，加盐、料酒和白胡椒抓匀，腌20分钟。","鸡蛋打散，另备两盘，一盘放淀粉，一盘放面粉，把腌好的肉先拍淀粉。","再蘸蛋液，最后裹一层面粉，用手轻轻压实，抖掉多余干粉。","油烧到五成热，逐条下锅中小火炸3分钟，炸到浅黄捞出。","油温升到七成复炸30秒，外壳金黄酥脆就捞出控油。"],"tip":"复炸一次外壳才脆；下锅后别马上翻，等定型再动，裹粉不掉。"},{"name":"炸藕盒","cat":"荤菜","region":"家常","time":45,"diff":"中等","main":[["莲藕","1节"],["猪肉末","200g"],["鸡蛋","1个"]],"sea":["面粉","淀粉","盐","生抽","葱","姜","食用油","白胡椒"],"steps":["莲藕去皮切成3毫米厚的夹刀片，就是第一刀不断、第二刀切断。","猪肉末加葱姜末、盐、生抽和白胡椒，顺一个方向搅到上劲。","把肉馅夹进藕片中间按平，边缘抹平，别塞太满以免炸开。","鸡蛋、面粉、淀粉加水调成能挂住勺的糊，藕盒逐个裹匀。","油烧到六成热下藕盒，中小火炸4分钟，两面金黄浮起捞出控油。"],"tip":"面糊调成酸奶稠度最合适，太稀挂不住；肉馅别太湿，否则夹层出水。"},{"name":"钵钵鸡","cat":"荤菜","region":"川","time":50,"diff":"中等","main":[["鸡腿","2个"],["莲藕","1节"],["木耳","50g"]],"sea":["辣椒油","花椒粉","白芝麻","生抽","醋","白糖","蒜","料酒"],"steps":["鸡腿冷水下锅加料酒，中火煮15分钟，关火再焖10分钟，捞出泡冰水。","莲藕切薄片，木耳泡发撕小朵，分别下开水锅焯1分钟，捞出过凉。","鸡腿晾凉后去骨片成薄片，和藕片、木耳一起串成小串或直接装碗。","碗里放辣椒油、花椒粉、生抽、醋、白糖、蒜末和白芝麻，加两勺煮鸡汤调开。","把红油汤汁浇在食材上，泡20分钟入味，撒葱花即可。"],"tip":"鸡肉煮好立刻泡冰水，皮才紧实弹牙；红油汁要宽，泡久更入味。"},{"name":"蒜蓉烤茄子","cat":"素菜","region":"东北","time":35,"diff":"简单","main":[["茄子","2个"]],"sea":["蒜","辣椒面","孜然","生抽","食用油","盐","葱"],"steps":["茄子对半剖开，表面刷油，切面朝下放进200度烤箱烤15分钟。","蒜剁成蓉，一半用热油泼香，拌上辣椒面、孜然、生抽和盐调成蒜蓉酱。","茄子烤到皮皱肉软，用勺子把茄肉划松，别划破底部外皮。","铺满蒜蓉酱，再回烤箱烤8分钟，烤到表面冒泡、蒜香浓郁。","出炉撒上葱花，趁热用勺子连茄肉带蒜蓉一起挖着吃，凉了蒜味发闷。"],"tip":"茄子先烤软再铺酱，蒜不会烤糊；蒜蓉一半生一半熟，香味更有层次。"},{"name":"铁板豆腐","cat":"素菜","region":"湘","time":25,"diff":"中等","main":[["豆腐","400g"]],"sea":["蒜","辣椒面","孜然","生抽","葱","食用油","盐","白芝麻"],"steps":["豆腐切成1厘米厚的方片，用厨房纸吸干表面水分，两面抹一层薄盐。","平底锅烧热多放油，中火下豆腐片，煎4分钟到一面金黄结壳再翻面。","两面都煎到焦黄起皱，推到锅边，利用余油炒香蒜末、辣椒面和孜然。","淋生抽，撒白芝麻和葱花，让豆腐两面都沾上料，再煎1分钟收汁。"],"tip":"豆腐一定要吸干水再下锅，锅热油足才不粘；煎出硬壳再翻面不碎。"},{"name":"剁椒蒸排骨","cat":"荤菜","region":"湘","time":45,"diff":"简单","main":[["排骨","500g"],["芋头","200g"]],"sea":["剁椒","蒜","姜","料酒","生抽","淀粉","食用油","葱"],"steps":["排骨斩成3厘米段，冷水泡20分钟去血水，冲净后沥干。","加料酒、生抽、姜末、淀粉抓匀，腌15分钟。","芋头去皮切滚刀块铺盘底，排骨码在上面。","剁椒拌蒜末和少许油，厚厚铺在排骨上，上汽大火蒸25分钟。","出锅撒葱花，淋一勺烧到冒烟的食用油激香。"],"tip":"排骨泡净血水再腌，蒸出来才不腥；芋头垫底吸汁比土豆更糯。"},{"name":"蒸茄子","cat":"素菜","region":"家常","time":20,"diff":"简单","main":[["长茄子","2根"],["蒜","1头"]],"sea":["生抽","香醋","香油","辣椒油","盐","葱"],"steps":["茄子去蒂切长条，放淡盐水泡5分钟，捞出挤干水分。","茄条平铺盘中，上汽后中火蒸10分钟，筷子能轻松扎透即可。","蒜剁成泥，加生抽、香醋、盐、香油和辣椒油调成料汁。","倒掉盘中蒸出的水，淋上料汁，撒葱花拌匀。"],"tip":"茄子先泡盐水再蒸，颜色不发黑，也不会吸一身油。"},{"name":"蒜蓉蒸丝瓜","cat":"素菜","region":"粤","time":15,"diff":"简单","main":[["丝瓜","2根"],["蒜","1头"],["粉丝","1小把"]],"sea":["蒸鱼豉油","食用油","盐","葱"],"steps":["粉丝温水泡软，剪成短段铺在盘底。","丝瓜刮去硬皮切5厘米段，竖着摆在粉丝上。","蒜切末，一半用热油炸到金黄，与生蒜末、盐拌匀。","蒜蓉铺在丝瓜上，上汽大火蒸6分钟，关火再焖2分钟。","淋蒸鱼豉油、撒葱花，浇一勺热油即成。"],"tip":"丝瓜蒸久就塌，六分钟足矣；蒜蓉一半生一半熟，香味才立体。"},{"name":"清蒸南瓜","cat":"素菜","region":"家常","time":25,"diff":"简单","main":[["南瓜","600g"],["枸杞","1小把"]],"sea":["蜂蜜","桂花"],"steps":["南瓜去瓤去皮，切成两厘米厚的方块，皮朝下摆入深盘。","枸杞用温水泡软，和桂花一起撒在南瓜上。","上汽后中火蒸15分钟，筷子能轻松插透就好。","出锅淋一勺蜂蜜，趁热吃最甜糯。"],"tip":"挑老一点的面南瓜，蒸前别放糖，出锅淋蜜才清甜不腻。"},{"name":"蒸水蛋","cat":"荤菜","region":"家常","time":15,"diff":"简单","main":[["鸡蛋","3个"],["虾皮","1小把"]],"sea":["盐","生抽","香油","葱"],"steps":["鸡蛋打散，加一小撮盐，按蛋液一倍半的量兑入温水搅匀。","蛋液过筛两遍，撇净表面浮沫，倒入浅碗。","碗上盖盘子，上汽后中小火蒸10分钟。","关火焖2分钟取出，撒虾皮和葱花，淋生抽、香油。"],"tip":"兑温水、过筛、盖盖子，这三步做到，蛋面才平滑无蜂窝。"},{"name":"隔水蒸鸡","cat":"荤菜","region":"粤","time":50,"diff":"中等","main":[["整鸡","半只"],["姜","1块"],["葱","3根"]],"sea":["盐","料酒","生抽","食用油","姜","葱"],"steps":["半只鸡洗净沥干，用盐和料酒里外抹匀，腌20分钟。","姜切片、葱切段，一半塞进鸡腹，一半铺在盘底。","水开后整盘入锅，加盖大火隔水蒸25分钟，中途不揭盖。","关火焖5分钟再取出，筷子扎鸡腿最厚处，无血水即熟。","晾到不烫手斩件，淋一勺生抽，浇热油激香葱姜。"],"tip":"全程大火足汽，关火再焖五分钟，鸡肉才嫩而不带血丝。"},{"name":"香菇蒸鸡","cat":"荤菜","region":"家常","time":40,"diff":"简单","main":[["鸡腿","3个"],["香菇","6朵"]],"sea":["生抽","蚝油","料酒","淀粉","白糖","食用油","姜","葱"],"steps":["鸡腿去骨切3厘米块，加生抽、蚝油、料酒、白糖、姜丝腌20分钟。","香菇去蒂切厚片，挤干水分，平铺在盘底。","鸡块拌入淀粉，再淋一勺油拌匀，平铺在香菇上。","上汽后大火蒸20分钟，关火再焖3分钟。","出锅撒葱花，盘底的汤汁拌饭最香。"],"tip":"腌好后加淀粉和油再蒸，鸡肉锁得住汁，香菇吸的都是鲜汤。"},{"name":"砂锅豆腐","cat":"素菜","region":"家常","time":30,"diff":"简单","main":[["豆腐","1块"],["娃娃菜","半棵"],["香菇","4朵"],["虾皮","1小把"]],"sea":["生抽","蚝油","盐","白胡椒","姜","葱","食用油"],"steps":["豆腐切两厘米方块，放淡盐水里泡10分钟，捞出沥干。","砂锅烧热放油，下姜片、虾皮小火炒香。","娃娃菜撕块铺底，摆上豆腐和香菇片，加生抽、蚝油和一碗热水。","大火烧开转小火炖12分钟，加盐和白胡椒调味。","撒上葱花，关火后连砂锅一起端上桌。"],"tip":"豆腐先用盐水泡，炖的时候不易碎，还能去掉豆腥味。"},{"name":"砂锅鱼头","cat":"荤菜","region":"粤","time":45,"diff":"中等","main":[["鱼头","1个"],["豆腐","1块"]],"sea":["生抽","料酒","盐","白胡椒","姜","葱","食用油","蒜"],"steps":["鱼头劈开洗净，用料酒、盐、姜片抹匀腌15分钟，擦干水分。","砂锅烧热放油，鱼头切面朝下煎到微黄，盛出。","余油炒香姜蒜，铺上豆腐块，鱼头放回，加生抽和开水到没过一半。","大火烧开转小火炖20分钟，汤色转白。","加盐、白胡椒调味，撒葱段，原锅上桌。"],"tip":"鱼头先煎再炖汤才白；一定加开水，冷水会让鱼肉发柴。"},{"name":"砂锅粥","cat":"主食","region":"粤","time":60,"diff":"中等","main":[["大米","150g"],["虾","200g"],["蟹","1只"]],"sea":["盐","姜","葱","白胡椒","香油","料酒"],"steps":["大米淘净，加一勺油和少许盐拌匀，泡30分钟。","砂锅加足量水烧开，倒入大米，大火煮开转小火熬25分钟。","虾挑去虾线、蟹斩块，用料酒和姜丝腌10分钟。","粥熬到米粒开花、汤稠，下虾蟹和姜丝，中火煮8分钟。","加盐、白胡椒调味，淋香油，撒葱花。"],"tip":"米先用油盐拌过再熬才绵滑起胶；水一次加足，中途别添。"},{"name":"黄焖鸡","cat":"荤菜","region":"鲁","time":50,"diff":"中等","main":[["鸡腿","4个"],["香菇","6朵"],["青椒","1个"],["土豆","1个"]],"sea":["生抽","老抽","蚝油","冰糖","料酒","姜","蒜","干辣椒"],"steps":["鸡腿剁成3厘米块，冷水下锅焯去血沫，捞出冲净。","锅中少油下冰糖，小火炒到枣红色，倒入鸡块翻炒上色。","加姜蒜、干辣椒炒香，烹入料酒，再加生抽、老抽、蚝油翻匀。","倒入开水没过鸡块，放香菇和土豆块，小火焖25分钟。","放青椒块，大火收汁到浓稠挂勺，出锅。"],"tip":"糖色炒到枣红立刻下鸡块，再晚就发苦；收汁留一点好拌饭。"},{"name":"柱侯牛腩","cat":"荤菜","region":"粤","time":120,"diff":"较难","main":[["牛腩","800g"],["白萝卜","1根"]],"sea":["柱侯酱","生抽","老抽","冰糖","料酒","八角","桂皮","蒜"],"steps":["牛腩切4厘米块，冷水下锅加料酒焯5分钟，撇净浮沫后冲净。","锅中放油，下蒜末、柱侯酱小火炒出酱香，倒入牛腩翻炒。","加生抽、老抽、冰糖、八角、桂皮，倒开水没过牛腩。","转入砂锅，小火焖90分钟，筷子能扎透即可。","白萝卜切块放入，再焖20分钟到萝卜透明入味。"],"tip":"柱侯酱要小火炒过才出香；牛腩别切太小，久焖还会缩。"},{"name":"栗子焖鸡","cat":"荤菜","region":"家常","time":55,"diff":"中等","main":[["鸡腿","4个"],["板栗","300g"]],"sea":["生抽","老抽","冰糖","料酒","姜","葱","食用油"],"steps":["板栗用刀划十字，下锅煮5分钟，趁热剥壳去内衣。","鸡腿剁块，冷水下锅焯去血水，捞出沥干。","锅中放油，下姜片和鸡块，中火煎到表面微黄。","烹入料酒，加生抽、老抽、冰糖翻匀，倒入开水和板栗。","小火焖30分钟，转大火收汁到浓稠，撒葱花出锅。"],"tip":"板栗先煮再剥不伤手；焖到后半程少翻动，栗子才不碎。"},{"name":"黄豆焖猪蹄","cat":"荤菜","region":"家常","time":120,"diff":"中等","main":[["猪蹄","1只"],["黄豆","150g"]],"sea":["生抽","老抽","冰糖","料酒","八角","桂皮","姜","葱"],"steps":["黄豆提前泡4小时，泡到手指能捏开。","猪蹄剁块，冷水下锅加料酒焯10分钟，拔净残毛后冲净。","锅中少油炒冰糖到起泡，下猪蹄翻裹糖色，加姜、八角、桂皮。","倒入开水和黄豆，加生抽、老抽，小火焖90分钟。","开盖大火收汁，撒葱花，汤汁粘唇即可。"],"tip":"猪蹄焯水后用温水冲，遇冷水皮会收紧，久焖也不软糯。"},{"name":"啫啫鸡煲","cat":"荤菜","region":"粤","time":40,"diff":"中等","main":[["鸡腿","4个"],["洋葱","半个"],["蒜","1头"],["姜","1块"]],"sea":["生抽","蚝油","老抽","白糖","料酒","淀粉","食用油"],"steps":["鸡腿剁小块，加生抽、蚝油、老抽、白糖、淀粉腌20分钟。","砂锅烧到冒烟，放两勺油，下姜片、蒜瓣、洋葱块铺满锅底。","鸡块平铺在料头上，加盖中火焗8分钟，中途沿锅边淋一圈料酒。","开盖翻动一次，再焗3分钟到鸡肉收缩、锅底微焦。","原锅端上桌，趁滋滋作响时拌匀开吃。"],"tip":"砂锅一定烧到冒烟再下料，锅气足才有那层啫啫焦香。"},{"name":"香芋扣肉","cat":"荤菜","region":"广西","time":100,"diff":"较难","main":[["五花肉","500g"],["芋头","400g"]],"sea":["生抽","老抽","料酒","冰糖","八角","姜","蒜","豆腐乳"],"steps":["五花肉整块冷水下锅，加姜片、料酒煮20分钟，捞出擦干抹老抽。","芋头去皮切1厘米厚片，下油锅炸到表面微黄结皮。","肉块皮朝下入锅煎成虎皮色，晾凉后切成与芋头同厚的片。","豆腐乳加生抽、冰糖、蒜末调成酱，肉片和芋头片逐片蘸匀。","肉皮朝下与芋头相间码入碗中，上汽蒸60分钟，倒扣上桌。"],"tip":"芋头先炸过才不散；肉片和芋头厚度一致，蒸完才齐整好看。"},{"name":"莲藕排骨煲","cat":"荤菜","region":"鄂","time":90,"diff":"简单","main":[["排骨","500g"],["莲藕","1节"]],"sea":["盐","料酒","姜","葱","白胡椒","食用油"],"steps":["排骨冷水下锅，加姜片、料酒焯去血沫，捞出洗净。","莲藕去皮切滚刀块，泡清水防发黑，用刀背把几块拍裂。","砂锅放少许油，煸香姜片，倒入排骨翻炒到表面微黄。","加开水没过排骨，放莲藕，大火烧开转小火煲60分钟。","汤色转浓、藕块粉糯时加盐和白胡椒，撒葱花。"],"tip":"莲藕拍裂几段再煲，淀粉融进汤里，汤才又浓又粉。"},{"name":"干锅鸡","cat":"荤菜","region":"川","time":45,"diff":"中等","main":[["鸡腿","4个"],["土豆","1个"],["青椒","1个"],["洋葱","半个"]],"sea":["豆瓣酱","干辣椒","花椒","姜","蒜","生抽","料酒","白糖"],"steps":["鸡腿剁小块，加料酒、生抽腌15分钟；土豆切条泡水。","锅中多放油，土豆条中火炸到金黄捞出，再下鸡块炸到表皮收紧。","留底油小火炒豆瓣酱出红油，下干辣椒、花椒、姜蒜炒香。","倒入鸡块和土豆条，加白糖、生抽大火翻炒2分钟。","放青椒、洋葱炒到断生，盛入干锅，小火边加热边吃。"],"tip":"鸡块先炸定型再炒，皮才紧实不脱；豆瓣酱必须小火炒出红油。"},{"name":"干锅肥肠","cat":"荤菜","region":"川","time":60,"diff":"较难","main":[["猪大肠","500g"],["洋葱","半个"],["青椒","1个"],["芹菜","2根"]],"sea":["豆瓣酱","干辣椒","花椒","姜","蒜","料酒","生抽","白糖"],"steps":["猪大肠用面粉和盐反复搓洗三遍，翻面撕净多余油脂。","冷水下锅，加姜片、料酒、花椒煮40分钟，煮到筷子能扎透。","捞出晾凉切段，锅中少油煸到表面起泡出油，盛出。","余油炒豆瓣酱出红油，下干辣椒、花椒、姜蒜炒香。","倒入肥肠，加生抽、白糖大火翻炒，放洋葱、青椒、芹菜炒断生。"],"tip":"大肠用面粉搓洗能去异味；煮到筷子能扎透再炒才软糯不韧。"},{"name":"番茄滑蛋饭","cat":"主食","region":"家常","time":15,"diff":"简单","main":[["西红柿","2个"],["鸡蛋","2个"],["米饭","1碗"]],"sea":["盐","白糖","番茄酱","淀粉","葱","食用油"],"steps":["西红柿顶部划十字，开水烫30秒后撕皮，切小块；鸡蛋加少许盐和1勺清水打散。","热锅多放油，倒入蛋液，用铲子从外往内推，蛋液八成凝固就盛出，别炒老。","原锅下西红柿块，中火炒3分钟出汁，加半勺白糖和1勺番茄酱炒匀。","倒回鸡蛋，淋小半碗水淀粉，翻两下让蛋块裹上汤汁，撒葱花盖在米饭上。"],"tip":"蛋液里加一勺清水，炒出来更嫩；鸡蛋八成熟就盛出，回锅后正好。"},{"name":"照烧鸡腿饭","cat":"主食","region":"家常","time":25,"diff":"中等","main":[["鸡腿","2个"],["米饭","1碗"],["西兰花","100g"],["胡萝卜","半根"]],"sea":["生抽","老抽","料酒","蜂蜜","白糖","姜","食用油","白芝麻"],"steps":["鸡腿去骨，用刀背把肉拍松，加1勺料酒和姜片抓匀，腌10分钟。","生抽2勺、料酒1勺、蜂蜜1勺、白糖半勺和3勺清水调成照烧汁。","平底锅不放油，鸡皮朝下小火煎6分钟，逼出鸡油后翻面再煎3分钟。","倒掉多余的油，倒入照烧汁，小火煮到汤汁浓稠挂勺，中途翻面两次。","鸡腿切条铺在米饭上，淋汁，配焯过水的西兰花和胡萝卜，撒白芝麻。"],"tip":"鸡皮朝下冷锅下锅，小火慢煎才能把油逼出来，皮才脆不腻。"},{"name":"土豆肉丝盖饭","cat":"主食","region":"家常","time":20,"diff":"简单","main":[["土豆","1个"],["猪里脊","150g"],["米饭","1碗"],["青椒","半个"]],"sea":["生抽","料酒","淀粉","醋","盐","蒜","食用油"],"steps":["猪里脊切细丝，加料酒、生抽和淀粉抓匀，封一层油腌10分钟。","土豆切细丝，清水淘洗两遍去淀粉，沥干；青椒切丝。","热锅滑油，肉丝下锅大火炒到变白立刻盛出，别炒久。","余油下蒜末和土豆丝，中火炒3分钟，沿锅边淋半勺醋保持脆。","倒回肉丝和青椒丝，加盐和1勺生抽大火翻匀，盖在米饭上。"],"tip":"土豆丝洗掉表面淀粉再炒，才爽脆不粘锅，也不容易糊成一团。"},{"name":"梅菜肉饼饭","cat":"主食","region":"客家","time":45,"diff":"中等","main":[["猪肉末","200g"],["梅干菜","40g"],["米饭","1碗"]],"sea":["生抽","老抽","白糖","料酒","淀粉","香油","姜"],"steps":["梅干菜温水泡20分钟，反复淘洗到没有沙，挤干水分切成碎末。","肉末加姜末、1勺生抽、半勺料酒、1勺淀粉，顺一个方向搅到起胶。","梅干菜下锅小火炒干水汽，加半勺白糖炒香，晾凉后拌进肉馅。","肉馅压成2厘米厚的饼放进碗里，淋半勺生抽和几滴香油。","水开后上锅大火蒸15分钟，关火焖2分钟，肉饼连汁扣在米饭上。"],"tip":"梅干菜要炒干再拌馅，蒸出来的肉饼才香不水塌，咸味也更均匀。"},{"name":"豆角焖面","cat":"主食","region":"家常","time":30,"diff":"中等","main":[["豆角","250g"],["面条","200g"],["五花肉","100g"]],"sea":["生抽","老抽","盐","蒜","八角","食用油"],"steps":["豆角掰成5厘米段，五花肉切薄片，面条抖散防止粘连。","热油下八角炸香，放肉片煸出油，加蒜末和生抽炒上色。","下豆角大火翻炒3分钟，加老抽和盐，倒热水到刚好没过豆角。","把面条平铺在豆角上，盖盖小火焖8分钟，中途不要翻动。","汤汁将干时开盖，用筷子把面和豆角抖散拌匀，再焖2分钟。"],"tip":"水别放多，面靠蒸汽焖熟；汤收干前别翻，翻早了面容易断。"},{"name":"腊肠焖饭","cat":"主食","region":"粤","time":45,"diff":"简单","main":[["香肠","1根"],["大米","150g"],["油菜","2棵"],["鸡蛋","1个"]],"sea":["生抽","老抽","白糖","香油","蚝油"],"steps":["大米淘净，按1比1.2加水泡20分钟；香肠斜切薄片。","米连水倒进锅，大火烧开转小火，煮到表面看不见水。","铺上香肠片，盖盖小火焖10分钟，关火再焖5分钟。","油菜用开水焯30秒捞出；鸡蛋另煎成溏心荷包蛋。","生抽、老抽、蚝油、白糖和香油调成汁，淋在饭上拌匀，配菜摆好。"],"tip":"香肠铺在米饭上焖，油脂渗进饭粒才香；关火后焖5分钟更松软。"},{"name":"蒜香排骨","cat":"荤菜","region":"粤","time":50,"diff":"中等","main":[["排骨","400g"],["蒜","1头"]],"sea":["生抽","蚝油","料酒","白糖","淀粉","白胡椒","食用油"],"steps":["排骨剁3厘米段，冷水泡20分钟去血水，换两次水后擦干。","蒜压成泥，取一半加生抽、蚝油、料酒、白糖和白胡椒调成腌料。","排骨拌入腌料和1勺淀粉，冷藏腌30分钟以上。","平底锅多放油，中火下排骨煎8分钟，两面金黄、边角微焦。","倒出多余油，下剩下的蒜泥小火炒香，翻匀让蒜末裹住排骨。"],"tip":"排骨擦干再腌才挂得住味；蒜末分两次放，一半腌一半炒更香。"},{"name":"香煎鸡胸","cat":"荤菜","region":"家常","time":25,"diff":"简单","main":[["鸡胸肉","1块"],["西兰花","100g"]],"sea":["盐","黑胡椒","生抽","料酒","蒜","食用油"],"steps":["鸡胸横刀片成两片，用刀背轻拍松，厚的地方划两刀让厚度均匀。","加盐、黑胡椒、生抽、料酒和蒜末抓匀，腌20分钟。","平底锅烧热刷薄油，鸡胸下锅中火煎3分钟，别急着翻。","翻面再煎3分钟，倒入2勺清水盖盖焖2分钟，中心不见粉红即可。","出锅静置3分钟再切条，配焯过水的西兰花装盒。"],"tip":"煎时加两勺水盖盖焖，鸡胸不会柴；静置后再切，肉汁不流失。"},{"name":"西红柿牛腩","cat":"荤菜","region":"家常","time":100,"diff":"中等","main":[["牛腩","400g"],["西红柿","3个"],["洋葱","半个"]],"sea":["盐","生抽","番茄酱","料酒","冰糖","姜","八角","食用油"],"steps":["牛腩切3厘米块，冷水下锅加姜片和料酒，煮开撇沫后捞出洗净。","两个西红柿切块，一个切碎；洋葱切丝。","热油炒洋葱到软，下切碎的西红柿和番茄酱炒5分钟成红汤。","下牛腩翻炒，加生抽、冰糖、八角，倒热水没过，小火炖60分钟。","放剩下的西红柿块再炖15分钟，加盐调味，收到汤汁略稠。"],"tip":"西红柿分两次下，一次炒成汤底，一次留形状，酸甜和口感都有。"},{"name":"肉末茄子","cat":"荤菜","region":"家常","time":25,"diff":"简单","main":[["长茄子","2根"],["猪肉末","100g"]],"sea":["生抽","老抽","豆瓣酱","白糖","蒜","葱","淀粉","食用油"],"steps":["茄子切滚刀块，撒少许盐抓匀腌10分钟，挤掉水分后拍薄淀粉。","锅中多放油，中火把茄子煎到表面微焦、变软，盛出控油。","余油下肉末炒散，加蒜末和1勺豆瓣酱炒出红油。","倒回茄子，加生抽、老抽、白糖和小半碗水，中小火烧5分钟。","汤汁收到浓稠裹住茄子，撒葱花出锅。"],"tip":"茄子先用盐杀水再拍淀粉，煎的时候不吸油，也不容易烂成泥。"},{"name":"鸡蛋抱豆腐","cat":"素菜","region":"家常","time":15,"diff":"简单","main":[["豆腐","1盒"],["鸡蛋","3个"]],"sea":["盐","生抽","蚝油","白糖","淀粉","葱","食用油"],"steps":["豆腐切2厘米方块，用厨房纸吸干表面的水分。","鸡蛋加少许盐打散，倒入豆腐里轻轻拌匀，让每块都裹上蛋液。","平底锅少油中火，倒入豆腐蛋液摊平，煎3分钟到底部定型。","翻面再煎2分钟，用铲子划成小块，倒入生抽、蚝油、白糖和水的料汁。","小火煮2分钟收汁，淋水淀粉勾薄芡，撒葱花。"],"tip":"豆腐先吸干水再裹蛋液，下锅才不溅油，蛋皮也能完整抱住豆腐。"},{"name":"鸡蛋炒木耳","cat":"素菜","region":"家常","time":20,"diff":"简单","main":[["鸡蛋","3个"],["木耳","30g"],["黄瓜","半根"]],"sea":["盐","生抽","蒜","食用油","香油"],"steps":["木耳提前用冷水泡发2小时，撕成小朵，开水焯1分钟捞出。","鸡蛋加少许盐打散；黄瓜切菱形片；蒜切片。","热锅多放油，倒蛋液炒成大块，八成熟时盛出。","余油下蒜片炒香，倒木耳中火炒2分钟，听到噼啪声。","加黄瓜片、盐和生抽，倒回鸡蛋大火翻炒30秒，淋香油出锅。"],"tip":"木耳一定要焯水再炒，既去土味又防炸锅，泡发别超过4小时。"},{"name":"青椒炒蛋","cat":"素菜","region":"家常","time":15,"diff":"简单","main":[["青椒","3个"],["鸡蛋","3个"]],"sea":["盐","生抽","蒜","食用油"],"steps":["青椒去籽切细丝，撒半勺盐抓匀腌5分钟，挤掉水分。","鸡蛋加少许盐打散，锅烧热多放油，倒蛋液炒成嫩块盛出。","余油下蒜末和青椒丝，大火炒2分钟到断生、边缘发软。","倒回鸡蛋，加1勺生抽大火翻匀10秒，出锅。"],"tip":"青椒先用盐腌一下再炒，去涩又易熟，颜色也更翠绿。"},{"name":"腐乳空心菜","cat":"素菜","region":"粤","time":12,"diff":"简单","main":[["空心菜","400g"],["豆腐乳","2块"]],"sea":["蒜","食用油","白糖","料酒"],"steps":["空心菜摘去老梗，掰成10厘米长段，梗和叶分开放。","腐乳加1勺腐乳汁和半勺白糖压成泥，兑1勺料酒调开。","锅烧到冒烟，多放油下蒜末爆香，先下菜梗大火炒30秒。","再下菜叶，快速翻炒到刚塌软，倒入调好的腐乳汁。","大火颠锅10秒让酱汁裹匀，立刻出锅，别久炒出水。"],"tip":"腐乳先加汁压成泥再下锅，味道才匀；全程大火快炒，菜不出水。"},{"name":"凉拌手撕鸡","cat":"凉菜","region":"川","time":40,"diff":"中等","main":[["鸡腿","2个"],["黄瓜","1根"]],"sea":["生抽","香醋","辣椒油","白糖","蒜","香油","姜","葱"],"steps":["鸡腿冷水下锅，加姜片和1勺料酒，水开后小火煮12分钟。","关火焖5分钟，捞出立刻放冰水里泡10分钟，肉质更紧实。","黄瓜拍裂切段铺在盘底；鸡腿放凉后撕成粗条。","生抽2勺、香醋1勺、辣椒油1勺、白糖半勺、蒜末和香油调成料汁。","鸡丝和料汁拌匀，静置10分钟入味，撒葱花即可。"],"tip":"煮好立刻冰水泡，鸡皮爽脆肉不柴；料汁最后拌，提前拌会出水。"},{"name":"家常豆腐","cat":"素菜","region":"川","time":20,"diff":"中等","main":[["豆腐","400g"],["青椒","1个"],["木耳","1小把"],["胡萝卜","半根"]],"sea":["豆瓣酱","生抽","白糖","蒜","淀粉","食用油","盐","姜"],"steps":["豆腐切1.5厘米厚的三角块，用厨房纸吸干表面水分。","平底锅放油烧至六成热，中火下豆腐煎至两面金黄盛出。","青椒、胡萝卜切菱形片，木耳撕成小朵，蒜切片。","锅留底油，小火下豆瓣酱和蒜片炒出红油，加半碗热水烧开。","下豆腐，加生抽、白糖，中火烧3分钟，再放青椒、木耳翻炒。","大火收汁，淋水淀粉勾薄芡，晃锅推匀后出锅。"],"tip":"豆腐煎前吸干水分，下锅不溅油，也不容易粘锅破皮。"},{"name":"卤豆腐","cat":"素菜","region":"家常","time":40,"diff":"简单","main":[["豆腐","400g"]],"sea":["生抽","老抽","冰糖","八角","桂皮","香叶","花椒","姜"],"steps":["豆腐切2厘米厚的大块，平底锅少油中火煎至两面微黄。","锅中加清水、生抽、老抽、冰糖、八角、桂皮、香叶、花椒和姜片。","大火烧开后放入豆腐，转小火卤15分钟，中途翻一次面。","关火连汤浸泡20分钟，让豆腐吸足卤汁，捞出切片装盘。"],"tip":"卤好别急着捞，泡在卤汁里放凉，颜色和味道才进得去。"},{"name":"红烧冻豆腐","cat":"素菜","region":"东北","time":30,"diff":"简单","main":[["豆腐","500g"]],"sea":["生抽","老抽","白糖","葱","姜","八角","淀粉","食用油"],"steps":["豆腐放冷冻室冻一夜，取出化开后双手挤干水分，切3厘米块。","锅中放油，中火下葱段、姜片、八角炒出香味。","加生抽、老抽、白糖和一碗清水烧开，下冻豆腐块。","转小火炖10分钟，冻豆腐吸满汤汁后体积变大、按压回弹。","大火收汁，淋水淀粉勾薄芡，撒葱花出锅。"],"tip":"冻豆腐化开后一定要挤干水，才能像海绵一样吸饱汤汁。"},{"name":"香干炒芹菜","cat":"素菜","region":"家常","time":15,"diff":"简单","main":[["香干","200g"],["芹菜","300g"]],"sea":["盐","生抽","蒜","干辣椒","食用油","香油"],"steps":["芹菜去叶留梗，撕掉老筋，切4厘米长段；香干切薄片。","水烧开加少许盐，芹菜下锅焯30秒捞出过凉水，保持翠绿。","热锅放油，中火下蒜片和干辣椒段炒出香味。","下香干片煎炒1分钟至边缘微焦，再倒芹菜大火翻炒1分钟。","加盐和生抽炒匀，淋香油立刻出锅，芹菜要保持脆口。"],"tip":"芹菜焯30秒再炒，颜色翠绿又去涩，久炒会发黄发软。"},{"name":"豆皮卷大葱","cat":"素菜","region":"东北","time":10,"diff":"简单","main":[["豆皮","2张"],["葱","2根"],["黄瓜","半根"]],"sea":["黄豆酱","甜面酱","香油","蒜"],"steps":["豆皮放开水里烫30秒捞出，过凉水沥干，切15厘米见方。","葱去老叶切8厘米长段，黄瓜切细条备用。","黄豆酱、甜面酱加蒜末，滴几滴香油调匀成蘸酱。","豆皮铺平，放葱段和黄瓜条，卷紧后斜切成两段，蘸酱吃。"],"tip":"豆皮烫过才有韧性不易裂，卷的时候要卷紧再切。"},{"name":"韭菜炒鸡蛋","cat":"素菜","region":"家常","time":10,"diff":"简单","main":[["韭菜","250g"],["鸡蛋","3个"]],"sea":["盐","料酒","食用油","白胡椒"],"steps":["韭菜洗净沥干，切3厘米段，根部和叶部分开放。","鸡蛋打散，加少许盐和料酒，搅到蛋液表面起小泡。","热锅倒油，六成热倒入蛋液，凝固后用铲子划成大块盛出。","锅留底油，大火下韭菜根炒20秒，再下叶部炒10秒。","倒回鸡蛋，加盐和白胡椒，快速翻匀立刻出锅。"],"tip":"韭菜下锅前一定沥干水，全程大火快炒，出水就不好吃。"},{"name":"洋葱炒蛋","cat":"素菜","region":"家常","time":12,"diff":"简单","main":[["洋葱","1个"],["鸡蛋","3个"]],"sea":["盐","生抽","食用油","白胡椒"],"steps":["洋葱切细丝，鸡蛋加少许盐打散备用。","锅烧热多放些油，倒入蛋液，中火炒至半凝固盛出。","原锅下洋葱丝，中火炒2分钟至边缘透明、香味发甜。","倒回鸡蛋，加生抽、盐和白胡椒，大火翻匀出锅。"],"tip":"洋葱切好泡一下冷水再炒，辣眼减轻，口感也更脆甜。"},{"name":"咸蛋黄豆腐","cat":"素菜","region":"粤","time":20,"diff":"中等","main":[["豆腐","400g"],["咸鸭蛋","2个"]],"sea":["盐","白糖","淀粉","葱","食用油","料酒"],"steps":["咸鸭蛋上锅蒸8分钟，取出蛋黄压碎，蛋白切小丁。","豆腐切2厘米块，放淡盐水泡5分钟去豆腥，捞出沥干。","锅中少油，小火下蛋黄碎炒到起细泡、颜色发亮。","加半碗水、盐和白糖烧开，下豆腐和蛋白丁，小火煨3分钟。","淋水淀粉勾芡，撒葱花，轻推锅让每块豆腐裹上蛋黄。"],"tip":"蛋黄要用小火炒到冒细泡才出沙，火大容易焦苦。"},{"name":"虎皮鸡蛋","cat":"素菜","region":"本帮","time":25,"diff":"中等","main":[["鸡蛋","6个"]],"sea":["生抽","老抽","白糖","料酒","葱","姜","八角","食用油"],"steps":["鸡蛋冷水下锅，水开煮8分钟，捞出泡凉水5分钟再剥壳。","剥好的鸡蛋擦干，用牙签在表面扎几个小孔。","锅中放油烧至七成热，下鸡蛋中火炸到表面起皱呈虎皮纹。","锅留底油炒香葱姜八角，加生抽、老抽、糖、料酒和一碗水烧开。","放鸡蛋小火焖10分钟，大火收汁至汤汁均匀裹在蛋上。"],"tip":"鸡蛋煮好立刻过凉水，蛋壳一剥就掉，表面还不坑洼。"},{"name":"糖醋荷包蛋","cat":"素菜","region":"家常","time":15,"diff":"简单","main":[["鸡蛋","4个"]],"sea":["醋","白糖","生抽","番茄酱","淀粉","葱","食用油"],"steps":["醋、白糖、生抽、番茄酱加两勺清水和少许淀粉，调成糖醋汁。","平底锅放油，中小火逐个打入鸡蛋，煎至蛋白凝固、边缘焦黄。","翻面再煎1分钟，蛋黄半熟时盛出，按同样方法煎完四个。","锅留底油倒入糖醋汁，小火煮到冒泡变稠，放回荷包蛋。","翻动鸡蛋让两面裹满糖醋汁，撒葱花出锅。"],"tip":"糖醋汁里加一点番茄酱，颜色红亮，酸甜也更柔和。"},{"name":"皮蛋拌豆腐","cat":"凉菜","region":"家常","time":10,"diff":"简单","main":[["豆腐","400g"],["皮蛋","2个"]],"sea":["生抽","香醋","香油","蒜","葱","辣椒油"],"steps":["豆腐倒扣盘中，切2厘米块，静置5分钟倒掉渗出的水。","皮蛋剥壳切小瓣，刀蘸凉水切，蛋黄不粘刀。","蒜切末，加生抽、香醋、香油和辣椒油调成料汁。","皮蛋瓣摆在豆腐上，淋上料汁，撒葱花，吃前轻拌两下。"],"tip":"皮蛋切前把刀蘸一下凉水，蛋黄不粘刀、切面也整齐。"},{"name":"卤蛋","cat":"凉菜","region":"家常","time":60,"diff":"简单","main":[["鸡蛋","8个"]],"sea":["生抽","老抽","冰糖","盐","八角","桂皮","香叶","姜"],"steps":["鸡蛋冷水下锅煮8分钟，捞出过凉水，剥壳后在表面划两刀。","锅中加水、生抽、老抽、冰糖、盐、八角、桂皮、香叶和姜片。","大火煮开后放鸡蛋，转小火卤20分钟，保持卤汁微沸。","关火浸泡30分钟以上，颜色变深、切开有卤汁纹路即可。"],"tip":"蛋壳剥好划两刀再卤，味道能渗到蛋黄，颜色也好看。"},{"name":"鱼头豆腐汤","cat":"汤羹","region":"家常","time":40,"diff":"中等","main":[["鱼头","600g"],["豆腐","400g"]],"sea":["盐","料酒","白胡椒","葱","姜","食用油","香油"],"steps":["鱼头洗净劈开，用料酒和姜片抹匀腌10分钟，擦干水分。","豆腐切3厘米块，放淡盐水泡5分钟去豆腥。","锅烧热用姜片擦一遍再倒油，鱼头剖面朝下，中火煎至两面金黄。","一次加足开水，大火滚10分钟至汤色奶白，撇去浮沫。","下豆腐再煮8分钟，加盐和白胡椒，撒葱花、滴香油。"],"tip":"煎好鱼头一定冲开水，大火滚才出奶白汤，冷水会腥。"},{"name":"西红柿豆腐汤","cat":"汤羹","region":"家常","time":20,"diff":"简单","main":[["西红柿","2个"],["豆腐","300g"],["鸡蛋","1个"]],"sea":["盐","白糖","葱","食用油","香油"],"steps":["西红柿顶部划十字，开水烫2分钟去皮，切小块。","豆腐切2厘米见方的小块，放淡盐水里泡5分钟；鸡蛋打散备用。","锅放油，中火下西红柿炒3分钟，炒出红油和沙。","加两碗清水烧开，下豆腐转中火煮5分钟。","转圈淋入蛋液，凝固后再推散，加盐、糖，撒葱花点香油。"],"tip":"西红柿先用油炒出沙再加水，汤才浓红有味，不必多放番茄酱。"},{"name":"腐竹烧肉","cat":"荤菜","region":"家常","time":50,"diff":"中等","main":[["腐竹","100g"],["五花肉","300g"]],"sea":["生抽","老抽","料酒","冰糖","八角","姜","葱","食用油"],"steps":["腐竹用温水泡2小时至完全变软，切5厘米段，沥干水。","五花肉切2厘米块，冷水下锅加料酒焯3分钟，捞出冲净。","锅中少油，中小火下冰糖炒到枣红色，倒入肉块翻炒上色。","加姜片、八角、生抽、老抽和热水没过肉，小火炖30分钟。","下腐竹再烧8分钟，大火收汁至浓稠，撒葱花出锅。"],"tip":"腐竹要最后放，烧久了会烂成糊，泡发用温水别用开水。"},{"name":"油豆腐塞肉","cat":"荤菜","region":"本帮","time":45,"diff":"中等","main":[["油豆腐","12个"],["猪肉末","250g"]],"sea":["盐","生抽","老抽","白糖","料酒","淀粉","葱","姜"],"steps":["猪肉末加葱姜末、盐、生抽、料酒和淀粉，搅到发黏上劲。","油豆腐用筷子戳小口，手指轻捏掏松内部，方便塞馅。","肉馅从小口挤进去，塞到八分满，口朝上摆进碗里。","生抽、老抽、白糖加热水调成汤汁浇上，上锅大火蒸20分钟。","蒸出的汤汁倒回锅中，淋水淀粉勾芡，再浇回油豆腐上。"],"tip":"肉馅塞八分满就好，塞太满蒸的时候会顶破油豆腐。"},{"name":"蒸咸蛋肉饼","cat":"荤菜","region":"粤","time":30,"diff":"简单","main":[["猪肉末","300g"],["咸鸭蛋","2个"]],"sea":["盐","生抽","淀粉","白胡椒","葱","姜","香油"],"steps":["猪肉末加葱姜末、盐、生抽、淀粉、白胡椒和两勺清水，顺向搅上劲。","肉末铺进浅盘，压成1.5厘米厚的圆饼，表面抹平。","咸鸭蛋磕开，蛋黄放在饼中央，蛋白淋在肉饼表面。","上锅水开后大火蒸15分钟，筷子插中间无血水即可。","出锅撒葱花、淋香油，趁热上桌，凉了肉饼会发硬。"],"tip":"肉饼里加两勺清水搅打，蒸出来才嫩，蛋黄居中好看。"},{"name":"蛋饺","cat":"荤菜","region":"家常","time":50,"diff":"较难","main":[["鸡蛋","4个"],["猪肉末","200g"]],"sea":["盐","生抽","料酒","淀粉","葱","姜","香油","食用油"],"steps":["肉末加葱姜末、盐、生抽、料酒、香油和淀粉，搅打上劲。","鸡蛋打散，加少许盐和淀粉水搅匀，过筛去掉泡沫。","小铁勺烧热抹一层薄油，舀一勺蛋液转圈摊成小圆皮。","蛋皮边缘还湿时放小团肉馅，对折压紧边缘成半月形。","做好的蛋饺摆盘中，上锅蒸10分钟或下汤煮5分钟。"],"tip":"蛋液里加一点淀粉水，蛋皮更有韧性，对折时才不破。"},{"name":"鸡蛋饼","cat":"主食","region":"家常","time":15,"diff":"简单","main":[["面粉","150g"],["鸡蛋","2个"],["葱","2根"]],"sea":["盐","白胡椒","食用油"],"steps":["面粉加250毫升清水，搅成无颗粒的稀面糊，静置10分钟。","鸡蛋打散倒入面糊，加盐、白胡椒和葱花搅匀。","平底锅小火烧热刷薄油，舀一勺面糊转锅摊成薄圆饼。","底面凝固后翻面，两面各烙1分钟至微黄。","出锅卷起切块，趁热吃最软，凉了会发硬。"],"tip":"面糊要调得稀一点，摊的时候才转得开，饼薄而软。"}];
